'use client'

import { useEffect, useState } from 'react'

export function useUnsavedChanges(hasChanges: boolean) {
  const [showWarning, setShowWarning] = useState(false)
  const [pendingAction, setPendingAction] = useState<(() => void) | null>(null)

  useEffect(() => {
    if (!hasChanges) return

    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      e.preventDefault()
      e.returnValue = ''
      return ''
    }

    window.addEventListener('beforeunload', handleBeforeUnload)
    return () => window.removeEventListener('beforeunload', handleBeforeUnload)
  }, [hasChanges])

  const confirmNavigation = (callback: () => void) => {
    if (hasChanges) {
      setPendingAction(() => callback)
      setShowWarning(true)
    } else {
      callback()
    }
  }

  const handleDiscard = () => {
    setShowWarning(false)
    if (pendingAction) {
      pendingAction()
      setPendingAction(null)
    }
  }

  return { showWarning, setShowWarning, confirmNavigation, handleDiscard }
}

'use client'

// Inspired by react-hot-toast library
import * as React from 'react'

import type { ToastActionElement, ToastProps } from '@/components/ui/toast'

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = {
  ADD_TOAST: 'ADD_TOAST'
  UPDATE_TOAST: 'UPDATE_TOAST'
  DISMISS_TOAST: 'DISMISS_TOAST'
  REMOVE_TOAST: 'REMOVE_TOAST'
}

type Action =
  | {
      type: ActionType['ADD_TOAST']
      toast: ToasterToast
    }
  | {
      type: ActionType['UPDATE_TOAST']
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType['DISMISS_TOAST']
      toastId?: ToasterToast['id']
    }
  | {
      type: ActionType['REMOVE_TOAST']
      toastId?: ToasterToast['id']
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: 'REMOVE_TOAST',
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'ADD_TOAST':
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case 'UPDATE_TOAST':
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t,
        ),
      }

    case 'DISMISS_TOAST': {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t,
        ),
      }
    }
    case 'REMOVE_TOAST':
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, 'id'>

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: 'UPDATE_TOAST',
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: 'DISMISS_TOAST', toastId: id })

  dispatch({
    type: 'ADD_TOAST',
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: 'DISMISS_TOAST', toastId }),
  }
}

export { useToast, toast }

import * as React from 'react'

const MOBILE_BREAKPOINT = 768
const MOBILE_QUERY = `(max-width: ${MOBILE_BREAKPOINT - 1}px)`

function subscribe(onChange: () => void) {
  const mediaQuery = window.matchMedia(MOBILE_QUERY)
  mediaQuery.addEventListener('change', onChange)
  return () => mediaQuery.removeEventListener('change', onChange)
}

function getSnapshot() {
  return window.matchMedia(MOBILE_QUERY).matches
}

export function useIsMobile() {
  return React.useSyncExternalStore(subscribe, getSnapshot, () => false)
}

'use client'

import { useRef, useState } from 'react'

export function useCmsSingletonSave(initialRevision: string) {
  const [revision, setRevision] = useState(initialRevision)
  const pendingSave = useRef<{ fingerprint: string; requestId: string } | null>(null)

  function prepareSave<T extends Record<string, unknown>>(item: T) {
    const saveBody = { expected_revision: revision, item }
    const fingerprint = JSON.stringify(saveBody)
    if (pendingSave.current?.fingerprint !== fingerprint) pendingSave.current = { fingerprint, requestId: crypto.randomUUID() }
    return { ...saveBody, request_id: pendingSave.current.requestId }
  }

  function acceptSave(nextRevision: string) {
    setRevision(nextRevision)
    pendingSave.current = null
  }

  return { prepareSave, acceptSave }
}

'use client'

import { useRef, useState } from 'react'

type PersistedItem = Record<string, unknown> & { id?: string | number | null }

export function useCmsAtomicListSave(initialItems: PersistedItem[], initialRevision: string) {
  const [revision, setRevision] = useState(initialRevision)
  const [savedItemIds, setSavedItemIds] = useState(() => initialItems.flatMap((item) => item.id == null ? [] : [String(item.id)]))
  const pendingSave = useRef<{ fingerprint: string; requestId: string } | null>(null)

  function prepareSave<T extends Record<string, unknown>>(body: T, currentItems: PersistedItem[]) {
    const retainedIds = new Set(currentItems.flatMap((item) => item.id == null ? [] : [String(item.id)]))
    const saveBody = {
      ...body,
      expected_revision: revision,
      deleted_ids: savedItemIds.filter((id) => !retainedIds.has(id)),
    }
    const fingerprint = JSON.stringify(saveBody)
    if (pendingSave.current?.fingerprint !== fingerprint) {
      pendingSave.current = { fingerprint, requestId: crypto.randomUUID() }
    }
    return { ...saveBody, request_id: pendingSave.current.requestId }
  }

  function acceptSave(items: PersistedItem[], nextRevision: string) {
    setSavedItemIds(items.flatMap((item) => item.id == null ? [] : [String(item.id)]))
    setRevision(nextRevision)
    pendingSave.current = null
  }

  return { prepareSave, acceptSave }
}

'use client'

import { Loader2, Save } from 'lucide-react'

type CmsSaveActionProps = {
  onClick: () => void
  isSaving?: boolean
  disabled?: boolean
  label?: string
  position?: 'bottom-right' | 'top-right' | 'inline'
}

export function CmsSaveAction({
  onClick,
  isSaving = false,
  disabled = false,
  label = 'Save Changes',
  position = 'bottom-right',
}: CmsSaveActionProps) {
  const positionClass =
    position === 'inline'
      ? 'static'
      : position === 'top-right'
        ? 'top-6 right-6'
        : 'bottom-6 right-6'

  return (
    <button
      onClick={onClick}
      disabled={isSaving || disabled}
      className={`${
        position === 'inline' ? 'inline-flex' : 'fixed'
      } ${positionClass} ${position === 'inline' ? '' : 'z-40'} flex items-center gap-2 rounded-lg bg-primary px-5 py-3 text-sm font-semibold text-white shadow-lg transition-colors hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-60`}
    >
      {isSaving ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />}
      {isSaving ? 'Saving...' : label}
    </button>
  )
}

'use client'

import { useState } from 'react'
import { resolveImageReference } from '@/lib/image-reference'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL?.replace(/\/$/, '')
const collectionBucket = process.env.NEXT_PUBLIC_SUPABASE_COLLECTION_BUCKET || 'hod'

export function resolveCatalogImageUrl(path?: string | null) {
  return resolveImageReference(path, supabaseUrl ? `${supabaseUrl}/storage/v1/object/public/${collectionBucket}` : undefined)
}

function isSvgImage(path: string) {
  return /\.svg(?:$|[?#])/i.test(path) || /^data:image\/svg\+xml/i.test(path)
}

export function CatalogImagePreview({
  path,
  alt,
  size = 'table',
  className = '',
}: {
  path?: string | null
  alt: string
  size?: 'table' | 'editor' | 'banner'
  className?: string
}) {
  const src = resolveCatalogImageUrl(path)
  const [failedSrc, setFailedSrc] = useState<string | null>(null)
  const failed = Boolean(src && failedSrc === src)

  const dimensions = size === 'table'
    ? 'h-14 w-14'
    : size === 'banner'
      ? 'h-36 w-full'
      : 'h-28 w-28'

  if (!src || failed) {
    return (
      <div
        role="img"
        aria-label={alt || 'No image'}
        className={`${dimensions} flex shrink-0 items-center justify-center border border-border bg-secondary/40 px-2 text-center text-[11px] font-medium text-muted-foreground ${className}`}
      >
        No image
      </div>
    )
  }

  return (
    <div className={`${dimensions} shrink-0 overflow-hidden border border-border bg-secondary/30 ${className}`}>
      {/* Native img supports SVG and storage URLs without requiring Next image host configuration. */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={src}
        alt={alt}
        onError={() => setFailedSrc(src)}
        className={`h-full w-full ${isSvgImage(src) ? 'object-contain p-1.5' : 'object-cover'}`}
      />
    </div>
  )
}

'use client'

import { useMemo, useState } from 'react'
import { Loader2, SlidersHorizontal } from 'lucide-react'
import { productFetch } from '@/lib/product-transport'
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'

type Operation = 'increase_amount' | 'decrease_amount' | 'increase_percent' | 'decrease_percent'
type SelectedProduct = { id: string; name: string; price: number | null }
type BulkPriceDialogProps = {
  open: boolean
  products: SelectedProduct[]
  allProducts: SelectedProduct[]
  lane: 'standard' | 'hiphop' | 'collection'
  onClose: () => void
  onApplied: (items: Array<{ id: string; price: number }>) => void
}

function roundMoney(value: number) { return Math.round((value + Number.EPSILON) * 100) / 100 }
function formatPrice(value: number) { return `$${value.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 })}` }
function calculatePrice(price: number, operation: Operation, value: number) {
  const delta = operation.endsWith('_percent') ? price * (value / 100) : value
  return roundMoney(operation.startsWith('increase_') ? price + delta : price - delta)
}

export function BulkPriceDialog(props: BulkPriceDialogProps) {
  if (!props.open) return null
  return <BulkPriceDialogContent {...props} />
}

function BulkPriceDialogContent({ products, allProducts, lane, onClose, onApplied }: BulkPriceDialogProps) {
  const [operation, setOperation] = useState<Operation>('increase_percent')
  const [rawValue, setRawValue] = useState('')
  const [confirmed, setConfirmed] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [scope, setScope] = useState<'selected' | 'all'>(() => products.length ? 'selected' : 'all')
  const [requestId] = useState(() => crypto.randomUUID())
  const effectiveProducts = scope === 'all' ? allProducts : products
  const value = Number(rawValue)
  const invalidPriceCount = effectiveProducts.filter((product) => product.price == null || !Number.isFinite(product.price) || product.price <= 0).length
  const valueIsValid = Number.isFinite(value) && value > 0 && value <= 1_000_000_000 && (!operation.endsWith('_percent') || value <= 1000) && (operation !== 'decrease_percent' || value < 100)
  const preview = useMemo(() => effectiveProducts.filter((product): product is SelectedProduct & { price: number } => product.price != null && Number.isFinite(product.price)).slice(0, 4).map((product) => ({ ...product, nextPrice: valueIsValid ? calculatePrice(product.price, operation, value) : product.price })), [effectiveProducts, operation, value, valueIsValid])
  const hasInvalidResult = preview.some((product) => product.nextPrice <= 0 || product.nextPrice > 1_000_000_000)

  const apply = async () => {
    if (loading || !requestId || !confirmed || !valueIsValid || invalidPriceCount || hasInvalidResult || !effectiveProducts.length) return
    setLoading(true)
    setError('')
    try {
      const response = await productFetch('/api/products/bulk-price', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ requestId, ids: effectiveProducts.map((product) => product.id), expectedPrices: effectiveProducts.map((product) => ({ id: product.id, price: product.price })), lane, operation, value, confirmation: 'ADJUST_BASE_PRICES' }),
      })
      const payload = await response.json().catch(() => null)
      if (!response.ok) throw new Error(payload?.error || 'Unable to update the selected prices.')
      onApplied(Array.isArray(payload?.items) ? payload.items : [])
    } catch (applyError) {
      setError(applyError instanceof Error ? applyError.message : 'Unable to update the selected prices.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <Dialog open onOpenChange={(next) => { if (!next && !loading) onClose() }}>
      <DialogContent className="sm:max-w-xl">
        <DialogHeader><DialogTitle className="flex items-center gap-2 font-jakarta text-lg font-semibold"><SlidersHorizontal size={19} />Adjust base prices</DialogTitle><DialogDescription>Updates only the listed base price. It cannot delete products or modify stock, status, variants, or discounts.</DialogDescription></DialogHeader>
        <div className="space-y-5 py-2">
          <div className="grid grid-cols-2 rounded-lg border border-border p-1">
            <button type="button" onClick={() => { setScope('selected'); setConfirmed(false); setError('') }} disabled={!products.length} className={`rounded-md px-3 py-2 text-sm font-semibold ${scope === 'selected' ? 'bg-primary text-white' : 'text-foreground hover:bg-secondary'} disabled:cursor-not-allowed disabled:opacity-40`}>Selected ({products.length})</button>
            <button type="button" onClick={() => { setScope('all'); setConfirmed(false); setError('') }} disabled={!allProducts.length} className={`rounded-md px-3 py-2 text-sm font-semibold ${scope === 'all' ? 'bg-primary text-white' : 'text-foreground hover:bg-secondary'} disabled:cursor-not-allowed disabled:opacity-40`}>All filtered ({allProducts.length})</button>
          </div>
          <p className="text-xs text-muted-foreground">“All filtered” applies only to this price change and does not add products to the deletion selection.</p>
          <div className="grid gap-4 sm:grid-cols-2">
            <label className="space-y-2 text-sm font-semibold text-foreground">Operation<select value={operation} onChange={(event) => { setOperation(event.target.value as Operation); setConfirmed(false); setError('') }} className="h-11 w-full rounded-lg border border-border bg-white px-3 text-sm font-normal outline-none focus:border-primary"><option value="increase_amount">Increase by amount</option><option value="decrease_amount">Decrease by amount</option><option value="increase_percent">Increase by percentage</option><option value="decrease_percent">Decrease by percentage</option></select></label>
            <label className="space-y-2 text-sm font-semibold text-foreground">{operation.endsWith('_percent') ? 'Percentage' : 'Amount'}<div className="relative"><input type="number" min="0.01" max={operation === 'decrease_percent' ? '99.99' : operation.endsWith('_percent') ? '1000' : '1000000000'} step="0.01" value={rawValue} onChange={(event) => { setRawValue(event.target.value); setConfirmed(false); setError('') }} className="h-11 w-full rounded-lg border border-border bg-white px-3 pr-10 text-sm outline-none focus:border-primary" placeholder="0.00" /><span className="absolute right-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">{operation.endsWith('_percent') ? '%' : '$'}</span></div></label>
          </div>
          {invalidPriceCount ? <p className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">{invalidPriceCount} product{invalidPriceCount === 1 ? ' has' : 's have'} no valid base price. Change the scope or add their prices before continuing.</p> : null}
          <div className="rounded-lg border border-border bg-secondary/30 p-4"><p className="text-xs font-semibold uppercase tracking-[.08em] text-muted-foreground">Preview · {effectiveProducts.length} product{effectiveProducts.length === 1 ? '' : 's'}</p><div className="mt-3 space-y-2">{preview.map((product) => <div key={product.id} className="flex items-center justify-between gap-4 text-sm"><span className="min-w-0 truncate text-foreground">{product.name}</span><span className="shrink-0 font-jakarta font-semibold">{formatPrice(product.price)} → {formatPrice(product.nextPrice)}</span></div>)}</div>{effectiveProducts.length > preview.length ? <p className="mt-3 text-xs text-muted-foreground">Plus {effectiveProducts.length - preview.length} more products.</p> : null}</div>
          <label className="flex items-start gap-3 rounded-lg border border-border p-4 text-sm"><input type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 rounded border-border text-primary focus:ring-ring" /><span>I confirm these base-price changes. Product records, stock, status, variants, discounts, and selections will not be deleted or modified.</span></label>
          {error ? <p role="alert" className="text-sm text-red-600">{error}</p> : null}
        </div>
        <DialogFooter><button type="button" onClick={onClose} disabled={loading} className="rounded-lg border border-border px-4 py-2.5 text-sm font-semibold hover:bg-secondary disabled:opacity-60">Cancel</button><button type="button" onClick={() => void apply()} disabled={loading || !confirmed || !valueIsValid || invalidPriceCount > 0 || hasInvalidResult || effectiveProducts.length === 0} className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-50">{loading ? <Loader2 size={16} className="animate-spin" /> : null}{loading ? 'Updating prices…' : 'Apply price changes'}</button></DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'
import { tryUploadAwsImage } from '@/lib/image-transport'
import { cmsFetch } from '@/lib/cms-transport'

import Link from 'next/link'
import { useEffect, useMemo, useRef, useState, type ChangeEvent } from 'react'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Bold, Heading2, Heading3, Italic, List, ListOrdered, Pilcrow, Plus, Quote, Trash2, Upload } from 'lucide-react'
import { CmsSaveAction } from '@/components/cms-save-action'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { useToast } from '@/hooks/use-toast'
import { useUnsavedChanges } from '@/hooks/use-unsaved-changes'
import { useEditor, useEditorState, EditorContent } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import Placeholder from '@tiptap/extension-placeholder'

export type BlogCatalogCategory = { id: string; name: string; slug: string }

type BlogTag = { clientId: string; id?: number | string; value: string }
type BlogProduct = {
  id: string
  relationId?: number | string
  slug: string
  name: string
  status?: string | null
  base_price?: number | null
}

async function prepareBlogImage(file: File) {
  if (file.type === 'image/svg+xml') return file
  if (!['image/jpeg', 'image/png', 'image/webp', 'image/avif'].includes(file.type)) {
    throw new Error('Invalid image type.')
  }

  const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' })
  try {
    const width = Math.min(bitmap.width, 2200)
    const height = Math.max(1, Math.round(bitmap.height * (width / bitmap.width)))
    const canvas = document.createElement('canvas')
    canvas.width = width
    canvas.height = height
    canvas.getContext('2d')?.drawImage(bitmap, 0, 0, width, height)
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/webp', 0.84))
    if (!blob) throw new Error('Unable to optimize image.')
    return new File([blob], `${crypto.randomUUID()}.webp`, { type: 'image/webp' })
  } finally {
    bitmap.close()
  }
}
type BlogContentBlock = {
  clientId: string
  id?: number | string
  block_type: 'text' | 'image' | 'heading' | 'quote'
  sort_order: number
  heading: string
  body_html: string
  image_path: string
  image_alt: string
  image_caption: string
  is_enabled: boolean
}

type BlogForm = {
  slug: string
  title: string
  title_html: string
  card_title: string
  subtitle: string
  category: string
  catalog_category_id: string
  author: string
  date_label: string
  read_time: string
  bg_key: string
  bg_color: string
  hero_image_path: string
  card_image_path: string
  hero_image_alt: string
  body_html: string
  is_published: boolean
  sort_order: number
}

export type BlogEditorInitialData = {
  post?: BlogForm & { id: number | string }
  tags?: Array<{ id: number | string; tag: string; sort_order: number }>
  products?: Array<{
    id: number | string
    product_id: string
    sort_order: number
    product: BlogProduct | BlogProduct[] | null
  }>
  revision?: string
  content_blocks?: Array<{
    id: number | string
    block_type: 'text' | 'image' | 'heading' | 'quote'
    sort_order: number
    heading: string | null
    body_html: string | null
    image_path: string | null
    image_alt: string | null
    image_caption: string | null
    is_enabled: boolean | null
  }>
  error?: string
}

function createEmptyBlock(
  type: BlogContentBlock['block_type'],
  sortOrder: number
): BlogContentBlock {
  return {
    clientId: `block-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    block_type: type,
    sort_order: sortOrder,
    heading: '',
    body_html: type === 'text' ? '<p></p>' : '',
    image_path: '',
    image_alt: '',
    image_caption: '',
    is_enabled: true,
  }
}

function formatBlogUrl(slug: string) {
  return `/blog/${slug.replace(/^\/+/, '').replace(/^blog\/?/, '')}`
}

function RichTextEditor({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const editor = useEditor({
    extensions: [
      StarterKit.configure({ heading: { levels: [2, 3, 4] } }),
      Placeholder.configure({ placeholder: 'Write the blog body here...' }),
    ],
    content: value || '<p></p>',
    immediatelyRender: false,
    editorProps: {
      attributes: {
        class:
          'min-h-[320px] w-full px-4 py-3 text-sm text-foreground outline-none prose prose-sm max-w-none',
      },
    },
    onUpdate: ({ editor }) => onChange(editor.getHTML()),
  })

  useEffect(() => {
    if (!editor) return
    const current = editor.getHTML()
    if (value !== current) editor.commands.setContent(value || '<p></p>')
  }, [editor, value])

  const state = useEditorState({
    editor,
    selector: ({ editor: currentEditor }) => ({
      paragraph: currentEditor?.isActive('paragraph') ?? false,
      heading2: currentEditor?.isActive('heading', { level: 2 }) ?? false,
      heading3: currentEditor?.isActive('heading', { level: 3 }) ?? false,
      bold: currentEditor?.isActive('bold') ?? false,
      italic: currentEditor?.isActive('italic') ?? false,
      bulletList: currentEditor?.isActive('bulletList') ?? false,
      orderedList: currentEditor?.isActive('orderedList') ?? false,
      blockquote: currentEditor?.isActive('blockquote') ?? false,
    }),
  })

  const buttonClass = (active: boolean) =>
    `inline-flex items-center gap-1 rounded-md border px-2.5 py-1.5 text-xs font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-45 ${active ? 'border-primary bg-primary text-primary-foreground shadow-sm' : 'border-border bg-white text-foreground hover:bg-secondary'}`

  return (
    <div className="max-h-[620px] overflow-y-auto rounded-lg border border-border bg-white focus-within:ring-2 focus-within:ring-primary/25">
      <div className="sticky top-0 z-10 flex flex-wrap gap-2 border-b border-border bg-secondary/95 p-2 shadow-sm backdrop-blur-sm">
        <button type="button" aria-pressed={state?.paragraph ?? false} disabled={!editor?.can().chain().focus().setParagraph().run()} onClick={() => editor?.chain().focus().setParagraph().run()} className={buttonClass(state?.paragraph ?? false)}><Pilcrow size={13} />Paragraph</button>
        <button type="button" aria-pressed={state?.heading2 ?? false} disabled={!editor?.can().chain().focus().toggleHeading({ level: 2 }).run()} onClick={() => editor?.chain().focus().toggleHeading({ level: 2 }).run()} className={buttonClass(state?.heading2 ?? false)}><Heading2 size={13} />H2</button>
        <button type="button" aria-pressed={state?.heading3 ?? false} disabled={!editor?.can().chain().focus().toggleHeading({ level: 3 }).run()} onClick={() => editor?.chain().focus().toggleHeading({ level: 3 }).run()} className={buttonClass(state?.heading3 ?? false)}><Heading3 size={13} />H3</button>
        <button type="button" aria-pressed={state?.bold ?? false} disabled={!editor?.can().chain().focus().toggleBold().run()} onClick={() => editor?.chain().focus().toggleBold().run()} className={buttonClass(state?.bold ?? false)}><Bold size={13} />Bold</button>
        <button type="button" aria-pressed={state?.italic ?? false} disabled={!editor?.can().chain().focus().toggleItalic().run()} onClick={() => editor?.chain().focus().toggleItalic().run()} className={buttonClass(state?.italic ?? false)}><Italic size={13} />Italic</button>
        <button type="button" aria-pressed={state?.bulletList ?? false} disabled={!editor?.can().chain().focus().toggleBulletList().run()} onClick={() => editor?.chain().focus().toggleBulletList().run()} className={buttonClass(state?.bulletList ?? false)}><List size={13} />Bullet</button>
        <button type="button" aria-pressed={state?.orderedList ?? false} disabled={!editor?.can().chain().focus().toggleOrderedList().run()} onClick={() => editor?.chain().focus().toggleOrderedList().run()} className={buttonClass(state?.orderedList ?? false)}><ListOrdered size={13} />Numbered</button>
        <button type="button" aria-pressed={state?.blockquote ?? false} disabled={!editor?.can().chain().focus().toggleBlockquote().run()} onClick={() => editor?.chain().focus().toggleBlockquote().run()} className={buttonClass(state?.blockquote ?? false)}><Quote size={13} />Quote</button>
      </div>
      <EditorContent editor={editor} />
    </div>
  )
}

async function adminApiFetch(input: RequestInfo | URL, init: RequestInit = {}) {
  if (typeof input === 'string' && input.startsWith('/api/cms/') && !input.startsWith('/api/cms/uploads/')) return cmsFetch(input, init)
  if (input === '/api/products') return cmsFetch('/api/cms/references/products', init)
  return fetch(input, { ...init, credentials: 'same-origin' })
}

const emptyForm: BlogForm = {
  slug: '',
  title: '',
  title_html: '',
  card_title: '',
  subtitle: '',
  category: '',
  catalog_category_id: '',
  author: '',
  date_label: '',
  read_time: '',
  bg_key: 'bg-0',
  bg_color: '#EEF1F8',
  hero_image_path: '',
  card_image_path: '',
  hero_image_alt: '',
  body_html: '<p></p>',
  is_published: true,
  sort_order: 1,
}

function initialTags(data?: BlogEditorInitialData) {
  const tags = (data?.tags ?? []).map((tag) => ({ clientId: `tag-${tag.id}`, id: tag.id, value: tag.tag }))
  return tags.length > 0 ? tags : [{ clientId: 'tag-empty', value: '' }]
}

function initialProducts(data?: BlogEditorInitialData) {
  return (data?.products ?? []).flatMap((item): BlogProduct[] => {
    const product = Array.isArray(item.product) ? item.product[0] : item.product
    return product?.id ? [{ ...product, relationId: item.id }] : []
  })
}

function initialContentBlocks(data?: BlogEditorInitialData): BlogContentBlock[] {
  return (data?.content_blocks ?? []).map((block, index) => ({
    clientId: `block-${block.id}`,
    id: block.id,
    block_type: block.block_type,
    sort_order: block.sort_order ?? index + 1,
    heading: block.heading ?? '',
    body_html: block.body_html ?? '',
    image_path: block.image_path ?? '',
    image_alt: block.image_alt ?? '',
    image_caption: block.image_caption ?? '',
    is_enabled: block.is_enabled !== false,
  }))
}

function blogDraftFingerprint(form: BlogForm, tags: BlogTag[], products: BlogProduct[], blocks: BlogContentBlock[]) {
  return JSON.stringify({
    form,
    tags: tags.filter((tag) => tag.value.trim()).map(({ id, value }) => ({ id, value: value.trim() })),
    products: products.map(({ id, relationId }) => ({ id, relationId })),
    blocks: blocks.map((block) => ({ id: block.id, block_type: block.block_type, heading: block.heading, body_html: block.body_html, image_path: block.image_path, image_alt: block.image_alt, image_caption: block.image_caption, is_enabled: block.is_enabled })),
  })
}

export function BlogEditorPage({ mode, id, categories, initialData }: { mode: 'create' | 'edit'; id?: string; categories: BlogCatalogCategory[]; initialData?: BlogEditorInitialData }) {
  const { toast } = useToast()
  const router = useRouter()
  const [form, setForm] = useState<BlogForm>(() => initialData?.post ? { ...initialData.post, catalog_category_id: initialData.post.catalog_category_id ?? '', card_title: initialData.post.card_title ?? '', card_image_path: initialData.post.card_image_path ?? '', hero_image_alt: initialData.post.hero_image_alt ?? '' } : emptyForm)
  const [tags, setTags] = useState<BlogTag[]>(() => initialTags(initialData))
  const [selectedProducts, setSelectedProducts] = useState<BlogProduct[]>(() => initialProducts(initialData))
  const [availableProducts, setAvailableProducts] = useState<BlogProduct[]>([])
  const [productSearch, setProductSearch] = useState('')
  const [contentBlocks, setContentBlocks] = useState<BlogContentBlock[]>(() => initialContentBlocks(initialData))
  const [status, setStatus] = useState(mode === 'create' ? 'Create a new blog post.' : initialData?.post ? 'Ready to edit' : 'Loading blog post...')
  const [isSaving, setIsSaving] = useState(false)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [isDeleting, setIsDeleting] = useState(false)
  const [revision, setRevision] = useState(initialData?.revision ?? '')
  const [savedTagIds, setSavedTagIds] = useState(() => (initialData?.tags ?? []).map((item) => String(item.id)))
  const [savedProductIds, setSavedProductIds] = useState(() => (initialData?.products ?? []).map((item) => String(item.id)))
  const [savedBlockIds, setSavedBlockIds] = useState(() => (initialData?.content_blocks ?? []).map((item) => String(item.id)))
  const [savedFingerprint, setSavedFingerprint] = useState(() => blogDraftFingerprint(
    initialData?.post ? { ...initialData.post, catalog_category_id: initialData.post.catalog_category_id ?? '', card_title: initialData.post.card_title ?? '', card_image_path: initialData.post.card_image_path ?? '', hero_image_alt: initialData.post.hero_image_alt ?? '' } : emptyForm,
    initialTags(initialData), initialProducts(initialData), initialContentBlocks(initialData)
  ))
  const pendingSave = useRef<{ fingerprint: string; requestId: string } | null>(null)
  const pendingDeleteId = useRef<string | null>(null)
  const currentFingerprint = useMemo(() => blogDraftFingerprint(form, tags, selectedProducts, contentBlocks), [form, tags, selectedProducts, contentBlocks])
  const isDirty = currentFingerprint !== savedFingerprint
  const unsaved = useUnsavedChanges(isDirty)

  const filteredProducts = useMemo(() => {
    const search = productSearch.trim().toLowerCase()
    const selectedIds = new Set(selectedProducts.map((product) => product.id))
    return availableProducts
      .filter((product) => !selectedIds.has(product.id))
      .filter((product) => {
        if (!search) return true
        return [product.name, product.slug, product.status].some((value) => String(value ?? '').toLowerCase().includes(search))
      })
      .slice(0, 8)
  }, [availableProducts, productSearch, selectedProducts])

  useEffect(() => {
    const loadProducts = async () => {
      const response = await adminApiFetch('/api/products')

      const payload = (await response.json().catch(() => null)) as { items?: BlogProduct[] } | null
      if (!response.ok) return
      setAvailableProducts(payload?.items ?? [])
    }

    loadProducts()
  }, [])

  useEffect(() => {
    if (mode !== 'edit' || !id || initialData?.post) return

    const load = async () => {
      const response = await adminApiFetch(`/api/cms/blog/posts/${id}`)

      const payload = (await response.json().catch(() => null)) as BlogEditorInitialData | null
      if (!response.ok || !payload?.post) return setStatus(payload?.error ?? 'Unable to load blog post.')

      const nextForm = { ...payload.post, catalog_category_id: payload.post.catalog_category_id ?? '', card_title: payload.post.card_title ?? '', card_image_path: payload.post.card_image_path ?? '', hero_image_alt: payload.post.hero_image_alt ?? '' }
      const nextTags = initialTags(payload)
      const nextProducts = initialProducts(payload)
      const nextBlocks = initialContentBlocks(payload)
      setForm(nextForm)
      setTags(nextTags)
      setSelectedProducts(nextProducts)
      setContentBlocks(nextBlocks)
      setSavedFingerprint(blogDraftFingerprint(nextForm, nextTags, nextProducts, nextBlocks))
      setRevision(payload.revision ?? '')
      setSavedTagIds((payload.tags ?? []).map((item) => String(item.id)))
      setSavedProductIds((payload.products ?? []).map((item) => String(item.id)))
      setSavedBlockIds((payload.content_blocks ?? []).map((item) => String(item.id)))
      setStatus('Blog post loaded')
    }

    load()
  }, [mode, id, initialData?.post])

  const uploadBlogMedia = async (file: File) => {
    if (file.size > 5 * 1024 * 1024) throw new Error('File too large. Max size is 5MB.')


      const awsPath = await tryUploadAwsImage(file, '/api/cms/uploads/blog', {})
      if (awsPath) { return awsPath }




    const { supabase } = await import('@/lib/supabase')
    try {
      const preparedFile = await prepareBlogImage(file)
      const signResponse = await adminApiFetch('/api/cms/uploads/blog/sign', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
        },
        body: JSON.stringify({ contentType: preparedFile.type, declaredSize: preparedFile.size }),
      })
      const signed = (await signResponse.json().catch(() => null)) as { bucket?: string; path?: string; token?: string; error?: string } | null
      if (!signResponse.ok || !signed?.bucket || !signed.path || !signed.token) {
        throw new Error(signed?.error ?? 'Unable to prepare upload.')
      }

      const { error } = await supabase.storage.from(signed.bucket)
        .uploadToSignedUrl(signed.path, signed.token, preparedFile, { contentType: preparedFile.type })
      if (error) throw error
      return signed.path
    } catch (directError) {
      const formData = new FormData()
      formData.append('file', file)
      const response = await adminApiFetch('/api/cms/uploads/blog', {
        method: 'POST',
        body: formData,
      })
      const payload = (await response.json().catch(() => null)) as { path?: string; error?: string } | null
      if (!response.ok || !payload?.path) {
        throw new Error(payload?.error ?? (directError instanceof Error ? directError.message : 'Unable to upload image.'))
      }
      return payload.path
    }
  }

  const uploadImage = async (file: File) => {
    setUploading(true)
    setStatus('Uploading blog image...')
    try {
      const path = await uploadBlogMedia(file)
      setForm((prev) => ({ ...prev, hero_image_path: path }))
      setStatus('Blog image uploaded successfully')
    } catch (error) {
      setStatus(error instanceof Error ? error.message : 'Unable to upload image.')
    } finally {
      setUploading(false)
    }
  }

  const uploadCardImage = async (file: File) => {
    setUploading(true)
    setStatus('Uploading blog card image...')
    try {
      const path = await uploadBlogMedia(file)
      setForm((prev) => ({ ...prev, card_image_path: path }))
      setStatus('Blog card image uploaded successfully')
    } catch (error) {
      setStatus(error instanceof Error ? error.message : 'Unable to upload card image.')
    } finally {
      setUploading(false)
    }
  }

  const uploadBlockImage = async (clientId: string, file: File) => {
    setUploading(true)
    setStatus('Uploading block image...')
    try {
      const path = await uploadBlogMedia(file)
      setContentBlocks((prev) =>
        prev.map((block) => (block.clientId === clientId ? { ...block, image_path: path } : block))
      )
      setStatus('Block image uploaded successfully')
    } catch (error) {
      setStatus(error instanceof Error ? error.message : 'Unable to upload image.')
    } finally {
      setUploading(false)
    }
  }

  const save = async () => {
    setIsSaving(true)
    try {
      const endpoint = mode === 'create' ? '/api/cms/blog/posts' : `/api/cms/blog/posts/${id}`
      const retainedTagIds = new Set(tags.flatMap((tag) => tag.id ? [String(tag.id)] : []))
      const retainedProductIds = new Set(selectedProducts.flatMap((product) => product.relationId ? [String(product.relationId)] : []))
      const retainedBlockIds = new Set(contentBlocks.flatMap((block) => block.id ? [String(block.id)] : []))
      const saveBody = {
        expected_revision: mode === 'edit' ? revision : null, post: form,
        tags: tags.filter((tag) => tag.value.trim()).map((tag) => ({ id: tag.id, tag: tag.value.trim() })),
        content_blocks: contentBlocks.map(({ id, block_type, heading, body_html, image_path, image_alt, image_caption, is_enabled }) => ({ id, block_type, heading, body_html, image_path, image_alt, image_caption, is_enabled })),
        products: selectedProducts.map((product) => ({ id: product.relationId, product_id: product.id })),
        deleted_tag_ids: savedTagIds.filter((savedId) => !retainedTagIds.has(savedId)),
        deleted_product_ids: savedProductIds.filter((savedId) => !retainedProductIds.has(savedId)),
        deleted_block_ids: savedBlockIds.filter((savedId) => !retainedBlockIds.has(savedId)),
      }
      const fingerprint = JSON.stringify(saveBody)
      if (pendingSave.current?.fingerprint !== fingerprint) pendingSave.current = { fingerprint, requestId: crypto.randomUUID() }
      const response = await adminApiFetch(endpoint, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ...saveBody, request_id: pendingSave.current.requestId }) })
      const payload = (await response.json().catch(() => null)) as (BlogEditorInitialData & { id?: number | string; slug?: string; error?: string }) | null
      if (!response.ok) throw new Error(payload?.error ?? 'Unable to save blog post.')
      if (!payload?.post || !payload.revision || !Array.isArray(payload.tags) || !Array.isArray(payload.products) || !Array.isArray(payload.content_blocks)) {
        throw new Error('Save response was interrupted. Retry to confirm the same save.')
      }
      const nextForm = { ...payload.post, catalog_category_id: payload.post.catalog_category_id ?? '', card_title: payload.post.card_title ?? '', card_image_path: payload.post.card_image_path ?? '', hero_image_alt: payload.post.hero_image_alt ?? '' }
      const nextTags = initialTags(payload)
      const nextProducts = initialProducts(payload)
      const nextBlocks = initialContentBlocks(payload)
      setForm(nextForm)
      setTags(nextTags)
      setSelectedProducts(nextProducts)
      setContentBlocks(nextBlocks)
      setRevision(payload.revision)
      setSavedTagIds(payload.tags.map((item) => String(item.id)))
      setSavedProductIds(payload.products.map((item) => String(item.id)))
      setSavedBlockIds(payload.content_blocks.map((item) => String(item.id)))
      setSavedFingerprint(blogDraftFingerprint(nextForm, nextTags, nextProducts, nextBlocks))
      pendingSave.current = null
      setConfirmOpen(false)
      setStatus('Blog post saved')
      toast({ title: 'Saved', description: 'Blog post updated successfully.' })
      if (mode === 'create' && payload.id) { router.push(`/dashboard/cms/blog/${payload.id}`); router.refresh() }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unable to save blog post.'
      setStatus(message)
      toast({ title: 'Save failed', description: message, variant: 'destructive' })
    } finally {
      setIsSaving(false)
    }
  }

  const deletePost = async () => {
    if (mode !== 'edit' || !id) return

    setIsDeleting(true)
    try {
      pendingDeleteId.current ??= crypto.randomUUID()
      const response = await adminApiFetch(`/api/cms/blog/posts/${id}`, { method: 'DELETE', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ request_id: pendingDeleteId.current, expected_revision: revision }) })
      const payload = (await response.json().catch(() => null)) as { ok?: boolean; error?: string } | null
      if (!response.ok || !payload?.ok) throw new Error(payload?.error ?? 'Delete response was interrupted. Reload before retrying.')
      setDeleteConfirmOpen(false)
      toast({ title: 'Deleted', description: 'Blog post deleted successfully.' })
      router.push('/dashboard/cms/blog')
      router.refresh()
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unable to delete blog post.'
      setStatus(message)
      toast({ title: 'Delete failed', description: message, variant: 'destructive' })
    } finally {
      setIsDeleting(false)
    }
  }

  const moveSelectedProduct = (productId: string, direction: -1 | 1) => {
    setSelectedProducts((prev) => {
      const index = prev.findIndex((product) => product.id === productId)
      const nextIndex = index + direction
      if (index < 0 || nextIndex < 0 || nextIndex >= prev.length) return prev
      const next = [...prev]
      const [item] = next.splice(index, 1)
      next.splice(nextIndex, 0, item)
      return next
    })
  }

  const moveContentBlock = (clientId: string, direction: -1 | 1) => {
    setContentBlocks((prev) => {
      const index = prev.findIndex((block) => block.clientId === clientId)
      const nextIndex = index + direction
      if (index < 0 || nextIndex < 0 || nextIndex >= prev.length) return prev

      const next = [...prev]
      const [block] = next.splice(index, 1)
      next.splice(nextIndex, 0, block)
      return next.map((entry, order) => ({ ...entry, sort_order: order + 1 }))
    })
  }

  return (
    <div className="min-h-screen bg-background p-8">
      <div className="mb-8 flex items-center justify-between gap-4">
        <Link href="/dashboard/cms/blog" onClick={(event) => { event.preventDefault(); unsaved.confirmNavigation(() => router.push('/dashboard/cms/blog')) }} className="inline-flex items-center gap-2 text-sm font-semibold text-primary hover:text-primary/80">
          <ArrowLeft size={16} />
          Back to Blog
        </Link>
        <div className="flex items-center gap-3">
          {mode === 'edit' ? (
            <button
              type="button"
              onClick={() => setDeleteConfirmOpen(true)}
              disabled={isDeleting || isSaving}
              className="inline-flex items-center gap-2 rounded-lg border border-red-200 px-5 py-3 text-sm font-semibold text-red-600 transition-colors hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-60"
            >
              <Trash2 size={16} />
              {isDeleting ? 'Deleting...' : 'Delete Blog'}
            </button>
          ) : null}
          <CmsSaveAction onClick={() => setConfirmOpen(true)} isSaving={isSaving} disabled={!isDirty || uploading} position="inline" />
        </div>
      </div>

      <div className="mb-10">
        <h1 className="font-jakarta text-3xl font-semibold text-foreground">{mode === 'create' ? 'Create Blog' : 'Edit Blog'}</h1>
        <p className="mt-1 text-sm text-muted-foreground">Write the article, upload images, and control whether it is live. The public URL is created automatically from the title.</p>
        <p className="mt-2 text-xs text-muted-foreground">{status}</p>
      </div>

      <div className="grid max-w-6xl grid-cols-1 gap-6 lg:grid-cols-2">
        <div className="space-y-4 rounded-lg border border-border bg-white p-6 shadow-xs">
          {mode === 'edit' && form.slug ? (
            <div>
              <label className="mb-2 block text-sm font-semibold text-foreground">Public URL</label>
              <div className="rounded-lg border border-border bg-secondary/30 px-3 py-2 text-sm text-muted-foreground">
                {formatBlogUrl(form.slug)}
              </div>
            </div>
          ) : null}
          <div>
            <label className="mb-2 block text-sm font-semibold text-foreground">Article Title</label>
            <input placeholder="Title shown in admin, SEO, and fallbacks" value={form.title} onChange={(e) => setForm((prev) => ({ ...prev, title: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="mb-2 block text-sm font-semibold text-foreground">Display Title</label>
            <textarea placeholder="Optional. Leave blank to use the Article Title. Advanced: supports simple HTML for line breaks or emphasis." value={form.title_html} onChange={(e) => setForm((prev) => ({ ...prev, title_html: e.target.value }))} rows={3} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" />
            <p className="mt-1 text-xs text-muted-foreground">Optional styled title for the website cards and article hero.</p>
          </div>
          <div>
            <label className="mb-2 block text-sm font-semibold text-foreground">Blog Card Title</label>
            <input placeholder="Optional. Falls back to Article Title" value={form.card_title} onChange={(e) => setForm((prev) => ({ ...prev, card_title: e.target.value }))} maxLength={160} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" />
            <p className="mt-1 text-xs text-muted-foreground">Shown only on blog listing and homepage cards.</p>
          </div>
          <div>
            <label className="mb-2 block text-sm font-semibold text-foreground">Short Intro</label>
            <textarea placeholder="Brief summary shown near the top of the article" value={form.subtitle} onChange={(e) => setForm((prev) => ({ ...prev, subtitle: e.target.value }))} rows={4} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" />
          </div>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <div>
              <label className="mb-2 block text-sm font-semibold text-foreground">Editorial Topic</label>
              <input placeholder="example: Buying Guide" value={form.category} onChange={(e) => setForm((prev) => ({ ...prev, category: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" />
              <p className="mt-1 text-xs text-muted-foreground">Optional editorial label shown on article cards.</p>
            </div>
            <div>
              <label className="mb-2 block text-sm font-semibold text-foreground">Master Catalog Category</label>
              <select value={form.catalog_category_id} onChange={(e) => setForm((prev) => ({ ...prev, catalog_category_id: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm">
                <option value="">Not associated</option>
                {categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}
              </select>
              <p className="mt-1 text-xs text-muted-foreground">Controls the category filter on the public blog page.</p>
            </div>
            <div><label className="mb-2 block text-sm font-semibold text-foreground">Written By</label><input placeholder="Author name" value={form.author} onChange={(e) => setForm((prev) => ({ ...prev, author: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" /></div>
            <div><label className="mb-2 block text-sm font-semibold text-foreground">Publish Date Text</label><input placeholder="example: Apr 22, 2026" value={form.date_label} onChange={(e) => setForm((prev) => ({ ...prev, date_label: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" /></div>
            <div><label className="mb-2 block text-sm font-semibold text-foreground">Reading Time</label><input placeholder="example: 5 min read" value={form.read_time} onChange={(e) => setForm((prev) => ({ ...prev, read_time: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" /></div>
