                          accept="image/*"
                          className="hidden"
                          disabled={uploading}
                          onChange={(e: ChangeEvent<HTMLInputElement>) => {
                            const file = e.target.files?.[0]
                            if (file) void uploadBlockImage(block.clientId, file)
                          }}
