              )}
            </div>
          ))}
        </div>
      </div>

      <ConfirmDialog
        isOpen={confirmOpen}
        title={mode === 'create' ? 'Create education post?' : 'Save education post?'}
        description="This will update the education content on the live site."
        confirmText="Save"
