async function seed() {
  const item = randomUUID(), section = randomUUID(), link = randomUUID(), featured = randomUUID()
  await db.query(`insert into navbar_items(id,label,slug,item_type,linked_category_id,display_order,status) values($1,'Fine Jewellery','fine-jewellery','mega_menu',$2,1,'active')`, [item, category])
  await db.query(`insert into navbar_sections(id,navbar_item_id,title,section_type,source_subcategory_id,column_number,display_order,status) values($1,$2,'Shop','category_list',$3,1,1,'active')`, [section, item, subcategory])
  await db.query(`insert into navbar_section_links(id,section_id,label,url,display_order,status) values($1,$2,'All','/all',1,'active')`, [link, section])
  await db.query(`insert into navbar_section_source_items(section_id,source_kind,source_item_id,sort_order,is_active) values($1,'subcategory_option',$2,1,true)`, [section, option])
  await db.query(`insert into navbar_featured_cards(id,navbar_item_id,image_alt,enabled) values($1,$2,'Fine',false)`, [featured, item])
  const sourceId = String((await db.query('select id from navbar_section_source_items')).rows[0].id)
  return { item, section, link, featured, sourceId }
}

function payload(ids, label = 'Fine Jewellery') {
  return {
    items: [{ key: ids.item, id: ids.item, label, slug: 'fine-jewellery', item_type: 'mega_menu', linked_category_id: category, direct_link_url: null, display_order: 1, status: 'active' }],
    sections: [{ key: `${ids.item}:${ids.section}`, id: ids.section, item_key: ids.item, title: 'Shop', icon_svg_path: null, section_type: 'category_list', source_subcategory_id: subcategory, source_category_slug: null, enable_category_link: false, linked_category_id: null, column_number: 1, show_as_filter: false, display_order: 1, status: 'active' }],
    links: [{ id: ids.link, section_key: `${ids.item}:${ids.section}`, label: 'All', url: '/all', display_order: 1, status: 'active' }],
    sources: [{ id: ids.sourceId, section_key: `${ids.item}:${ids.section}`, source_kind: 'subcategory_option', source_item_id: option, sort_order: 1, is_active: true }],
    featured: [{ id: ids.featured, item_key: ids.item, image_path: null, image_alt: 'Fine', button_label: null, button_url: null, enabled: false }],
