test('rejects stale revisions and returns the same result for an idempotent retry', async () => {
  const ids = await seed(), before = await snapshot(), data = payload(ids, 'First'), requestId = randomUUID()
  const first = await save(before, data, undefined, requestId)
  const retry = await save(before, data, undefined, requestId)
  assert.deepEqual(retry, first)
  await assert.rejects(save(before, payload(ids, 'Stale')), /changed since you opened it/)
})

test('invalid catalog references and late uniqueness failures roll back all changes', async () => {
  const ids = await seed(), before = await snapshot(), data = payload(ids, 'Should Roll Back')
  data.sources[0].source_item_id = randomUUID()
  await assert.rejects(save(before, data), /missing catalog data/)
  assert.equal((await snapshot()).items[0].label, 'Fine Jewellery')

  const second = randomUUID()
  data.sources[0].source_item_id = option
  data.items.push({ ...data.items[0], key: second, id: null, label: 'Duplicate', linked_category_id: null })
  await assert.rejects(save(before, data), /unique|duplicate/i)
  assert.equal((await snapshot()).items[0].label, 'Fine Jewellery')
  assert.equal((await snapshot()).items.length, 1)
})

test('non-admin callers are denied', async () => {
  const ids = await seed(), before = await snapshot(), data = payload(ids)
