"""Compare already saved Phase A live catalog evidence; no database connection."""
import csv
import json
import re
from collections import Counter
from pathlib import Path

out = Path(__file__).resolve().parents[1] / 'docs/aws-phase-a'
live = json.loads((out / 'rds-targeted-live-2026-10-14.json').read_text(encoding='utf-8-sig'))
original = json.loads((out / 'rds-admin-definition-metadata.json').read_text(encoding='utf-8-sig'))
security = json.loads((out / 'rds-admin-security-metadata.json').read_text(encoding='utf-8-sig'))
definitions = {(f['name'], f['arguments']): f for f in original['functions']}
routine_security = {(f['name'], f['arguments']): f for f in security['functions']}
relations = {t['name']: t for t in original['tables']}
policies = {(p['tablename'], p['policyname']): p for p in original['policies']}
definition_drift, routine_drift, relation_drift, policy_drift = [], [], [], []
for routine in live['reviewed_routines']:
    key = (routine['name'], routine['arguments'])
    if key not in definitions or routine['definition'] != definitions[key]['definition']:
        definition_drift.append(routine['name'])
    if key not in routine_security or any(routine.get(field) != routine_security[key].get(field)
        for field in ['returns', 'owner', 'security_definer', 'settings', 'acl']):
        routine_drift.append(routine['name'])
for relation in live['relevant_relations']:
    if relation['name'] not in relations or any(relation.get(field) != relations[relation['name']].get(field)
        for field in ['owner', 'rls', 'force_rls', 'acl']):
        relation_drift.append(relation['name'])
for policy in live['relevant_policies']:
    assert isinstance(policy['roles'], list), 'Reader must cast pg_policies.roles to text[]'
    key = (policy['tablename'], policy['policyname'])
    if policy != policies.get(key):
        policy_drift.append(key)
legacy = [policy for policy in live['relevant_policies'] if 'public' in policy['roles']
          and re.search(r'auth\.|is_admin\s*\(', (policy.get('qual') or '') + ' ' + (policy.get('with_check') or ''), re.I)]
roles = sorted({row['rolname'] for row in live['actor_execution']})
summary = {
    'checked_at': live['checked_at'], 'routine_definition_drift': definition_drift,
    'routine_security_drift': routine_drift, 'relation_security_drift': relation_drift,
    'policy_drift': policy_drift, 'reviewed_routine_count': len(live['reviewed_routines']),
    'live_relevant_relation_count': len(live['relevant_relations']),
    'live_relevant_policy_count': len(live['relevant_policies']), 'schema_access': live['schema_access'],
    'public_legacy_policies': legacy,
    'effective_actor_execute_by_role': {role: {
        'true': sum(row['rolname'] == role and row['can_execute'] for row in live['actor_execution']),
        'false': sum(row['rolname'] == role and not row['can_execute'] for row in live['actor_execution'])}
        for role in roles},
    'admin_runtime_present': any(row['rolname'] == 'hod_admin_app' for row in live['roles']),
    'sequence_dependency_types': dict(Counter(row['dependency_type'] for row in live['sequences'])),
}
(out / 'rds-targeted-live-review.json').write_text(json.dumps(summary, indent=2) + '\n', encoding='utf-8')
with (out / 'rds-sequence-review.csv').open('w', newline='', encoding='utf-8') as handle:
    writer = csv.DictWriter(handle, fieldnames=['relation', 'column_name', 'sequence_name', 'dependency_type', 'owner', 'acl'])
    writer.writeheader()
    writer.writerows(live['sequences'])
print(json.dumps({key: value for key, value in summary.items() if key != 'public_legacy_policies'}, indent=2))

// Phase A only: catalog reads, verified TLS, no business routines or writes.
// Supply an existing reader env file and installed pg manifest; never copy secrets.
import fs from 'node:fs'
import path from 'node:path'
import tls from 'node:tls'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const folder = path.join(root, 'docs/aws-phase-a')
const args = process.argv.slice(2)
const option = name => { const index = args.indexOf(name); return index >= 0 ? args[index + 1] : undefined }
let client
let auditStage = 'connect'
try {
  const envFile = option('--env-file')
  const pgManifest = option('--pg-manifest')
  if (!envFile || !pgManifest) throw new Error('Supply --env-file and --pg-manifest for an existing metadata reader.')
  const env = {}
  for (const line of fs.readFileSync(path.resolve(root, envFile), 'utf8').split(/\r?\n/)) {
    const match = line.match(/^\s*([A-Z][A-Z0-9_]*)\s*=\s*(.*)$/)
    if (!match) continue
    let value = match[2].trim()
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) value = value.slice(1, -1)
    env[match[1]] = value
  }
  const databaseUrl = new URL(env.DATABASE_URL)
  if (!['postgres:', 'postgresql:'].includes(databaseUrl.protocol)
    || !['localhost', '127.0.0.1'].includes(databaseUrl.hostname)
    || databaseUrl.port !== '15432' || databaseUrl.pathname !== '/hod_staging'
    || !['hod_app', 'hod_dev_migration'].includes(decodeURIComponent(databaseUrl.username))) {
    throw new Error('Reader must target the intended staging database through the existing local tunnel.')
  }
  if (!env.DB_CA_CERT_PATH || env.DB_TLS_EXPECTED_HOST !== 'database-1.cqngaqgio3hj.us-east-1.rds.amazonaws.com') {
    throw new Error('Require the configured RDS CA and expected hostname.')
  }
  if ([...databaseUrl.searchParams.keys()].some(name => /^ssl/i.test(name))) {
    throw new Error('URL SSL options must not override the explicitly verified TLS configuration.')
  }
  const caPath = path.isAbsolute(env.DB_CA_CERT_PATH) ? env.DB_CA_CERT_PATH
    : path.resolve(path.dirname(path.resolve(root, envFile)), env.DB_CA_CERT_PATH)
  const { Client } = createRequire(path.resolve(root, pgManifest))('pg')
  client = new Client({
    host: '127.0.0.1', port: 15432, database: 'hod_staging',
    user: decodeURIComponent(databaseUrl.username), password: decodeURIComponent(databaseUrl.password),
    application_name: 'hod-admin-phase-a-readonly', connectionTimeoutMillis: 10000,
    options: '-c default_transaction_read_only=on -c statement_timeout=15000 -c lock_timeout=5000',
    ssl: { ca: fs.readFileSync(caPath, 'utf8'), rejectUnauthorized: true,
      servername: env.DB_TLS_EXPECTED_HOST,
      checkServerIdentity: (_host, cert) => tls.checkServerIdentity(env.DB_TLS_EXPECTED_HOST, cert) },
  })
  await client.connect()
  const stream = client.connection.stream
  if (!stream.encrypted || !stream.authorized) throw new Error('Verified encrypted TLS is required.')
  const prepared = fs.readFileSync(path.join(folder, 'rds-targeted-boundaries.sql'), 'utf8')
  const statements = prepared.replace(/^\s*--.*$/gm, '').split(';').map(value => value.trim()).filter(Boolean)
  const stageNames = ['begin', 'connection', 'helpers', 'actor_execution', 'triggers', 'defaults', 'identity_relations', 'foreign_keys', 'commit']
  if (statements.length !== stageNames.length) throw new Error('Unexpected targeted SQL structure.')
  const results = []
  for (const [index, statement] of statements.entries()) {
    auditStage = stageNames[index]
    results.push(await client.query(statement))
  }
  const selects = results.filter(result => result.command === 'SELECT')
  const names = ['connection', 'helpers', 'actor_execution', 'triggers', 'defaults', 'identity_relations', 'foreign_keys']
  if (selects.length !== names.length) throw new Error('Unexpected targeted-check result shape.')
  const sections = Object.fromEntries(names.map((name, index) => [name, selects[index].rows]))
  if (sections.connection[0]?.database !== 'hod_staging') throw new Error('Unexpected database identity.')
  await client.query('BEGIN READ ONLY')
  try {
    auditStage = 'session_evidence'
    sections.session = (await client.query("SELECT current_database() AS database, current_user AS reader, current_setting('transaction_read_only') AS transaction_read_only, current_setting('default_transaction_read_only') AS default_transaction_read_only")).rows
    sections.tls = (await client.query('SELECT ssl, version, cipher, bits FROM pg_stat_ssl WHERE pid = pg_backend_pid()')).rows
    sections.roles = (await client.query("SELECT rolname, rolcanlogin, rolsuper, rolbypassrls, rolinherit, rolcreaterole, rolcreatedb, rolreplication FROM pg_roles WHERE rolname IN ('hod_app','hod_admin_app','hod_dev_migration','hod_migration') ORDER BY rolname")).rows
    const original = JSON.parse(fs.readFileSync(path.join(folder, 'rds-admin-security-metadata.json'), 'utf8').replace(/^\uFEFF/, ''))
    auditStage = 'routine_freshness'
    sections.reviewed_routines = (await client.query(`SELECT p.proname AS name,
      pg_get_function_identity_arguments(p.oid) AS arguments, pg_get_function_result(p.oid) AS returns,
      pg_get_userbyid(p.proowner) AS owner, p.prosecdef AS security_definer, p.proconfig AS settings,
      COALESCE(p.proacl,acldefault('f',p.proowner))::text AS acl, pg_get_functiondef(p.oid) AS definition
      FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
      WHERE n.nspname='public' AND p.prokind='f' AND p.proname=ANY($1::text[]) ORDER BY p.proname,arguments`,
      [original.functions.map(routine => routine.name)])).rows
    const triggerNames = [...new Set(sections.triggers.map(row => row.routine))]
    auditStage = 'trigger_definitions'
    sections.trigger_routines = (await client.query(`SELECT p.oid::regprocedure::text AS routine,
      pg_get_userbyid(p.proowner) AS owner,p.prosecdef AS security_definer,p.proconfig AS settings,
      COALESCE(p.proacl,acldefault('f',p.proowner))::text AS acl,pg_get_functiondef(p.oid) AS definition
      FROM pg_proc p WHERE p.prokind='f' AND p.oid IN (SELECT to_regprocedure(value) FROM unnest($1::text[]) AS value)
      ORDER BY routine`, [triggerNames])).rows
    auditStage = 'sequence_dependencies'
    sections.sequences = (await client.query(`SELECT tbl.relname AS relation,a.attname AS column_name,
      seq.relname AS sequence_name,dep.deptype AS dependency_type,
      pg_get_userbyid(seq.relowner) AS owner,
      COALESCE(seq.relacl,acldefault('s',seq.relowner))::text AS acl
      FROM pg_class seq JOIN pg_namespace ns ON ns.oid=seq.relnamespace
      JOIN pg_depend dep ON dep.objid=seq.oid AND dep.classid='pg_class'::regclass
        AND dep.refclassid='pg_class'::regclass AND dep.deptype IN ('a','i')
      JOIN pg_class tbl ON tbl.oid=dep.refobjid
      JOIN pg_attribute a ON a.attrelid=tbl.oid AND a.attnum=dep.refobjsubid
      WHERE ns.nspname='public' AND seq.relkind='S' ORDER BY relation,column_name`)).rows
    const boundaries = JSON.parse(fs.readFileSync(path.join(folder, 'database-boundary-review.json'), 'utf8'))
    const originalDefinitions = JSON.parse(fs.readFileSync(path.join(folder, 'rds-admin-definition-metadata.json'), 'utf8'))
    const knownRelations = new Set(originalDefinitions.tables.map(row => row.name))
    const relevantNames = new Set(['profiles', 'orders', 'order_items', 'order_love_letters', 'order_status_history', 'inventory_reservations'])
    for (const routine of [...sections.reviewed_routines, ...sections.trigger_routines]) {
      for (const match of routine.definition.matchAll(/\bpublic\.([a-z_][a-z_0-9]*)/gi)) {
        if (knownRelations.has(match[1])) relevantNames.add(match[1])
      }
    }
    for (const routine of boundaries.routines) for (const name of routine.reviewed_dynamic_tables) relevantNames.add(name)
    auditStage = 'relevant_relation_security'
    sections.relevant_relations = (await client.query(`SELECT c.relname AS name,c.relkind AS kind,
      pg_get_userbyid(c.relowner) AS owner,c.relrowsecurity AS rls,c.relforcerowsecurity AS force_rls,
      COALESCE(c.relacl,acldefault('r',c.relowner))::text AS acl
      FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m') AND c.relname=ANY($1::text[]) ORDER BY name`,
      [[...relevantNames]])).rows
    sections.relevant_policies = (await client.query('SELECT schemaname,tablename,policyname,permissive,roles::text[] AS roles,cmd,qual,with_check FROM pg_policies WHERE schemaname=$1 AND tablename=ANY($2::text[]) ORDER BY tablename,policyname',
      ['public', [...relevantNames]])).rows
    auditStage = 'reader_schema_access'
    sections.schema_access = (await client.query("SELECT nspname,has_schema_privilege(current_user,oid,'USAGE') AS reader_has_usage FROM pg_namespace WHERE nspname IN ('public','auth') ORDER BY nspname")).rows
    await client.query('COMMIT')
  } catch (error) { await client.query('ROLLBACK'); throw error }
  const evidence = { checked_at: new Date().toISOString(), scope: 'catalog metadata only; no business routine execution or data mutation',
    verified_tls: { encrypted: true, authorized: true, expected_hostname_verified: true }, ...sections }
  const date = evidence.checked_at.slice(0, 10)
  const output = path.join(folder, `rds-targeted-live-${date}.json`)
  fs.writeFileSync(output, JSON.stringify(evidence, null, 2) + '\n')
  console.log(JSON.stringify({ output: path.relative(root, output), database: sections.connection[0].database,
    reader: sections.connection[0].reader, tls_verified: true, readonly: sections.session[0],
    counts: Object.fromEntries(Object.entries(sections).map(([name, rows]) => [name, rows.length])) }, null, 2))
} catch (error) {
  // Avoid logging connection strings, environment values or driver error details.
  console.error(JSON.stringify({ status: 'failed', audit_stage: auditStage, code: error.code ?? 'AUDIT_CHECK_FAILED', name: error.name,
    hint: 'Check the existing tunnel/reader/TLS configuration. No credentials or grants were changed.' }))
  process.exitCode = 1
} finally {
  if (client) await client.end()
}

// Source-only reconciliation. Never loads env values or contacts providers.
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { fileURLToPath } from 'node:url'
import ts from 'typescript'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const out = path.join(root, 'docs/aws-phase-a')
const legacy = /supabase|@supabase|postgrest|PGRST|\/rest\/v1|\/auth\/v1|\/storage\/v1|cloudflare|\bR2\b/i
const records = []
function walk(folder) {
  return fs.readdirSync(folder, { withFileTypes: true }).flatMap(entry => {
    const target = path.join(folder, entry.name)
    return entry.isDirectory() ? walk(target) : /\.tsx?$/.test(entry.name) ? [target] : []
  })
}
for (const file of ['app', 'components', 'lib'].flatMap(folder => walk(path.join(root, folder))).sort()) {
  const source = fs.readFileSync(file, 'utf8')
  const rel = path.relative(root, file).replaceAll('\\', '/')
  const ast = ts.createSourceFile(rel, source, ts.ScriptTarget.Latest, true)
  const evidence = []
  const imports = []
  const mark = (node, kind, value) => evidence.push({ line: ast.getLineAndCharacterOfPosition(node.getStart(ast)).line + 1, kind, value })
  function visit(node) {
    if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier)) {
      const specifier = node.moduleSpecifier.text
      imports.push(specifier)
      if (/supabase|\/r2$/.test(specifier)) mark(node, 'provider-import', specifier)
    }
    if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression)) {
      const method = node.expression.name.text
      const receiver = node.expression.expression.getText(ast)
      // Array.from and Buffer.from are not database accesses.
      if (['from', 'rpc', 'channel', 'removeChannel'].includes(method) && !['Array', 'Buffer', 'Uint8Array'].includes(receiver)) {
        mark(node, 'transport-call', `${receiver}.${method}(${node.arguments[0]?.getText(ast) ?? ''})`)
      }
      if (/\.(?:auth|storage)(?:\.|$)/.test(receiver)) mark(node, 'auth-or-storage-call', node.expression.getText(ast))
    }
    if (ts.isPropertyAccessExpression(node) && node.expression.getText(ast) === 'process.env' && /SUPABASE|CLOUDFLARE/.test(node.name.text)) {
      mark(node, 'provider-env', node.name.text)
    }
    if (ts.isStringLiteral(node) && /PGRST\d+|\/rest\/v1|\/auth\/v1|\/storage\/v1/.test(node.text)) mark(node, 'transport-contract', node.text)
    ts.forEachChild(node, visit)
  }
  visit(ast)
  const candidate = legacy.test(source)
  let classification = evidence.length ? 'required-source-edit' : 'no-direct-edit-evidence'
  let reason = evidence.length ? [...new Set(evidence.map(row => row.kind))].join('; ') : ''
  // Explicitly reviewed exceptions; keep historical URL consumers until Phase C parity.
  if (rel === 'app/dashboard/customers/customers-client.tsx') {
    classification = 'conditional-consumer-edit'
    reason = 'Provider label and confirmed/pending semantics; change only with agreed customer read model.'
  } else if (rel === 'components/catalog-image-preview.tsx') {
    classification = 'phase-c-compatibility-edit'
    reason = 'Relative paths resolve to legacy storage; preserve preview rollback until CDN parity.'
  } else if (!evidence.length && candidate) {
    classification = 'mention-review'
    reason = 'No parsed provider operation; inspect mention before counting as an edit.'
  }
  const feature = /\/(products|collection-products|inventory)\//.test(rel) || /lib\/product-|lib\/inventory-|bulk-price|product-form/.test(rel) ? 'B3-products-inventory'
    : /catalog|navbar/.test(rel) ? 'B4-catalog-navbar'
    : /uploads|media|\/r2\.ts|upload|image-preview/.test(rel) ? 'C-media'
    : /cms|bespoke|blog|education|couples/.test(rel) && !/cms-auth/.test(rel) ? 'B5-cms-bespoke'
    : /auth|admin-server|supabase|\/login\/|admin-gate/.test(rel) ? 'B1-identity-session'
    : 'B6-operations-read-model'
  records.push({ path: rel, candidate, classification, feature, reason, imports, evidence,
    sha256: crypto.createHash('sha256').update(source).digest('hex') })
}
// Record indirect consumers separately: a changed provider-free loader/command contract
// can require edits, but an import alone is not proof of a required source change.
const byPath = new Map(records.map(row => [row.path.replace(/\.tsx?$/, ''), row]))
for (const row of records) {
  row.migration_consumers = row.imports.flatMap(specifier => {
    const target = specifier.startsWith('@/') ? specifier.slice(2)
      : specifier.startsWith('.') ? path.posix.normalize(path.posix.join(path.posix.dirname(row.path), specifier)) : ''
    const dependency = byPath.get(target)
    return dependency && dependency.classification !== 'no-direct-edit-evidence' ? [dependency.path] : []
  })
  if (row.classification === 'no-direct-edit-evidence' && row.migration_consumers.length) {
    row.classification = 'consumer-contract-review'
    row.reason = 'Imports migration dependency; retain source if replacement preserves its contract.'
  }
}
const csv = values => values.map(value => `"${String(value).replaceAll('"', '""')}"`).join(',')
fs.writeFileSync(path.join(out, 'runtime-reconciliation.csv'), [csv(['path', 'legacy_candidate', 'classification', 'slice', 'reason', 'dependency_consumers', 'line_evidence', 'sha256']),
  ...records.filter(row => row.candidate || row.evidence.length || row.migration_consumers.length).map(row => csv([row.path, row.candidate, row.classification, row.feature, row.reason,
    row.migration_consumers.join('; '), row.evidence.map(item => `${item.line}:${item.kind}:${item.value}`).join('; '), row.sha256]))].join('\n') + '\n')
const count = predicate => records.filter(predicate).length
const summary = {
  source_files: records.length,
  legacy_candidates: count(row => row.candidate),
  candidate_groups: Object.fromEntries(['app/api/', 'app/dashboard/', 'components/', 'lib/'].map(prefix => [prefix, count(row => row.candidate && row.path.startsWith(prefix))])),
  candidate_pages: count(row => row.candidate && row.path.startsWith('app/') && !row.path.startsWith('app/api/')),
  classifications: Object.fromEntries([...new Set(records.map(row => row.classification))].map(value => [value, count(row => row.classification === value)])),
  direct_edits_without_legacy_keyword: count(row => !row.candidate && row.classification === 'required-source-edit'),
  limitation: 'Parsed source evidence plus reviewed exceptions; not a certified effort count, full runtime import graph, or semantic API parity sign-off.',
}
fs.writeFileSync(path.join(out, 'runtime-reconciliation.json'), JSON.stringify({ summary, files: records }, null, 2) + '\n')
console.log(JSON.stringify(summary, null, 2))

'use client'

import { useState } from 'react'
import { ArrowDown, ArrowUp, GripVertical, Plus, Trash2 } from 'lucide-react'
import { PillToggle } from './ProductFormControls'
import type { ProductCustomDropdown } from '@/lib/product-custom-dropdowns'

const inputClass = 'h-10 w-full rounded-md border border-border bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring'
const uuid = () => crypto.randomUUID()

export function ProductCustomDropdownEditor({ enabled, onEnabledChange, groups, onChange }: { enabled: boolean; onEnabledChange: (value: boolean) => void; groups: ProductCustomDropdown[]; onChange: (groups: ProductCustomDropdown[]) => void }) {
  const [draggingOption, setDraggingOption] = useState<{ groupIndex: number; optionIndex: number } | null>(null)
  const addGroup = () => onChange([...groups, { id: uuid(), name: '', label: '', is_enabled: true, is_required: false, display_order: groups.length, options: [{ id: uuid(), label: '', value: '', is_enabled: true, display_order: 0 }] }])
  const updateGroup = (index: number, patch: Partial<ProductCustomDropdown>) => onChange(groups.map((group, i) => i === index ? { ...group, ...patch } : group))
  const move = (index: number, offset: number) => { const next = [...groups]; const target = index + offset; if (target < 0 || target >= next.length) return; [next[index], next[target]] = [next[target], next[index]]; onChange(next) }
  const moveOption = (groupIndex: number, optionIndex: number, targetIndex: number) => {
    const options = [...groups[groupIndex].options]
    if (targetIndex < 0 || targetIndex >= options.length || targetIndex === optionIndex) return
    const [option] = options.splice(optionIndex, 1)
    options.splice(targetIndex, 0, option)
    updateGroup(groupIndex, { options })
  }

  return <div className="rounded-lg border border-border bg-secondary/10 p-4">
    <div className="flex flex-wrap items-start justify-between gap-4">
      <div><p className="text-sm font-semibold">Custom Product Dropdowns</p><p className="mt-2 text-xs text-muted-foreground">Create product-specific choices shown as dropdowns on the product page.</p></div>
      <PillToggle value={enabled} onChange={onEnabledChange} onLabel="Enabled" offLabel="Disabled" />
    </div>
    {enabled ? <div className="mt-5 space-y-4">
      {groups.length ? groups.map((group, groupIndex) => <div key={group.id} className="rounded-md border border-border bg-card p-4">
        <div className="mb-4 flex items-center justify-between gap-3"><p className="text-sm font-semibold">Dropdown {groupIndex + 1}</p><div className="flex gap-1">
          <button type="button" aria-label="Move up" onClick={() => move(groupIndex, -1)} disabled={!groupIndex} className="rounded border p-2 disabled:opacity-30"><ArrowUp size={14}/></button>
          <button type="button" aria-label="Move down" onClick={() => move(groupIndex, 1)} disabled={groupIndex === groups.length - 1} className="rounded border p-2 disabled:opacity-30"><ArrowDown size={14}/></button>
          <button type="button" aria-label="Remove dropdown" onClick={() => onChange(groups.filter((_, i) => i !== groupIndex))} className="rounded border p-2 text-destructive"><Trash2 size={14}/></button>
        </div></div>
        <label className="block text-xs font-medium">Customer label<input className={`${inputClass} mt-1`} value={group.label} onChange={(e) => updateGroup(groupIndex, { label: e.target.value })} placeholder="e.g. Select chain style" /><span className="mt-1.5 block font-normal text-muted-foreground">The question customers will see on the product page.</span></label>
        <div className="mt-3 flex flex-wrap gap-5"><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={group.is_enabled} onChange={(e) => updateGroup(groupIndex, { is_enabled: e.target.checked })}/> Enabled</label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={group.is_required} onChange={(e) => updateGroup(groupIndex, { is_required: e.target.checked })}/> Required</label></div>
        <div className="mt-4 space-y-3">
          <div><p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Customer options</p><p className="mt-1 text-xs text-muted-foreground">Add the answers customers can choose from.</p></div>
          <div className="flex flex-wrap items-stretch gap-2">
            {group.options.map((option, optionIndex) => <div
              key={option.id}
              onDragOver={(event) => { if (draggingOption?.groupIndex === groupIndex) event.preventDefault() }}
              onDrop={(event) => { event.preventDefault(); if (draggingOption?.groupIndex === groupIndex) moveOption(groupIndex, draggingOption.optionIndex, optionIndex); setDraggingOption(null) }}
              className={`flex min-w-0 basis-full items-center gap-1.5 rounded-xl border bg-secondary/30 p-1.5 shadow-sm transition-all sm:basis-auto ${draggingOption?.groupIndex === groupIndex && draggingOption.optionIndex === optionIndex ? 'border-ring opacity-50 ring-2 ring-ring' : option.is_enabled ? 'border-border hover:border-foreground/25' : 'border-dashed border-border/70 opacity-60'}`}
            >
              <button
                type="button"
                draggable
                aria-label={`Reorder option ${optionIndex + 1}. Use up and down arrow keys, or drag.`}
                aria-describedby={`option-reorder-instructions-${group.id}`}
                className="inline-flex h-9 w-7 shrink-0 cursor-grab touch-none items-center justify-center rounded-lg text-muted-foreground hover:bg-background hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing"
                onDragStart={(event) => { event.dataTransfer.effectAllowed = 'move'; event.dataTransfer.setData('text/plain', option.id); setDraggingOption({ groupIndex, optionIndex }) }}
                onDragEnd={() => setDraggingOption(null)}
                onKeyDown={(event) => {
                  if (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') return
                  event.preventDefault()
                  moveOption(groupIndex, optionIndex, optionIndex + (event.key === 'ArrowUp' ? -1 : 1))
                }}
              ><GripVertical size={16}/></button>
              {optionIndex === 0 ? <span id={`option-reorder-instructions-${group.id}`} className="sr-only">Drag to reorder. When using a keyboard, press the up or down arrow key to move this option.</span> : null}
              <input aria-label={`Customer option ${optionIndex + 1} label`} className="h-9 min-w-0 flex-1 rounded-lg border-0 bg-background px-3 text-sm font-medium text-foreground outline-none ring-1 ring-inset ring-border placeholder:font-normal placeholder:text-muted-foreground focus:ring-2 focus:ring-ring sm:w-44" value={option.label} onChange={(e) => updateGroup(groupIndex, { options: group.options.map((row, i) => i === optionIndex ? { ...row, label: e.target.value } : row) })} placeholder="Option label"/>
              <button
                type="button"
                role="switch"
                aria-checked={option.is_enabled}
                aria-label={`Enable option ${optionIndex + 1}`}
                className={`relative inline-flex h-5 w-9 shrink-0 items-center rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ${option.is_enabled ? 'bg-primary' : 'bg-muted-foreground/35'}`}
                onClick={() => updateGroup(groupIndex, { options: group.options.map((row, i) => i === optionIndex ? { ...row, is_enabled: !row.is_enabled } : row) })}
              ><span aria-hidden="true" className={`block h-3.5 w-3.5 rounded-full bg-background shadow-sm transition-transform ${option.is_enabled ? 'translate-x-[18px]' : 'translate-x-[3px]'}`}/></button>
              <div className="flex border-l border-border/70 pl-1.5">
                <button type="button" aria-label={`Remove option ${optionIndex + 1}`} className="inline-flex h-9 w-9 items-center justify-center rounded-lg text-muted-foreground hover:bg-destructive/10 hover:text-destructive focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" onClick={() => updateGroup(groupIndex, { options: group.options.filter((_, i) => i !== optionIndex) })}><Trash2 size={14}/></button>
              </div>
            </div>)}
            <button type="button" className="inline-flex min-h-12 basis-full items-center justify-center gap-2 rounded-xl border border-dashed border-border bg-background px-4 py-2 text-sm font-medium text-muted-foreground transition-colors hover:border-foreground/30 hover:bg-secondary/30 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring sm:basis-auto" onClick={() => updateGroup(groupIndex, { options: [...group.options, { id: uuid(), label: '', value: '', is_enabled: true, display_order: group.options.length }] })}><Plus size={14}/> Add option</button>
          </div>
        </div>
      </div>) : <div className="rounded-md border border-dashed p-5 text-sm text-muted-foreground">No dropdowns yet. Add one to create a customer-selectable product option.</div>}
      <button type="button" onClick={addGroup} className="inline-flex items-center gap-2 rounded-md border border-border bg-background px-4 py-2 text-sm font-semibold"><Plus size={15}/> Add dropdown</button>
    </div> : null}
  </div>
}

'use client'

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
