export function VideoLibraryDialog({ open, onClose, onSelect }: {
  open: boolean
  onClose: () => void
  onSelect: (video: VideoAsset) => void
}) {
  const [items, setItems] = useState<VideoAsset[]>([])
  const [query, setQuery] = useState('')
  const [loading, setLoading] = useState(false)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState('')
  const loadVersion = useRef(0)

  const loadLibrary = async (forceRefresh = false) => {
    const version = ++loadVersion.current
    if (forceRefresh) setRefreshing(true)
    else setLoading(true)
    setError('')
    try { const next = await fetchVideoLibrary(forceRefresh); if (version === loadVersion.current) setItems(next) }
    catch (loadError) { if (version === loadVersion.current) setError(loadError instanceof Error ? loadError.message : 'Unable to load videos.') }
    finally { if (version === loadVersion.current) { setLoading(false); setRefreshing(false) } }
  }

  useEffect(() => {
    if (!open) return
    const version = ++loadVersion.current
    let active = true
    void Promise.resolve().then(async () => {
      if (!active) return
      setLoading(true)
      setError('')
      try { const next = await fetchVideoLibrary(false); if (active && version === loadVersion.current) setItems(next) }
      catch (loadError) { if (active && version === loadVersion.current) setError(loadError instanceof Error ? loadError.message : 'Unable to load videos.') }
      finally { if (active && version === loadVersion.current) { setLoading(false); setRefreshing(false) } }
    })
    return () => { active = false }
  }, [open])

  const closeDialog = () => {
    setQuery('')
    setError('')
    onClose()
  }

  useEffect(() => {
    if (!open) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return
      setQuery('')
      setError('')
      onClose()
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [onClose, open])

  const filteredItems = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase()
    if (!normalizedQuery) return items
    return items.filter((item) => `${displayName(item.key)} ${displayFolder(item.key)}`.toLowerCase().includes(normalizedQuery))
  }, [items, query])

  if (!open) return null
  return (
    <div className="fixed inset-0 z-[10020] flex items-center justify-center bg-black/55 p-4" role="dialog" aria-modal="true" aria-labelledby="video-library-title">
      <button type="button" className="absolute inset-0 cursor-default" aria-label="Close video library" onClick={closeDialog} />
      <div className="relative flex max-h-[90vh] w-full max-w-5xl flex-col overflow-hidden rounded-2xl border border-border bg-white shadow-2xl">
        <div className="flex items-start justify-between gap-4 border-b border-border px-6 py-5">
          <div><h2 id="video-library-title" className="text-xl font-bold text-foreground">Choose a video</h2><p className="mt-1 text-sm text-muted-foreground">Search the central video library by filename or folder. Selecting affects only this media slot.</p></div>
          <div className="flex items-center gap-2">
            <button type="button" disabled={refreshing} onClick={() => void loadLibrary(true)} className="inline-flex h-10 items-center gap-2 whitespace-nowrap rounded-lg border border-border px-3 text-sm font-semibold text-foreground hover:bg-secondary disabled:opacity-60"><RefreshCw size={15} className={refreshing ? 'animate-spin' : ''} />Refresh</button>
            <button type="button" onClick={closeDialog} className="inline-flex h-10 w-10 items-center justify-center rounded-full border border-border text-foreground hover:bg-secondary" aria-label="Close"><X size={18} /></button>
          </div>
        </div>
        <div className="border-b border-border px-6 py-4"><div className="relative"><Search size={17} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search videos by filename or folder" className="w-full rounded-lg border border-border bg-white py-2.5 pl-10 pr-4 text-sm outline-none focus:border-ring focus:ring-1 focus:ring-ring" /></div></div>
        <div className="min-h-[320px] flex-1 overflow-y-auto p-6">
          {loading ? <div className="flex min-h-[300px] items-center justify-center gap-3 text-sm text-muted-foreground"><Loader2 size={20} className="animate-spin" />Loading the video library...</div>
          : error ? <div className="flex min-h-[300px] flex-col items-center justify-center text-center"><p className="text-sm font-medium text-destructive">{error}</p><button type="button" onClick={() => void loadLibrary(false)} className="mt-4 rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-white">Try again</button></div>
          : filteredItems.length === 0 ? <div className="flex min-h-[300px] flex-col items-center justify-center text-center text-muted-foreground"><Film size={28} /><p className="mt-3 text-sm">No matching videos found.</p></div>
          : <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{filteredItems.map((item) => (
              <button key={item.url} type="button" onClick={() => onSelect(item)} className="group overflow-hidden rounded-xl border border-border bg-white text-left transition hover:border-[#86B8E8] hover:shadow-md">
                <div className="relative aspect-video overflow-hidden bg-[#EEF7FF]"><LazyVideoThumbnail video={item} /><span className="absolute bottom-2 left-2 rounded bg-[#0A1628]/75 px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.14em] text-white">Video</span><span className="absolute right-2 top-2 inline-flex h-8 w-8 items-center justify-center rounded-full bg-white/90 text-[#3779B5] opacity-0 shadow transition-opacity group-hover:opacity-100"><Check size={16} /></span></div>
                <div className="p-3"><p className="truncate text-sm font-semibold text-foreground" title={displayName(item.key)}>{displayName(item.key)}</p><p className="mt-1 truncate text-[11px] text-muted-foreground" title={displayFolder(item.key)}>{displayFolder(item.key)}</p><p className="mt-1 text-xs text-muted-foreground">{formatBytes(item.size)}{item.lastModified ? ` · ${new Date(item.lastModified).toLocaleDateString()}` : ''}</p></div>
              </button>
            ))}</div>}
        </div>
      </div>
    </div>
  )
}

'use client'
import { isCanonicalAwsVideoReference } from './video-reference'

export type ClientVideoAsset = { key: string; url: string; size: number; lastModified: string | null; contentType?: string; extension?: string }
let generation = 0
let cached: { namespace: string; items: ClientVideoAsset[]; at: number } | undefined
let pending: { namespace: string; promise: Promise<ClientVideoAsset[]> } | undefined
export function invalidateClientVideoLibrary() { generation++; cached = undefined; pending = undefined }
export async function readClientVideoProvider(): Promise<{ provider: 'aws' | 'legacy'; namespace: string }> {
  const response = await fetch('/api/videos/provider', { credentials: 'same-origin', cache: 'no-store' })
  const payload = await response.json().catch(() => null)
  if (!response.ok || !['aws', 'legacy'].includes(payload?.provider) || typeof payload.namespace !== 'string' || !payload.namespace) throw new Error('Video service unavailable.')
  return payload
}
async function csrf() {
  const response = await fetch('/api/auth/session', { credentials: 'same-origin', cache: 'no-store' })
  const session = await response.json().catch(() => null)
  if (!response.ok || session?.authenticated !== true || typeof session.csrfToken !== 'string' || !session.csrfToken) throw new Error('Please sign in again.')
  return session.csrfToken as string
}
export async function tryUploadAwsVideo(file: File, endpoint: string, fields: Record<string, string>): Promise<string | null> {
  if (!['/api/products/media', '/api/cms/uploads/about-hero'].includes(endpoint) || fields.kind !== 'video') throw new Error('Invalid video endpoint.')
  if ((await readClientVideoProvider()).provider === 'legacy') return null
  const form = new FormData()
  form.set('file', file)
  for (const [key, value] of Object.entries(fields)) if (key !== 'file') form.set(key, value)
  const response = await fetch(endpoint, { method: 'POST', credentials: 'same-origin', headers: { 'x-admin-csrf': await csrf(), 'x-admin-video-upload': '1' }, body: form })
  const payload = await response.json().catch(() => null)
  if (!response.ok || payload?.provider !== 's3' || !isCanonicalAwsVideoReference(payload.path) || payload.path !== payload.url) throw new Error('Unable to upload video.')
  invalidateClientVideoLibrary()
  return payload.path
}
export async function fetchVideoLibrary(refresh = false): Promise<ClientVideoAsset[]> {
  const mode = await readClientVideoProvider()
  if (!refresh && cached?.namespace === mode.namespace && Date.now() - cached.at < 300000) return cached.items
  if (!refresh && pending?.namespace === mode.namespace) return pending.promise
  const version = ++generation
  cached = undefined
  const promise = (async () => {
    const headers = new Headers()
    if (mode.provider === 'legacy') {
      const { supabase } = await import('./supabase')
      const token = (await supabase.auth.getSession()).data.session?.access_token
      if (token) headers.set('authorization', `Bearer ${token}`)
    }
    const response = await fetch(`/api/products/videos${refresh ? '?refresh=1' : ''}`, { credentials: 'same-origin', cache: 'no-store', headers })
    const payload = await response.json().catch(() => null)
    if (!response.ok || !Array.isArray(payload?.items)) throw new Error('Unable to load videos.')
    // A configuration change between discovery and read cannot seed another namespace.
    if (mode.provider === 'aws' && payload.namespace !== mode.namespace) throw new Error('Video service configuration changed. Refresh the library.')
    for (const item of payload.items) {
      if (typeof item?.key !== 'string' || typeof item.url !== 'string' || !Number.isSafeInteger(item.size) || item.size < 0 || !(item.lastModified === null || typeof item.lastModified === 'string') || (mode.provider === 'aws' && !isCanonicalAwsVideoReference(item.url))) throw new Error('Invalid video library response.')
    }
    if (generation === version) cached = { namespace: mode.namespace, items: payload.items, at: Date.now() }
    return payload.items as ClientVideoAsset[]
  })().finally(() => { if (generation === version) pending = undefined })
  pending = { namespace: mode.namespace, promise }
  return promise
}

import 'server-only'
import { createHash } from 'node:crypto'
import { S3Client, PutObjectCommand, HeadObjectCommand, ListObjectsV2Command, type HeadObjectCommandOutput, type ListObjectsV2CommandOutput } from '@aws-sdk/client-s3'
import type { VideoSource } from './video-provider'
import { productVideoContentsMatch } from './product-operations-validation'

export const MAX_VIDEO_BYTES = 100 * 1024 * 1024
export const videoTypes = { 'video/mp4': 'mp4', 'video/quicktime': 'mov', 'video/webm': 'webm' } as const
export type VideoMime = keyof typeof videoTypes
export type VideoAsset = { key: string; url: string; size: number; lastModified: string | null; contentType: string; extension: string }
type Command = PutObjectCommand | HeadObjectCommand | ListObjectsV2Command
export type VideoSend = (command: Command) => Promise<Partial<HeadObjectCommandOutput & ListObjectsV2CommandOutput>>
let client: S3Client | undefined
const send: VideoSend = async command => {
  client ??= new S3Client({ region: process.env.AWS_REGION || 'us-east-1' })
  if (command instanceof PutObjectCommand) return client.send(command)
  if (command instanceof HeadObjectCommand) return client.send(command)
  return client.send(command)
}
export function videoUrl(source: VideoSource, key: string) {
  if (!key.startsWith(source.prefix) || key.length > 1024 || /[\u0000-\u001f\u007f\\]/.test(key) || key.split('/').some(p => !p || p === '.' || p === '..')) throw new Error('Invalid video key.')
  return `${source.baseUrl}/${key.split('/').map(encodeURIComponent).join('/')}`
}
export function createVideoStorage(dispatch: VideoSend = send) {
  return {
    async upload(source: VideoSource, body: Buffer, mime: VideoMime, uuid = crypto.randomUUID()) {
      if (!Object.hasOwn(videoTypes, mime) || !body.length || body.length > MAX_VIDEO_BYTES || !productVideoContentsMatch(mime, body)) throw new Error('Invalid video.')
      if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(uuid)) throw new Error('Invalid video key.')
      const key = `${source.prefix}${uuid}.${videoTypes[mime]}`, url = videoUrl(source, key)
      const checksum = createHash('sha256').update(body).digest('base64')
      await dispatch(new PutObjectCommand({ Bucket: source.bucket, Key: key, Body: body, ContentType: mime, ContentLength: body.length, CacheControl: 'public, max-age=86400', ChecksumSHA256: checksum, IfNoneMatch: '*' }))
      const head = await dispatch(new HeadObjectCommand({ Bucket: source.bucket, Key: key, ChecksumMode: 'ENABLED' }))
      if (head.ContentLength !== body.length || head.ContentType !== mime || head.ChecksumSHA256 !== checksum) throw new Error('Video verification failed.')
      return { key, url }
    },
    async list(sources: VideoSource[]) {
      const found = new Map<string, VideoAsset>()
      let pages = 0, scanned = 0
      for (const source of sources) {
        let token: string | undefined
        const tokens = new Set<string>()
        do {
          if (++pages > 200) throw new Error('Video inventory exceeds listing budget.')
          const result = await dispatch(new ListObjectsV2Command({ Bucket: source.bucket, Prefix: source.prefix, ContinuationToken: token, MaxKeys: 1000 }))
          for (const item of result.Contents ?? []) {
            if (++scanned > 100000) throw new Error('Video inventory exceeds listing budget.')
            const key = item.Key, extension = key?.match(/\.(mp4|mov|webm|m4v)$/i)?.[1].toLowerCase()
            if (!key || !extension) continue
            const url = videoUrl(source, key)
            const size = item.Size ?? 0
            if (!Number.isSafeInteger(size) || size < 0) throw new Error('Invalid video inventory.')
            const asset = { key, url, size, lastModified: item.LastModified?.toISOString() ?? null, extension, contentType: extension === 'mov' ? 'video/quicktime' : extension === 'webm' ? 'video/webm' : extension === 'm4v' ? 'video/x-m4v' : 'video/mp4' }
            const old = found.get(url)
            if (!old || (asset.lastModified ?? '') > (old.lastModified ?? '')) found.set(url, asset)
          }
          token = result.IsTruncated ? result.NextContinuationToken : undefined
          if (result.IsTruncated && (!token || tokens.has(token))) throw new Error('Invalid video pagination.')
          if (token) tokens.add(token)
        } while (token)
      }
      return [...found.values()].sort((a, b) => (Date.parse(b.lastModified ?? '') || 0) - (Date.parse(a.lastModified ?? '') || 0) || a.url.localeCompare(b.url))
    },
  }
}

import 'server-only'
import { readVideoProvider, videoTarget } from './video-provider'
import { createVideoStorage, MAX_VIDEO_BYTES, videoTypes, type VideoMime } from './video-storage'
import { invalidateAwsVideoLibrary } from './video-library'
import { authorizeProductRequest } from './product-session-runtime'
import { ProductSessionError } from './product-session-error'
import { boundedImageForm, ImageBodyTooLarge } from './image-validation'

const failure = (status: number, error = 'Video service unavailable.') => Response.json({ error }, { status, headers: { 'Cache-Control': 'no-store' } })
export async function selectedMixedVideo(request: Request, context: 'product' | 'about'): Promise<Response | null> {
  if (request.headers.get('x-admin-video-upload') !== '1') return null
  try {
    if (readVideoProvider() === 'legacy') return failure(409, 'Video service configuration changed. Reload the uploader.')
    if (request.headers.has('x-admin-image-upload')) return failure(400, 'Invalid media protocol.')
    await authorizeProductRequest(request, true)
    const length = Number(request.headers.get('content-length'))
    if (!Number.isSafeInteger(length) || length <= 0) return failure(411, 'A valid upload size is required.')
    if (length > MAX_VIDEO_BYTES + 1024 * 1024) return failure(413, 'The upload request is too large.')
    const form = await boundedImageForm(request, MAX_VIDEO_BYTES + 1024 * 1024)
    const file = form?.get('file'), folder = form?.get('folder')
    if (!form || form.get('kind') !== 'video' || !(file instanceof File) || (context === 'product' && folder !== 'products' && folder !== 'hiphop')) return failure(400, 'Invalid video upload request.')
    if (file.size > MAX_VIDEO_BYTES) return failure(413, 'Videos must be 100 MB or smaller.')
    if (!file.size || !Object.hasOwn(videoTypes, file.type)) return failure(400, 'Only MP4, MOV, or WebM videos are allowed.')
    const body = Buffer.from(await file.arrayBuffer())
    const { productVideoContentsMatch } = await import('./product-operations-validation')
    if (!productVideoContentsMatch(file.type, body)) return failure(400, 'The file contents do not match the selected video type.')
    const source = videoTarget(context === 'about' ? 'about' : folder as 'products' | 'hiphop')
    try {
      const stored = await createVideoStorage().upload(source, body, file.type as VideoMime)
      invalidateAwsVideoLibrary()
      return Response.json({ provider: 's3', path: stored.url, url: stored.url }, { status: context === 'about' ? 200 : 201, headers: { 'Cache-Control': 'no-store' } })
    } catch { return failure(500, 'Unable to store the uploaded video.') }
  } catch (error) {
    return failure(error instanceof ProductSessionError ? error.status : error instanceof ImageBodyTooLarge ? 413 : 503)
  }
}
export function denyLegacyVideoInAwsMode(): Response | null {
  try { return readVideoProvider() === 'legacy' ? null : failure(409, 'Use the authenticated video upload protocol.') }
  catch { return failure(503) }
}
/** About signing is mixed and legacy-only; selected videos use bounded server uploads. */
export async function denyAwsVideoSigning(request: Request): Promise<Response | null> {
  try {
    if (readVideoProvider() === 'legacy') return null
    await authorizeProductRequest(request, true)
    return failure(503, 'Use the authenticated media upload endpoint.')
  } catch (error) { return failure(error instanceof ProductSessionError ? error.status : 503) }
}

/** Canonical video URLs are permanent CDN references; historical references are never rewritten. */
export function isCanonicalAwsVideoReference(value: unknown): value is string {
  if (typeof value !== 'string') return false
  try {
    const url = new URL(value)
    if (url.href !== value || url.protocol !== 'https:' || !['media.houseofdiams.com', 'content.houseofdiams.com'].includes(url.hostname) || url.port || url.username || url.password || url.search || url.hash) return false
    const key = decodeURIComponent(url.pathname.slice(1))
    return /\.(mp4|mov|webm|m4v)$/i.test(key) && key.includes('/') && !/[\u0000-\u001f\u007f\\]/.test(key) && key.split('/').every(p => p && p !== '.' && p !== '..')
  } catch { return false }
}

import 'server-only'
import { readAdminAuthProvider } from './auth/integration'
import { imageTarget } from './image-provider'

export type VideoProvider = 'legacy' | 'aws'
export type VideoContext = 'products' | 'hiphop' | 'about'
export type VideoSource = { bucket: string; baseUrl: string; prefix: string }
export function readVideoProvider(env: NodeJS.ProcessEnv = process.env): VideoProvider {
  readAdminAuthProvider(env)
  const value = env.ADMIN_VIDEO_PROVIDER
  if (!value || value === 'legacy') return 'legacy'
  if (value === 'aws') return 'aws'
  throw new Error('Video service unavailable.')
}
export function videoTarget(context: VideoContext, env: NodeJS.ProcessEnv = process.env): VideoSource {
  if (env.ADMIN_VIDEO_ROUTING_VERIFIED !== 'true') throw new Error('Video service unavailable.')
  const target = imageTarget(context === 'about' ? 'content' : 'product', env)
  return { ...target, prefix: context === 'about' ? 'about/hero/video/' : `${context}/videos/` }
}
/** Explicit inventory, never a root bucket scan or a rewrite of historical URLs. */
export function videoSources(env: NodeJS.ProcessEnv = process.env): VideoSource[] {
  const product = videoTarget('products', env)
  return [product, videoTarget('hiphop', env),
    { ...product, prefix: 'bespoke/videos/' },
    { ...product, prefix: 'about/hero/video/' }, videoTarget('about', env)]
}
export function videoNamespace(sources: VideoSource[]) {
  return JSON.stringify(['aws-video-v1', ...sources.map(s => [s.bucket, s.prefix, s.baseUrl])])
}
export function legacyVideoNamespace(env: NodeJS.ProcessEnv = process.env) {
  return JSON.stringify(['legacy-r2-v1', env.CLOUDFLARE_R2_ACCOUNT_ID?.trim() ?? '', env.CLOUDFLARE_R2_BUCKET?.trim() ?? '', env.CLOUDFLARE_R2_PUBLIC_BASE_URL?.trim() ?? '', env.CLOUDFLARE_R2_VIDEO_PREFIX?.trim() || 'products/videos', env.CLOUDFLARE_R2_BESPOKE_VIDEO_PREFIX?.trim() || 'bespoke/videos'])
}

import 'server-only'
import { videoNamespace, videoSources } from './video-provider'
import { createVideoStorage, type VideoAsset } from './video-storage'

/** A single bounded namespace; invalidation/refresh cannot repopulate from an older request. */
export function createVideoLibrary<T>(now: () => number = Date.now) {
  let generation = 0
  let cached: { namespace: string; items: T[]; at: number } | undefined
  let pending: { namespace: string; promise: Promise<T[]> } | undefined
  return {
    invalidate() { generation++; cached = undefined; pending = undefined },
    async get(namespace: string, load: () => Promise<T[]>, refresh = false): Promise<T[]> {
      if (!refresh && cached?.namespace === namespace && now() - cached.at < 300000) return cached.items
      if (!refresh && pending?.namespace === namespace) return pending.promise
      const version = ++generation
      // A failed refresh must not leave an earlier success eligible for reuse.
      cached = undefined
      const promise = Promise.resolve().then(load).then(items => {
        if (generation === version) cached = { namespace, items, at: now() }
        return items
      }).finally(() => { if (generation === version) pending = undefined })
      pending = { namespace, promise }
      return promise
    },
  }
}
const cache = createVideoLibrary<VideoAsset>()
export function invalidateAwsVideoLibrary() { cache.invalidate() }
export function getAwsVideoLibrary(refresh = false) {
  const sources = videoSources()
  return cache.get(videoNamespace(sources), () => createVideoStorage().list(sources), refresh)
}

