import { cookies } from 'next/headers'
import { assertLegacyAdminAuth } from './auth/integration'
import { createClient } from '@supabase/supabase-js'
import { createServerClient, type CookieOptions } from '@supabase/ssr'

function requireEnv(value: string | undefined, name: string) {
  if (!value) {
    throw new Error(`Missing ${name} environment variable for the admin app.`)
  }
  return value
}

export function createSupabaseServerClient() {
  assertLegacyAdminAuth()
  const supabaseUrl = requireEnv(process.env.NEXT_PUBLIC_SUPABASE_URL, 'NEXT_PUBLIC_SUPABASE_URL')
  const supabaseAnonKey = requireEnv(process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY, 'NEXT_PUBLIC_SUPABASE_ANON_KEY')
  return createClient(supabaseUrl, supabaseAnonKey)
}

export async function createSupabaseServerSessionClient() {
  assertLegacyAdminAuth()
  const supabaseUrl = requireEnv(process.env.NEXT_PUBLIC_SUPABASE_URL, 'NEXT_PUBLIC_SUPABASE_URL')
  const supabaseAnonKey = requireEnv(process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY, 'NEXT_PUBLIC_SUPABASE_ANON_KEY')
  const cookieStore = await cookies()

  return createServerClient(supabaseUrl, supabaseAnonKey, {
    cookies: {
      getAll() {
        return cookieStore.getAll()
      },
      setAll(cookiesToSet: Array<{ name: string; value: string; options: CookieOptions }>) {
        try {
          for (const { name, value, options } of cookiesToSet) {
            cookieStore.set(name, value, options)
          }
        } catch {
          // Server Components can read auth cookies even when writes are unavailable.
        }
      },
    },
  })
}

import 'server-only'
import { createHash } from 'node:crypto'
import { HeadObjectCommand, PutObjectCommand, S3Client, type HeadObjectCommandOutput } from '@aws-sdk/client-s3'

const bucket = process.env.AWS_MEDIA_BUCKET?.trim()
const baseUrl = process.env.NEXT_PUBLIC_MEDIA_CDN_BASE_URL?.trim().replace(/\/+$/, '')
let client: S3Client | null = null

export function isS3MediaConfigured() {
  return bucket === 'house-of-diams' && baseUrl === 'https://media.houseofdiams.com'
}

function getClient() {
  if (!isS3MediaConfigured()) throw new Error('AWS media storage is not configured.')
  return client ??= new S3Client({ region: process.env.AWS_REGION || 'us-east-1' })
}

type Target = { bucket: string; baseUrl: string }
type Send = (command: PutObjectCommand | HeadObjectCommand) => Promise<Partial<HeadObjectCommandOutput>>

/** Injectable command boundary; constructing/importing this module never resolves credentials. */
export function createMediaUploader(send: Send) {
 return async (path: string, body: Buffer, contentType: string, target: Target, verify = true) => {
  if (!/^[a-zA-Z0-9_./-]+$/.test(path) || path.includes('..') || path.startsWith('/')) throw new Error('Invalid media key.')
  if (verify && (path.length > 512 || path.includes('//') || !/^[a-zA-Z0-9_-]+(?:\/[a-zA-Z0-9_.-]+)+$/.test(path))) throw new Error('Invalid image key.')
  if (verify && (!/\/[a-zA-Z0-9_.-]*[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(webp|svg)$/.test(path) || !['image/webp', 'image/svg+xml'].includes(contentType))) throw new Error('Invalid image key.')
  if (!body.length) throw new Error('Empty media upload.')
  const checksum = createHash('sha256').update(body).digest('base64')
  await send(new PutObjectCommand({
    Bucket: target.bucket, Key: path, Body: body, ContentType: contentType,
    CacheControl: 'public, max-age=86400', ChecksumSHA256: checksum,
    IfNoneMatch: '*',
  }))
  const uploaded = await send(new HeadObjectCommand({ Bucket: target.bucket, Key: path, ...(verify ? { ChecksumMode: 'ENABLED' as const } : {}) }))
  if (uploaded.ContentLength !== body.length || (verify && (uploaded.ChecksumSHA256 !== checksum || uploaded.ContentType !== contentType))) throw new Error('AWS media upload verification failed.')
  return { path, url: `${target.baseUrl}/${path}` }
 }
}

export async function uploadMediaToS3(path: string, body: Buffer, contentType: string, target?: Target) {
  // Default legacy contract (including video) retains its original target/verification behavior.
  const selected = target ?? { bucket: bucket ?? '', baseUrl: baseUrl ?? '' }
  const send: Send = async command => {
    const selectedClient = target ? (client ??= new S3Client({ region: process.env.AWS_REGION || 'us-east-1' })) : getClient()
    return command instanceof PutObjectCommand ? selectedClient.send(command) : selectedClient.send(command)
  }
  return createMediaUploader(send)(path, body, contentType, selected, Boolean(target))
}

import 'server-only'

import { ListObjectsV2Command, PutObjectCommand, S3Client } from '@aws-sdk/client-s3'
import { getSignedUrl } from '@aws-sdk/s3-request-presigner'

type ProductMediaFolder = 'products' | 'hiphop' | 'bespoke'

const r2AccountId = process.env.CLOUDFLARE_R2_ACCOUNT_ID?.trim() ?? ''
const r2AccessKeyId = process.env.CLOUDFLARE_R2_ACCESS_KEY_ID?.trim() ?? ''
const r2SecretAccessKey = process.env.CLOUDFLARE_R2_SECRET_ACCESS_KEY?.trim() ?? ''
const r2Bucket = process.env.CLOUDFLARE_R2_BUCKET?.trim() ?? ''
const r2PublicBaseUrl = process.env.CLOUDFLARE_R2_PUBLIC_BASE_URL?.trim() ?? ''
const r2VideoPrefix = process.env.CLOUDFLARE_R2_VIDEO_PREFIX?.trim() || 'products/videos'
const r2BespokeVideoPrefix = process.env.CLOUDFLARE_R2_BESPOKE_VIDEO_PREFIX?.trim() || 'bespoke/videos'

let client: S3Client | null = null

function requireR2Config() {
  if (!r2AccountId || !r2AccessKeyId || !r2SecretAccessKey || !r2Bucket || !r2PublicBaseUrl) {
    throw new Error('Cloudflare R2 video upload is not configured completely.')
  }
}

export function isR2Configured() {
  return Boolean(r2AccountId && r2AccessKeyId && r2SecretAccessKey && r2Bucket && r2PublicBaseUrl)
}

function getR2Client() {
  requireR2Config()
  if (client) return client

  client = new S3Client({
    region: 'auto',
    endpoint: `https://${r2AccountId}.r2.cloudflarestorage.com`,
    forcePathStyle: true,
    credentials: {
      accessKeyId: r2AccessKeyId,
      secretAccessKey: r2SecretAccessKey,
    },
  })

  return client
}

function normalizePrefix(value: string) {
  return value.split('/').map((part) => part.trim()).filter(Boolean).join('/')
}

function joinPublicUrl(baseUrl: string, key: string) {
  const cleanBase = baseUrl.replace(/\/+$/, '')
  const cleanKey = key.replace(/^\/+/, '')
  return `${cleanBase}/${cleanKey}`
}

function buildVideoObjectKey(folder: ProductMediaFolder, extension: string) {
  const prefix = normalizePrefix(
    folder === 'bespoke'
      ? r2BespokeVideoPrefix
      : folder === 'hiphop'
        ? `${r2VideoPrefix}/hiphop`
        : r2VideoPrefix,
  )

  return prefix ? `${prefix}/${crypto.randomUUID()}.${extension}` : `${crypto.randomUUID()}.${extension}`
}

function normalizeObjectSegment(value: string | null | undefined) {
  return (value || 'draft')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'draft'
}

export async function createPresignedProductImageUpload({
  folder,
  productKey,
  contentType,
  declaredSize,
}: {
  folder: 'products' | 'hiphop'
  productKey?: string | null
  contentType: 'image/webp'
  declaredSize: number
}) {
  const objectKey = `${folder}/${normalizeObjectSegment(productKey)}/images/${crypto.randomUUID()}.webp`
  const command = new PutObjectCommand({
    Bucket: r2Bucket,
    Key: objectKey,
    ContentType: contentType,
    ContentLength: declaredSize,
  })
  const uploadUrl = await getSignedUrl(getR2Client(), command, { expiresIn: 300 })

  return {
    key: objectKey,
    uploadUrl,
    url: joinPublicUrl(r2PublicBaseUrl, objectKey),
  }
}

export function inferVideoContentType(extension: string, fallback?: string | null) {
  const normalized = extension.trim().toLowerCase()
  if (normalized === 'mov') return 'video/quicktime'
  if (normalized === 'webm') return 'video/webm'
  if (normalized === 'mp4') return 'video/mp4'
  return fallback?.trim() || 'video/mp4'
}

export async function uploadProductVideoToR2({
  buffer,
  extension,
  folder,
  contentType,
}: {
  buffer: Buffer
  extension: string
  folder: ProductMediaFolder
  contentType?: string | null
}) {
  const safeExtension = extension.trim().toLowerCase() || 'mp4'
  const objectKey = buildVideoObjectKey(folder, safeExtension)

  await getR2Client().send(
    new PutObjectCommand({
      Bucket: r2Bucket,
      Key: objectKey,
      Body: buffer,
      ContentType: inferVideoContentType(safeExtension, contentType),
    }),
  )

  return {
    key: objectKey,
    url: joinPublicUrl(r2PublicBaseUrl, objectKey),
  }
}

export async function listProductVideosFromR2({
  folder,
  cursor,
  pageSize = 48,
}: {
  folder: 'products' | 'hiphop'
  cursor?: string | null
  pageSize?: number
}) {
  requireR2Config()
  const prefix = normalizePrefix(
    folder === 'hiphop' ? `${r2VideoPrefix}/hiphop` : r2VideoPrefix,
  )
  const result = await getR2Client().send(
    new ListObjectsV2Command({
      Bucket: r2Bucket,
      Prefix: prefix ? `${prefix}/` : undefined,
      ContinuationToken: cursor || undefined,
      MaxKeys: Math.min(Math.max(pageSize, 1), 100),
    }),
  )

  return {
    items: (result.Contents ?? [])
      .filter((item) => Boolean(item.Key))
      .map((item) => ({
        key: item.Key as string,
        url: joinPublicUrl(r2PublicBaseUrl, item.Key as string),
        size: item.Size ?? 0,
        lastModified: item.LastModified?.toISOString() ?? null,
      })),
    nextCursor: result.IsTruncated ? result.NextContinuationToken ?? null : null,
  }
}

type CentralVideoAsset = {
  key: string
  url: string
  size: number
  lastModified: string | null
}

const CENTRAL_VIDEO_CACHE_TTL_MS = 5 * 60 * 1000
let centralVideoCache: { items: CentralVideoAsset[]; loadedAt: number } | null = null
let centralVideoPending: Promise<CentralVideoAsset[]> | null = null

function isVideoObjectKey(key: string) {
  return /\.(mp4|mov|webm|m4v)$/i.test(key)
}

async function loadAllR2Videos() {
  requireR2Config()
  const items: CentralVideoAsset[] = []
  let continuationToken: string | undefined

  do {
    const result = await getR2Client().send(
      new ListObjectsV2Command({
        Bucket: r2Bucket,
        ContinuationToken: continuationToken,
        MaxKeys: 1000,
      }),
    )
    for (const item of result.Contents ?? []) {
      if (!item.Key || !isVideoObjectKey(item.Key)) continue
      items.push({
        key: item.Key,
        url: joinPublicUrl(r2PublicBaseUrl, item.Key),
        size: item.Size ?? 0,
        lastModified: item.LastModified?.toISOString() ?? null,
      })
    }
    continuationToken = result.IsTruncated ? result.NextContinuationToken : undefined
  } while (continuationToken)

  return items.sort((left, right) => {
    const leftTime = left.lastModified ? Date.parse(left.lastModified) : 0
    const rightTime = right.lastModified ? Date.parse(right.lastModified) : 0
    return rightTime - leftTime
  })
}

export async function getCentralVideoLibrary({ forceRefresh = false }: { forceRefresh?: boolean } = {}) {
  if (!forceRefresh && centralVideoCache && Date.now() - centralVideoCache.loadedAt < CENTRAL_VIDEO_CACHE_TTL_MS) {
    return centralVideoCache.items
  }
  if (!forceRefresh && centralVideoPending) return centralVideoPending

  centralVideoPending = loadAllR2Videos()
    .then((items) => {
      centralVideoCache = { items, loadedAt: Date.now() }
      return items
    })
    .finally(() => {
      centralVideoPending = null
    })

  return centralVideoPending
}

export function invalidateCentralVideoLibrary() {
  centralVideoCache = null
}

'use client'

type CacheEntry<T> = {
  data: T
  loadedAt: number
}

const queryData = new Map<string, CacheEntry<unknown>>()
const queryPending = new Map<string, Promise<unknown>>()

export function getCachedQueryData<T>(key: string, staleTimeMs: number): T | null {
  const entry = queryData.get(key)
  if (!entry || Date.now() - entry.loadedAt >= staleTimeMs) return null
  return entry.data as T
}

export function setCachedQueryData<T>(key: string, data: T) {
  queryData.set(key, { data, loadedAt: Date.now() })
}

export function deleteCachedQueryData(key: string) {
  queryData.delete(key)
  queryPending.delete(key)
}

export async function fetchCachedQuery<T>({
  key,
  staleTimeMs,
  fetcher,
}: {
  key: string
  staleTimeMs: number
  fetcher: () => Promise<T | null>
}) {
  const cached = getCachedQueryData<T>(key, staleTimeMs)
  if (cached) return cached

  const pending = queryPending.get(key) as Promise<T | null> | undefined
  if (pending) return pending

  const request = fetcher()
    .then((data) => {
      if (data) setCachedQueryData(key, data)
      return data
    })
    .finally(() => {
      queryPending.delete(key)
    })

  queryPending.set(key, request)
  return request
}

'use client'

/** Server-authoritative selection per operation; never cache an activation or retry writes. */
export async function productRequestHeaders(mutation = true): Promise<Headers> {
  const contract = await fetch('/api/products/provider', { credentials: 'same-origin', cache: 'no-store' })
  const payload = await contract.json()
  if (!contract.ok || !['supabase', 'rds'].includes(payload?.provider)) throw new Error('Product service unavailable.')
  const headers = new Headers({ 'content-type': 'application/json' })
  if (payload.provider === 'rds') {
    const response = await fetch('/api/auth/session', { credentials: 'same-origin', cache: 'no-store' })
    const session = await response.json()
    if (!response.ok || session?.authenticated !== true || typeof session.csrfToken !== 'string' || !session.csrfToken) throw new Error('Please sign in again.')
    if (mutation) headers.set('x-admin-csrf', session.csrfToken)
  } else {
    const { supabase } = await import('./supabase')
    const { data } = await supabase.auth.getSession()
    if (!data.session?.access_token) throw new Error('Please sign in again.')
    headers.set('authorization', `Bearer ${data.session.access_token}`)
  }
  return headers
}
export async function productFetch(url: string, options: RequestInit = {}) {
  if (!/^\/api\/(?:products|inventory)(?:[/?]|$)/.test(url)) throw new Error('Invalid product API path.')
  const headers = await productRequestHeaders(!['GET', 'HEAD'].includes(options.method ?? 'GET'))
  new Headers(options.headers).forEach((value, key) => {
    if (!['authorization', 'x-admin-csrf'].includes(key.toLowerCase())) headers.set(key, value)
  })
  return fetch(url, { ...options, credentials: 'same-origin', headers })
}

import 'server-only'
import type { SupabaseClient } from '@supabase/supabase-js'

import { buildProductSlugBase, getRetiredProductSlug, selectAvailableProductSlug } from '@/lib/product-slug-core'

export async function allocateProductSlug(client: SupabaseClient, name: string) {
  const base = buildProductSlugBase(name)
  const [productsResult, redirectsResult] = await Promise.all([
    client.from('products').select('slug').like('slug', `${base}%`),
    client.from('seo_redirects').select('source_path').like('source_path', `/shop/${base}%`),
  ])

  if (productsResult.error) {
    throw new Error(`Unable to check existing product slugs: ${productsResult.error.message}`)
  }
  if (redirectsResult.error) {
    throw new Error(`Unable to check retired product slugs: ${redirectsResult.error.message}`)
  }

  const unavailable = new Set<string>((productsResult.data ?? []).map((row: { slug: string }) => row.slug))
  for (const redirect of redirectsResult.data ?? []) {
    const retiredSlug = getRetiredProductSlug(String(redirect.source_path || ''))
    if (retiredSlug) unavailable.add(retiredSlug)
  }

  return selectAvailableProductSlug(base, unavailable)
}

const MAX_SUFFIX_ATTEMPTS = 10_000

export function buildProductSlugBase(name: string) {
  const base = name
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')

  if (!base) throw new Error('Product name must contain characters that can form a public URL slug.')
  return base
}

export function getRetiredProductSlug(sourcePath: string) {
  const pathname = sourcePath.split('?', 1)[0]
  return pathname.startsWith('/shop/') ? pathname.slice('/shop/'.length) : null
}

export function selectAvailableProductSlug(base: string, unavailableSlugs: Iterable<string>) {
  const unavailable = new Set(unavailableSlugs)
  for (let suffix = 1; suffix <= MAX_SUFFIX_ATTEMPTS; suffix += 1) {
    const candidate = suffix === 1 ? base : `${base}-${suffix}`
    if (!unavailable.has(candidate)) return candidate
  }
  throw new Error(`Unable to allocate a unique product slug for "${base}".`)
}

import 'server-only'
import { readAuthConfig } from './auth/config'
import { createKeycloak } from './auth/keycloak'
import { createSessionStore } from './auth/session-store'
import { createSessions } from './auth/session'
import { lookupAdminIdentity } from './db/admin-repositories/identity'
import { ProductSessionError } from './product-session-error'

let sessions: ReturnType<typeof createSessions> | undefined
/** Scoped composition of the real B1 session and B2 identity adapters; no alternate actor path. */
export async function authorizeProductRequest(request: Request, mutation = false) {
  try {
    if (!sessions) {
      const config = readAuthConfig()
      sessions = createSessions({ config, oidc: createKeycloak(config), store: createSessionStore(), lookup: lookupAdminIdentity })
    }
  } catch { throw new ProductSessionError(503) }
  try { return await sessions.authorize(request, mutation) }
  catch (error) {
    const message = error instanceof Error ? error.message : ''
    if (['Session missing', 'Session expired', 'Expired session', 'Session revoked'].includes(message)) throw new ProductSessionError(401)
    if (['Invalid origin', 'Invalid CSRF', 'Invalid method', 'Admin identity denied'].includes(message)) throw new ProductSessionError(403)
    throw new ProductSessionError(503)
  }
}

export class ProductSessionError extends Error {
  constructor(readonly status: 401 | 403 | 503) { super('Administrator session unavailable.') }
}

