  }))
}

export function serializeProductFaqItems(items: ProductFaqItem[]) {
  return items
    .map((item, index) => ({
      id: item.id,
      product_id: item.product_id,
      question: item.question.trim(),
      answer: item.answer.trim(),
      sort_order: index + 1,
      is_active: item.is_active !== false,
      source: item.source || 'admin',
