export async function loadProductEditorPage(lookup: string): Promise<Awaited<ReturnType<typeof loadProductEditorItem>>> {
  if (readProductDataProvider(process.env) === 'supabase') return loadProductEditorItem(createSupabaseAdminClient(), lookup)
  await authorizeProductPage()
  return adminTransaction(async db => {
    const id = await findRdsProductId(db, lookup)
    if (!id) return { status: 'not_found' as const }
    const item = await loadRdsProductEditor(db, id)
    return item ? { status: 'found' as const, item } : { status: 'not_found' as const }
  })
}

import { z } from 'zod'

const uuid = z.string().uuid()
const lane = z.enum(['standard', 'hiphop', 'collection'])
const productIds = z.array(uuid).min(1).max(500).superRefine((ids, context) => {
  if (new Set(ids).size !== ids.length) {
    context.addIssue({ code: z.ZodIssueCode.custom, message: 'Product IDs must be unique.' })
  }
})

export const productStatusSchema = z.object({
  status: z.literal('draft'),
  expected_status: z.enum(['active', 'hidden', 'archived']),
}).strict()

export const duplicateProductSchema = z.object({ requestId: uuid }).strict()

export const bulkPriceSchema = z.object({
  requestId: uuid,
  ids: productIds,
  expectedPrices: z.array(z.object({ id: uuid, price: z.number().finite().positive().max(1_000_000_000) }).strict()).min(1).max(500),
  lane,
  operation: z.enum(['increase_amount', 'decrease_amount', 'increase_percent', 'decrease_percent']),
  value: z.number().finite().positive().max(1_000_000_000),
  confirmation: z.literal('ADJUST_BASE_PRICES'),
}).strict().superRefine((value, context) => {
  if (value.operation.endsWith('_percent') && value.value > 1_000) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['value'], message: 'Percentage adjustments cannot exceed 1000%.' })
  }
  if (value.operation === 'decrease_percent' && value.value >= 100) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['value'], message: 'Percentage decreases must be less than 100%.' })
  }
  const expectedIds = value.expectedPrices.map((item) => item.id)
  if (new Set(expectedIds).size !== expectedIds.length || expectedIds.length !== value.ids.length || value.ids.some((id) => !expectedIds.includes(id))) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['expectedPrices'], message: 'Price verification data must contain each selected product exactly once.' })
  }
})

export const bulkDeleteSchema = z.object({
  requestId: uuid,
  ids: productIds,
  lane,
  confirmation: z.literal('DELETE_PRODUCTS'),
}).strict()

export const activateDraftsSchema = z.object({
  requestId: uuid,
  ids: productIds,
  lane,
  confirmation: z.literal('ACTIVATE_DRAFTS'),
}).strict()

export const productMediaSignSchema = z.object({
  folder: z.enum(['products', 'hiphop']),
  contentType: z.literal('image/webp'),
  declaredSize: z.number().int().min(1).max(25 * 1024 * 1024),
  productKey: z.string().trim().min(1).max(120).regex(/^[a-zA-Z0-9_-]+$/, 'Product media keys may only contain letters, numbers, hyphens, and underscores.'),
}).strict()

export const videoLibraryQuerySchema = z.object({
  refresh: z.enum(['0', '1']).optional(),
}).strict()

export function productVideoContentsMatch(mime: string, buffer: Buffer) {
  if (mime === 'video/webm') return buffer.length >= 4 && buffer.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]))
  if (mime === 'video/mp4' || mime === 'video/quicktime') return buffer.length >= 12 && buffer.toString('ascii', 4, 8) === 'ftyp'
  return false
}

export type ProductOperationError = { code?: string; message?: string }

export function productOperationError(error: ProductOperationError, action: 'status' | 'duplicate' | 'price' | 'delete' | 'activate') {
  if (error.code === 'PGRST202' || error.code === '42883') {
    return { status: 503, message: action === 'duplicate' ? 'Product duplication is awaiting its database migration.' : 'Product operations are awaiting their database migration.' }
  }
  if (error.code === 'P0002') return { status: 404, message: 'One or more selected products were not found.' }
  if (error.code === '40001' || error.code === '23505') return { status: 409, message: 'The selected products changed after you loaded them. Refresh the list and try again.' }
  if (error.code === '23503') return { status: 409, message: action === 'delete' ? 'One or more selected products are still referenced and cannot be deleted.' : 'A selected product dependency is no longer available.' }
  if (error.code === '42501') return { status: 403, message: 'Administrator access is required.' }
  if (['22023', '22P02', '23502', '23514', 'P0001'].includes(error.code ?? '')) return { status: 400, message: 'The product operation is invalid.' }
  const descriptions = {
    status: 'Unable to change the product status.',
    duplicate: 'Unable to duplicate this product. The original product was not changed.',
    price: 'Unable to update product prices. No prices were changed.',
    delete: 'Unable to delete the selected products. No products were deleted.',
    activate: 'Unable to activate the selected drafts. No statuses were changed.',
  }
  return { status: 500, message: descriptions[action] }
}

import type { CatalogMetal } from '@/lib/product-catalog'
import type { SupabaseClient } from '@supabase/supabase-js'

export type ProductVariantMediaItem = {
  id?: string
  product_id?: string
  variant_id?: string | null
  media_type: 'image' | 'video'
  media_path: string
  alt_text?: string | null
  sort_order: number
  is_default_fallback?: boolean
}

export type ProductMetalVariant = {
  id?: string
  product_id?: string
  metal_id: string
  price: number
  is_default: boolean
  sort_order: number
  media_items?: ProductVariantMediaItem[]
}

function isMissingRelation(error: { message?: string | null } | null | undefined, table: string) {
  return (
    error?.message?.includes(`relation "${table}" does not exist`) ||
    error?.message?.includes(`Could not find the table 'public.${table}' in the schema cache`)
  ) ?? false
}

function normalizeMediaItems(items: ProductVariantMediaItem[] | null | undefined) {
  return (items ?? [])
    .map((item, index) => ({
      id: item.id,
      media_type: item.media_type === 'video' ? 'video' : 'image',
      media_path: item.media_path?.trim() ?? '',
      alt_text: item.alt_text?.trim() || null,
      sort_order: Number(item.sort_order ?? index + 1),
      is_default_fallback: Boolean(item.is_default_fallback),
    }))
    .filter((item) => item.media_path.length > 0)
}

export function buildCombinedMetalDisplayLabel(metal: Pick<CatalogMetal, 'display_label' | 'name' | 'purity_label' | 'base_metal_name'>) {
  const purity = metal.purity_label?.trim()
  const baseMetal = metal.base_metal_name?.trim() || metal.name.trim()
  const displayLabel = metal.display_label?.trim()
  const generatedLabel = (() => {
    if (!purity) return baseMetal

    const normalizedPurity = purity.toLowerCase()
    const normalizedBaseMetal = baseMetal.toLowerCase()
    return normalizedBaseMetal === normalizedPurity || normalizedBaseMetal.startsWith(`${normalizedPurity} `)
      ? baseMetal
      : `${purity} ${baseMetal}`.trim()
  })()

  if (displayLabel && displayLabel !== metal.name.trim() && displayLabel !== baseMetal) {
    return displayLabel
  }
  return generatedLabel
}

export async function replaceProductMetalVariants(
  adminClient: SupabaseClient,
  productId: string,
  variants: ProductMetalVariant[]
) {
  const existingResult = await adminClient
    .from('product_metal_variants')
    .select('id, metal_id')
    .eq('product_id', productId)

  if (existingResult.error && !isMissingRelation(existingResult.error, 'product_metal_variants')) {
    return { error: existingResult.error }
  }

  const nextVariants = variants
    .map((variant, index) => ({
      metal_id: variant.metal_id,
      price: Number(variant.price ?? 0),
      is_default: Boolean(variant.is_default),
      sort_order: Number(variant.sort_order ?? index + 1),
    }))
    .filter((variant) => variant.metal_id)

  if (nextVariants.length < 1) {
    const deleteResult = await adminClient.from('product_metal_variants').delete().eq('product_id', productId)
    if (deleteResult.error && !isMissingRelation(deleteResult.error, 'product_metal_variants')) {
      return { error: deleteResult.error }
    }
    return { data: [] as Array<{ id: string; metal_id: string }> }
  }

  const hasExplicitDefault = nextVariants.some((variant) => variant.is_default)
  const normalizedVariants = nextVariants.map((variant, index) => ({
    ...variant,
    is_default: hasExplicitDefault ? variant.is_default : index === 0,
  }))

  const existingByMetalId = new Map(
    ((existingResult.data ?? []) as Array<{ id: string; metal_id: string }>).map((row) => [row.metal_id, row.id])
  )
  const keepMetalIds = new Set(normalizedVariants.map((variant) => variant.metal_id))
  const deleteIds = ((existingResult.data ?? []) as Array<{ id: string; metal_id: string }>)
    .filter((row) => !keepMetalIds.has(row.metal_id))
    .map((row) => row.id)

  if (deleteIds.length > 0) {
    const deleteResult = await adminClient.from('product_metal_variants').delete().in('id', deleteIds)
    if (deleteResult.error) return { error: deleteResult.error }
  }

  const persisted: Array<{ id: string; metal_id: string }> = []

  for (const variant of normalizedVariants) {
    const existingId = existingByMetalId.get(variant.metal_id)
    if (existingId) {
      const updateResult = await adminClient
        .from('product_metal_variants')
        .update({
          price: variant.price,
          is_default: variant.is_default,
          sort_order: variant.sort_order,
          updated_at: new Date().toISOString(),
        })
        .eq('id', existingId)
        .select('id, metal_id')
        .single()
      if (updateResult.error) return { error: updateResult.error }
      persisted.push(updateResult.data)
    } else {
      const insertResult = await adminClient
        .from('product_metal_variants')
        .insert({
          product_id: productId,
          metal_id: variant.metal_id,
          price: variant.price,
          is_default: variant.is_default,
          sort_order: variant.sort_order,
        })
        .select('id, metal_id')
        .single()
      if (insertResult.error) return { error: insertResult.error }
      persisted.push(insertResult.data)
    }
  }

  return { data: persisted }
}

export async function replaceProductVariantMediaItems(
  adminClient: SupabaseClient,
  productId: string,
  params: {
    variants: ProductMetalVariant[]
    defaultMediaItems?: ProductVariantMediaItem[]
    persistedVariantRows: Array<{ id: string; metal_id: string }>
  }
) {
  const existingResult = await adminClient
    .from('product_variant_media_items')
    .select('id')
    .eq('product_id', productId)

  if (existingResult.error && !isMissingRelation(existingResult.error, 'product_variant_media_items')) {
    return { error: existingResult.error }
  }

  const deleteResult = await adminClient.from('product_variant_media_items').delete().eq('product_id', productId)
  if (deleteResult.error && !isMissingRelation(deleteResult.error, 'product_variant_media_items')) {
    return { error: deleteResult.error }
  }

  const variantIdByMetalId = new Map(params.persistedVariantRows.map((row) => [row.metal_id, row.id]))
  const insertRows: Array<Record<string, unknown>> = []

  for (const [index, item] of normalizeMediaItems(params.defaultMediaItems).entries()) {
    insertRows.push({
      product_id: productId,
      variant_id: null,
      media_type: item.media_type,
      media_path: item.media_path,
      alt_text: item.alt_text,
      sort_order: Number(item.sort_order ?? index + 1),
      is_default_fallback: true,
    })
  }

  for (const variant of params.variants) {
    const variantId = variantIdByMetalId.get(variant.metal_id)
    if (!variantId) continue

    for (const [index, item] of normalizeMediaItems(variant.media_items).entries()) {
      insertRows.push({
        product_id: productId,
        variant_id: variantId,
        media_type: item.media_type,
        media_path: item.media_path,
        alt_text: item.alt_text,
        sort_order: Number(item.sort_order ?? index + 1),
        is_default_fallback: false,
      })
    }
  }

  if (insertRows.length < 1) {
    return { ok: true }
  }

  const insertResult = await adminClient.from('product_variant_media_items').insert(insertRows)
  if (insertResult.error) return { error: insertResult.error }
  return { ok: true }
}

export async function loadProductMetalVariantBundle(adminClient: SupabaseClient, productId: string) {
  const [variantsResult, mediaResult] = await Promise.all([
    adminClient
      .from('product_metal_variants')
      .select('*')
      .eq('product_id', productId)
      .order('sort_order', { ascending: true }),
    adminClient
      .from('product_variant_media_items')
      .select('*')
      .eq('product_id', productId)
      .order('sort_order', { ascending: true }),
  ])

  const variants =
    variantsResult.error && isMissingRelation(variantsResult.error, 'product_metal_variants')
      ? []
      : ((variantsResult.data ?? []) as ProductMetalVariant[])

  const mediaItems =
    mediaResult.error && isMissingRelation(mediaResult.error, 'product_variant_media_items')
      ? []
      : ((mediaResult.data ?? []) as ProductVariantMediaItem[])

  const defaultMediaItems = mediaItems.filter((item) => item.variant_id == null && item.is_default_fallback)

  return {
    metalVariants: variants.map((variant) => ({
      ...variant,
      media_items: mediaItems.filter((item) => item.variant_id === variant.id),
    })),
    defaultVariantMediaItems: defaultMediaItems,
  }
}

import 'server-only'
import type { SupabaseClient } from '@supabase/supabase-js'

export type ProductMasterValidationPayload = {
  main_category_id?: string | null
  subcategory_id?: string | null
  linked_subcategory_ids?: string[]
  option_id?: string | null
  linked_option_ids?: string[]
  style_id?: string | null
  gst_slab_id?: string | null
  metal_ids?: string[]
  metal_variants?: Array<{ metal_id?: string | null }>
  certificate_ids?: string[]
  ring_enabled?: boolean
  ring_category_id?: string | null
  material_value_ids?: string[]
  shape_ids?: string[]
  shipping_rule_id?: string | null
  care_warranty_rule_id?: string | null
}

type ValidationResult = { ok: true } | { ok: false; message: string }

function uniqueStrings(values: Array<string | null | undefined>) {
  return Array.from(new Set(values.map((value) => value?.trim()).filter((value): value is string => Boolean(value))))
}

function invalid(label: string): ValidationResult {
  return {
    ok: false,
    message: `${label} no longer exists in master data. Please refresh the product form and choose a valid value.`,
  }
}

async function loadRowsByIds<T extends { id: string }>(adminClient: SupabaseClient, table: string, ids: string[], columns: string) {
  if (ids.length < 1) return { rows: [] as T[], error: null }
  const { data, error } = await adminClient.from(table).select(columns).in('id', ids)
  return { rows: (data ?? []) as unknown as T[], error }
}

export type ProductMasterRowLoader = <T extends { id: string }>(table: string, ids: string[], columns: string) => Promise<{ rows: T[]; error: unknown }>

async function validateSimpleIds(load: ProductMasterRowLoader, table: string, ids: string[], label: string) {
  const { rows, error } = await load<{ id: string }>(table, ids, 'id')
  if (error) return { ok: false, message: 'Unable to validate the selected master data.' } as ValidationResult
  return rows.length === ids.length ? ({ ok: true } as ValidationResult) : invalid(label)
}

export async function validateProductMasterRows(
  load: ProductMasterRowLoader,
  payload: ProductMasterValidationPayload
): Promise<ValidationResult> {
  const categoryId = payload.main_category_id?.trim()
  if (!categoryId) return invalid('Selected category')

  const categoryCheck = await validateSimpleIds(load, 'catalog_categories', [categoryId], 'Selected category')
  if (!categoryCheck.ok) return categoryCheck

  const subcategoryIds = uniqueStrings([payload.subcategory_id, ...(payload.linked_subcategory_ids ?? [])])
  const { rows: subcategoryRows, error: subcategoryError } = await load<{ id: string; category_id: string }>(
    'catalog_subcategories',
    subcategoryIds,
    'id, category_id'
  )
  if (subcategoryError) return { ok: false, message: 'Unable to validate the selected subcategories.' }
  if (subcategoryRows.length !== subcategoryIds.length) return invalid('Selected subcategory')
  const primarySubcategory = payload.subcategory_id ? subcategoryRows.find((row) => row.id === payload.subcategory_id) : null
  if (primarySubcategory && primarySubcategory.category_id !== categoryId) {
    return { ok: false, message: 'Selected subcategory does not belong to the selected category. Please refresh and choose again.' }
  }

  const optionIds = uniqueStrings([payload.option_id, ...(payload.linked_option_ids ?? [])])
  const { rows: optionRows, error: optionError } = await load<{ id: string; subcategory_id: string }>(
    'catalog_options',
    optionIds,
    'id, subcategory_id'
  )
  if (optionError) return { ok: false, message: 'Unable to validate the selected options.' }
  if (optionRows.length !== optionIds.length) return invalid('Selected option')
  const primaryOption = payload.option_id ? optionRows.find((row) => row.id === payload.option_id) : null
  if (primaryOption && payload.subcategory_id && primaryOption.subcategory_id !== payload.subcategory_id) {
    return { ok: false, message: 'Selected option does not belong to the selected subcategory. Please refresh and choose again.' }
  }
  const allowedSubcategoryIds = new Set(subcategoryIds)
  const hasMismatchedLinkedOption = optionRows.some((row) => allowedSubcategoryIds.size > 0 && !allowedSubcategoryIds.has(row.subcategory_id))
  if (hasMismatchedLinkedOption) {
    return { ok: false, message: 'One selected option does not belong to the selected subcategory list. Please refresh and choose again.' }
  }

  const validations: Array<Promise<ValidationResult>> = []
  if (payload.style_id) validations.push(validateSimpleIds(load, 'catalog_styles', [payload.style_id], 'Selected style'))
  if (payload.gst_slab_id) validations.push(validateSimpleIds(load, 'catalog_gst_slabs', [payload.gst_slab_id], 'Selected GST slab'))

  const metalIds = uniqueStrings([...(payload.metal_ids ?? []), ...(payload.metal_variants ?? []).map((entry) => entry.metal_id)])
  if (metalIds.length > 0) validations.push(validateSimpleIds(load, 'catalog_metals', metalIds, 'Selected metal'))

  const certificateIds = uniqueStrings(payload.certificate_ids ?? [])
  if (certificateIds.length > 0) validations.push(validateSimpleIds(load, 'catalog_certificates', certificateIds, 'Selected certificate'))

  const materialValueIds = uniqueStrings(payload.material_value_ids ?? [])
  if (materialValueIds.length > 0) validations.push(validateSimpleIds(load, 'catalog_material_values', materialValueIds, 'Selected material value'))

  const shapeIds = uniqueStrings(payload.shape_ids ?? [])
  if (shapeIds.length > 0) validations.push(validateSimpleIds(load, 'catalog_stone_shapes', shapeIds, 'Selected stone shape'))

  if (payload.ring_enabled && payload.ring_category_id) {
    validations.push(validateSimpleIds(load, 'catalog_ring_categories', [payload.ring_category_id], 'Selected ring category'))
  }

  const simpleResults = await Promise.all(validations)
  const firstFailure = simpleResults.find((result) => !result.ok)
  if (firstFailure) return firstFailure

  const contentRuleIds = uniqueStrings([payload.shipping_rule_id, payload.care_warranty_rule_id])
  const { rows: contentRuleRows, error: contentRuleError } = await load<{ id: string; kind: string }>(
    'product_content_rules',
    contentRuleIds,
    'id, kind'
  )
  if (contentRuleError) return { ok: false, message: 'Unable to validate the selected content rules.' }
  if (contentRuleRows.length !== contentRuleIds.length) return invalid('Selected content rule')
  if (payload.shipping_rule_id && contentRuleRows.find((row) => row.id === payload.shipping_rule_id)?.kind !== 'shipping') {
    return { ok: false, message: 'Selected shipping rule is not a shipping rule. Please refresh and choose again.' }
  }
  if (payload.care_warranty_rule_id && contentRuleRows.find((row) => row.id === payload.care_warranty_rule_id)?.kind !== 'care_warranty') {
    return { ok: false, message: 'Selected care and warranty rule is not a care/warranty rule. Please refresh and choose again.' }
  }

  return { ok: true }
}

export async function validateProductMasterReferences(adminClient: SupabaseClient, payload: ProductMasterValidationPayload): Promise<ValidationResult> {
  return validateProductMasterRows((table, ids, columns) => loadRowsByIds(adminClient, table, ids, columns), payload)
}

import { revalidateTag, unstable_cache } from 'next/cache'
import { createSupabaseAdminClient } from '@/lib/admin-supabase'
import type { CatalogCategory, CatalogOption, CatalogSubcategory } from '@/lib/product-catalog'

export const PRODUCT_LIST_REFERENCE_CACHE_TAG = 'admin-product-list-reference-data'

async function loadProductListReferenceData() {
  const adminClient = createSupabaseAdminClient()
  const [categoriesResult, subcategoriesResult, optionsResult] = await Promise.all([
    adminClient.from('catalog_categories').select('id, code, name, slug, nav_type, direct_link_url, display_order, status'),
    adminClient.from('catalog_subcategories').select('id, category_id, name, slug, sub_type, display_order, status'),
    adminClient.from('catalog_options').select('id, subcategory_id, name, slug, display_order, status'),
  ])

  const error = categoriesResult.error || subcategoriesResult.error || optionsResult.error
  if (error) throw new Error(error.message)

  return {
    categories: (categoriesResult.data ?? []) as CatalogCategory[],
    subcategories: (subcategoriesResult.data ?? []) as CatalogSubcategory[],
    options: (optionsResult.data ?? []) as CatalogOption[],
  }
}

const getCachedProductListReferenceData = unstable_cache(
  loadProductListReferenceData,
  ['admin-product-list-reference-data'],
  {
    revalidate: 300,
    tags: [PRODUCT_LIST_REFERENCE_CACHE_TAG],
  }
)

export async function getProductListReferenceData() {
  try {
    return await getCachedProductListReferenceData()
  } catch {
    return loadProductListReferenceData()
  }
}

export function invalidateProductListReferenceData() {
  revalidateTag(PRODUCT_LIST_REFERENCE_CACHE_TAG, { expire: 0 })
}

import type { ProductFaqItem } from '@/lib/product-catalog'
import type { SupabaseClient } from '@supabase/supabase-js'

function isMissingRelation(error: { message?: string | null } | null | undefined, table: string) {
  return (
    error?.message?.includes(`relation "${table}" does not exist`) ||
    error?.message?.includes(`Could not find the table 'public.${table}' in the schema cache`)
  ) ?? false
}

export async function loadProductFaqItems(adminClient: SupabaseClient, productId: string) {
  const { data, error } = await adminClient
    .from('product_faq_items')
    .select('id, product_id, question, answer, sort_order, is_active, source')
    .eq('product_id', productId)
    .order('sort_order', { ascending: true })

  if (error) {
    if (isMissingRelation(error, 'product_faq_items')) return []
    throw error
  }

  return (data ?? []) as ProductFaqItem[]
}

export async function replaceProductFaqItems(adminClient: SupabaseClient, productId: string, items: ProductFaqItem[], source = 'admin') {
  const normalizedRows = items
    .map((item, index) => ({
      question: item.question?.trim() ?? '',
      answer: item.answer?.trim() ?? '',
      sort_order: Number(item.sort_order ?? index + 1),
      is_active: item.is_active !== false,
      source: item.source || source,
    }))
    .filter((item) => item.question && item.answer)
    .map((item, index) => ({
      ...item,
      product_id: productId,
      sort_order: item.sort_order || index + 1,
    }))

  const deleteResult = await adminClient.from('product_faq_items').delete().eq('product_id', productId)
  if (deleteResult.error) {
    if (isMissingRelation(deleteResult.error, 'product_faq_items')) return { ok: true }
    return { error: deleteResult.error }
  }

  if (normalizedRows.length < 1) return { ok: true }

  const insertResult = await adminClient.from('product_faq_items').insert(normalizedRows)
  if (insertResult.error) return { error: insertResult.error }
  return { ok: true }
}

import 'server-only'

import type { SupabaseClient } from '@supabase/supabase-js'
import type { ProductRecord } from '@/lib/product-catalog'
import { loadProductLinkSelections } from '@/lib/product-catalog-links'
import { loadProductCustomDropdowns } from '@/lib/product-custom-dropdowns'
import type { ProductEditorItem } from '@/lib/product-editor'
import { loadProductFaqItems } from '@/lib/product-faqs'
import { loadProductMetalVariantBundle } from '@/lib/product-metal-variants'

type ProductEditorLoadResult =
  | { status: 'found'; item: ProductEditorItem }
  | { status: 'not_found' }
  | { status: 'error'; message: string }

function isMissingRelation(error: { message?: string | null } | null | undefined, table: string) {
  return Boolean(
    error?.message?.includes(`relation "${table}" does not exist`) ||
      error?.message?.includes(`Could not find the table 'public.${table}' in the schema cache`)
  )
}

function optionalRows<T>(
  result: { data: T[] | null; error: { message?: string | null } | null },
  table: string
) {
  if (!result.error || isMissingRelation(result.error, table)) {
    return { data: result.error ? [] : (result.data ?? []) }
  }
  return { error: true as const }
}

export async function loadProductEditorItem(
  adminClient: SupabaseClient,
  lookupValue: string
): Promise<ProductEditorLoadResult> {
  const lookup = lookupValue.trim()
  if (!lookup) return { status: 'not_found' }

  try {
    const slugResult = await adminClient.from('products').select('id').eq('slug', lookup).maybeSingle()
    if (slugResult.error) return { status: 'error', message: 'Unable to load the product.' }

    const idResult = slugResult.data?.id
      ? slugResult
      : await adminClient.from('products').select('id').eq('id', lookup).maybeSingle()

    if (idResult.error) return { status: 'error', message: 'Unable to load the product.' }
    if (!idResult.data?.id) return { status: 'not_found' }

    const id = String(idResult.data.id)
    const [
      productResult,
      metalsResult,
      materialValuesResult,
      purityPricesResult,
      metalMediaResult,
      shapeResult,
      linkSelections,
      metalVariantBundle,
      faqItems,
      customDropdowns,
    ] = await Promise.all([
      adminClient.from('products').select('*').eq('id', id).single(),
      adminClient.from('product_metal_selections').select('metal_id').eq('product_id', id).order('sort_order', { ascending: true }),
      adminClient.from('product_material_value_selections').select('material_value_id').eq('product_id', id).order('sort_order', { ascending: true }),
      adminClient.from('product_purity_prices').select('*').eq('product_id', id).order('sort_order', { ascending: true }),
      adminClient.from('product_metal_media').select('*').eq('product_id', id),
      adminClient.from('product_stone_shapes').select('shape_id').eq('product_id', id),
      loadProductLinkSelections(adminClient, id),
      loadProductMetalVariantBundle(adminClient, id),
      loadProductFaqItems(adminClient, id),
      loadProductCustomDropdowns(adminClient, id),
    ])

    if (productResult.error || !productResult.data || customDropdowns.error) {
      return { status: 'error', message: 'Unable to load the complete product.' }
    }

    const metals = optionalRows(metalsResult, 'product_metal_selections')
    const materialValues = optionalRows(materialValuesResult, 'product_material_value_selections')
    const purityPrices = optionalRows(purityPricesResult, 'product_purity_prices')
    const metalMedia = optionalRows(metalMediaResult, 'product_metal_media')
    const shapes = optionalRows(shapeResult, 'product_stone_shapes')
    if (metals.error || materialValues.error || purityPrices.error || metalMedia.error || shapes.error) {
      return { status: 'error', message: 'Unable to load the complete product.' }
    }

    return {
      status: 'found',
      item: {
        ...(productResult.data as ProductRecord),
        metal_ids: metals.data.map((entry: { metal_id: string }) => entry.metal_id),
        linked_subcategory_ids: linkSelections.linkedSubcategoryIds,
        linked_option_ids: linkSelections.linkedOptionIds,
        material_value_ids: materialValues.data.map((entry: { material_value_id: string }) => entry.material_value_id),
        shape_ids: shapes.data.map((entry: { shape_id: string }) => entry.shape_id),
        purity_prices: purityPrices.data,
        metal_media: metalMedia.data,
        metal_variants: metalVariantBundle.metalVariants,
        default_variant_media_items: metalVariantBundle.defaultVariantMediaItems,
        faq_items: faqItems,
        custom_dropdowns: customDropdowns.data ?? [],
      },
    }
  } catch {
    return { status: 'error', message: 'Unable to load the product.' }
  }
}

import type { SupabaseClient } from '@supabase/supabase-js'

export type ProductCustomDropdownOption = {
  id: string
  label: string
  value: string
  is_enabled: boolean
  display_order: number
}

export type ProductCustomDropdown = {
  id: string
  name: string
  label: string
  is_enabled: boolean
  is_required: boolean
  display_order: number
  options: ProductCustomDropdownOption[]
}

function hasDropdownContent(group: ProductCustomDropdown) {
  return Boolean(
    group.name.trim() ||
    group.label.trim() ||
    group.options.some((option) => option.label.trim() || option.value.trim())
  )
}

function normalizedKey(label: string, fallback: string) {
  return label
    .trim()
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '') || fallback
}

function uniqueKey(base: string, used: Set<string>) {
  let candidate = base
  let suffix = 2
  while (used.has(candidate.toLowerCase())) candidate = `${base}_${suffix++}`
  used.add(candidate.toLowerCase())
  return candidate
}

export function normalizeProductCustomDropdowns(groups: ProductCustomDropdown[]) {
  const contentGroups = groups
    .filter(hasDropdownContent)
    .map((group) => ({
      ...group,
      name: group.name.trim(),
      label: group.label.trim(),
      options: group.options
        .filter((option) => option.label.trim() || option.value.trim())
        .map((option) => ({
          ...option,
          label: option.label.trim(),
          value: option.value.trim(),
        })),
    }))

  // Reserve stored identifiers first so newly generated ones can never replace or
  // collide with the stable values used by existing carts and orders.
  const usedNames = new Set(contentGroups.map((group) => group.name.toLowerCase()).filter(Boolean))
  return contentGroups.map((group) => {
    const name = group.name || uniqueKey(normalizedKey(group.label, 'dropdown'), usedNames)
    const usedValues = new Set(group.options.map((option) => option.value.toLowerCase()).filter(Boolean))
    const options = group.options.map((option) => ({
      ...option,
      value: option.value || uniqueKey(normalizedKey(option.label, 'option'), usedValues),
    }))
    return { ...group, name, options }
  })
}

export function validateProductCustomDropdowns(groups: ProductCustomDropdown[]) {
  const names = new Set<string>()
  const enabledGroups = normalizeProductCustomDropdowns(groups).filter((group) => group.is_enabled)
  if (!enabledGroups.length) return 'Add at least one enabled custom dropdown, or disable custom product dropdowns.'

  for (const group of enabledGroups) {
    const name = group.name.trim().toLowerCase()
    if (!group.label.trim()) return 'Every enabled dropdown needs a customer label.'
    if (names.has(name)) return 'Each enabled dropdown needs a unique customer label.'
    names.add(name)
    const values = new Set<string>()
    const enabled = group.options.filter((option) => option.is_enabled)
    if (!enabled.length) return `“${group.label.trim()}” needs at least one enabled option.`
    for (const option of enabled) {
      const value = option.value.trim().toLowerCase()
      if (!option.label.trim()) return `Every enabled option in “${group.label.trim()}” needs a customer-visible label.`
      if (values.has(value)) return `Each enabled option in “${group.label.trim()}” needs a unique label.`
      values.add(value)
    }
  }
  return null
}

export async function loadProductCustomDropdowns(adminClient: SupabaseClient, productId: string): Promise<{ data?: ProductCustomDropdown[]; error?: string }> {
  const groupsResult = await adminClient.from('product_custom_dropdowns').select('*').eq('product_id', productId).order('display_order')
  if (groupsResult.error) return { error: groupsResult.error.message }
  const groups = groupsResult.data ?? []
  if (!groups.length) return { data: [] }
  const typedGroups = groups as Array<Omit<ProductCustomDropdown, 'options'>>
  const optionsResult = await adminClient.from('product_custom_dropdown_options').select('*').in('dropdown_id', typedGroups.map((row) => row.id)).order('display_order')
  if (optionsResult.error) return { error: optionsResult.error.message }
  const options = (optionsResult.data ?? []) as Array<ProductCustomDropdownOption & { dropdown_id: string }>
  return { data: typedGroups.map((group) => ({ ...group, options: options.filter((option) => option.dropdown_id === group.id) })) }
}

export async function syncProductCustomDropdowns(adminClient: SupabaseClient, productId: string, groups: ProductCustomDropdown[], validateEnabledGroups = true) {
  const normalizedGroups = normalizeProductCustomDropdowns(groups)
  const validationError = validateEnabledGroups ? validateProductCustomDropdowns(normalizedGroups) : null
  if (validationError) return { error: validationError }

  const parentRows = normalizedGroups.map((group, index) => ({ id: group.id, product_id: productId, name: group.name, label: group.label, is_enabled: group.is_enabled, is_required: group.is_required, display_order: index }))
  if (parentRows.length) {
    const result = await adminClient.from('product_custom_dropdowns').upsert(parentRows, { onConflict: 'id' })
    if (result.error) return { error: result.error.message }
  }
  for (const group of normalizedGroups) {
    const children = group.options.map((option, index) => ({ id: option.id, dropdown_id: group.id, label: option.label, value: option.value, is_enabled: option.is_enabled, display_order: index }))
    if (children.length) {
      const result = await adminClient.from('product_custom_dropdown_options').upsert(children, { onConflict: 'id' })
      if (result.error) return { error: result.error.message }
    }
    const keep = children.map((row) => row.id)
    let stale = adminClient.from('product_custom_dropdown_options').delete().eq('dropdown_id', group.id)
    if (keep.length) stale = stale.not('id', 'in', `(${keep.join(',')})`)
    const staleResult = await stale
    if (staleResult.error) return { error: staleResult.error.message }
  }
  const keepParents = parentRows.map((row) => row.id)
  let staleParents = adminClient.from('product_custom_dropdowns').delete().eq('product_id', productId)
  if (keepParents.length) staleParents = staleParents.not('id', 'in', `(${keepParents.join(',')})`)
  const staleParentResult = await staleParents
  return staleParentResult.error ? { error: staleParentResult.error.message } : { error: null }
}

import type { SupabaseClient } from '@supabase/supabase-js'

function isMissingRelation(error: { message?: string | null } | null | undefined, table: string) {
  return (
    error?.message?.includes(`relation "${table}" does not exist`) ||
    error?.message?.includes(`Could not find the table 'public.${table}' in the schema cache`)
  ) ?? false
}

function uniqueOrderedIds(ids: Array<string | null | undefined>) {
  const seen = new Set<string>()
  const ordered: string[] = []

  for (const id of ids) {
    if (!id || seen.has(id)) continue
    seen.add(id)
    ordered.push(id)
  }

  return ordered
}

export function buildResolvedLinkedIds(primaryId: string | null | undefined, linkedIds: Array<string | null | undefined>) {
  return uniqueOrderedIds([primaryId, ...linkedIds])
}

export async function replaceProductSubcategoryLinks(
  adminClient: SupabaseClient,
  productId: string,
  primarySubcategoryId: string | null | undefined,
  linkedSubcategoryIds: Array<string | null | undefined>
) {
  const resolvedIds = buildResolvedLinkedIds(primarySubcategoryId, linkedSubcategoryIds)

  const deleteResult = await adminClient.from('product_subcategory_links').delete().eq('product_id', productId)
  if (deleteResult.error && !isMissingRelation(deleteResult.error, 'product_subcategory_links')) {
    return { error: deleteResult.error }
  }

  if (resolvedIds.length < 1) {
    return { ok: true }
  }

  const insertResult = await adminClient.from('product_subcategory_links').insert(
    resolvedIds.map((subcategoryId, index) => ({
      product_id: productId,
      subcategory_id: subcategoryId,
      is_primary: Boolean(primarySubcategoryId) && subcategoryId === primarySubcategoryId,
      sort_order: index + 1,
    }))
  )

  if (insertResult.error && !isMissingRelation(insertResult.error, 'product_subcategory_links')) {
    return { error: insertResult.error }
  }

  return { ok: true }
}

