/** Saves one navbar item only. Other menu items are intentionally outside this transaction. */
export async function saveNavbarItem(access: Access, itemId: string, input: unknown) {
  if (!uuidPattern.test(itemId)) return NextResponse.json({ error: 'Invalid navbar item.' }, { status: 400 })
  const parsed = itemEnvelope.safeParse(input)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.issues[0]?.message ?? 'Invalid navbar save request.' }, { status: 400 })
  if (parsed.data.item.id !== itemId) return NextResponse.json({ error: 'Navbar item does not match this edit route.' }, { status: 400 })
  const deleted = parsed.data.deleted_ids
  if (![deleted.sections, deleted.links, deleted.source_items, deleted.featured_cards].every(unique)) return NextResponse.json({ error: 'Deleted navbar IDs must be unique.' }, { status: 400 })

  const navItem = normalizeNavbarItemForSave(parsed.data.item)
  const sections: Record<string, unknown>[] = []
  const links: Record<string, unknown>[] = []
  const sourceItems: Record<string, unknown>[] = []
  for (const [sectionIndex, navSection] of (navItem.type === 'mega' ? navItem.sections ?? [] : []).entries()) {
    const sectionKey = navSection.id
    const sectionType = mapSectionTypeToDb(navSection.type)
    sections.push({ key: sectionKey, id: uuidPattern.test(navSection.id) ? navSection.id : null, title: navSection.title, icon_svg_path: navSection.iconSvgPath ?? null, section_type: sectionType, source_subcategory_id: sectionType === 'category_list' ? navSection.sourceSubcategoryId : null, source_category_slug: sectionType === 'category_link' ? navSection.sourceCategorySlug ?? null : null, enable_category_link: navSection.enableCategoryLink ?? false, linked_category_id: navSection.linkedCategoryId ?? null, column_number: Math.max(1, navSection.column), show_as_filter: navSection.showAsFilter ?? false, display_order: sectionIndex + 1, status: navItem.visible ? 'active' : 'hidden' })
    for (const [linkIndex, navLink] of navSection.links.entries()) links.push({ id: navLink.id ?? null, section_key: sectionKey, label: navLink.label, url: navLink.url, display_order: linkIndex + 1, status: navItem.visible ? 'active' : 'hidden' })
    for (const [sourceIndex, navSource] of (navSection.selectedSourceItems ?? []).entries()) sourceItems.push({ id: navSource.id ?? null, section_key: sectionKey, source_kind: navSource.sourceKind, source_item_id: navSource.sourceItemId, sort_order: navSource.sortOrder || sourceIndex + 1, is_active: navSource.isActive })
  }
  const itemRow = { id: itemId, label: navItem.label, slug: navItem.slug, item_type: navItem.type === 'mega' ? 'mega_menu' : 'direct_link', linked_category_id: navItem.type === 'mega' ? navItem.linkedCategoryId ?? null : null, direct_link_url: navItem.type === 'direct' ? navItem.url ?? '/' : null, status: navItem.visible ? 'active' : 'hidden' }
  const card = navItem.featuredImage ?? { enabled: false, imageUrl: '', buttonLabel: '', buttonUrl: '', imageAlt: navItem.label }
  const featured = { id: card.id ?? null, image_path: card.imageUrl || null, image_alt: card.imageAlt || navItem.label, button_label: card.buttonLabel || null, button_url: card.buttonUrl || null, enabled: card.enabled }
  const { data, error } = await navbarMutation(access, 'navbar_item_save_v1', { p_request_id: parsed.data.request_id, p_expected_revision: parsed.data.expected_revision, p_item_id: itemId, p_item: itemRow, p_sections: sections, p_links: links, p_source_items: sourceItems, p_featured_card: featured, p_deleted_section_ids: deleted.sections, p_deleted_link_ids: deleted.links, p_deleted_source_item_ids: ('provider' in access ? deleted.source_items : deleted.source_items.map(Number)), p_deleted_featured_card_ids: deleted.featured_cards })
  if (error) return navbarSaveErrorResponse(error)
  return NextResponse.json({ ok: true, revision: (data as { revision?: string } | null)?.revision }, { headers: { 'Cache-Control': 'no-store' } })
}

import type { DbExecutor } from './db/query'
import { createNavbarRepository } from './db/admin-repositories/navbar'
import { loadRdsProductBootstrap } from './db/admin-repositories/product-bootstrap'
import type { SupabaseClient } from '@supabase/supabase-js'
import {
  buildFallbackNavbarItems,
  buildNavbarItemsFromRows,
  syncNavbarItemsWithCatalog,
  type NavbarBuilderPayload,
} from './navbar'
import type { CatalogCategory } from './product-catalog'

export type NavbarSnapshot = {
  items: Parameters<typeof buildNavbarItemsFromRows>[0]['items']
  sections: Parameters<typeof buildNavbarItemsFromRows>[0]['sections']
  links: Parameters<typeof buildNavbarItemsFromRows>[0]['sectionLinks']
  source_items: Parameters<typeof buildNavbarItemsFromRows>[0]['sectionSourceItems']
  featured_cards: Parameters<typeof buildNavbarItemsFromRows>[0]['featuredCards']
  revision: string
  item_revisions?: Record<string, string>
}

export async function loadNavbarBuilderData(client: SupabaseClient): Promise<NavbarBuilderPayload> {
  const [categoriesResult, subcategoriesResult, optionsResult, metalsResult, stoneShapesResult, ringSizesResult, certificatesResult, stylesResult, snapshotResult] = await Promise.all([
    client.from('catalog_categories').select('*').order('display_order', { ascending: true }),
    client.from('catalog_subcategories').select('*').order('display_order', { ascending: true }),
    client.from('catalog_options').select('*').order('display_order', { ascending: true }),
    client.from('catalog_metals').select('*').order('display_order', { ascending: true }),
    client.from('catalog_stone_shapes').select('*').order('display_order', { ascending: true }),
    client.from('catalog_ring_sizes').select('*').order('display_order', { ascending: true }),
    client.from('catalog_certificates').select('*').order('display_order', { ascending: true }),
    client.from('catalog_styles').select('*').order('display_order', { ascending: true }),
    client.rpc('navbar_snapshot_v1'),
  ])

  const error = categoriesResult.error || subcategoriesResult.error || optionsResult.error || metalsResult.error || stoneShapesResult.error || ringSizesResult.error || certificatesResult.error || stylesResult.error || snapshotResult.error
  if (error) {
    if (snapshotResult.error?.code === 'PGRST202' || snapshotResult.error?.code === '42883') throw new Error('The navbar editor is awaiting its database migration.')
    throw new Error('Unable to load the navbar editor.')
  }

  const categories = (categoriesResult.data ?? []) as CatalogCategory[]
  const subcategories = subcategoriesResult.data ?? []
  const options = optionsResult.data ?? []
  const metals = metalsResult.data ?? []
  const stoneShapes = stoneShapesResult.data ?? []
  const ringSizes = ringSizesResult.data ?? []
  const certificates = certificatesResult.data ?? []
  const styles = stylesResult.data ?? []
  const snapshot = snapshotResult.data as NavbarSnapshot
  const builtItems = snapshot.items.length
    ? buildNavbarItemsFromRows({
        items: snapshot.items,
        sections: snapshot.sections,
        sectionLinks: snapshot.links,
        sectionSourceItems: snapshot.source_items,
        featuredCards: snapshot.featured_cards,
        categories,
        subcategories,
        options,
        metals,
        stoneShapes,
        ringSizes,
        certificates,
        styles,
      })
    : buildFallbackNavbarItems(categories, subcategories, options)

  const itemRevisionResults = await Promise.all(
    snapshot.items.map((entry) => client.rpc('navbar_item_snapshot_v1', { p_item_id: entry.id }))
  )
  const itemRevisionError = itemRevisionResults.find((entry) => entry.error)?.error
  if (itemRevisionError) {
    if (itemRevisionError.code === 'PGRST202' || itemRevisionError.code === '42883') throw new Error('The navbar editor is awaiting its database migration.')
    throw new Error('Unable to load the navbar editor.')
  }
  const itemRevisions = Object.fromEntries(
    snapshot.items.map((entry, index) => [entry.id, ((itemRevisionResults[index].data as { revision?: string } | null)?.revision ?? '')])
  )

  return {
    revision: snapshot.revision,
    itemRevisions,
    items: syncNavbarItemsWithCatalog(builtItems, categories, subcategories, options),
    categories,
    subcategories,
    options,
    metals,
    stoneShapes,
    ringSizes,
    certificates,
    styles,
  }
}

/** Authorized executor only; all reference/snapshot failures deny rather than empty success. */
export async function loadRdsNavbarBuilderData(db: DbExecutor): Promise<NavbarBuilderPayload> {
  const references = await loadRdsProductBootstrap(db, 'all')
  const repo = createNavbarRepository(db)
  const snapshot = await repo.execute('navbar_snapshot_v1', {}) as NavbarSnapshot
  const { categories = [], subcategories = [], options = [], metals = [], stoneShapes = [], ringSizes = [], certificates = [], styles = [] } = references as NavbarBuilderPayload
  const builtItems = snapshot.items.length
    ? buildNavbarItemsFromRows({ items: snapshot.items, sections: snapshot.sections, sectionLinks: snapshot.links, sectionSourceItems: snapshot.source_items, featuredCards: snapshot.featured_cards, categories, subcategories, options, metals, stoneShapes, ringSizes, certificates, styles })
    : buildFallbackNavbarItems(categories, subcategories, options)
  const itemRevisions: Record<string, string> = {}
  for (const entry of snapshot.items) {
    const item = await repo.execute('navbar_item_snapshot_v1', { p_item_id: entry.id }) as { revision: string }
    itemRevisions[entry.id] = item.revision
  }
  // B2 uses READ COMMITTED. Refuse mixed content/revisions if another editor
  // changed the menu between the full snapshot and item revision reads.
  const confirmed = await repo.execute('navbar_snapshot_v1', {})
  if (confirmed.revision !== snapshot.revision) throw new Error('Navbar changed during loading')
  return { revision: snapshot.revision, itemRevisions, items: syncNavbarItemsWithCatalog(builtItems, categories, subcategories, options), categories, subcategories, options, metals, stoneShapes, ringSizes, certificates, styles }
}

import { normalizeNavbarItemForSave, type NavbarItem } from './navbar'

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const numericPattern = /^[1-9][0-9]*$/

function collectIds(items: NavbarItem[]) {
  const sectionIds: string[] = []
  const linkIds: string[] = []
  const sourceItemIds: string[] = []
  const featuredCardIds: string[] = []

  for (const item of items) {
    if (item.featuredImage?.id && uuidPattern.test(item.featuredImage.id)) featuredCardIds.push(item.featuredImage.id)
    for (const section of item.sections ?? []) {
      if (uuidPattern.test(section.id)) sectionIds.push(section.id)
      for (const link of section.links) if (link.id && uuidPattern.test(link.id)) linkIds.push(link.id)
      for (const source of section.selectedSourceItems ?? []) if (source.id && numericPattern.test(source.id)) sourceItemIds.push(source.id)
    }
  }

  return { sectionIds, linkIds, sourceItemIds, featuredCardIds }
}

function removed(original: string[], current: string[]) {
  const retained = new Set(current)
  return original.filter((id) => !retained.has(id))
}

export function navbarSaveBody(items: NavbarItem[], originalItems: NavbarItem[], expectedRevision: string) {
  const original = collectIds(originalItems)
  const normalizedItems = items.map(normalizeNavbarItemForSave)
  const current = collectIds(normalizedItems)
  return JSON.stringify({
    request_id: crypto.randomUUID(),
    expected_revision: expectedRevision,
    items: normalizedItems,
    deleted_ids: {
      sections: removed(original.sectionIds, current.sectionIds),
      links: removed(original.linkIds, current.linkIds),
      source_items: removed(original.sourceItemIds, current.sourceItemIds),
      featured_cards: removed(original.featuredCardIds, current.featuredCardIds),
    },
  })
}

/** Builds an intentionally item-scoped save request for the dedicated edit route. */
export function navbarItemSaveBody(item: NavbarItem, originalItem: NavbarItem, expectedRevision: string) {
  const original = collectIds([originalItem])
  const normalizedItem = normalizeNavbarItemForSave(item)
  const current = collectIds([normalizedItem])
  return JSON.stringify({
    request_id: crypto.randomUUID(),
    expected_revision: expectedRevision,
    item: normalizedItem,
    deleted_ids: {
      sections: removed(original.sectionIds, current.sectionIds),
      links: removed(original.linkIds, current.linkIds),
      source_items: removed(original.sourceItemIds, current.sourceItemIds),
      featured_cards: removed(original.featuredCardIds, current.featuredCardIds),
    },
  })
}

export function formatUsd(amount: number | null | undefined, options?: { maximumFractionDigits?: number }) {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: options?.maximumFractionDigits ?? 0,
  }).format(Number(amount || 0))
}

import type { SupabaseClient } from '@supabase/supabase-js'

export type InventoryDataItem = {
  id: string
  name: string
  slug: string
  sku: string
  stockQuantity: number
  status: 'in-stock' | 'low-stock' | 'out-of-stock'
  categoryPath: string
  updatedAt: string
}

type InventoryProductRow = {
  id: string
  name: string
  slug: string
  sku: string | null
  stock_quantity: number | null
  updated_at: string
  main_category_id: string | null
  subcategory_id: string | null
  option_id: string | null
}

type NamedRow = { id: string; name: string }
type SubcategoryLinkRow = { product_id: string; subcategory_id: string; is_primary: boolean | null }
type OptionLinkRow = { product_id: string; option_id: string; is_primary: boolean | null }

function buildDisplayCategoryPath(primaryPath: string, linkedSubcategoryNames: string[], linkedOptionNames: string[]) {
  const linkedParts = [...linkedSubcategoryNames, ...linkedOptionNames].filter(Boolean)
  return linkedParts.length ? `${primaryPath} | Linked: ${linkedParts.join(', ')}` : primaryPath
}

export async function loadInventoryItems(client: SupabaseClient, query = ''): Promise<InventoryDataItem[]> {
  const { data, error } = await client
    .from('products')
    .select('id, name, slug, sku, stock_quantity, updated_at, main_category_id, subcategory_id, option_id')
    .order('updated_at', { ascending: false })

  if (error) throw new Error('Unable to load inventory products.')
  const products = (data ?? []) as InventoryProductRow[]
  const categoryIds = [...new Set(products.flatMap((item) => item.main_category_id ? [item.main_category_id] : []))]
  const subcategoryIds = [...new Set(products.flatMap((item) => item.subcategory_id ? [item.subcategory_id] : []))]
  const optionIds = [...new Set(products.flatMap((item) => item.option_id ? [item.option_id] : []))]
  const productIds = products.map((item) => item.id)

  const [categoriesResult, subcategoriesResult, optionsResult, subcategoryLinksResult, optionLinksResult] = await Promise.all([
    categoryIds.length ? client.from('catalog_categories').select('id, name').in('id', categoryIds) : Promise.resolve({ data: [] as NamedRow[], error: null }),
    subcategoryIds.length ? client.from('catalog_subcategories').select('id, name').in('id', subcategoryIds) : Promise.resolve({ data: [] as NamedRow[], error: null }),
    optionIds.length ? client.from('catalog_options').select('id, name').in('id', optionIds) : Promise.resolve({ data: [] as NamedRow[], error: null }),
    productIds.length ? client.from('product_subcategory_links').select('product_id, subcategory_id, is_primary').in('product_id', productIds) : Promise.resolve({ data: [] as SubcategoryLinkRow[], error: null }),
    productIds.length ? client.from('product_option_links').select('product_id, option_id, is_primary').in('product_id', productIds) : Promise.resolve({ data: [] as OptionLinkRow[], error: null }),
  ])

  if ([categoriesResult, subcategoriesResult, optionsResult, subcategoryLinksResult, optionLinksResult].some((result) => result.error)) {
    throw new Error('Unable to load inventory catalog details.')
  }

  const categoryMap = new Map(((categoriesResult.data ?? []) as NamedRow[]).map((item) => [item.id, item.name]))
  const subcategoryMap = new Map(((subcategoriesResult.data ?? []) as NamedRow[]).map((item) => [item.id, item.name]))
  const optionMap = new Map(((optionsResult.data ?? []) as NamedRow[]).map((item) => [item.id, item.name]))
  const linkedSubcategoryMap = new Map<string, string[]>()
  for (const row of (subcategoryLinksResult.data ?? []) as SubcategoryLinkRow[]) {
    if (row.is_primary) continue
    const name = subcategoryMap.get(row.subcategory_id)
    if (name) linkedSubcategoryMap.set(row.product_id, [...(linkedSubcategoryMap.get(row.product_id) ?? []), name])
  }
  const linkedOptionMap = new Map<string, string[]>()
  for (const row of (optionLinksResult.data ?? []) as OptionLinkRow[]) {
    if (row.is_primary) continue
    const name = optionMap.get(row.option_id)
    if (name) linkedOptionMap.set(row.product_id, [...(linkedOptionMap.get(row.product_id) ?? []), name])
  }

  const normalizedQuery = query.trim().toLowerCase()
  return products.map((product) => {
    const stock = Number(product.stock_quantity ?? 0)
    const primaryPath = [categoryMap.get(product.main_category_id ?? ''), subcategoryMap.get(product.subcategory_id ?? ''), optionMap.get(product.option_id ?? '')].filter(Boolean).join(' > ')
    return {
      id: product.id, name: product.name, slug: product.slug, sku: product.sku ?? '', stockQuantity: stock,
      status: stock <= 0 ? 'out-of-stock' as const : stock <= 5 ? 'low-stock' as const : 'in-stock' as const,
      categoryPath: buildDisplayCategoryPath(primaryPath, linkedSubcategoryMap.get(product.id) ?? [], linkedOptionMap.get(product.id) ?? []),
      updatedAt: product.updated_at,
    }
  }).filter((item) => !normalizedQuery || `${item.name} ${item.sku} ${item.categoryPath}`.toLowerCase().includes(normalizedQuery))
}

const ALLOWED_HOSTS = new Set(['instagram.com', 'www.instagram.com'])
const ALLOWED_TYPES = new Set(['reel', 'reels', 'p', 'tv'])
const SHORTCODE_PATTERN = /^[A-Za-z0-9_-]+$/
export function canonicalizeInstagramUrl(value: unknown): string | null {
  if (typeof value !== 'string' || value.length > 500) return null
  try {
    const url = new URL(value.trim())
    if (url.protocol !== 'https:' || !ALLOWED_HOSTS.has(url.hostname.toLowerCase()) || url.username || url.password || url.port || url.hash) return null
    const parts = url.pathname.split('/').filter(Boolean)
    if (parts.length !== 2 || !ALLOWED_TYPES.has(parts[0].toLowerCase()) || !SHORTCODE_PATTERN.test(parts[1])) return null
    return `https://www.instagram.com/${parts[0].toLowerCase()}/${parts[1]}/`
  } catch { return null }
}

/** Conservative XML subset: quoted attributes, no declarations/entities, active elements or external references. */
export function validateAwsSvg(buffer: Buffer) {
  let text = buffer.toString('utf8').trim()
  if (buffer.includes(0) || text.includes('\ufffd')) return false
  text = text.replace(/^<\?xml\s+[^?]*\?>\s*/i, '').replace(/<!--[\s\S]*?-->/g, '')
  if (/<!|<\?|&(?:#|[a-z]+;)/i.test(text)) return false
  const tags = new Set(['svg','g','defs','path','rect','circle','ellipse','line','polyline','polygon','title','desc','text','tspan','use','symbol','clipPath','mask','linearGradient','radialGradient','stop','pattern'])
  const stack: string[] = []
  let root = false, end = 0
  for (const match of text.matchAll(/<([^<>]+)>/g)) {
    if (text.slice(end, match.index).includes('<')) return false
    const token = match[1], closing = token.startsWith('/'), self = token.endsWith('/')
    const parsed = /^(\/)?([A-Za-z][A-Za-z0-9]*)([\s\S]*?)(\/)?$/.exec(token)
    if (!parsed || !tags.has(parsed[2])) return false
    const name = parsed[2], attrs = parsed[3]
    if (closing) {
      if (attrs.trim() || self || stack.pop() !== name) return false
    } else {
      if (!root) { if (name !== 'svg') return false; root = true }
      else if (!stack.length) return false
      let offset = 0
      const seen = new Set<string>()
      for (const attr of attrs.matchAll(/\s+([A-Za-z_:][A-Za-z0-9_:.-]*)\s*=\s*(["'])([\s\S]*?)\2/g)) {
        if (attrs.slice(offset, attr.index).trim()) return false
        const key = attr[1], value = attr[3]
        if (seen.has(key) || /^on/i.test(key) || key === 'style' || /[<>&\\]|javascript:|data:|https?:|\/\/|@/i.test(value)) {
          if (!(key === 'xmlns' && value === 'http://www.w3.org/2000/svg') && !(key === 'xmlns:xlink' && value === 'http://www.w3.org/1999/xlink')) return false
        }
        if ((key.includes(':') && !['xmlns:xlink','xlink:href','xml:space'].includes(key)) || (key === 'href' || key === 'xlink:href') && !/^#[A-Za-z0-9_-]+$/.test(value)) return false
        if (/url\(/i.test(value) && !/^url\(#[A-Za-z0-9_-]+\)$/.test(value)) return false
        seen.add(key); offset = attr.index + attr[0].length
      }
      if (attrs.slice(offset).trim()) return false
      if (!self) stack.push(name)
    }
    end = match.index + match[0].length
  }
  return root && stack.length === 0 && !text.slice(end).trim()
}

export class ImageBodyTooLarge extends Error {}
export async function boundedImageForm(request: Request, maxBytes: number): Promise<FormData | null> {
  const reader = request.body?.getReader()
  if (!reader) return null
  const chunks: Uint8Array[] = []
  let bytes = 0
  try {
    while (true) {
      const chunk = await reader.read()
      if (chunk.done) break
      bytes += chunk.value.length
      if (bytes > maxBytes) { await reader.cancel(); throw new ImageBodyTooLarge() }
      chunks.push(chunk.value)
    }
    return await new Response(Buffer.concat(chunks), { headers: { 'content-type': request.headers.get('content-type') ?? '' } }).formData()
  } catch (error) { if (error instanceof ImageBodyTooLarge) throw error; return null }
  finally { reader.releaseLock() }
}

'use client'
import { isCanonicalAwsImageReference } from './image-reference'

const endpoints = /^\/api\/(?:cms\/uploads\/[a-z-]+|catalog\/(?:categories|subcategories|options|styles|stone-shapes)\/upload|navbar\/(?:section-icon|featured-image)|products\/media|bespoke\/media)$/
export async function readClientImageProvider(): Promise<'legacy' | 'aws'> {
  const response = await fetch('/api/images/provider', { credentials: 'same-origin', cache: 'no-store' })
  const payload = await response.json().catch(() => null)
  if (!response.ok || !['legacy', 'aws'].includes(payload?.provider)) throw new Error('Image service unavailable.')
  return payload.provider
}

/** null explicitly means legacy mode. Any selected AWS failure propagates without fallback. */
export async function tryUploadAwsImage(file: File, endpoint: string, fields: Record<string, string> = {}, activity?: { start: () => void; finish: (ok: boolean) => void }): Promise<string | null> {
  if (!endpoints.test(endpoint)) throw new Error('Invalid image endpoint.')
  if (await readClientImageProvider() === 'legacy') return null
  activity?.start()
  let ok = false
  try {
  const sessionResponse = await fetch('/api/auth/session', { credentials: 'same-origin', cache: 'no-store' })
  const session = await sessionResponse.json().catch(() => null)
  if (!sessionResponse.ok || session?.authenticated !== true || typeof session.csrfToken !== 'string' || !session.csrfToken) throw new Error('Please sign in again.')
  const form = new FormData()
  form.set('file', file)
  for (const [key, value] of Object.entries(fields)) if (key !== 'file') form.set(key, value)
  const response = await fetch(endpoint, { method: 'POST', credentials: 'same-origin', headers: { 'x-admin-csrf': session.csrfToken, 'x-admin-image-upload': '1' }, body: form })
  const payload = await response.json().catch(() => null)
  if (!response.ok || payload?.provider !== 's3' || !isCanonicalAwsImageReference(payload.path) || payload.path !== payload.url) throw new Error('Unable to upload image.')
  ok = true
  return payload.path
  } finally { activity?.finish(ok) }
}

import 'server-only'
import { NextResponse } from 'next/server'
import { readImageProvider, imageTarget, type ImageContext } from './image-provider'
import { authorizeProductRequest } from './product-session-runtime'
import { ProductSessionError } from './product-session-error'
import { handleAdminImageUpload, type UploadConfig } from './admin-image-upload'

export async function handleImageUpload(request: Request, config: UploadConfig, context: ImageContext = 'content'): Promise<Response> {
  try {
    if (readImageProvider() === 'aws') {
      const { actor } = await authorizeProductRequest(request, true)
      return handleAdminImageUpload(request, { provider: 'aws', actor, target: imageTarget(context) }, config)
    }
  } catch (error) {
    return NextResponse.json({ error: 'Image service unavailable.' }, { status: error instanceof ProductSessionError ? error.status : 503, headers: { 'Cache-Control': 'no-store' } })
  }
  const { assertAdmin } = await import('./cms-auth')
  const access = await assertAdmin(request)
  if ('error' in access) return access.error!
  return handleAdminImageUpload(request, access, config)
}

/** Direct image protocols lack content validation/finalization; never issue AWS signatures. */
export async function denyAwsImageSigning(request: Request): Promise<Response | null> {
  try {
    if (readImageProvider() === 'legacy') return null
    await authorizeProductRequest(request, true)
    return NextResponse.json({ error: 'Use the authenticated image upload endpoint.' }, { status: 503, headers: { 'Cache-Control': 'no-store' } })
  } catch (error) {
    return NextResponse.json({ error: 'Image service unavailable.' }, { status: error instanceof ProductSessionError ? error.status : 503, headers: { 'Cache-Control': 'no-store' } })
  }
}

/** New AWS references are absolute permanent URLs. Relative legacy keys never change origin. */
export function isCanonicalAwsImageReference(value: unknown): value is string {
  if (typeof value !== 'string') return false
  try {
    const url = new URL(value)
    return url.protocol === 'https:' && ['media.houseofdiams.com','content.houseofdiams.com'].includes(url.hostname)
      && !url.port && !url.username && !url.password && !url.search && !url.hash
      && /^\/(?:[a-zA-Z0-9_-]+\/)+[a-zA-Z0-9_.-]+\.(?:webp|svg)$/.test(url.pathname)
      && !url.pathname.includes('..')
  } catch { return false }
}

export function resolveStoredImage(input: string | null | undefined, bucket = process.env.NEXT_PUBLIC_SUPABASE_COLLECTION_BUCKET || 'hod') {
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL?.replace(/\/+$/, '')
  return resolveImageReference(input, base ? `${base}/storage/v1/object/public/${bucket}` : undefined)
}

export function resolveImageReference(input: string | null | undefined, legacyBase?: string): string | null {
  const value = input?.trim()
  if (!value || /[\u0000-\u001f\\]/.test(value) || value.startsWith('//')) return null
  if (/^https?:\/\//i.test(value)) {
    try {
      const url = new URL(value)
      if (url.username || url.password) return null
      // Expiring signatures must never become a new canonical media reference.
      // Legacy stored signed URLs remain unchanged for compatibility, never rewritten.
      return value
    } catch { return null }
  }
  if (/^blob:/i.test(value)) return value
  if (/^[a-z][a-z0-9+.-]*:/i.test(value)) return null
  let decoded: string
  try { decoded = decodeURIComponent(value.split(/[?#]/)[0]) } catch { return null }
  if (decoded.split('/').some(segment => segment === '..' || segment === '.') || /[\\\u0000-\u001f]/.test(decoded)) return null
  if (value.startsWith('/')) return value
  return legacyBase ? `${legacyBase.replace(/\/+$/, '')}/${value}` : null
}

import 'server-only'
import { readAdminAuthProvider } from './auth/integration'

export type ImageProvider = 'legacy' | 'aws'
export function readImageProvider(env: NodeJS.ProcessEnv = process.env): ImageProvider {
  readAdminAuthProvider(env)
  const value = env.ADMIN_IMAGE_PROVIDER
  if (!value || value === 'legacy') return 'legacy'
  if (value === 'aws') return 'aws'
  throw new Error('Image service unavailable.')
}

export type ImageContext = 'product' | 'content'
export function imageTarget(context: ImageContext, env: NodeJS.ProcessEnv = process.env) {
  // Historical admin CMS objects are in the product bucket. New content routing
  // requires separate review; never reinterpret or move those existing keys.
  if (context === 'content' && env.ADMIN_IMAGE_CONTENT_ROUTING_VERIFIED !== 'true') throw new Error('Image service unavailable.')
  const bucket = context === 'product' ? env.AWS_MEDIA_BUCKET : env.AWS_CONTENT_BUCKET
  const baseUrl = context === 'product' ? env.NEXT_PUBLIC_MEDIA_CDN_BASE_URL : env.AWS_CONTENT_CDN_BASE_URL
  const expected = context === 'product'
    ? { bucket: 'house-of-diams', baseUrl: 'https://media.houseofdiams.com' }
    : { bucket: 'house-of-diams-hod', baseUrl: 'https://content.houseofdiams.com' }
  if (bucket?.trim() !== expected.bucket || baseUrl?.trim().replace(/\/+$/, '') !== expected.baseUrl) throw new Error('Image service unavailable.')
  return expected
}

import 'server-only'
import { readImageProvider } from './image-provider'
import { handleImageUpload } from './image-route'

/** The marker selects only the image branch; authority still comes from server mode + B1. */
export async function selectedMixedImage(request: Request, context: 'product' | 'bespoke' | 'about'): Promise<Response | null> {
  if (request.headers.get('x-admin-image-upload') !== '1') return null
  try { if (readImageProvider() === 'legacy') return null }
  catch { return Response.json({ error: 'Image service unavailable.' }, { status: 503 }) }
  return handleImageUpload(request, {
    bucket: process.env.SUPABASE_COLLECTION_BUCKET ?? 'hod',
    maxBytes: (context === 'product' ? 25 : context === 'bespoke' ? 10 : 8) * 1024 * 1024,
    rasterWidth: context === 'about' ? 2400 : 2200,
    preserveAspectRatio: context === 'about',
    quality: context === 'about' ? 86 : 84,
    successStatus: context === 'about' ? 200 : 201,
    validateForm: form => {
      const kind = form.get('kind')
      if (kind !== 'image' && !(context === 'about' && kind === 'poster')) return 'Invalid image upload kind.'
      if (context === 'product' && !['products', 'hiphop'].includes(String(form.get('folder')))) return 'Invalid product media folder.'
      return null
    },
    buildPath: (extension, form) => context === 'product'
      ? `${form.get('folder')}/images/${crypto.randomUUID()}.${extension}`
      : context === 'bespoke' ? `bespoke/images/${crypto.randomUUID()}.${extension}`
        : `about/hero/${form.get('kind')}/${crypto.randomUUID()}.${extension}`,
  }, context === 'product' ? 'product' : 'content')
}

/** Old callers may still send bearer requests, but selected AWS images never write legacy storage. */
export function denyLegacyImageInAwsMode(): Response | null {
  try {
    if (readImageProvider() === 'legacy') return null
    return Response.json({ error: 'Use the authenticated image upload protocol.' }, { status: 409 })
  } catch { return Response.json({ error: 'Image service unavailable.' }, { status: 503 }) }
}

type EducationSlugClient = {
  from: (table: 'education_posts') => {
    select: (columns: string) => {
      eq: (column: string, value: string) => {
        maybeSingle: () => Promise<{ data: { id: number } | null; error: { message?: string } | null }>
      }
    }
  }
}

export function createEducationSlug(title: string) {
  const slug = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-')

  return slug || `education-${Date.now()}`
}

export function isCleanEducationSlug(slug: string) {
  return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)
}

export async function createUniqueEducationSlug(
  adminClient: EducationSlugClient,
  title: string,
  currentPostId?: number
) {
  const baseSlug = createEducationSlug(title)
  let slug = baseSlug
  let suffix = 2

  while (true) {
    const { data, error } = await adminClient
      .from('education_posts')
      .select('id')
      .eq('slug', slug)
      .maybeSingle()

    if (error) throw new Error(error.message ?? 'Unable to validate education URL.')
    if (!data || data.id === currentPostId) return slug

    slug = `${baseSlug}-${suffix}`
    suffix += 1
  }
}

'use client'

import { cmsFetch } from '@/lib/cms-transport'

export type DocsAdminPayload = {
  page?: { id?: number | string; slug?: string; eyebrow?: string; title?: string; subtitle?: string; faq_category_id?: number | string | null } | null
  blocks?: Array<{ id?: number | string; sort_order: number; heading: string; description: string; body: string }>
  faqCategories?: Array<{ id: number | string; name: string; slug: string; image_path?: string | null; image_alt?: string; is_active: boolean }>
  revision?: string
  error?: string
}

type CacheEntry = { payload: DocsAdminPayload; cachedAt: number }

const CACHE_TTL_MS = 60_000
const memoryCache = new Map<string, CacheEntry>()
const pendingRequests = new Map<string, Promise<DocsAdminPayload>>()

export function getCachedDocsPage(slug: string): DocsAdminPayload | null {
  const memoryEntry = memoryCache.get(slug)
  if (memoryEntry && Date.now() - memoryEntry.cachedAt < CACHE_TTL_MS && /^[a-f0-9]{32}$/.test(memoryEntry.payload.revision ?? '')) {
    return memoryEntry.payload
  }
  if (memoryEntry) memoryCache.delete(slug)
  return null
}

export function setCachedDocsPage(slug: string, payload: DocsAdminPayload) {
  const entry = { payload, cachedAt: Date.now() }
  memoryCache.set(slug, entry)
}

export function loadDocsPage(slug: string): Promise<DocsAdminPayload> {
  const cached = getCachedDocsPage(slug)
  if (cached) return Promise.resolve(cached)

  const pending = pendingRequests.get(slug)
  if (pending) return pending

  const request = cmsFetch(`/api/cms/docs/${slug}`, { cache: 'no-store' })
    .then(async (response) => {
      const payload = (await response.json().catch(() => null)) as DocsAdminPayload | null
      if (!response.ok) throw new Error(payload?.error ?? 'Unable to load docs page.')
      const resolved = payload ?? { page: null, blocks: [] }
      setCachedDocsPage(slug, resolved)
      return resolved
    })
    .finally(() => pendingRequests.delete(slug))

  pendingRequests.set(slug, request)
  return request
}

