import type { QueryResultRow } from 'pg'
import { AdminDbError, mapAdminDbError } from './errors'
export interface DbExecutor {
  query<Row extends QueryResultRow = QueryResultRow>(text: string, values?: unknown[]): Promise<{ rows: Row[] }>
}
export interface DbClient extends DbExecutor { release(error?: boolean): void }
export interface DbPool { connect(): Promise<DbClient> }
const principalSql = `SELECT session_user::text AS login_role, current_user::text AS active_role,
  EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'hod_admin_app') AS capability_exists,
  EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = session_user
    AND NOT rolinherit AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls) AS safe_login,
  NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname <> 'hod_admin_app'
    AND r.rolname <> session_user AND pg_catalog.pg_has_role(session_user, r.oid, 'MEMBER')) AS isolated_login,
  EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'hod_admin_app'
    AND NOT rolinherit AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls) AS safe_capability,
  NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname <> 'hod_admin_app'
    AND pg_catalog.pg_has_role('hod_admin_app', r.oid, 'MEMBER')) AS isolated_capability`
export async function withAdminTransaction<T>(pool: DbPool, loginRole: string, run: (db: DbExecutor) => Promise<T>): Promise<T> {
  let client: DbClient | undefined
  let began = false
  let discard = false
  try {
    client = await pool.connect()
    await client.query('BEGIN'); began = true
    const { rows } = await client.query(principalSql)
    const p = rows[0]
    if (rows.length !== 1 || p.login_role !== loginRole || p.active_role !== loginRole
      || p.safe_login !== true || p.isolated_login !== true || p.safe_capability !== true
      || p.isolated_capability !== true || p.capability_exists !== true) {
      discard = true
      throw new AdminDbError('permission')
    }
    await client.query('SET LOCAL ROLE hod_admin_app')
    const value = await run(client)
    await client.query('COMMIT'); began = false
    return value
  } catch (error) {
    if (client && began) {
      try { await client.query('ROLLBACK') } catch { discard = true }
    } else { discard = true }
    throw mapAdminDbError(error)
  } finally { client?.release(discard) }
}
export async function queryAdmin<Row extends QueryResultRow>(pool: DbPool, loginRole: string, text: string, values: unknown[] = []): Promise<Row[]> {
  return withAdminTransaction(pool, loginRole, async db => (await db.query<Row>(text, values)).rows)
}

import 'server-only'
import { readFileSync } from 'node:fs'
import { Pool } from 'pg'
import { readAdminDbConfig } from './config'
import { queryAdmin, withAdminTransaction } from './query'
import type { DbExecutor } from './query'
import type { QueryResultRow } from 'pg'
const state = globalThis as typeof globalThis & { hodAdminDb?: { pool: Pool; loginRole: string } }
function database() {
  if (!state.hodAdminDb) {
    const config = readAdminDbConfig(process.env, path => readFileSync(path, 'utf8'))
    const pool = new Pool(config.pool)
    // pg requires a handler for idle-client errors; do not log credentials/query details.
    pool.on('error', () => {})
    state.hodAdminDb = { pool, loginRole: config.loginRole }
  }
  return state.hodAdminDb
}
export function adminQuery<Row extends QueryResultRow>(text: string, values: unknown[] = []): Promise<Row[]> {
  const db = database()
  return queryAdmin<Row>(db.pool, db.loginRole, text, values)
}
export function adminTransaction<T>(run: (db: DbExecutor) => Promise<T>): Promise<T> {
  const db = database()
  return withAdminTransaction(db.pool, db.loginRole, run)
}
export async function closeAdminPool(): Promise<void> {
  const db = state.hodAdminDb
  delete state.hodAdminDb
  if (db) await db.pool.end()
}

export type AdminDbErrorKind = 'unavailable' | 'permission' | 'conflict' | 'invalid' | 'internal'
export class AdminDbError extends Error {
  constructor(public readonly kind: AdminDbErrorKind, public readonly sqlState?: string) {
    super('Admin database operation failed')
    this.name = 'AdminDbError'
  }
}
export function mapAdminDbError(error: unknown): AdminDbError {
  if (error instanceof AdminDbError) return error
  const code = typeof error === 'object' && error !== null && 'code' in error ? String(error.code) : ''
  const state = /^[0-9A-Z]{5}$/.test(code) ? code : undefined
  const kind = code === '42501' ? 'permission'
    : ['40001', '40P01', '23505', 'PT409'].includes(code) ? 'conflict'
    : ['23503', '23514', '22P02'].includes(code) ? 'invalid'
    : ['42883', '42P01', '53300', '57P01', '57014'].includes(code) || code.startsWith('08')
      || ['ECONNREFUSED', 'ETIMEDOUT', 'ENOTFOUND'].includes(code) ? 'unavailable' : 'internal'
  return new AdminDbError(kind, state)
}

import { checkServerIdentity } from 'node:tls'
import { isIP } from 'node:net'
import { X509Certificate } from 'node:crypto'
import type { PoolConfig } from 'pg'

export type AdminDbConfig = { pool: PoolConfig; loginRole: string }
const identifier = /^[a-z][a-z0-9_]{0,62}$/
export function readAdminDbConfig(env: NodeJS.ProcessEnv, readCa: (path: string) => string): AdminDbConfig {
  try {
    const url = new URL(env.ADMIN_DATABASE_URL ?? '')
    const loginRole = env.ADMIN_DB_LOGIN_ROLE ?? ''
    const username = decodeURIComponent(url.username)
    if (!['postgres:', 'postgresql:'].includes(url.protocol) || !url.hostname || !url.pathname.slice(1)
      || !url.password || url.search || url.hash || !identifier.test(loginRole) || username !== loginRole
      || (loginRole !== 'hod_admin_app' && !loginRole.startsWith('hod_admin_login_'))) throw new Error()
    const transportHost = url.hostname.replace(/^\[|\]$/g, '')
    const host = transportHost === 'localhost' ? '127.0.0.1' : transportHost
    if (isIP(host) && host !== '127.0.0.1' && host !== '::1') throw new Error()
    const expected = env.ADMIN_DB_TLS_EXPECTED_HOST || host
    if (isIP(expected) || expected === 'localhost' || !/^[a-z0-9.-]+$/i.test(expected)
      || (!isIP(host) && host !== 'localhost' && expected !== host)) throw new Error()
    const ca = readCa(env.ADMIN_DB_TLS_CA_FILE ?? '')
    const certificates = ca.match(/-----BEGIN CERTIFICATE-----[\s\S]+?-----END CERTIFICATE-----/g)
    if (!certificates?.length) throw new Error()
    for (const certificate of certificates) { if (!new X509Certificate(certificate).ca) throw new Error() }
    const port = url.port ? Number(url.port) : 5432
    if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error()
    return { loginRole, pool: {
      host, port, database: decodeURIComponent(url.pathname.slice(1)), user: loginRole,
      password: decodeURIComponent(url.password), max: 5, idleTimeoutMillis: 30_000,
      connectionTimeoutMillis: 5_000, statement_timeout: 10_000, query_timeout: 12_000,
      lock_timeout: 3_000, idle_in_transaction_session_timeout: 15_000,
      application_name: 'hod-admin',
      ssl: { ca, rejectUnauthorized: true, servername: expected,
        checkServerIdentity: (_host, certificate) => checkServerIdentity(expected, certificate) },
    } }
  } catch { throw new Error('Admin database configuration is missing or invalid') }
}

