import 'server-only'
import type { DbExecutor } from '../query'
import { siteSettingsSchema } from '../../settings-validation'
import type { CatalogGstSlab } from '../../product-catalog'
import { jsonRows, OperationsError } from './operations-shared'
const key='global_site_settings'
const fields=['whatsapp_number','default_gst_slab_id','maintenance_mode_enabled','maintenance_mode_message','estimated_delivery_text'] as const
type Settings={whatsapp_number:string;default_gst_slab_id:string|null;maintenance_mode_enabled:boolean;maintenance_mode_message:string;estimated_delivery_text:string}
export function createSettingsRepository(db:DbExecutor) {
  async function read() {
    const records=await jsonRows<Settings>(db,`SELECT jsonb_build_object(${fields.map(f=>`'${f}',${f}`).join(',')})::text AS item FROM public.site_settings WHERE settings_key=$1::text`,[key])
    if(records.length>1)throw new Error('Ambiguous settings')
    const data=records[0]
    return {settings_key:key,whatsapp_number:data?.whatsapp_number??'',default_gst_slab_id:data?.default_gst_slab_id??'',maintenance_mode_enabled:Boolean(data?.maintenance_mode_enabled),maintenance_mode_message:data?.maintenance_mode_message??'',estimated_delivery_text:data?.estimated_delivery_text??'Approximately 3 to 4 weeks'}
  }
  async function gst() {return jsonRows<CatalogGstSlab>(db,'SELECT to_jsonb(g)::text AS item FROM public.catalog_gst_slabs g ORDER BY display_order,id')}
  async function save(raw:unknown) {
    const input=siteSettingsSchema.parse(raw)
    if(input.default_gst_slab_id){
      const {rows}=await db.query('SELECT id FROM public.catalog_gst_slabs WHERE id=$1::uuid AND status::text <> \'hidden\' FOR SHARE',[input.default_gst_slab_id])
      if(rows.length!==1)throw new OperationsError(400,'Select an active GST slab.')
    }
    // Serialize the legacy update-or-insert contract without assuming an unverified unique constraint.
    await db.query('SELECT pg_advisory_xact_lock(hashtextextended($1::text,0))',['admin:global_site_settings'])
    const payload=JSON.stringify(input)
    const projection=fields.map(f=>`(jsonb_populate_record(NULL::public.site_settings,$2::jsonb)).${f}`).join(',')
    const result=await db.query(`UPDATE public.site_settings SET (${fields.join(',')})=(${projection}) WHERE settings_key=$1::text RETURNING settings_key`,[key,payload])
    if(result.rows.length>1)throw new Error('Ambiguous settings')
    if(!result.rows.length)await db.query(`INSERT INTO public.site_settings (settings_key,${fields.join(',')}) SELECT $1::text,${projection}`,[key,payload])
    return {success:true}
  }
  return {read,gst,save}
}

import 'server-only'
import type { z } from 'zod'
import type { AdminActor } from '../../auth/admin-identity-core'
import type { ProductPayload } from '../../product-payload-validation'
import type { bulkPriceSchema, bulkDeleteSchema, activateDraftsSchema } from '../../product-operations-validation'
import type { DbExecutor } from '../query'

export type DuplicateProduct = { product_id: string; slug: string; lane: 'standard' | 'hiphop' | 'collection' }
export type ProductOperationResult = Record<string, unknown>

/** Executor must be inside B2's authorized transaction; actor comes from B1 authorization. */
export function createProductRepository(db: DbExecutor) {
  async function scalar(sql: string, values: unknown[]): Promise<ProductOperationResult> {
    const { rows } = await db.query<{ result: ProductOperationResult }>(sql, values)
    if (rows.length !== 1 || !rows[0].result || typeof rows[0].result !== 'object' || Array.isArray(rows[0].result)) throw new Error('Invalid product result')
    return rows[0].result
  }
  return {
    save(actor: AdminActor, input: { productId?: string | null; slug?: string | null; payload: ProductPayload }) {
      return scalar('SELECT public.admin_product_save_v1($1::uuid,$2::uuid,$3::text,$4::jsonb) AS result',
        [actor.profileId, input.productId ?? null, input.slug ?? null, JSON.stringify(input.payload)])
    },
    bulkPrice(actor: AdminActor, input: z.infer<typeof bulkPriceSchema>) {
      return scalar('SELECT public.admin_product_bulk_price_v1($1::uuid,$2::uuid,$3::text,$4::text,$5::numeric,$6::uuid[],$7::jsonb) AS result',
        [actor.profileId, input.requestId, input.lane, input.operation, input.value, input.ids, JSON.stringify(input.expectedPrices)])
    },
    bulkDelete(actor: AdminActor, input: z.infer<typeof bulkDeleteSchema>) {
      return scalar('SELECT public.admin_product_bulk_delete_v1($1::uuid,$2::uuid,$3::text,$4::uuid[]) AS result',
        [actor.profileId, input.requestId, input.lane, input.ids])
    },
    activateDrafts(actor: AdminActor, input: z.infer<typeof activateDraftsSchema>) {
      return scalar('SELECT public.admin_product_activate_drafts_v1($1::uuid,$2::uuid,$3::text,$4::uuid[]) AS result',
        [actor.profileId, input.requestId, input.lane, input.ids])
    },
    async duplicate(actor: AdminActor, sourceId: string, requestId: string): Promise<DuplicateProduct> {
      // Audited order is source, request, admin (unlike the actor-first v1 routines).
      const { rows } = await db.query<DuplicateProduct>('SELECT * FROM public.duplicate_product($1::uuid,$2::uuid,$3::uuid)', [sourceId, requestId, actor.profileId])
      if (rows.length !== 1 || !rows[0].product_id || !rows[0].slug || !['standard', 'hiphop', 'collection'].includes(rows[0].lane)) throw new Error('Invalid duplicate result')
      return rows[0]
    },
    async source(id: string) {
      const { rows } = await db.query<{ id: string; product_lane: string | null }>('SELECT id, product_lane FROM public.products WHERE id=$1::uuid', [id])
      return rows[0] ?? null
    },
    async draft(id: string, expectedStatus: string) {
      const { rows } = await db.query<{ id: string; status: string }>("UPDATE public.products SET status='draft',updated_at=$3::timestamptz WHERE id=$1::uuid AND status=$2::text RETURNING id,status", [id, expectedStatus, new Date().toISOString()])
      if (rows[0]) return { status: 'updated' as const, item: rows[0] }
      const current = await db.query<{ id: string }>('SELECT id FROM public.products WHERE id=$1::uuid', [id])
      return { status: current.rows.length ? 'conflict' as const : 'not_found' as const }
    },
  }
}

