export async function findRdsProductId(db: DbExecutor, lookup: string, byId = false): Promise<string | null> {
  if (!byId) {
    const result = await db.query<{ id: string }>('SELECT id FROM public.products WHERE slug=$1::text', [lookup.trim()])
    if (result.rows[0]) return result.rows[0].id
  }
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(lookup)) return null
  return (await db.query<{ id: string }>('SELECT id FROM public.products WHERE id=$1::uuid', [lookup])).rows[0]?.id ?? null
}

export async function loadRdsProductEditor(db: DbExecutor, id: string): Promise<ProductEditorItem | null> {
  const result = await db.query<{ item: ProductRecord }>('SELECT to_jsonb(p) AS item FROM public.products p WHERE p.id=$1::uuid', [id])
  if (!result.rows[0]) return null
  // Static statements, jsonb decoding preserves numeric/timestamp response contracts.
  const metals = await db.query<{ metal_id: string }>('SELECT metal_id FROM public.product_metal_selections WHERE product_id=$1::uuid ORDER BY sort_order', [id])
  const materials = await db.query<{ material_value_id: string }>('SELECT material_value_id FROM public.product_material_value_selections WHERE product_id=$1::uuid ORDER BY sort_order', [id])
  const shapes = await db.query<{ shape_id: string }>('SELECT shape_id FROM public.product_stone_shapes WHERE product_id=$1::uuid', [id])
  const subs = await db.query<{ subcategory_id: string }>('SELECT subcategory_id FROM public.product_subcategory_links WHERE product_id=$1::uuid AND is_primary IS NOT TRUE ORDER BY sort_order', [id])
  const options = await db.query<{ option_id: string }>('SELECT option_id FROM public.product_option_links WHERE product_id=$1::uuid AND is_primary IS NOT TRUE ORDER BY sort_order', [id])
  const prices = await db.query<{ item: NonNullable<ProductEditorItem['purity_prices']>[number] }>('SELECT to_jsonb(p) AS item FROM public.product_purity_prices p WHERE product_id=$1::uuid ORDER BY sort_order', [id])
  const metalMedia = await db.query<{ item: NonNullable<ProductEditorItem['metal_media']>[number] }>('SELECT to_jsonb(p) AS item FROM public.product_metal_media p WHERE product_id=$1::uuid', [id])
  const variants = await db.query<{ item: ProductMetalVariant }>('SELECT to_jsonb(p) AS item FROM public.product_metal_variants p WHERE product_id=$1::uuid ORDER BY sort_order', [id])
  const media = await db.query<{ item: ProductVariantMediaItem }>('SELECT to_jsonb(p) AS item FROM public.product_variant_media_items p WHERE product_id=$1::uuid ORDER BY sort_order', [id])
  const faq = await db.query<{ item: ProductFaqItem }>('SELECT to_jsonb(p) AS item FROM public.product_faq_items p WHERE product_id=$1::uuid ORDER BY sort_order', [id])
  const groups = await db.query<{ item: Omit<ProductCustomDropdown, 'options'> }>('SELECT to_jsonb(p) AS item FROM public.product_custom_dropdowns p WHERE product_id=$1::uuid ORDER BY display_order', [id])
  const dropdownOptions = groups.rows.length ? await db.query<{ item: ProductCustomDropdownOption & { dropdown_id: string } }>('SELECT to_jsonb(p) AS item FROM public.product_custom_dropdown_options p WHERE dropdown_id=ANY($1::uuid[]) ORDER BY display_order', [groups.rows.map(row => row.item.id)]) : { rows: [] }
  const mediaItems = media.rows.map(row => row.item)
  return { ...result.rows[0].item,
    metal_ids: metals.rows.map(row => row.metal_id), material_value_ids: materials.rows.map(row => row.material_value_id),
    shape_ids: shapes.rows.map(row => row.shape_id), linked_subcategory_ids: subs.rows.map(row => row.subcategory_id), linked_option_ids: options.rows.map(row => row.option_id),
    purity_prices: prices.rows.map(row => row.item), metal_media: metalMedia.rows.map(row => row.item),
    metal_variants: variants.rows.map(row => ({ ...row.item, media_items: mediaItems.filter(item => item.variant_id === row.item.id) })),
    default_variant_media_items: mediaItems.filter(item => item.variant_id == null && item.is_default_fallback),
    faq_items: faq.rows.map(row => row.item), custom_dropdowns: groups.rows.map(row => ({ ...row.item, options: dropdownOptions.rows.filter(option => option.item.dropdown_id === row.item.id).map(option => option.item) })),
  }
}

import 'server-only'
import type { DbExecutor } from '../query'
import type { BootstrapPayload } from '../../../components/product-form'

export type ProductBootstrapScope = 'basics' | 'pricing' | 'attributes' | 'content' | 'all'
export async function loadRdsProductBootstrap(db: DbExecutor, scope: ProductBootstrapScope): Promise<BootstrapPayload & { ringSizes?: unknown[]; navbarItems?: unknown[] }> {
  async function scalar<T>(sql: string, values: unknown[] = []): Promise<T> {
    const result = await db.query<{ result: T }>(sql, values)
    if (result.rows.length !== 1 || result.rows[0].result == null) throw new Error('Invalid product reference result')
    return result.rows[0].result
  }
  const result: BootstrapPayload & { ringSizes?: unknown[]; navbarItems?: unknown[] } = {}
  if (scope === 'all' || scope === 'basics') {
    result.categories = await scalar('SELECT public.catalog_hierarchy_list_v1($1::text) AS result', ['category'])
    result.subcategories = await scalar('SELECT public.catalog_hierarchy_list_v1($1::text) AS result', ['subcategory'])
    result.options = await scalar('SELECT public.catalog_hierarchy_list_v1($1::text) AS result', ['option'])
    result.styles = await scalar("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY display_order),'[]'::jsonb) AS result FROM public.catalog_styles r")
  }
  if (scope === 'all' || scope === 'pricing' || scope === 'attributes') {
    result.metals = await scalar('SELECT public.catalog_metal_list_v1() AS result')
    result.certificates = await scalar("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY display_order),'[]'::jsonb) AS result FROM public.catalog_certificates r")
  }
  if (scope === 'all' || scope === 'pricing') result.gstSlabs = await scalar("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY display_order),'[]'::jsonb) AS result FROM public.catalog_gst_slabs r")
  if (scope === 'all' || scope === 'attributes') {
    result.materialValues = await scalar("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY display_order),'[]'::jsonb) AS result FROM public.catalog_material_values r")
    result.stoneShapes = await scalar("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY display_order),'[]'::jsonb) AS result FROM public.catalog_stone_shapes r")
    result.ringSizes = await scalar("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY display_order),'[]'::jsonb) AS result FROM public.catalog_ring_sizes r")
    const ring = await scalar<{ categories: BootstrapPayload['ringCategories']; sizes: BootstrapPayload['ringCategorySizes'] }>('SELECT public.catalog_ring_snapshot_v1() AS result')
    result.ringCategories = ring.categories
    result.ringCategorySizes = ring.sizes
  }
  if (scope === 'all' || scope === 'content') result.productContentRules = await scalar('SELECT public.catalog_master_list_v1($1::text) AS result', ['content_rule'])
  if (scope === 'all') result.navbarItems = await scalar("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY display_order),'[]'::jsonb) AS result FROM public.navbar_items r")
  return result
}

import 'server-only'
import type { z } from 'zod'
import type { DbExecutor } from '../query'
import { orderStatusUpdateSchema } from '../../order-inventory-validation'
import { sanitizeLoveLetterHtml } from '../../love-letter-html'
import { jsonRows, OperationsError, pageNumber, safeCount, uuid } from './operations-shared'
export type OrderRecord = {
  id: string; order_number: string; customer_first_name: string | null; customer_last_name: string | null;
  customer_email: string; total_amount: number | string | null; payment_status: string | null;
  status: 'pending' | 'processing' | 'shipped' | 'delivered' | 'cancelled'; created_at: string;
  courier_name: string | null; courier_awb_number: string | null; shipped_at: string | null;
}
export type OrderLine = { product_name: string; quantity: number | string; line_total: number | string; [key: string]: unknown }
const updateColumns=['id','status','order_number','customer_email','customer_first_name','customer_last_name','total_amount','created_at','courier_name','courier_awb_number','shipped_at'] as const
export function createOrdersRepository(db: DbExecutor) {
  async function list(page = 1) {
    page = pageNumber(page)
    // One statement snapshot includes exact total even beyond the last page.
    const { rows } = await db.query<{ total: string; items: string }>(`WITH page AS (
      SELECT o.id,o.order_number,o.customer_first_name,o.customer_last_name,o.customer_email,o.total_amount,
      o.payment_status,o.status,o.created_at,(SELECT count(*) FROM public.order_items i WHERE i.order_id=o.id) AS items
      FROM public.orders o ORDER BY o.created_at DESC,o.id DESC LIMIT 20 OFFSET $1::integer)
      SELECT (SELECT count(*)::text FROM public.orders) AS total,COALESCE((SELECT jsonb_agg(to_jsonb(page) ORDER BY page.created_at DESC,page.id DESC) FROM page),'[]'::jsonb)::text AS items`, [(page - 1) * 20])
    if (rows.length !== 1) throw new Error('Invalid order list')
    const { parseCmsJson } = await import('../../cms-id-safety')
    const records = parseCmsJson(rows[0].items) as Array<OrderRecord & { items: number }>
    const total = safeCount(rows[0].total)
    return { items: records.map(o => ({ id:o.id,orderNumber:o.order_number || 'Order',customer:[o.customer_first_name,o.customer_last_name].filter(Boolean).join(' ') || o.customer_email,customerEmail:o.customer_email,total:Number(o.total_amount || 0),paymentStatus:o.payment_status || 'pending',status:o.status,createdAt:o.created_at,items:safeCount(o.items) })), page,pageSize:20,total,totalPages:Math.max(1,Math.ceil(total/20)) }
  }
  async function detail(id: string) {
    uuid(id)
    const order = (await jsonRows<OrderRecord>(db,'SELECT to_jsonb(o)::text AS item FROM public.orders o WHERE id=$1::uuid',[id]))[0]
    if (!order) throw new OperationsError(404,'Order not found.')
    const items = await jsonRows<OrderLine>(db,'SELECT to_jsonb(i)::text AS item FROM public.order_items i WHERE order_id=$1::uuid ORDER BY created_at,id',[id])
    const letters = await jsonRows<{final_letter_html:string;[key:string]:unknown}>(db,'SELECT to_jsonb(l)::text AS item FROM public.order_love_letters l WHERE order_id=$1::uuid',[id])
    if (letters.length > 1) throw new Error('Invalid love letter result')
    return { order, items, loveLetter:letters[0] ? {...letters[0],final_letter_html:sanitizeLoveLetterHtml(letters[0].final_letter_html)} : null }
  }
  async function update(id: string, raw: z.infer<typeof orderStatusUpdateSchema>, now = new Date().toISOString()) {
    uuid(id)
    const input = orderStatusUpdateSchema.parse(raw)
    const existing = (await jsonRows<OrderRecord>(db,'SELECT to_jsonb(o)::text AS item FROM public.orders o WHERE id=$1::uuid FOR UPDATE',[id]))[0]
    if (!existing) throw new OperationsError(404,'Order not found.')
    if (existing.status !== input.expected_status || (existing.courier_name || null) !== (input.expected_courier_name || null) || (existing.courier_awb_number || null) !== (input.expected_courier_awb_number || null)) throw new OperationsError(409,'This order changed after you opened it. Reload before saving.')
    const items = await jsonRows<OrderLine>(db,'SELECT to_jsonb(i)::text AS item FROM public.order_items i WHERE order_id=$1::uuid ORDER BY created_at,id',[id])
    // Stock restoration and history belong exclusively to existing database triggers.
    const result = await jsonRows<OrderRecord>(db,`UPDATE public.orders SET
      status=(jsonb_populate_record(NULL::public.orders,$2::jsonb)).status,
      courier_name=$3::text,courier_awb_number=$4::text,
      shipped_at=CASE WHEN $5::text='shipped' THEN COALESCE(shipped_at,$6::timestamptz) ELSE shipped_at END
      WHERE id=$1::uuid AND status::text=$7::text AND courier_name IS NOT DISTINCT FROM $8::text
      AND courier_awb_number IS NOT DISTINCT FROM $9::text RETURNING jsonb_build_object(${updateColumns.map(column=>`'${column}',${column}`).join(',')})::text AS item`,
      [id,JSON.stringify({status:input.status}),input.courier_name || null,input.courier_awb_number || null,input.status,now,input.expected_status,input.expected_courier_name || null,input.expected_courier_awb_number || null])
    if (result.length !== 1) throw new OperationsError(409,'This order changed after you opened it. Reload before saving.')
    return { item:result[0],items,statusChanged:existing.status !== input.status }
  }
  return {list,detail,update}
}

import 'server-only'
import { z } from 'zod'
import type { DbExecutor } from '../query'
import { parseCmsJson } from '../../cms-id-safety'

export class OperationsError extends Error {
  constructor(public readonly status: 400 | 404 | 409 | 503, message: string) { super(message) }
}
export const uuid = (value: string) => z.string().uuid().parse(value)
export function pageNumber(value: unknown, max = 100_000) { return z.coerce.number().int().min(1).max(max).parse(value) }
export function exactId(value: unknown): string {
  if (typeof value === 'number' && !Number.isSafeInteger(value)) throw new OperationsError(400, 'Invalid ID.')
  const text = String(value)
  if (!/^[1-9][0-9]{0,18}$/.test(text) || BigInt(text) > BigInt('9223372036854775807')) throw new OperationsError(400, 'Invalid ID.')
  return text
}
export function safeCount(value: unknown): number {
  const count = Number(value)
  if (!Number.isSafeInteger(count) || count < 0) throw new Error('Invalid count')
  return count
}
/** JSON text keeps bigint IDs exact and preserves PostgreSQL numeric JSON contracts. */
export async function jsonRows<T>(db: DbExecutor, sql: string, values: unknown[] = []): Promise<T[]> {
  const { rows } = await db.query<{ item: string }>(sql, values)
  return rows.map(row => { if (typeof row.item !== 'string') throw new Error('Invalid operation result'); return parseCmsJson(row.item) as T })
}
export async function optionalRelation(db: DbExecutor, table: 'newsletter_submissions' | 'promotion_popup_responses'): Promise<boolean> {
  // Presence only: permissions/column/query failures must propagate, never look like an empty feature.
  const { rows } = await db.query<{ present: boolean }>('SELECT to_regclass($1::text) IS NOT NULL AS present', [`public.${table}`])
  if (rows.length !== 1 || typeof rows[0].present !== 'boolean') throw new Error('Invalid feature availability')
  return rows[0].present
}

import 'server-only'
import type { AdminActor } from '../../auth/admin-identity-core'
import type { DbExecutor } from '../query'
import { notificationReadSchema } from '../../admin-read-validation'
import { presentNotifications } from '../../operations-presenters'
import { createEnquiriesRepository } from './enquiries'
import { uuid } from './operations-shared'
export function createNotificationsRepository(db:DbExecutor,actor:AdminActor) {
  const actorId=uuid(actor.profileId)
  async function read() {
    const enquiries=createEnquiriesRepository(db)
    const sources=await enquiries.sources(true)
    const ordersResult=await enquiries.notificationOrders()
    const {rows}=await db.query<{notification_key:string}>('SELECT notification_key FROM public.admin_notification_reads WHERE admin_user_id=$1::uuid',[actorId])
    return presentNotifications({...sources,ordersResult,readKeys:new Set(rows.map(row=>row.notification_key))})
  }
  async function mark(raw:unknown,now=new Date().toISOString()) {
    const {notificationKey}=notificationReadSchema.parse(raw)
    await db.query(`INSERT INTO public.admin_notification_reads(admin_user_id,notification_key,read_at)
      VALUES($1::uuid,$2::text,$3::timestamptz) ON CONFLICT(admin_user_id,notification_key) DO NOTHING`,[actorId,notificationKey,now])
    return {ok:true}
  }
  async function markAll(now=new Date().toISOString()) {
    const data=await read();const unread=data.items.filter(i=>!i.read)
    if(unread.length)await db.query(`INSERT INTO public.admin_notification_reads(admin_user_id,notification_key,read_at)
      SELECT $1::uuid,k,$3::timestamptz FROM unnest($2::text[]) k ON CONFLICT(admin_user_id,notification_key) DO NOTHING`,[actorId,unread.map(i=>i.notificationKey),now])
    return {ok:true,count:unread.length}
  }
  return {read,mark,markAll}
}

