export const identityLookupSql = 'SELECT issuer, subject, profile_id, enabled, revoked_at, profile_role FROM public.admin_identity_lookup_v1($1::text, $2::text)'
export function createAdminIdentityLookup(db: DbExecutor) {
  return async (issuer: string, subject: string): Promise<readonly AdminIdentityRecord[]> => {
    if (!issuer || !subject) return []
    const { rows } = await db.query(identityLookupSql, [issuer, subject])
    return rows.map(row => ({ issuer: row.issuer, subject: row.subject, profileId: row.profile_id,
      enabled: row.enabled, revokedAt: row.revoked_at instanceof Date ? row.revoked_at.toISOString() : row.revoked_at,
      profileRole: row.profile_role }))
  }
}

import 'server-only'
import type { DbExecutor } from '../query'
import { jsonRows, optionalRelation, pageNumber, safeCount } from './operations-shared'
type Bespoke={id:string;full_name:string;email:string;phone:string|null;piece_type:string|null;country:string|null;message:string|null;status:string|null;created_at:string}
type Contact={id:string;full_name:string;email:string;phone:string|null;topic:string|null;message:string|null;status:string|null;created_at:string}
type Newsletter={id:string;email:string;source:string|null;status:string|null;created_at:string}
type Promotion={id:string;promotion_id:number|string;email:string;answers:unknown;coupon_revealed:boolean;revealed_at:string|null;created_at:string}
type Question={promotion_id:number|string;field_key:string;question:string}
type Order={id:string;order_number:string;customer_first_name:string|null;customer_last_name:string|null;customer_email:string;total_amount:number|string;status:string;created_at:string}
type Result<T>={data:T[];error:null;enabled:boolean}
const result=<T>(data:T[],enabled=true):Result<T>=>({data,error:null,enabled})
export type EnquirySources={bespokeResult:Result<Bespoke>;contactResult:Result<Contact>;newsletterResult:Result<Newsletter>;promotionResult:Result<Promotion>;promotionQuestionsResult:Result<Question>}
export type NotificationSources={ordersResult:Result<Order>;bespokeResult:Result<Bespoke>;contactResult:Result<Contact>;newsletterResult:Result<Newsletter>;readKeys:Set<string>}
const bespokeColumns='id,full_name,email,phone,piece_type,country,message,status,created_at'
const contactColumns='id,full_name,email,phone,topic,message,status,created_at'
export function createEnquiriesRepository(db:DbExecutor) {
  async function sources(notifications=false):Promise<EnquirySources> {
    const tail=notifications ? " WHERE status='new' ORDER BY created_at DESC,id DESC LIMIT 25" : ' ORDER BY created_at DESC,id DESC'
    const bespokeResult=result(await jsonRows<Bespoke>(db,`SELECT to_jsonb(t)::text AS item FROM (SELECT ${bespokeColumns} FROM public.bespoke_submissions${tail}) t`))
    const contactResult=result(await jsonRows<Contact>(db,`SELECT to_jsonb(t)::text AS item FROM (SELECT ${contactColumns} FROM public.contact_submissions${tail}) t`))
    const newsletterEnabled=await optionalRelation(db,'newsletter_submissions')
    const newsletterResult=result(newsletterEnabled ? await jsonRows<Newsletter>(db,`SELECT to_jsonb(t)::text AS item FROM (SELECT id,email,source,status,created_at FROM public.newsletter_submissions${tail}) t`) : [],newsletterEnabled)
    const promotionEnabled=!notifications && await optionalRelation(db,'promotion_popup_responses')
    const promotionResult=result(promotionEnabled ? await jsonRows<Promotion>(db,'SELECT to_jsonb(t)::text AS item FROM (SELECT id,promotion_id,email,answers,coupon_revealed,revealed_at,created_at FROM public.promotion_popup_responses ORDER BY created_at DESC,id DESC) t') : [],promotionEnabled)
    const promotionQuestionsResult=result(promotionEnabled ? await jsonRows<Question>(db,'SELECT jsonb_build_object(\'promotion_id\',promotion_id,\'field_key\',field_key,\'question\',question)::text AS item FROM public.promotion_popup_questions') : [])
    return {bespokeResult,contactResult,newsletterResult,promotionResult,promotionQuestionsResult}
  }
  async function contactPage(page=1,pageSize=25) {
    page=pageNumber(page);pageSize=pageNumber(pageSize,100)
    const {rows}=await db.query<{total:string;items:string}>(`WITH page AS (SELECT ${contactColumns} FROM public.contact_submissions ORDER BY created_at DESC,id DESC LIMIT $1::integer OFFSET $2::integer)
      SELECT (SELECT count(*)::text FROM public.contact_submissions) AS total,COALESCE((SELECT jsonb_agg(to_jsonb(page) ORDER BY page.created_at DESC,page.id DESC) FROM page),'[]'::jsonb)::text AS items`,[pageSize,(page-1)*pageSize])
    if(rows.length!==1)throw new Error('Invalid contact page')
    const {parseCmsJson}=await import('../../cms-id-safety')
    return {items:parseCmsJson(rows[0].items),page,pageSize,total:safeCount(rows[0].total)}
  }
  async function notificationOrders() {return result(await jsonRows<Order>(db,"SELECT to_jsonb(t)::text AS item FROM (SELECT id,order_number,customer_first_name,customer_last_name,customer_email,total_amount,status,created_at FROM public.orders WHERE payment_status='paid' ORDER BY created_at DESC,id DESC LIMIT 25) t"))}
  return {sources,contactPage,notificationOrders}
}

import 'server-only'
import type { DbExecutor } from '../query'
import { parseCmsJson } from '../../cms-id-safety'
import { safeCount } from './operations-shared'
type Recent={id:string;order_number:string|null;customer_first_name:string|null;customer_last_name:string|null;customer_email:string|null;total_amount:number|string|null;status:string|null;created_at:string}
type Snapshot={products:number;orders:number;identities:number;guestOrders:number;revenue:Array<{total_amount:number|string|null;status:string|null}>;recent:Recent[];items:Array<{product_name:string;quantity:number|string;line_total:number|string}>}
export async function dashboardSources(db:DbExecutor) {
  // All summary inputs use one PostgreSQL statement snapshot, including empty tables.
  const {rows}=await db.query<{item:string}>(`SELECT jsonb_build_object(
    'products',(SELECT count(*) FROM public.products),'orders',(SELECT count(*) FROM public.orders),
    'identities',(SELECT count(*) FROM public.customer_identities),
    'guestOrders',(SELECT count(*) FROM public.orders WHERE user_id IS NULL AND customer_identity_id IS NULL AND guest_token_hash IS NOT NULL),
    'revenue',COALESCE((SELECT jsonb_agg(jsonb_build_object('total_amount',total_amount,'status',status)) FROM public.orders),'[]'::jsonb),
    'recent',COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT id,order_number,customer_first_name,customer_last_name,customer_email,total_amount,status,created_at FROM public.orders ORDER BY created_at DESC,id DESC LIMIT 5) t),'[]'::jsonb),
    'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('product_name',product_name,'quantity',quantity,'line_total',line_total)) FROM public.order_items),'[]'::jsonb))::text AS item`)
  if(rows.length!==1 || typeof rows[0].item!=='string')throw new Error('Invalid dashboard snapshot')
  const data=parseCmsJson(rows[0].item) as Snapshot
  return {productsCount:{count:safeCount(data.products)},ordersCount:{count:safeCount(data.orders)},revenueResult:{data:data.revenue},recentOrdersResult:{data:data.recent},orderItemsResult:{data:data.items},customerCount:safeCount(data.identities),customerLabel:'Customer identities',customerNote:`Persisted identities; ${safeCount(data.guestOrders)} guest orders; historical registrations unavailable`}
}

import 'server-only'
import type { DbExecutor } from '../query'
import { jsonRows, safeCount, uuid } from './operations-shared'
export type CustomerIdentitySummary = {id:string;email:string;name:string;firstSeenAt:string;emailVerified:boolean}
export function createCustomersRepository(db:DbExecutor) {
  async function list():Promise<CustomerIdentitySummary[]> {
    // Explicit projection excludes provider subjects, sessions and unrelated private profile fields.
    return jsonRows(db,`SELECT jsonb_build_object('id',i.id,'email',i.email,
      'name',COALESCE(NULLIF(btrim(concat_ws(' ',p.first_name,p.last_name)),''),'Unnamed customer'),
      'firstSeenAt',i.created_at,'emailVerified',i.email_verified)::text AS item
      FROM public.customer_identities i LEFT JOIN public.customer_profiles p ON p.identity_id=i.id
      ORDER BY i.created_at DESC,i.id DESC`)
  }
  async function metrics() {
    const {rows}=await db.query<{identities:string;guest_orders:string;legacy_account_orders:string}>(`SELECT
      (SELECT count(*)::text FROM public.customer_identities) AS identities,
      count(*) FILTER (WHERE user_id IS NULL AND customer_identity_id IS NULL AND guest_token_hash IS NOT NULL)::text AS guest_orders,
      count(*) FILTER (WHERE user_id IS NOT NULL)::text AS legacy_account_orders FROM public.orders`)
    if(rows.length!==1)throw new Error('Invalid customer metrics')
    return {persistedCustomerIdentities:safeCount(rows[0].identities),guestOrders:safeCount(rows[0].guest_orders),legacyAccountOrders:safeCount(rows[0].legacy_account_orders),historicalRegistrations:null}
  }
  async function orders(id:string) {
    return jsonRows<{id:string;order_number:string;created_at:string;total_amount:number|string;status:string}>(db,
      'SELECT jsonb_build_object(\'id\',id,\'order_number\',order_number,\'created_at\',created_at,\'total_amount\',total_amount,\'status\',status)::text AS item FROM public.orders WHERE customer_identity_id=$1::uuid ORDER BY created_at DESC,id DESC',[uuid(id)])
  }
  return {list,metrics,orders}
}

import 'server-only'
import type { DbExecutor } from '../query'
import type { CouponRow } from '@/app/dashboard/coupons/coupon-types'
import { couponSaveSchema } from '../../coupon-save'
import { exactId, jsonRows, OperationsError, uuid } from './operations-shared'
const fields=['code','title','discount_type','discount_value','reward_type','minimum_order_amount','gift_product_id','gift_variant_data','gift_banner_image_url','banner_enabled','banner_title','banner_description','starts_at','ends_at','featured_priority','usage_limit','is_active'] as const
const columns='id,code,title,discount_type,discount_value,reward_type,minimum_order_amount,gift_product_id,gift_variant_data,gift_banner_image_url,banner_enabled,banner_title,banner_description,starts_at,ends_at,featured_priority,usage_limit,usage_count,is_active,created_at'
export function createCouponsRepository(db:DbExecutor) {
  async function list() {return jsonRows<CouponRow>(db,`SELECT to_jsonb(c)::text AS item FROM (SELECT ${columns} FROM public.coupons ORDER BY created_at DESC,id DESC) c`)}
  async function one(id:unknown) {return (await jsonRows<CouponRow>(db,`SELECT to_jsonb(c)::text AS item FROM (SELECT ${columns} FROM public.coupons WHERE id=$1::bigint) c`,[exactId(id)]))[0]??null}
  async function save(raw:unknown) {
    const coupon=couponSaveSchema.parse(raw)
    const date=(value:string|null)=>{if(!value)return null;const d=new Date(value);if(Number.isNaN(d.getTime()))throw new OperationsError(400,'Enter a valid coupon date.');return d.toISOString()}
    const starts=date(coupon.starts_at),ends=date(coupon.ends_at)
    if(starts && ends && ends<=starts)throw new OperationsError(400,'The end date and time must be after the start date and time.')
    const gift=coupon.reward_type==='free_gift'?coupon.gift_product_id:null
    const variantData=coupon.reward_type==='free_gift'?coupon.gift_variant_data:{}
    if(gift){
      const product=await db.query('SELECT id FROM public.products WHERE id=$1::uuid AND status::text=\'active\' AND stock_quantity>=1 FOR UPDATE',[uuid(gift)])
      if(product.rows.length!==1)throw new OperationsError(400,'The selected gift product must be active and in stock.')
      // Lock existing association rows until commit; the parent UPDATE lock also serializes FK checks.
      const variants=await db.query<{id:string}>('SELECT id FROM public.product_metal_variants WHERE product_id=$1::uuid FOR SHARE',[gift])
      const variant=variantData.variant_id
      if(variants.rows.length && !variant)throw new OperationsError(400,'Select the exact gift variant.')
      if(variant && !variants.rows.some(v=>v.id===variant))throw new OperationsError(400,'The selected gift variant does not belong to this product.')
    }
    const payload={...coupon,code:coupon.code.toUpperCase(),title:coupon.title.trim(),discount_type:coupon.reward_type==='fixed'?'fixed':'percentage',discount_value:coupon.reward_type==='free_gift'?0:coupon.discount_value,gift_product_id:gift,gift_variant_data:variantData,starts_at:starts,ends_at:ends,gift_banner_image_url:coupon.gift_banner_image_url?.trim()||null,banner_title:coupon.banner_title?.trim()||null,banner_description:coupon.banner_description?.trim()||null}
    const projection=fields.map(f=>`(jsonb_populate_record(NULL::public.coupons,$1::jsonb)).${f}`).join(',')
    const rows=await jsonRows<{id:number|string}>(db,coupon.id
      ?`UPDATE public.coupons SET (${fields.join(',')})=(${projection}) WHERE id=$2::bigint RETURNING jsonb_build_object('id',id)::text AS item`
      :`INSERT INTO public.coupons (${fields.join(',')}) SELECT ${projection} RETURNING jsonb_build_object('id',id)::text AS item`,coupon.id?[JSON.stringify(payload),exactId(coupon.id)]:[JSON.stringify(payload)])
    if(rows.length!==1)throw new OperationsError(404,'Coupon not found.')
    return {ok:true,id:rows[0].id}
  }
  async function remove(id:unknown) {
    const result=await db.query('DELETE FROM public.coupons WHERE id=$1::bigint RETURNING id',[exactId(id)])
    if(result.rows.length!==1)throw new OperationsError(404,'Coupon not found.')
    return {ok:true}
  }
  return {list,one,save,remove}
}

