export type CatalogCommand = keyof CatalogArguments

type Snapshot<T> = { item: T | null; revision: string }
export type CatalogResults = { [K in CatalogCommand]: K extends `${string}_delete_${string}` ? { ok: true; id: string; usage?: unknown }
  : K extends `catalog_ring_${string}` ? CatalogRingSnapshot
  : K extends `catalog_metal_${string}` ? K extends `${string}_list_${string}` ? CatalogMetalRow[] : Snapshot<CatalogMetalRow>
  : K extends `catalog_hierarchy_${string}` ? K extends `${string}_list_${string}` ? CatalogHierarchyRow[] : Snapshot<CatalogHierarchyRow>
  : K extends `${string}_list_${string}` ? CatalogMasterRow[] : Snapshot<CatalogMasterRow> }

export function createCatalogRepository(db: DbExecutor, actor?: AdminActor) {
  async function execute<K extends CatalogCommand>(name: K, input: CatalogArguments[K]): Promise<CatalogResults[K]> {
    const routine = catalogRoutines[name]
    if (!routine) throw new Error('Unsupported command')
    const supplied = input as Record<string, unknown>
    const values = routine.args.map((key, index) => {
      const value = key === 'p_actor_id' ? actor?.profileId : supplied[key]
      if (value === undefined) throw new Error('Missing trusted actor or routine argument')
      return routine.types[index] === 'jsonb' ? JSON.stringify(value) : value
    })
    let sql: string = routine.sql
    if (name === 'catalog_metal_list_v1') sql = `WITH snapshot AS MATERIALIZED (${routine.sql}) SELECT coalesce((SELECT jsonb_agg(jsonb_set(m.value,'{composition_parts}',coalesce((SELECT jsonb_agg(p.value || jsonb_build_object('id',p.value->>'id') ORDER BY p.ordinality) FROM jsonb_array_elements(m.value->'composition_parts') WITH ORDINALITY p),'[]'::jsonb)) ORDER BY m.ordinality) FROM jsonb_array_elements(snapshot.result) WITH ORDINALITY m),'[]'::jsonb) AS result FROM snapshot`
    if (name === 'catalog_metal_row_v1' || name === 'catalog_metal_save_v1') sql = `WITH snapshot AS MATERIALIZED (${routine.sql}) SELECT CASE WHEN result->'item' = 'null'::jsonb THEN result ELSE jsonb_set(result,'{item,composition_parts}',coalesce((SELECT jsonb_agg(p.value || jsonb_build_object('id',p.value->>'id') ORDER BY p.ordinality) FROM jsonb_array_elements(result#>'{item,composition_parts}') WITH ORDINALITY p),'[]'::jsonb)) END AS result FROM snapshot`
    const { rows } = await db.query<{ result: unknown }>(sql, values)
    if (rows.length !== 1 || rows[0].result === null || typeof rows[0].result !== 'object') throw new Error('Invalid database result')
    const result = rows[0].result
    if (name.includes('_list_')) { if (!Array.isArray(result)) throw new Error('Invalid list result') }
    else if (Array.isArray(result)) throw new Error('Invalid snapshot result')
    if (!name.includes('_list_')) {
      const record = result as Record<string, unknown>
      if (name.includes('_delete_')) {
        if (record.ok !== true || typeof record.id !== 'string') throw new Error('Invalid deletion result')
      } else {
        if (typeof record.revision !== 'string' || !/^[a-f0-9]{32}$/.test(record.revision)) throw new Error('Invalid catalog revision')
        if (name.startsWith('catalog_ring_')) {
          if (!Array.isArray(record.categories) || !Array.isArray(record.sizes)) throw new Error('Invalid ring snapshot')
        } else if (!('item' in record) || (record.item !== null && (typeof record.item !== 'object' || Array.isArray(record.item)))) throw new Error('Invalid catalog item')
      }
    }
    return result as CatalogResults[K]
  }
  return { execute, async navbarItems(): Promise<CatalogNavbarItem[]> {
    const { rows } = await db.query<{ result: CatalogNavbarItem[] }>("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY display_order),'[]'::jsonb) AS result FROM public.navbar_items r")
    if (rows.length !== 1 || !Array.isArray(rows[0].result)) throw new Error('Invalid navbar references')
    return rows[0].result
  } }
}

import 'server-only'
import type { z } from 'zod'
import type { portfolioCategoryCreateSchema, portfolioItemCreateSchema } from '../../bespoke-portfolio-validation'
import type { PortfolioCategory, PortfolioItem, BespokeSubmission } from '@/app/dashboard/bespoke/bespoke-client'
import type { DbExecutor } from '../query'

type CategoryInput = z.infer<typeof portfolioCategoryCreateSchema>
type ItemInput = z.infer<typeof portfolioItemCreateSchema>
type PortfolioInputs = { category: CategoryInput; item: ItemInput }
type PortfolioRows = { category: PortfolioCategory; item: PortfolioItem }
const fields = {
  category: ['name','slug','image_path','display_order','status'],
  item: ['title','tag','category_id','media_type','media_path','thumbnail_path','gem_style','gem_color','dark_theme','short_description','display_order','status'],
} as const
const tables = { category: 'bespoke_portfolio_categories', item: 'bespoke_portfolio_items' } as const
const submissionColumns = 'id,full_name,email,phone,country,piece_type,stone_preference,approx_carat,preferred_metal,message,status,created_at'
export function createBespokeRepository(db: DbExecutor) {
  function tableFor(kind: keyof PortfolioRows) {
    if (!Object.hasOwn(tables,kind)) throw new Error('Unsupported portfolio kind')
    return tables[kind]
  }
  async function list<K extends keyof PortfolioRows>(kind: K): Promise<PortfolioRows[K][]> {
    const { rows } = await db.query<{item: PortfolioRows[K]}>(`SELECT to_jsonb(t) AS item FROM public.${tableFor(kind)} t ORDER BY display_order`)
    return rows.map(row => row.item)
  }
  async function exists(kind: keyof PortfolioRows, id: string) {
    return (await db.query(`SELECT id FROM public.${tableFor(kind)} WHERE id=$1::uuid`,[id])).rows.length === 1
  }
  async function save<K extends keyof PortfolioRows>(kind: K, input: PortfolioInputs[K], id?: string, expected?: string, now = new Date().toISOString()): Promise<PortfolioRows[K] | null> {
    const table = tableFor(kind)
    const columns = fields[kind]
    const projection = columns.map(column => `(jsonb_populate_record(NULL::public.${table},$1::jsonb)).${column}`).join(',')
    const sql = id
      ? `UPDATE public.${table} SET (${columns.join(',')},updated_at)=(${projection},$4::timestamptz) WHERE id=$2::uuid AND updated_at=$3::timestamptz RETURNING to_jsonb(${table}) AS item`
      : `INSERT INTO public.${table} (${columns.join(',')}) SELECT ${projection} RETURNING to_jsonb(${table}) AS item`
    const { rows } = await db.query<{item: PortfolioRows[K]}>(sql,id ? [JSON.stringify(input),id,expected,now] : [JSON.stringify(input)])
    if (rows.length > 1) throw new Error('Invalid portfolio result')
    return rows[0]?.item ?? null
  }
  async function remove(kind: keyof PortfolioRows, id: string, expected: string) {
    return (await db.query(`DELETE FROM public.${tableFor(kind)} WHERE id=$1::uuid AND updated_at=$2::timestamptz RETURNING id`,[id,expected])).rows.length === 1
  }
  async function submissions(filters: {from?:string;to?:string;q?:string} = {}, bounded = true): Promise<BespokeSubmission[]> {
    const { rows } = await db.query<{item:BespokeSubmission}>(`SELECT to_jsonb(t) AS item FROM (SELECT ${submissionColumns} FROM public.bespoke_submissions WHERE ($1::timestamptz IS NULL OR created_at >= $1::timestamptz) AND ($2::timestamptz IS NULL OR created_at <= $2::timestamptz) ORDER BY created_at DESC ${bounded ? 'LIMIT 1000' : ''}) t`,[filters.from ? `${filters.from}T00:00:00.000Z` : null, filters.to ? `${filters.to}T23:59:59.999Z` : null])
    const q=filters.q?.toLowerCase() ?? ''
    return rows.map(row=>row.item).filter(item=>!q || [item.full_name,item.email,item.phone,item.country,item.piece_type,item.stone_preference,item.approx_carat,item.preferred_metal,item.message,item.status].filter(Boolean).join(' ').toLowerCase().includes(q))
  }
  async function submission(id: string): Promise<BespokeSubmission | null> {
    const {rows}=await db.query<{item:BespokeSubmission}>(`SELECT to_jsonb(t) AS item FROM (SELECT ${submissionColumns} FROM public.bespoke_submissions WHERE id=$1::uuid) t`,[id])
    if(rows.length>1)throw new Error('Invalid submission result')
    return rows[0]?.item ?? null
  }
  return {list,exists,save,remove,submissions,submission}
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { cmsIdSchema } from './cms-id-safety'
import type { assertAdmin } from './cms-auth'

type Access = Exclude<Awaited<ReturnType<typeof assertAdmin>>, { error: NextResponse }>
type DatabaseError = { code?: string; message?: string }

const optionalText = (max: number) => z.string().max(max)
const optionalNullableText = (max: number) => z.string().max(max).nullable()

const giftVariantSchema = z.object({
  variant_id: z.string().uuid().optional(),
  label: optionalText(500).optional(),
  price: z.number().finite().nonnegative().optional(),
  image_url: optionalText(2_000).optional(),
  sku: optionalText(200).optional(),
  product_name: optionalText(500).optional(),
  product_slug: optionalText(500).optional(),
}).strict()

export const couponSaveSchema = z.object({
  id: cmsIdSchema.optional(),
  code: z.string().trim().min(1, 'Coupon code is required.').max(100).regex(/^[A-Za-z0-9_-]+$/, 'Coupon code may only contain letters, numbers, hyphens, and underscores.'),
  title: optionalText(500),
  reward_type: z.enum(['percentage', 'fixed', 'free_gift']),
  discount_type: z.enum(['percentage', 'fixed']),
  discount_value: z.number().finite().nonnegative(),
  minimum_order_amount: z.number().finite().nonnegative(),
  gift_product_id: z.string().uuid().nullable(),
  gift_variant_id: z.union([z.string().uuid(), z.literal('')]),
  gift_variant_data: giftVariantSchema,
  gift_banner_image_url: optionalNullableText(2_000),
  banner_enabled: z.boolean(),
  banner_title: optionalNullableText(500),
  banner_description: optionalNullableText(5_000),
  starts_at: optionalNullableText(100),
  ends_at: optionalNullableText(100),
  featured_priority: z.number().int().min(0).max(1_000_000),
  usage_limit: z.number().int().positive().nullable(),
  is_active: z.boolean(),
}).strict().superRefine((value, context) => {
  if (value.reward_type === 'percentage' && value.discount_value > 100) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['discount_value'], message: 'Percentage discount cannot exceed 100%.' })
  }
  if (value.reward_type === 'free_gift' && (!value.gift_product_id || value.minimum_order_amount <= 0)) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['gift_product_id'], message: 'Free-gift coupons require a product and a minimum order amount.' })
  }
})

function parseOptionalDate(value: string | null, label: string) {
  if (!value) return { value: null as string | null }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) return { error: `${label} must be a valid date and time.` }
  return { value: parsed.toISOString() }
}

export function couponDatabaseError(error: DatabaseError, operation: 'save' | 'delete') {
  if (error.code === '23505') return { status: 409, message: 'A coupon with this code already exists.' }
  if (error.code === '23503') return { status: 409, message: operation === 'delete' ? 'This coupon is still referenced and cannot be deleted.' : 'A selected coupon reference is no longer available.' }
  if (['22023', '22P02', '23502', '23514'].includes(error.code ?? '')) return { status: 400, message: 'The coupon details are invalid.' }
  return { status: 500, message: operation === 'delete' ? 'Unable to delete the coupon.' : 'Unable to save the coupon. No changes were applied.' }
}

export async function saveCoupon(access: Access, input: unknown) {
  const parsed = couponSaveSchema.safeParse(input)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.issues[0]?.message ?? 'Invalid coupon details.' }, { status: 400 })

  const coupon = parsed.data
  const startsAt = parseOptionalDate(coupon.starts_at, 'Start date')
  if ('error' in startsAt) return NextResponse.json({ error: startsAt.error }, { status: 400 })
  const endsAt = parseOptionalDate(coupon.ends_at, 'End date')
  if ('error' in endsAt) return NextResponse.json({ error: endsAt.error }, { status: 400 })
  if (startsAt.value && endsAt.value && new Date(endsAt.value) <= new Date(startsAt.value)) {
    return NextResponse.json({ error: 'The end date and time must be after the start date and time.' }, { status: 400 })
  }

  const rewardType = coupon.reward_type
  const giftProductId = rewardType === 'free_gift' ? coupon.gift_product_id : null
  const giftVariantData = rewardType === 'free_gift' ? coupon.gift_variant_data : {}

  if (giftProductId) {
    const { data: giftProduct, error: giftProductError } = await access.adminClient.from('products').select('id, status, stock_quantity').eq('id', giftProductId).maybeSingle()
    if (giftProductError) {
      const safe = couponDatabaseError(giftProductError, 'save')
      return NextResponse.json({ error: safe.message }, { status: safe.status })
    }
    if (!giftProduct || giftProduct.status !== 'active' || Number(giftProduct.stock_quantity ?? 0) < 1) {
      return NextResponse.json({ error: 'The selected gift product must be active and in stock.' }, { status: 400 })
    }

    const variantId = giftVariantData.variant_id ?? null
    const { count: variantCount, error: countError } = await access.adminClient.from('product_metal_variants').select('id', { count: 'exact', head: true }).eq('product_id', giftProductId)
    if (countError) {
      const safe = couponDatabaseError(countError, 'save')
      return NextResponse.json({ error: safe.message }, { status: safe.status })
    }
    if ((variantCount ?? 0) > 0 && !variantId) return NextResponse.json({ error: 'Select the exact gift variant.' }, { status: 400 })
    if (variantId) {
      const { data: variant, error: variantError } = await access.adminClient.from('product_metal_variants').select('id').eq('id', variantId).eq('product_id', giftProductId).maybeSingle()
      if (variantError) {
        const safe = couponDatabaseError(variantError, 'save')
        return NextResponse.json({ error: safe.message }, { status: safe.status })
      }
      if (!variant) return NextResponse.json({ error: 'The selected gift variant does not belong to this product.' }, { status: 400 })
    }
  }

  const payload = {
    code: coupon.code.toUpperCase(), title: coupon.title.trim(), discount_type: rewardType === 'fixed' ? 'fixed' : 'percentage',
    discount_value: rewardType === 'free_gift' ? 0 : coupon.discount_value, reward_type: rewardType,
    minimum_order_amount: coupon.minimum_order_amount, gift_product_id: giftProductId, gift_variant_data: giftVariantData,
    gift_banner_image_url: coupon.gift_banner_image_url?.trim() || null, banner_enabled: coupon.banner_enabled,
    banner_title: coupon.banner_title?.trim() || null, banner_description: coupon.banner_description?.trim() || null,
    starts_at: startsAt.value, ends_at: endsAt.value, featured_priority: coupon.featured_priority,
    usage_limit: coupon.usage_limit, is_active: coupon.is_active,
  }

  const result = coupon.id
    ? await access.adminClient.from('coupons').update(payload).eq('id', coupon.id).select('id').maybeSingle()
    : await access.adminClient.from('coupons').insert(payload).select('id').single()
  if (result.error) {
    const safe = couponDatabaseError(result.error, 'save')
    return NextResponse.json({ error: safe.message }, { status: safe.status })
  }
  if (!result.data?.id) return NextResponse.json({ error: 'Coupon not found.' }, { status: 404 })
  return NextResponse.json({ ok: true, id: result.data.id }, { headers: { 'Cache-Control': 'no-store' } })
}

export async function deleteCoupon(access: Access, rawId: string) {
  const id = cmsIdSchema.safeParse(rawId)
  if (!id.success) return NextResponse.json({ error: 'Invalid coupon ID.' }, { status: 400 })
  const { data, error } = await access.adminClient.from('coupons').delete().eq('id', id.data).select('id').maybeSingle()
  if (error) {
    const safe = couponDatabaseError(error, 'delete')
    return NextResponse.json({ error: safe.message }, { status: safe.status })
  }
  if (!data) return NextResponse.json({ error: 'Coupon not found.' }, { status: 404 })
  return NextResponse.json({ ok: true }, { headers: { 'Cache-Control': 'no-store' } })
}

import { tryUploadAwsImage } from '@/lib/image-transport'
import { cmsFetch } from '@/lib/cms-transport'

export type CoupleSection = {
  section_key: string
  eyebrow: string
  heading: string
  subtitle: string
}

export type CoupleItem = {
  clientId: string
  id?: number | string
  sort_order: number
  names: string
  location: string
  story: string
  product_name: string
  product_link: string
  product_detail: string
  image_path: string
}

type CouplesPayload = {
  section?: CoupleSection
  items?: Array<{
    id: number | string
    sort_order: number
    names: string
    location: string
    story: string
    product_name: string
    product_link: string
    product_detail: string
    image_path: string
  }>
  error?: string
}

export const defaultCoupleSection: CoupleSection = {
  section_key: 'home_couples',
  eyebrow: 'Love Stories',
  heading: 'Our Cute Couples',
  subtitle: 'Real couples. Real proposals. Real diamonds. Every ring tells a story.',
}

export function emptyCouple(sortOrder: number): CoupleItem {
  return {
    clientId: `draft-${Date.now()}`,
    sort_order: sortOrder,
    names: '',
    location: '',
    story: '',
    product_name: '',
    product_link: '',
    product_detail: '',
    image_path: '',
  }
}

export async function getAdminAccessToken() {
  const { supabase } = await import('@/lib/supabase')
    const { data } = await supabase.auth.getSession()
  return data.session?.access_token ?? null
}

export async function loadCouples() {



  const response = await cmsFetch('/api/cms/home/couples', {
    headers: {  },
  })
  const payload = (await response.json().catch(() => null)) as CouplesPayload | null

  if (!response.ok) {
    return { error: payload?.error ?? 'Unable to load couples.' } as const
  }

  return {
    section: payload?.section ?? defaultCoupleSection,
    items: (payload?.items ?? []).map((item) => ({
      clientId: `id-${item.id}`,
      id: item.id,
      sort_order: Number(item.sort_order ?? 0),
      names: item.names ?? '',
      location: item.location ?? '',
      story: item.story ?? '',
      product_name: item.product_name ?? '',
      product_link: item.product_link ?? '',
      product_detail: item.product_detail ?? '',
      image_path: item.image_path ?? '',
    })),
  } as const
}

export async function saveCouples(section: Omit<CoupleSection, 'section_key'>, items: CoupleItem[]) {



  const sortedItems = [...items].sort((a, b) => a.sort_order - b.sort_order || a.clientId.localeCompare(b.clientId))
  const response = await cmsFetch('/api/cms/home/couples', {
    method: 'POST',
    headers: {
      'content-type': 'application/json',

    },
    body: JSON.stringify({
      section,
      items: sortedItems.map(({ sort_order, names, location, story, product_name, product_link, product_detail, image_path }) => ({
        sort_order,
        names,
        location,
        story,
        product_name,
        product_link,
        product_detail,
        image_path,
      })),
    }),
  })

  const payload = (await response.json().catch(() => null)) as CouplesPayload | null
  if (!response.ok) {
    return { error: payload?.error ?? 'Unable to save couples.' } as const
  }

  return { ok: true } as const
}

export async function uploadCoupleImage(file: File) {

    try {
      const awsPath = await tryUploadAwsImage(file, '/api/cms/uploads/couples', {})
      if (awsPath) { return {path: awsPath} as const }
    } catch (error) { return {error: error instanceof Error ? error.message : 'Unable to upload image.'} as const }


  const token = await getAdminAccessToken()
  if (!token) return { error: 'You are not signed in.' } as const

  if (file.size > 5 * 1024 * 1024) return { error: 'File too large. Max size is 5MB.' } as const

  const { supabase } = await import('@/lib/supabase')
    try {
    const preparedFile = await prepareCoupleImage(file)
    const signResponse = await fetch('/api/cms/uploads/couples/sign', {
      method: 'POST',
      headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
        body: JSON.stringify({ contentType: preparedFile.type, declaredSize: preparedFile.size }),
    })
    const signed = await signResponse.json().catch(() => null) as { bucket?: string; path?: string; token?: string; error?: string } | null
    if (!signResponse.ok || !signed?.bucket || !signed.path || !signed.token) throw new Error(signed?.error ?? 'Unable to prepare upload.')
    const { error } = await supabase.storage.from(signed.bucket)
      .uploadToSignedUrl(signed.path, signed.token, preparedFile, { contentType: preparedFile.type })
    if (error) throw error
    return { path: signed.path } as const
  } catch {
    // Preserve the established server upload as an operational fallback.
  }

  const formData = new FormData()
  formData.append('file', file)

  const response = await fetch('/api/cms/uploads/couples', {
    method: 'POST',
    headers: { authorization: `Bearer ${token}` },
    body: formData,
  })

  const payload = (await response.json().catch(() => null)) as { path?: string; error?: string } | null
  if (!response.ok || !payload?.path) {
    return { error: payload?.error ?? 'Unable to upload image.' } as const
  }

  return { path: payload.path } as const
}

async function prepareCoupleImage(file: File) {
  if (file.type === 'image/svg+xml') return file
  if (!['image/jpeg', 'image/png', 'image/webp', 'image/avif'].includes(file.type)) throw new Error('Invalid image type.')
  const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' })
  try {
    const width = Math.min(bitmap.width, 1600)
    const height = Math.max(1, Math.round(bitmap.height * (width / bitmap.width)))
    const canvas = document.createElement('canvas')
    canvas.width = width
    canvas.height = height
    canvas.getContext('2d')?.drawImage(bitmap, 0, 0, width, height)
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/webp', 0.82))
    if (!blob) throw new Error('Unable to optimize image.')
    return new File([blob], `${crypto.randomUUID()}.webp`, { type: 'image/webp' })
  } finally {
    bitmap.close()
  }
}

'use client'
export async function cmsRequestHeaders(mutation = true): Promise<Headers> {
  const contract = await fetch('/api/cms/provider', { credentials: 'same-origin', cache: 'no-store' })
  const payload = await contract.json()
  if (!contract.ok || !['supabase','rds'].includes(payload?.provider)) throw new Error('Content service unavailable.')
  const headers = new Headers({ 'content-type': 'application/json' })
  if (payload.provider === 'rds') {
    const result = await fetch('/api/auth/session', { credentials: 'same-origin', cache: 'no-store' })
    const session = await result.json()
    if (!result.ok || session?.authenticated !== true || typeof session.csrfToken !== 'string' || !session.csrfToken) throw new Error('Please sign in again.')
    if (mutation) headers.set('x-admin-csrf', session.csrfToken)
  } else {
    const { supabase } = await import('./supabase')
    const { data } = await supabase.auth.getSession()
    if (!data.session?.access_token) throw new Error('Please sign in again.')
    headers.set('authorization', `Bearer ${data.session.access_token}`)
  }
  return headers
}
export async function cmsFetch(url: string, options: RequestInit = {}) {
  const pathname = url.split('?')[0]
  const cms = /^\/api\/cms\/(?:about\/(?:founders|hero|timeline|values|wide-banner)|bespoke\/(?:manufacturing|process)|(?:blog|education)\/(?:hero|posts(?:\/[1-9][0-9]*)?)|contact\/(?:hero|info)|docs\/(?:terms|privacy-policy|shipping|returns)|home\/(?:bespoke-showcase|bestsellers|certifications|collection|collection-page|couples|discover-rings|discover-shapes|hero|hiphop|hiphop-showcase|reels|shop-by-category|testimonials-cards)|checkout-result|promotion|service-banner|summary|support\/(?:announcement-bar|faq(?:\/categories)?)|references\/products)$/
  const bespoke = /^\/api\/bespoke\/(?:hero|form-config|(?:submissions|portfolio-categories|portfolio-items)(?:\/[0-9a-f-]{36})?)$/i
  if ((!cms.test(pathname) && !bespoke.test(pathname)) || url.includes('#')) throw new Error('Invalid content data path.')
  try {
    const headers = await cmsRequestHeaders(!['GET','HEAD'].includes((options.method ?? 'GET').toUpperCase()))
    new Headers(options.headers).forEach((value,key) => { if (!['authorization','x-admin-csrf'].includes(key.toLowerCase())) headers.set(key,value) })
    return await fetch(url,{...options,credentials:'same-origin',headers})
  } catch {
    return Response.json({error:'Content request unavailable. Please sign in again or retry after the service is restored.'},{status:503})
  }
}

