import { NextResponse } from 'next/server'
import { z } from 'zod'
import { cmsMutation, readCms, type CmsAccess, type CmsReader } from './cms-command'
import { supportAnnouncementItemSchema, supportAnnouncementParentSchema, supportFaqItemSchema, supportFaqParentSchema } from './cms-support-schemas'
import { checkoutResultItemSchema, checkoutResultParentSchema, promotionItemSchema, promotionParentSchema, serviceBannerItemSchema, serviceBannerParentSchema, summaryItemSchema, summaryParentSchema } from './cms-shared-schemas'

export type CmsRelationalKind = 'checkout_result' | 'promotion' | 'service_banner' | 'summary' | 'announcement' | 'faq'
type Access = CmsAccess
const uuid = z.string().uuid()

const schemas: Record<CmsRelationalKind, { parent: z.ZodTypeAny; item: z.ZodTypeAny }> = {
  checkout_result: {
    parent: checkoutResultParentSchema,
    item: checkoutResultItemSchema,
  },
  promotion: {
    parent: promotionParentSchema,
    item: promotionItemSchema,
  },
  service_banner: {
    parent: serviceBannerParentSchema,
    item: serviceBannerItemSchema,
  },
  summary: {
    parent: summaryParentSchema,
    item: summaryItemSchema,
  },
  announcement: {
    parent: supportAnnouncementParentSchema,
    item: supportAnnouncementItemSchema,
  },
  faq: {
    parent: supportFaqParentSchema,
    item: supportFaqItemSchema,
  },
}

const envelope = z.object({ request_id: uuid, expected_revision: z.string().regex(/^[a-f0-9]{32}$/), deleted_ids: z.array(z.string().min(1)).max(500), parent: z.record(z.string(), z.unknown()), items: z.array(z.record(z.string(), z.unknown())).max(500) }).strict()
export type CmsRelationalSnapshot = { parent: Record<string, unknown> | null; items: Array<Record<string, unknown>>; revision: string }

export async function loadCmsRelationalSnapshot(client: CmsReader, kind: CmsRelationalKind) {
  const { data, error } = await readCms(client, 'cms_relational_snapshot_v1', { p_kind: kind })
  if (error) throw new Error(error.code === 'PGRST202' || error.code === '42883' ? 'This CMS section is awaiting its database migration.' : 'Unable to load this CMS section.')
  return data as CmsRelationalSnapshot
}

export function errorResponse(error: { code?: string; message?: string }) {
  if (error.code === 'PGRST202' || error.code === '42883') return NextResponse.json({ error: 'This CMS section is awaiting its database update. Existing content was not changed.' }, { status: 503 })
  if (error.code === '40001') return NextResponse.json({ error: 'This section changed after you opened it. Reload before saving again.' }, { status: 409 })
  if (['22023', '22P02', '23502', '23503', '23505', '23514'].includes(error.code ?? '')) return NextResponse.json({ error: 'This section contains invalid or conflicting data.' }, { status: 400 })
  return NextResponse.json({ error: 'Unable to save this section. No partial changes were committed.' }, { status: 500 })
}

export async function saveCmsRelational(access: Access, kind: CmsRelationalKind, input: unknown) {
  const parsed = envelope.safeParse(input)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.issues[0]?.message ?? 'Invalid save payload.' }, { status: 400 })
  const parent = schemas[kind].parent.safeParse(parsed.data.parent)
  if (!parent.success) return NextResponse.json({ error: parent.error.issues[0]?.message ?? 'Invalid section details.' }, { status: 400 })
  const items = z.array(schemas[kind].item).safeParse(parsed.data.items)
  if (!items.success) return NextResponse.json({ error: items.error.issues[0]?.message ?? 'Invalid section item.' }, { status: 400 })
  const ids = items.data.flatMap((item: { id?: unknown }) => item.id == null ? [] : [String(item.id)])
  if (new Set(ids).size !== ids.length || new Set(parsed.data.deleted_ids).size !== parsed.data.deleted_ids.length || ids.some((id) => parsed.data.deleted_ids.includes(id))) return NextResponse.json({ error: 'Item IDs must be unique and cannot also be deleted.' }, { status: 400 })
  if (kind === 'checkout_result' && (items.data.length !== 4 || new Set(items.data.map((item: { state: string }) => item.state)).size !== 4)) return NextResponse.json({ error: 'All four checkout states are required.' }, { status: 400 })
  if (kind === 'promotion') {
    const promotion = parent.data as { cta_action: string; cta_link: string; selected_coupon_id: number | string | null }
    if (promotion.cta_action === 'redirect' && !promotion.cta_link.trim()) return NextResponse.json({ error: 'A destination link is required for Redirect mode.' }, { status: 400 })
    if (promotion.cta_action === 'reveal_coupon') {
      if (!promotion.selected_coupon_id) return NextResponse.json({ error: 'Select an active coupon for Reveal coupon mode.' }, { status: 400 })
      const coupon = 'provider' in access
        ? (await access.db.query<{ id: number; usage_limit: number | null; usage_count: number | null }>('SELECT id,usage_limit,usage_count FROM public.coupons WHERE id=$1::bigint AND is_active=true', [promotion.selected_coupon_id])).rows[0]
        : (await access.adminClient.from('coupons').select('id,usage_limit,usage_count').eq('id', promotion.selected_coupon_id).eq('is_active', true).maybeSingle()).data
      if (!coupon || (coupon.usage_limit != null && Number(coupon.usage_count ?? 0) >= Number(coupon.usage_limit))) return NextResponse.json({ error: 'The selected coupon is unavailable or has reached its usage limit.' }, { status: 400 })
    }
  }
  const { data, error } = await cmsMutation(access, 'cms_save_relational_v1', { p_request_id: parsed.data.request_id, p_expected_revision: parsed.data.expected_revision, p_kind: kind, p_parent: parent.data, p_items: items.data, p_deleted_ids: parsed.data.deleted_ids })
  if (error) return errorResponse(error)
  return NextResponse.json({ ok: true, ...(data as object) }, { headers: { 'Cache-Control': 'no-store' } })
}

import 'server-only'
import type { CmsReader } from './cms-command'
import type { CmsReferenceResults } from './db/admin-repositories/cms-references'
import type { createSupabaseAdminClient } from './admin-supabase'
export async function readCmsReference<K extends keyof CmsReferenceResults>(reader: CmsReader, name: K): Promise<{data: CmsReferenceResults[K]; error: {message: string} | null}> {
  if ('execute' in reader) return { data: await reader.references.read(name), error: null }
  const client = reader as ReturnType<typeof createSupabaseAdminClient>
  const queries = {
    categories: () => client.from('catalog_categories').select('*').order('display_order'),
    activeCategories: () => client.from('catalog_categories').select('id,name,slug').eq('status','active').order('display_order'),
    subcategories: () => client.from('catalog_subcategories').select('*').order('display_order'),
    options: () => client.from('catalog_options').select('*').order('display_order'),
    shapes: () => client.from('catalog_stone_shapes').select('id,name,slug').eq('status','active').order('display_order'),
    products: () => client.from('products').select('*').order('created_at',{ascending:false}),
    coupons: () => client.from('coupons').select('id,code,title,is_active,usage_limit,usage_count').eq('is_active',true).order('created_at',{ascending:false}),
    blog: () => client.from('blog_posts').select('id,slug,title,category,catalog_category_id,author,date_label,read_time,is_published,sort_order,updated_at').order('sort_order'),
    education: () => client.from('education_posts').select('id,slug,title,category,author,date_label,read_time,is_published,sort_order,updated_at').order('sort_order'),
    faqCategories: () => client.from('support_faq_categories').select('id,name,slug,image_path,image_alt,is_active').order('sort_order'),
  }
  const result = await queries[name]()
  return { data: (result.data ?? []) as CmsReferenceResults[K], error: result.error }
}

import { z } from 'zod'
import { canonicalizeInstagramUrl } from './instagram-url'

const instagramUrl = z.string().max(500).transform((value, ctx) => {
  const canonical = canonicalizeInstagramUrl(value)
  if (!canonical) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'Use a valid public Instagram Reel or post URL.' })
    return z.NEVER
  }
  return canonical
})

export const reelsSaveSchema = z.object({
  request_id: z.string().uuid(),
  expected_revision: z.string().regex(/^[a-f0-9]{32}$/),
  heading: z.string().trim().min(1).max(120),
  subtitle: z.string().trim().max(240),
  is_enabled: z.boolean(),
  marquee_duration_seconds: z.number().int().min(10).max(180),
  pause_on_hover: z.boolean(),
  deleted_ids: z.array(z.string().uuid()).max(30),
  items: z.array(z.object({
    id: z.string().uuid().optional(),
    instagram_url: instagramUrl,
    title: z.string().trim().max(100),
    is_enabled: z.boolean(),
    cover_image_url: z.string().trim().max(1000).url().refine((value) => /^https?:\/\//i.test(value), 'Use HTTP or HTTPS.').nullable().optional(),
  }).strict()).max(30),
}).strict().superRefine((payload, ctx) => {
  const ids = payload.items.flatMap((item) => item.id ? [item.id] : [])
  const urls = payload.items.map((item) => item.instagram_url)
  if (new Set(ids).size !== ids.length || new Set(payload.deleted_ids).size !== payload.deleted_ids.length
    || payload.deleted_ids.some((id) => ids.includes(id))) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'A reel ID was duplicated or both retained and deleted.' })
  }
  if (new Set(urls).size !== urls.length) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'Each reel URL must be unique.' })
  }
})

export function reelsSaveError(error: { code?: string; message?: string }) {
  if (error.code === 'PGRST202' || error.code === '42883') {
    return { status: 503, message: 'Reels saving is awaiting a database update. Your saved content has not been changed.' }
  }
  if (error.code === '40001') return { status: 409, message: 'This Reels section changed after you opened it. Reload before saving again.' }
  if (error.code === '42501') return { status: 403, message: 'Administrator access is required.' }
  if (error.code === '22023' || error.code === '22P02') return { status: 400, message: 'The Reels section contains invalid or conflicting data.' }
  if (error.code === '23505') return { status: 409, message: 'A reel URL or position conflicts with another entry. Your changes were not saved.' }
  return { status: 500, message: 'Unable to save reels. No part of this save was committed. Please try again.' }
}

import { homeGroup1Error } from './cms-home-group1-save'
import { contentListError } from './cms-content-list-save'
import { categoryError } from './cms-faq-category-error'
import 'server-only'
import { singletonError } from './cms-singleton-save'
import { errorResponse as relationalError } from './cms-relational-save'
import { articleError } from './cms-article-save'
import { docsError } from './cms-docs-save'
import { errorResponse as heroError } from './bespoke-hero-save'
import { saveErrorResponse as formError } from './bespoke-form-save'
import { reelsSaveError } from './cms-reels-save'
import { portfolioMutationError } from './bespoke-portfolio-validation'
import type { AdminActor } from './auth/admin-identity-core'
import type { DbExecutor } from './db/query'
import type { CmsAccess } from './cms-command'
import { assertAdmin } from './cms-auth'
import { adminTransaction } from './db/pool'
import { mapAdminDbError } from './db/errors'
import { authorizeProductRequest } from './product-session-runtime'
import { ProductSessionError } from './product-session-error'
import { createCmsRepository } from './db/admin-repositories/cms'
import { readCmsDataProvider } from './cms-provider'

type Dependencies = {
  provider: () => 'supabase' | 'rds'
  authorize: (request: Request, mutation: boolean) => Promise<{ actor: AdminActor }>
  transaction: <T>(run: (db: DbExecutor) => Promise<T>) => Promise<T>
  legacy: typeof assertAdmin
}
export function cmsErrorResponse(error: unknown, request?: Request) {
  const mapped = mapAdminDbError(error)
  const code = mapped.sqlState
  if (code && request && !['GET','HEAD'].includes(request.method) && mapped.kind !== 'permission' && mapped.kind !== 'unavailable' && !(error instanceof ProductSessionError)) {
    const path = new URL(request.url).pathname
    const failure = {code:code==='40P01'?'40001':code}
    let result: Response | undefined
    if (/\/bespoke\/portfolio-/.test(path)) {
      const safe=portfolioMutationError(failure,path.includes('categories')?'category':'item',request.method==='DELETE'?'delete':'save')
      result=Response.json({error:safe.message},{status:safe.status})
    } else if (path==='/api/bespoke/hero') result=heroError(failure)
    else if (path==='/api/bespoke/form-config') result=formError(failure)
    else if (path==='/api/cms/support/faq/categories') result=categoryError(failure)
    else if (/\/cms\/(?:blog|education)\/posts/.test(path)) result=articleError(failure,request.method==='DELETE'?'delete':'save')
    else if (path.startsWith('/api/cms/docs/')) result=docsError(failure,'save')
    else if (path==='/api/cms/home/reels') { const safe=reelsSaveError(failure);result=Response.json({error:safe.message},{status:safe.status}) }
    else if (/\/(?:promotion|summary|checkout-result|service-banner|support\/(?:faq|announcement-bar))$/.test(path)) result=relationalError(failure)
    else if (/\/cms\/home\/(?:hero|collection|certifications|discover-shapes|bestsellers|shop-by-category)$/.test(path)) result=homeGroup1Error(failure)
    else if (/\/cms\/(?:about\/(?:values|timeline|founders)|contact\/info|bespoke\/(?:process|manufacturing))$/.test(path)) result=contentListError(failure)
    else if (/\/(?:hero|wide-banner|bespoke-showcase|collection-page|hiphop-showcase)$/.test(path)) result=singletonError(failure)
    if (result) { result.headers.set('Cache-Control','no-store');return result }
  }
  const status = error instanceof ProductSessionError ? error.status
    : mapped.kind === 'permission' ? 403 : mapped.kind === 'unavailable' ? 503
    : ['40001','40P01','PT409'].includes(code ?? '') ? 409 : code === 'P0002' ? 404
    : ['22023','22P02','23502','23503','23505','23514'].includes(code ?? '') ? 400 : 503
  return Response.json({ error: status === 401 ? 'Unauthorized.' : status === 403 ? 'Administrator access is required.'
    : status === 409 ? 'This content changed or the request was reused. Reload before continuing.'
    : status === 404 ? 'Content not found.' : status === 400 ? 'The content contains invalid or conflicting data.'
    : 'Content service unavailable. No fallback was attempted.' }, { status, headers: { 'Cache-Control': 'no-store' } })
}
export function createCmsDataRoute(deps: Dependencies) {
  return async (request: Request, run: (access: CmsAccess) => Promise<Response>): Promise<Response> => {
    try {
      if (deps.provider() === 'supabase') {
        const access = await deps.legacy(request)
        if ('error' in access) return access.error ?? cmsErrorResponse(new Error('Authorization unavailable'))
        return run(access)
      }
      const { actor } = await deps.authorize(request, !['GET','HEAD'].includes(request.method))
      const result = await deps.transaction(async db => {
        // A caught read failure must still roll back; never commit an aborted/partial operation.
        let failure: unknown
        const checked: DbExecutor = { query: async (sql, values) => {
          try { return await db.query(sql, values) } catch (error) { failure = error; throw error }
        } }
        const response = await run({ provider: 'rds', actor, cms: createCmsRepository(checked, actor), db: checked })
        if (failure) throw failure
        return response
      })
      result.headers.set('Cache-Control','no-store')
      return result
    } catch (error) { return cmsErrorResponse(error, request) }
  }
}
export const withCmsDataRoute = createCmsDataRoute({ provider: () => readCmsDataProvider(process.env), authorize: authorizeProductRequest, transaction: adminTransaction, legacy: assertAdmin })

/** Keep the same request ID only while the exact reviewed save envelope is unchanged. */
export function createCmsPendingSave() {
  let pending: {fingerprint:string;body:string}|null=null
  return {
    prepare(body:string) {
      const parsed=JSON.parse(body) as Record<string,unknown>
      const payload={...parsed}
      delete payload.request_id
      const fingerprint=JSON.stringify(payload)
      if(pending?.fingerprint!==fingerprint)pending={fingerprint,body}
      return pending.body
    },
    clear(){pending=null},
  }
}

