export type CmsContentListKind = 'about_values' | 'about_timeline' | 'about_founders' | 'contact_info' | 'bespoke_process' | 'bespoke_manufacturing'
type Access = CmsAccess

export { readCmsSaveEnvelope }

export async function loadCmsContentListSnapshot(
  client: CmsReader,
  kind: CmsContentListKind,
) {
  const { data, error } = await readCms(client, 'cms_content_list_snapshot_v1', { p_kind: kind })
  if (error) {
    throw new Error(error.code === 'PGRST202' || error.code === '42883'
      ? 'This CMS section is awaiting its database migration.'
      : 'Unable to load this CMS section.')
  }
  return data as { items: Array<Record<string, unknown>>; revision: string }
}

export async function saveCmsContentList(
  access: Access,
  kind: CmsContentListKind,
  envelope: { requestId: string; revision: string; deletedIds: string[] },
  items: Array<Record<string, unknown>>,
) {
  const retainedIds = items.flatMap((item) => item.id == null ? [] : [String(item.id)])
  if (new Set(retainedIds).size !== retainedIds.length) {
    return NextResponse.json({ error: 'The same saved item cannot appear more than once.' }, { status: 400 })
  }
  if (envelope.deletedIds.some((id) => retainedIds.includes(id))) {
    return NextResponse.json({ error: 'An item cannot be retained and deleted in the same save.' }, { status: 400 })
  }
  const { data, error } = await cmsMutation(access, 'cms_save_content_list_v1', {
    p_request_id: envelope.requestId,
    p_expected_revision: envelope.revision,
    p_kind: kind,
    p_items: items,
    p_deleted_ids: envelope.deletedIds,
  })

  if (!error) return NextResponse.json({ ok: true, ...data }, { headers: { 'Cache-Control': 'no-store' } })
  return contentListError(error)
}

export function contentListError(error: {code?:string}) {
  if (error.code === 'PGRST202' || error.code === '42883') {
    return NextResponse.json({ error: 'This CMS section is awaiting its database update. Existing content was not changed.' }, { status: 503 })
  }
  if (error.code === '40001') return NextResponse.json({ error: 'This section changed after you opened it. Reload before saving again.' }, { status: 409 })
  if (error.code === '22023' || error.code === '22P02' || error.code === '23503' || error.code === '23514') {
    return NextResponse.json({ error: 'The section contains invalid or conflicting data.' }, { status: 400 })
  }
  return NextResponse.json({ error: 'Unable to save this section. No part of the save was committed.' }, { status: 500 })
}

import 'server-only'
import type { assertAdmin } from './cms-auth'
import type { AdminActor } from './auth/admin-identity-core'
import type { CmsArguments, CmsCommand, createCmsRepository } from './db/admin-repositories/cms'
import type { DbExecutor } from './db/query'
type LegacyAccess = Exclude<Awaited<ReturnType<typeof assertAdmin>>, { error: unknown }>
export type CmsRdsAccess = { provider: 'rds'; actor: AdminActor; cms: ReturnType<typeof createCmsRepository>; db: DbExecutor }
export type CmsAccess = LegacyAccess | CmsRdsAccess
export type CmsReader = { rpc: (name: string, args?: Record<string, unknown>) => PromiseLike<{ data: unknown; error: { code?: string; message?: string } | null }> } | ReturnType<typeof createCmsRepository>
export function cmsReader(access: CmsAccess): CmsReader { return 'provider' in access ? access.cms : access.adminClient }
export async function readCms<K extends CmsCommand>(reader: CmsReader, name: K, input: CmsArguments[K]) {
  if ('execute' in reader) return { data: await reader.execute(name, input), error: null }
  return reader.rpc(name, input)
}
export async function cmsMutation<K extends CmsCommand>(access: CmsAccess, name: K, input: CmsArguments[K]) {
  if ('provider' in access) return { data: await access.cms.execute(name, input), error: null }
  return access.adminClient.rpc(name, { ...input, p_actor_id: access.user.id })
}

import { NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { createSupabaseServerSessionClient } from '@/lib/server-supabase'
import { assertLegacyAdminAuth } from './auth/integration'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY
const supabaseServiceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY

export function buildAuthClient(accessToken: string) {
  assertLegacyAdminAuth()
  if (!supabaseUrl || !supabaseAnonKey) return null
  return createClient(supabaseUrl, supabaseAnonKey, {
    global: { headers: { Authorization: `Bearer ${accessToken}` } },
  })
}

export function buildAdminClient() {
  assertLegacyAdminAuth()
  if (!supabaseUrl || !supabaseServiceRoleKey) return null
  return createClient(supabaseUrl, supabaseServiceRoleKey)
}

export async function assertAdmin(request: Request) {
  try { assertLegacyAdminAuth() }
  catch { return { error: NextResponse.json({ error: 'Legacy admin access unavailable.' }, { status: 503, headers: { 'Cache-Control': 'no-store' } }) } }
  const authHeader = request.headers.get('authorization')
  const adminClient = buildAdminClient()

  if (!adminClient) {
    return { error: NextResponse.json({ error: 'Missing Supabase env vars.' }, { status: 500 }) }
  }

  let authClient: Awaited<ReturnType<typeof createSupabaseServerSessionClient>> | ReturnType<typeof buildAuthClient> | null = null
  let accessToken: string | null = null

  if (authHeader?.startsWith('Bearer ')) {
    accessToken = authHeader.slice('Bearer '.length)
    authClient = buildAuthClient(accessToken)
  } else {
    authClient = await createSupabaseServerSessionClient()
  }

  if (!authClient) {
    return { error: NextResponse.json({ error: 'Missing authorization token.' }, { status: 401 }) }
  }

  const { data: userData, error: userError } = await authClient.auth.getUser()
  if (userError || !userData.user) {
    return { error: NextResponse.json({ error: 'Unauthorized.' }, { status: 401 }) }
  }

  const { data: profile, error: profileError } = await adminClient
    .from('profiles')
    .select('role')
    .eq('id', userData.user.id)
    .single()

  if (profileError || profile?.role !== 'admin') {
    return { error: NextResponse.json({ error: 'Forbidden.' }, { status: 403 }) }
  }

  return { adminClient, authClient, accessToken, user: userData.user }
}

export type CmsSaveEnvelope = {
  requestId: string
  revision: string
  deletedIds: string[]
}

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const revisionPattern = /^[0-9a-f]{32}$/

export function readCmsSaveEnvelope(body: Record<string, unknown>): CmsSaveEnvelope | null {
  const requestId = typeof body.request_id === 'string' && uuidPattern.test(body.request_id) ? body.request_id : null
  const revision = typeof body.expected_revision === 'string' && revisionPattern.test(body.expected_revision) ? body.expected_revision : null
  const rawDeletedIds = Array.isArray(body.deleted_ids) && body.deleted_ids.every((id) => typeof id === 'string' && id.length > 0)
    ? body.deleted_ids as string[]
    : null
  const deletedIds = rawDeletedIds && new Set(rawDeletedIds).size === rawDeletedIds.length ? rawDeletedIds : null
  return requestId && revision && deletedIds ? { requestId, revision, deletedIds } : null
}

import { z } from 'zod'

const cmsIdSchema = z.union([z.number().int().safe().positive(), z.string().regex(/^[1-9][0-9]*$/).refine(value => /^[1-9][0-9]*$/.test(value) && BigInt(value) <= BigInt('9223372036854775807'), 'Invalid CMS identifier')])

const persistedId = cmsIdSchema.transform(String)
const uuid = z.string().uuid()
const optionalText = z.string().max(200_000).default('')

const tagSchema = z.object({ id: persistedId.optional(), tag: z.string().trim().min(1).max(200) }).strict()
const productSchema = z.object({ id: persistedId.optional(), product_id: uuid }).strict()
const blockSchema = z.object({
  id: persistedId.optional(), block_type: z.enum(['text', 'image', 'heading', 'quote']), heading: optionalText,
  body_html: optionalText, image_path: optionalText, image_alt: optionalText, image_caption: optionalText, is_enabled: z.boolean(),
}).strict().superRefine((block, context) => {
  const required = block.block_type === 'image' ? block.image_path : block.block_type === 'heading' ? block.heading : block.body_html
  if (!required.trim()) context.addIssue({ code: z.ZodIssueCode.custom, message: 'The content block is incomplete.' })
})

const articlePostSchema = z.object({
  slug: optionalText, title: z.string().trim().min(1).max(500), title_html: optionalText, card_title: optionalText,
  subtitle: z.string().trim().min(1).max(10_000), category: optionalText, catalog_category_id: z.union([uuid, z.literal(''), z.null()]).optional(),
  author: optionalText, date_label: optionalText, read_time: optionalText, bg_key: optionalText, bg_color: optionalText,
  hero_image_path: optionalText, card_image_path: optionalText, hero_image_alt: optionalText,
  body_html: z.string().trim().min(1).max(1_000_000), is_published: z.boolean(), sort_order: z.coerce.number().int().min(-1_000_000).max(1_000_000),
}).strict()

export const articleSaveSchema = z.object({
  request_id: uuid, expected_revision: z.string().regex(/^[a-f0-9]{32}$/).nullable().optional(), post: articlePostSchema,
  tags: z.array(tagSchema).max(100), products: z.array(productSchema).max(100), content_blocks: z.array(blockSchema).max(100),
  deleted_tag_ids: z.array(persistedId).max(100), deleted_product_ids: z.array(persistedId).max(100), deleted_block_ids: z.array(persistedId).max(100),
}).strict().superRefine((payload, context) => {
  const checks: Array<[string, Array<string | undefined>, string[]]> = [
    ['tag', payload.tags.map((item) => item.id), payload.deleted_tag_ids],
    ['product relation', payload.products.map((item) => item.id), payload.deleted_product_ids],
    ['content block', payload.content_blocks.map((item) => item.id), payload.deleted_block_ids],
  ]
  for (const [label, ids, deletedIds] of checks) {
    const saved = ids.filter((id): id is string => Boolean(id))
    if (new Set(saved).size !== saved.length) context.addIssue({ code: z.ZodIssueCode.custom, message: `A ${label} ID is duplicated.` })
    if (new Set(deletedIds).size !== deletedIds.length || deletedIds.some((id) => saved.includes(id))) {
      context.addIssue({ code: z.ZodIssueCode.custom, message: `A deleted ${label} ID is invalid or duplicated.` })
    }
  }
  const normalizedTags = payload.tags.map((item) => item.tag.toLowerCase())
  if (new Set(normalizedTags).size !== normalizedTags.length) context.addIssue({ code: z.ZodIssueCode.custom, message: 'Tags must be unique.' })
  if (new Set(payload.products.map((item) => item.product_id)).size !== payload.products.length) context.addIssue({ code: z.ZodIssueCode.custom, message: 'Products may only be selected once.' })
})

export const articleDeleteSchema = z.object({ request_id: uuid, expected_revision: z.string().regex(/^[a-f0-9]{32}$/) }).strict()

import { sanitizeCmsHtml } from './cms-html'
import { NextResponse } from 'next/server'
import { cmsMutation, readCms, cmsReader, type CmsAccess } from './cms-command'
import { createBlogSlug } from './blog-slug'
import { createEducationSlug } from './education-slug'
import { articleDeleteSchema, articleSaveSchema } from './cms-article-schemas'
export { articleDeleteSchema, articleSaveSchema } from './cms-article-schemas'

export type CmsArticleKind = 'blog' | 'education'
type Access = CmsAccess

export type ArticleSnapshot = {
  post: Record<string, unknown>
  tags: Array<Record<string, unknown>>
  products: Array<{ id: number | string; product_id: string; sort_order: number }>
  content_blocks: Array<Record<string, unknown>>
  revision: string
}

export function articleError(error: { code?: string; message?: string }, action: 'load' | 'save' | 'delete') {
  if (error.code === 'PGRST202' || error.code === '42883') {
    return NextResponse.json({ error: 'This CMS section is awaiting its database update. Existing content was not changed.' }, { status: 503 })
  }
  if (error.code === 'P0002') return NextResponse.json({ error: 'Article not found.' }, { status: 404 })
  if (error.code === '40001') return NextResponse.json({ error: 'This article changed after you opened it. Reload before saving again.' }, { status: 409 })
  if (['22023', '22P02', '23503', '23505', '23514'].includes(error.code ?? '')) {
    return NextResponse.json({ error: 'The article contains invalid or conflicting data.' }, { status: 400 })
  }
  return NextResponse.json({ error: `Unable to ${action} this article. No partial changes were committed.` }, { status: 500 })
}

export async function enrichArticleSnapshot(access: Access, snapshot: ArticleSnapshot) {
  const productIds = snapshot.products.map((item) => item.product_id)
  let productsById = new Map<string, Record<string, unknown>>()
  if (productIds.length) {
    const { data, error } = 'provider' in access
      ? { data: (await access.db.query<{ item: Record<string, unknown> }>("SELECT to_jsonb(p) AS item FROM (SELECT id,slug,name,base_price,status FROM public.products WHERE id=ANY($1::uuid[])) p", [productIds])).rows.map(row => row.item), error: null }
      : await access.adminClient.from('products').select('id, slug, name, base_price, status').in('id', productIds)
    if (error) throw new Error('Unable to load linked products.')
    productsById = new Map((data ?? []).map((product) => [String(product.id), product]))
  }
  return {
    ...snapshot,
    products: snapshot.products.map((relation) => ({
      ...relation,
      product: productsById.get(relation.product_id) ?? null,
    })),
  }
}

export async function loadCmsArticle(access: Access, kind: CmsArticleKind, postId: number | string) {
  const { data, error } = await readCms(cmsReader(access), 'cms_article_snapshot_v1', { p_kind: kind, p_post_id: postId })
  if (error) return articleError(error, 'load')
  try {
    return NextResponse.json(await enrichArticleSnapshot(access, data as ArticleSnapshot), { headers: { 'Cache-Control': 'no-store' } })
  } catch (error) {
    if ('provider' in access) throw error
    return NextResponse.json({ error: 'Unable to load linked products.' }, { status: 500 })
  }
}

export async function saveCmsArticle(access: Access, kind: CmsArticleKind, postId: number | string | null, input: unknown) {
  const parsed = articleSaveSchema.safeParse(input)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.issues[0]?.message ?? 'Invalid article payload.' }, { status: 400 })
  }
  if (postId === null && parsed.data.expected_revision) {
    return NextResponse.json({ error: 'A new article cannot use an existing revision.' }, { status: 400 })
  }
  if (postId !== null && !parsed.data.expected_revision) {
    return NextResponse.json({ error: 'This editor is out of date. Reload it before saving.' }, { status: 409 })
  }

  const slugBase = kind === 'blog' ? createBlogSlug(parsed.data.post.title) : createEducationSlug(parsed.data.post.title)
  const post = {
    ...parsed.data.post,
    slug_base: slugBase,
    title_html: sanitizeCmsHtml(parsed.data.post.title_html.trim() || parsed.data.post.title),
    body_html: sanitizeCmsHtml(parsed.data.post.body_html),
    catalog_category_id: kind === 'blog' ? parsed.data.post.catalog_category_id || null : null,
  }
  const { data, error } = await cmsMutation(access, 'cms_save_article_v1', {
    p_request_id: parsed.data.request_id,
    p_kind: kind,
    p_post_id: postId,
    p_expected_revision: parsed.data.expected_revision ?? null,
    p_post: post,
    p_tags: parsed.data.tags,
    p_products: parsed.data.products,
    p_blocks: parsed.data.content_blocks.map(block => ({...block,body_html:sanitizeCmsHtml(block.body_html),heading:sanitizeCmsHtml(block.heading)})),
    p_deleted_tag_ids: parsed.data.deleted_tag_ids,
    p_deleted_product_ids: parsed.data.deleted_product_ids,
    p_deleted_block_ids: parsed.data.deleted_block_ids,
  })
  if (error) return articleError(error, 'save')
  try {
    const result = await enrichArticleSnapshot(access, data as ArticleSnapshot)
    return NextResponse.json({ ok: true, ...result, id: result.post.id, slug: result.post.slug }, { headers: { 'Cache-Control': 'no-store' } })
  } catch (error) {
    if ('provider' in access) throw error
    return NextResponse.json({ error: 'The article was saved, but its linked product details could not be reloaded.' }, { status: 500 })
  }
}

export async function deleteCmsArticle(access: Access, kind: CmsArticleKind, postId: number | string, input: unknown) {
  const parsed = articleDeleteSchema.safeParse(input)
  if (!parsed.success) return NextResponse.json({ error: 'Reload this editor before deleting.' }, { status: 409 })
  const { data, error } = await cmsMutation(access, 'cms_delete_article_v1', {
    p_request_id: parsed.data.request_id,
    p_kind: kind,
    p_post_id: postId,
    p_expected_revision: parsed.data.expected_revision,
  })
  if (error) return articleError(error, 'delete')
  return NextResponse.json(data, { headers: { 'Cache-Control': 'no-store' } })
}

