import { operationsPage } from '@/lib/operations-page-data'
import { createCouponsRepository } from '@/lib/db/admin-repositories/coupons'
import { couponProductSources } from '@/lib/db/admin-repositories/coupon-products'
import { createSupabaseAdminClient } from '@/lib/admin-supabase'
import type { CouponProduct, CouponRow } from './coupon-types'

const bucket = process.env.SUPABASE_COLLECTION_BUCKET ?? 'hod'

export function couponMediaUrl(path?: string | null) {
  if (!path) return ''
  if (/^https?:\/\//i.test(path)) return path
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL?.replace(/\/$/, '')
  return base ? `${base}/storage/v1/object/public/${bucket}/${path.replace(/^\/+/, '')}` : path
}

async function legacyGetCoupons(): Promise<CouponRow[]> {
  const client = createSupabaseAdminClient()
  const { data, error } = await client.from('coupons').select('id, code, title, discount_type, discount_value, reward_type, minimum_order_amount, gift_product_id, gift_variant_data, gift_banner_image_url, banner_enabled, banner_title, banner_description, starts_at, ends_at, featured_priority, usage_limit, usage_count, is_active, created_at').order('created_at', { ascending: false })
  if (error) throw new Error(error.message)
  return (data ?? []) as CouponRow[]
}

async function legacyGetCoupon(id: number | string): Promise<CouponRow | null> {
  const client = createSupabaseAdminClient()
  const { data, error } = await client.from('coupons').select('id, code, title, discount_type, discount_value, reward_type, minimum_order_amount, gift_product_id, gift_variant_data, gift_banner_image_url, banner_enabled, banner_title, banner_description, starts_at, ends_at, featured_priority, usage_limit, usage_count, is_active, created_at').eq('id', id).maybeSingle()
  if (error) throw new Error(error.message)
  return data as CouponRow | null
}

export async function getCouponProducts(): Promise<CouponProduct[]> {
  const {products,variants,metals,media}=await operationsPage(db=>couponProductSources(db),async()=>{
  const client = createSupabaseAdminClient()
  const [products, variants, metals, media] = await Promise.all([
    client.from('products').select('id, name, slug, sku, status, stock_quantity, base_price, image_1_path').eq('status', 'active').order('name'),
    client.from('product_metal_variants').select('id, product_id, metal_id, price, is_default, sort_order').order('sort_order'),
    client.from('catalog_metals').select('id, name, display_label, purity_label, base_metal_name'),
    client.from('product_variant_media_items').select('variant_id, media_type, media_path, sort_order').eq('media_type', 'image').order('sort_order'),
  ])
return {products,variants,metals,media}
})
  for (const result of [products, variants, metals, media]) if (result.error) throw new Error(result.error.message)
  const metalById = new Map((metals.data ?? []).map((item) => [item.id, item]))
  const mediaByVariant = new Map<string, string>()
  for (const item of media.data ?? []) if (item.variant_id && !mediaByVariant.has(item.variant_id)) mediaByVariant.set(item.variant_id, couponMediaUrl(item.media_path))
  return (products.data ?? []).map((product) => {
    const productImage = couponMediaUrl(product.image_1_path)
    return {
      ...product,
      image_1_path: productImage,
      stock_quantity: Number(product.stock_quantity ?? 0),
      base_price: Number(product.base_price ?? 0),
      variants: (variants.data ?? []).filter((variant) => variant.product_id === product.id).map((variant) => {
        const metal = metalById.get(variant.metal_id)
        return { id: variant.id, label: metal?.display_label || [metal?.purity_label, metal?.base_metal_name || metal?.name].filter(Boolean).join(' ') || 'Default variant', price: Number(variant.price ?? 0), image_url: mediaByVariant.get(variant.id) || productImage, is_default: Boolean(variant.is_default) }
      }),
    }
  }) as CouponProduct[]
}

export function getCoupons():Promise<CouponRow[]> { return operationsPage(db=>createCouponsRepository(db).list(),legacyGetCoupons) }
export function getCoupon(id:number|string):Promise<CouponRow|null> {return operationsPage(db=>createCouponsRepository(db).one(id),()=>legacyGetCoupon(id))}

import 'server-only'
import { readCatalogDataProvider } from './catalog-provider'
import { authorizeProductPage } from './product-server-request'
import { adminQuery, adminTransaction } from './db/pool'
import { createCatalogRepository } from './db/admin-repositories/catalog'
import { createSupabaseAdminClient } from './admin-supabase'
import { loadNavbarBuilderData, loadRdsNavbarBuilderData } from './navbar-data'
import type { CatalogReader } from './catalog-command'
import type { CatalogNavbarItem } from './product-catalog'

export async function catalogPageReader() {
  if (readCatalogDataProvider(process.env) === 'supabase') return createSupabaseAdminClient()
  await authorizeProductPage()
  // Each read uses B2 principal/TLS/transaction validation; no escaped pooled client.
  return createCatalogRepository({ query: async (sql, values) => ({ rows: await adminQuery(sql, values) }) })
}
export async function loadCatalogNavbarItems(reader: CatalogReader): Promise<CatalogNavbarItem[]> {
  if ('execute' in reader) return reader.navbarItems()
  const client = reader as ReturnType<typeof createSupabaseAdminClient>
  const result = await client.from('navbar_items').select('id, label, slug, item_type, linked_category_id, direct_link_url, status').order('display_order', { ascending: true })
  return result.error ? [] : result.data ?? []
}
export async function loadNavbarPageData() {
  if (readCatalogDataProvider(process.env) === 'supabase') return loadNavbarBuilderData(createSupabaseAdminClient())
  await authorizeProductPage()
  return adminTransaction(loadRdsNavbarBuilderData)
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { catalogMutation, catalogReader, readCatalog, type CatalogAccess, type CatalogReader } from './catalog-command'
import { invalidateProductListReferenceData } from './product-list-reference-cache'
import { buildCombinedMetalDisplayLabel } from './product-metal-variants'

type Access = CatalogAccess
type RpcError={code?:string;message?:string}
type RpcClient = CatalogReader
const optional=(max=2_000)=>z.string().max(max).nullable().optional()
const metal=z.object({name:z.string().trim().min(1).max(200),slug:z.string().trim().min(1).max(200).regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),purity_label:optional(100),base_metal_name:optional(200),display_label:optional(300),is_combined_option:z.boolean(),color_hex:optional(50),composition_description:optional(5_000),display_order:z.coerce.number().int().min(0).max(1_000_000),status:z.enum(['active','hidden'])}).strict()
const part=z.object({id:z.coerce.number().int().positive().optional(),part_name:z.string().trim().min(1).max(200),percentage:z.coerce.number().min(0).max(100),color_hex:optional(50),sort_order:z.coerce.number().int().min(0).max(1_000_000)}).strict()
const rdsPartId = z.union([z.number().int().positive().safe(), z.string().regex(/^[1-9][0-9]*$/).refine(value => /^[1-9][0-9]{0,18}$/.test(value) && BigInt(value) <= BigInt('9223372036854775807'))]).transform(String)
const rdsPart = part.extend({ id: rdsPartId.optional() })
const saveEnvelope=z.object({request_id:z.string().uuid(),expected_revision:z.string().regex(/^[a-f0-9]{32}$/).nullable(),metal:z.record(z.string(),z.unknown()),parts:z.array(z.record(z.string(),z.unknown())).max(500),deleted_part_ids:z.array(z.coerce.number().int().positive()).max(500)}).strict()
const deleteEnvelope=z.object({request_id:z.string().uuid(),expected_revision:z.string().regex(/^[a-f0-9]{32}$/)}).strict()
const rdsSaveEnvelope = saveEnvelope.extend({ deleted_part_ids: z.array(rdsPartId).max(500) })
export type CatalogMetalRow=Record<string,unknown>&{id:string;_revision:string;composition_parts:Array<Record<string,unknown>&{id:number|string}>}
type Snapshot={item:CatalogMetalRow|null;revision:string}

export async function loadCatalogMetalList(client:RpcClient){const{data,error}=await readCatalog(client, 'catalog_metal_list_v1',{});if(error)throw new Error(error.code==='PGRST202'||error.code==='42883'?'Metals are awaiting their database migration.':'Unable to load metals.');return(Array.isArray(data)?data:[])as CatalogMetalRow[]}
export async function loadCatalogMetal(client:RpcClient,id:string){const{data,error}=await readCatalog(client, 'catalog_metal_row_v1',{p_id:id});if(error)throw new Error(error.code==='PGRST202'||error.code==='42883'?'Metals are awaiting their database migration.':'Unable to load this metal.');return(data as Snapshot).item}
export function catalogMetalErrorResponse(error:RpcError,action:'save'|'delete'){if(error.code==='PGRST202'||error.code==='42883')return NextResponse.json({error:'Metals are awaiting their database update. Existing data was not changed.'},{status:503});if(error.code==='40001'||error.code==='P0001')return NextResponse.json({error:'This metal changed or conflicts with another saved record. Reload before continuing.'},{status:409});if(error.code==='P0002')return NextResponse.json({error:'This metal no longer exists.'},{status:404});if(error.code==='42501')return NextResponse.json({error:'Administrator access is required.'},{status:403});if(['22023','22P02','23502','23503','23505','23514'].includes(error.code??''))return NextResponse.json({error:'This metal contains invalid or conflicting data.'},{status:400});return NextResponse.json({error:`Unable to ${action} this metal. No partial changes were committed.`},{status:500})}
export async function listCatalogMetals(access:Access){try{return NextResponse.json({items:await loadCatalogMetalList(catalogReader(access))},{headers:{'Cache-Control':'no-store'}})}catch{return NextResponse.json({error:'Unable to load metals.'},{status:503})}}
export async function saveCatalogMetal(access:Access,id:string|null,input:unknown){const envelope=('provider' in access ? rdsSaveEnvelope : saveEnvelope).safeParse(input);if(!envelope.success)return NextResponse.json({error:envelope.error.issues[0]?.message??'Invalid metal save request.'},{status:400});if((id===null)!==(envelope.data.expected_revision===null))return NextResponse.json({error:id===null?'New metals cannot include an existing revision.':'An existing revision is required.'},{status:400});const parsedId=id===null?null:z.string().uuid().safeParse(id);if(parsedId!==null&&!parsedId.success)return NextResponse.json({error:'Invalid metal ID.'},{status:400});const parsedMetal=metal.safeParse(envelope.data.metal),parsedParts=z.array('provider' in access ? rdsPart : part).safeParse(envelope.data.parts);if(!parsedMetal.success)return NextResponse.json({error:parsedMetal.error.issues[0]?.message??'Invalid metal details.'},{status:400});if(!parsedParts.success)return NextResponse.json({error:parsedParts.error.issues[0]?.message??'Invalid composition details.'},{status:400});if(new Set(parsedParts.data.flatMap(x=>x.id?[x.id]:[])).size!==parsedParts.data.filter(x=>x.id).length||new Set<string | number>(envelope.data.deleted_part_ids).size!==envelope.data.deleted_part_ids.length)return NextResponse.json({error:'Composition IDs must be unique.'},{status:400});const base=parsedMetal.data.base_metal_name?.trim()||parsedMetal.data.name;const label=buildCombinedMetalDisplayLabel({...parsedMetal.data,base_metal_name:base});const normalized={...parsedMetal.data,name:parsedMetal.data.is_combined_option?label:parsedMetal.data.name,base_metal_name:base,display_label:label};const{data,error}=await catalogMutation(access, 'catalog_metal_save_v1',{p_request_id:envelope.data.request_id,p_expected_revision:envelope.data.expected_revision,p_id:parsedId===null?null:parsedId.data,p_metal:normalized,p_parts:parsedParts.data,p_deleted_part_ids:envelope.data.deleted_part_ids});if(error)return catalogMetalErrorResponse(error,'save');invalidateProductListReferenceData();return NextResponse.json(data,{headers:{'Cache-Control':'no-store'}})}
export async function deleteCatalogMetal(access:Access,id:string,input:unknown){const parsedId=z.string().uuid().safeParse(id),envelope=deleteEnvelope.safeParse(input);if(!parsedId.success||!envelope.success)return NextResponse.json({error:'A valid metal ID, request ID, and revision are required.'},{status:400});const{data,error}=await catalogMutation(access, 'catalog_metal_delete_v1',{p_request_id:envelope.data.request_id,p_expected_revision:envelope.data.expected_revision,p_id:parsedId.data});if(error)return catalogMetalErrorResponse(error,'delete');invalidateProductListReferenceData();return NextResponse.json(data,{headers:{'Cache-Control':'no-store'}})}

type Part={id?:number|string}
export function catalogMetalSaveBody(metal:Record<string,unknown>,parts:Part[],expectedRevision:string|null,originalParts:Part[]=[]){const retained=new Set(parts.flatMap(x=>x.id?[x.id]:[]));return JSON.stringify({request_id:crypto.randomUUID(),expected_revision:expectedRevision,metal,parts,deleted_part_ids:originalParts.flatMap(x=>x.id&&!retained.has(x.id)?[x.id]:[])})}
export function catalogMetalDeleteBody(expectedRevision:string){return JSON.stringify({request_id:crypto.randomUUID(),expected_revision:expectedRevision})}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { catalogMutation, catalogReader, readCatalog, type CatalogAccess, type CatalogReader } from './catalog-command'

export type CatalogMasterKind = 'gst_slab' | 'certificate' | 'material_value' | 'ring_size' | 'stone_shape' | 'style' | 'content_rule'
type Access = CatalogAccess
type RpcClient = CatalogReader

const required = (max = 10_000) => z.string().trim().min(1).max(max)
const optional = (max = 10_000) => z.string().max(max).nullable().optional()
const order = z.coerce.number().int().min(0).max(1_000_000)
const status = z.enum(['active', 'hidden'])
const slug = z.string().trim().min(1).max(200).regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'Use a lowercase URL slug with hyphens only.')

const schemas: Record<CatalogMasterKind, z.ZodTypeAny> = {
  gst_slab: z.object({ name: required(200), code: required(50), percentage: z.coerce.number().min(0).max(100), description: optional(2_000), status, display_order: order }).strict(),
  certificate: z.object({ name: required(200), code: optional(100), status, display_order: order }).strict(),
  material_value: z.object({ name: required(200), slug, cta_mode: z.enum(['both', 'enquire_only', 'checkout_only']), cta_label: optional(200), status, display_order: order }).strict(),
  ring_size: z.object({ name: required(200), slug, status, display_order: order }).strict(),
  stone_shape: z.object({ name: required(200), slug, svg_asset_url: optional(2_000), status, display_order: order }).strict(),
  style: z.object({ name: required(200), icon_svg_path: optional(2_000), status, display_order: order }).strict(),
  content_rule: z.object({ kind: z.enum(['shipping', 'care_warranty']), name: required(200), slug, title: required(500), body: required(50_000), status, display_order: order }).strict(),
}

const saveEnvelope = z.object({
  request_id: z.string().uuid(),
  expected_revision: z.string().regex(/^[a-f0-9]{32}$/).nullable(),
  item: z.record(z.string(), z.unknown()),
}).strict()
const deleteEnvelope = z.object({ request_id: z.string().uuid(), expected_revision: z.string().regex(/^[a-f0-9]{32}$/) }).strict()

export type CatalogMasterRow = Record<string, unknown> & { id: string; _revision: string }
export type CatalogMasterSnapshot = { item: Record<string, unknown> | null; revision: string }

export async function loadCatalogMasterList(client: RpcClient, kind: CatalogMasterKind) {
  const { data, error } = await readCatalog(client, 'catalog_master_list_v1', { p_kind: kind })
  if (error) throw new Error(error.code === 'PGRST202' || error.code === '42883' ? 'Catalog masters are awaiting their database migration.' : 'Unable to load catalog masters.')
  return (Array.isArray(data) ? data : []) as CatalogMasterRow[]
}

export function catalogMasterErrorResponse(error: { code?: string; message?: string }, action: 'save' | 'delete') {
  if (error.code === 'PGRST202' || error.code === '42883') return NextResponse.json({ error: 'This catalog section is awaiting its database update. Existing data was not changed.' }, { status: 503 })
  if (error.code === '40001') return NextResponse.json({ error: 'This catalog record changed after you opened it. Reload before continuing.' }, { status: 409 })
  if (error.code === 'P0001') return NextResponse.json({ error: 'This catalog record conflicts with another saved record.' }, { status: 409 })
  if (error.code === 'P0002') return NextResponse.json({ error: 'The catalog record no longer exists.' }, { status: 404 })
  if (['22023', '22P02', '23502', '23503', '23505', '23514'].includes(error.code ?? '')) return NextResponse.json({ error: 'This catalog record contains invalid or conflicting data.' }, { status: 400 })
  return NextResponse.json({ error: `Unable to ${action} this catalog record. No partial changes were committed.` }, { status: 500 })
}

export async function listCatalogMasters(access: Access, kind: CatalogMasterKind) {
  try {
    const items = await loadCatalogMasterList(catalogReader(access), kind)
    return NextResponse.json({ items }, { headers: { 'Cache-Control': 'no-store' } })
  } catch (error) { if ('provider' in access) throw error;
    return NextResponse.json({ error: 'Unable to load this catalog section.' }, { status: 503 })
  }
}

export async function saveCatalogMaster(access: Access, kind: CatalogMasterKind, id: string | null, input: unknown) {
  const envelope = saveEnvelope.safeParse(input)
  if (!envelope.success) return NextResponse.json({ error: envelope.error.issues[0]?.message ?? 'Invalid save request.' }, { status: 400 })
  if ((id === null) !== (envelope.data.expected_revision === null)) return NextResponse.json({ error: id === null ? 'New records cannot include an existing revision.' : 'An existing revision is required.' }, { status: 400 })
  const item = schemas[kind].safeParse(envelope.data.item)
  if (!item.success) return NextResponse.json({ error: item.error.issues[0]?.message ?? 'Invalid catalog details.' }, { status: 400 })
  const parsedId = id === null ? null : z.string().uuid().safeParse(id)
  if (parsedId !== null && !parsedId.success) return NextResponse.json({ error: 'Invalid catalog record ID.' }, { status: 400 })
  const { data, error } = await catalogMutation(access, 'catalog_save_master_v1', {
    p_request_id: envelope.data.request_id,
    p_expected_revision: envelope.data.expected_revision,
    p_kind: kind,
    p_id: parsedId === null ? null : parsedId.data,
    p_item: item.data,
  })
  if (error) return catalogMasterErrorResponse(error, 'save')
  const snapshot = data as CatalogMasterSnapshot
  return NextResponse.json({ ok: true, item: snapshot.item, revision: snapshot.revision }, { headers: { 'Cache-Control': 'no-store' } })
}

export async function deleteCatalogMaster(access: Access, kind: CatalogMasterKind, id: string, input: unknown) {
  const parsedId = z.string().uuid().safeParse(id)
  const envelope = deleteEnvelope.safeParse(input)
  if (!parsedId.success || !envelope.success) return NextResponse.json({ error: 'A valid record ID, request ID, and revision are required.' }, { status: 400 })
  const { data, error } = await catalogMutation(access, 'catalog_delete_master_v1', {
    p_request_id: envelope.data.request_id,
    p_expected_revision: envelope.data.expected_revision,
    p_kind: kind,
    p_id: parsedId.data,
  })
  if (error) return catalogMasterErrorResponse(error, 'delete')
  return NextResponse.json(data, { headers: { 'Cache-Control': 'no-store' } })
}

export function catalogMasterSaveBody(item: Record<string, unknown>, expectedRevision?: string | null) {
  return JSON.stringify({ request_id: crypto.randomUUID(), expected_revision: expectedRevision ?? null, item })
}

export function catalogMasterDeleteBody(expectedRevision: string) {
  return JSON.stringify({ request_id: crypto.randomUUID(), expected_revision: expectedRevision })
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { catalogMutation, catalogReader, readCatalog, type CatalogAccess, type CatalogReader } from './catalog-command'
import { invalidateProductListReferenceData } from './product-list-reference-cache'

export type CatalogHierarchyKind = 'category' | 'subcategory' | 'option'
type Access = CatalogAccess
type RpcError = { code?: string; message?: string }
type RpcClient = CatalogReader

const required = (max = 200) => z.string().trim().min(1).max(max)
const optional = (max = 2_000) => z.string().max(max).nullable().optional()
const order = z.coerce.number().int().min(0).max(1_000_000)
const status = z.enum(['active', 'hidden'])
const slug = z.string().trim().min(1).max(200).regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'Use a lowercase URL slug with hyphens only.')
const category = z.object({
  code: required(100), name: required(), slug, show_in_nav: z.boolean(), nav_type: z.enum(['mega_menu', 'direct_link']).nullable(), direct_link_url: optional(), display_order: order, status,
  banner_desktop_image_path: optional(), banner_mobile_image_path: optional(), banner_desktop_image_alt: optional(), banner_mobile_image_alt: optional(), banner_title: optional(500), banner_subtitle: optional(2_000), banner_cta_label: optional(200), banner_cta_link: optional(), banner_enabled: z.boolean().optional(),
}).strict()
const subcategory = z.object({ category_id: z.string().uuid(), name: required(), slug, sub_type: z.enum(['standard', 'auto_shape', 'manual_style', 'auto_metal', 'gender_split']), icon_svg_path: optional(), image_path: optional(), image_alt: optional(500), display_order: order, status }).strict()
const option = z.object({ subcategory_id: z.string().uuid(), name: required(), slug, icon_svg_path: optional(), image_path: optional(), image_alt: optional(500), display_order: order, status }).strict()
const schemas = { category, subcategory, option } as const
const saveEnvelope = z.object({ request_id: z.string().uuid(), expected_revision: z.string().regex(/^[a-f0-9]{32}$/).nullable(), item: z.record(z.string(), z.unknown()) }).strict()
const deleteEnvelope = z.object({ request_id: z.string().uuid(), expected_revision: z.string().regex(/^[a-f0-9]{32}$/) }).strict()

export type CatalogHierarchyRow = Record<string, unknown> & { id: string; _revision: string }
type Snapshot = { item: CatalogHierarchyRow | null; revision: string }

export async function loadCatalogHierarchyList(client: RpcClient, kind: CatalogHierarchyKind) {
  const { data, error } = await readCatalog(client, 'catalog_hierarchy_list_v1', { p_kind: kind })
  if (error) throw new Error(error.code === 'PGRST202' || error.code === '42883' ? 'Catalog hierarchy is awaiting its database migration.' : 'Unable to load the catalog hierarchy.')
  return (Array.isArray(data) ? data : []) as CatalogHierarchyRow[]
}

export function catalogHierarchyErrorResponse(error: RpcError, action: 'save' | 'delete') {
  if (error.code === 'PGRST202' || error.code === '42883') return NextResponse.json({ error: 'Catalog hierarchy is awaiting its database update. Existing data was not changed.' }, { status: 503 })
  if (error.code === '40001' || error.code === 'P0001') return NextResponse.json({ error: 'This catalog hierarchy changed or conflicts with another saved record. Reload before continuing.' }, { status: 409 })
  if (error.code === 'P0002') return NextResponse.json({ error: 'This catalog record no longer exists.' }, { status: 404 })
  if (error.code === '42501') return NextResponse.json({ error: 'Administrator access is required.' }, { status: 403 })
  if (['22023', '22P02', '23502', '23503', '23505', '23514'].includes(error.code ?? '')) return NextResponse.json({ error: 'The catalog hierarchy contains invalid or conflicting data.' }, { status: 400 })
  return NextResponse.json({ error: `Unable to ${action} this catalog record. No partial changes were committed.` }, { status: 500 })
}

async function loadSnapshot(client: RpcClient, kind: CatalogHierarchyKind, id: string): Promise<{ ok: false; error: RpcError } | { ok: true; snapshot: Snapshot }> {
  const { data, error } = await readCatalog(client, 'catalog_hierarchy_row_v1', { p_kind: kind, p_id: id })
  if (error) return { ok: false, error }
  return { ok: true, snapshot: data as Snapshot }
}

export async function saveCatalogHierarchy(access: Access, kind: CatalogHierarchyKind, id: string | null, input: unknown) {
  const envelope = saveEnvelope.safeParse(input)
  if (!envelope.success) return NextResponse.json({ error: envelope.error.issues[0]?.message ?? 'Invalid save request.' }, { status: 400 })
  if ((id === null) !== (envelope.data.expected_revision === null)) return NextResponse.json({ error: id === null ? 'New records cannot include an existing revision.' : 'An existing revision is required.' }, { status: 400 })
  const parsedId = id === null ? null : z.string().uuid().safeParse(id)
  if (parsedId !== null && !parsedId.success) return NextResponse.json({ error: 'Invalid catalog record ID.' }, { status: 400 })

  let candidate = envelope.data.item
  if (parsedId !== null) {
    const loaded = await loadSnapshot(catalogReader(access), kind, parsedId.data)
    if (!loaded.ok) return catalogHierarchyErrorResponse(loaded.error, 'save')
    if (!loaded.snapshot.item) return NextResponse.json({ error: 'This catalog record no longer exists.' }, { status: 404 })
    const excludedKeys = new Set(['id', '_revision', 'is_system_locked', 'category_lane'])
    const current = Object.fromEntries(
      Object.entries(loaded.snapshot.item).filter(([key]) => !excludedKeys.has(key)),
    )
    candidate = { ...current, ...candidate }
  }
  const item = schemas[kind].safeParse(candidate)
  if (!item.success) return NextResponse.json({ error: item.error.issues[0]?.message ?? 'Invalid catalog details.' }, { status: 400 })
  const { data, error } = await catalogMutation(access, 'catalog_hierarchy_save_v1', { p_request_id: envelope.data.request_id, p_expected_revision: envelope.data.expected_revision, p_kind: kind, p_id: parsedId === null ? null : parsedId.data, p_item: item.data })
  if (error) return catalogHierarchyErrorResponse(error, 'save')
  invalidateProductListReferenceData()
  const snapshot = data as Snapshot
  return NextResponse.json({ ok: true, item: snapshot.item, revision: snapshot.revision }, { headers: { 'Cache-Control': 'no-store' } })
}

export async function deleteCatalogHierarchy(access: Access, kind: CatalogHierarchyKind, id: string, input: unknown) {
  const parsedId = z.string().uuid().safeParse(id)
  const envelope = deleteEnvelope.safeParse(input)
  if (!parsedId.success || !envelope.success) return NextResponse.json({ error: 'A valid record ID, request ID, and revision are required.' }, { status: 400 })
  const { data, error } = await catalogMutation(access, 'catalog_hierarchy_delete_v1', { p_request_id: envelope.data.request_id, p_expected_revision: envelope.data.expected_revision, p_kind: kind, p_id: parsedId.data })
  if (error) return catalogHierarchyErrorResponse(error, 'delete')
  invalidateProductListReferenceData()
  return NextResponse.json(data, { headers: { 'Cache-Control': 'no-store' } })
}

export function catalogHierarchySaveBody(item: Record<string, unknown>, expectedRevision: string | null) {
  return JSON.stringify({ request_id: crypto.randomUUID(), expected_revision: expectedRevision, item })
}

export function catalogHierarchyDeleteBody(expectedRevision: string) {
  return JSON.stringify({ request_id: crypto.randomUUID(), expected_revision: expectedRevision })
}

import 'server-only'
import type { assertAdmin } from './cms-auth'
import type { AdminActor } from './auth/admin-identity-core'
import type { CatalogArguments, CatalogCommand, createCatalogRepository } from './db/admin-repositories/catalog'
import type { NavbarArguments, NavbarCommand, createNavbarRepository } from './db/admin-repositories/navbar'

type LegacyAccess = Exclude<Awaited<ReturnType<typeof assertAdmin>>, { error: unknown }>
export type CatalogRdsAccess = { provider: 'rds'; actor: AdminActor; catalog: ReturnType<typeof createCatalogRepository>; navbar: ReturnType<typeof createNavbarRepository> }
export type CatalogAccess = LegacyAccess | CatalogRdsAccess
type RpcClient = { rpc: (name: string, args: Record<string, unknown>) => PromiseLike<{ data: unknown; error: { code?: string; message?: string } | null }> }
export type CatalogReader = RpcClient | ReturnType<typeof createCatalogRepository>

export function catalogReader(access: CatalogAccess): CatalogReader {
  return 'provider' in access ? access.catalog : access.adminClient
}
export async function readCatalog<K extends CatalogCommand>(reader: CatalogReader, name: K, input: CatalogArguments[K]) {
  if ('execute' in reader) return { data: await reader.execute(name, input), error: null }
  return reader.rpc(name, input)
}
export async function catalogMutation<K extends CatalogCommand>(access: CatalogAccess, name: K, input: CatalogArguments[K]) {
  if ('provider' in access) return { data: await access.catalog.execute(name, input), error: null }
  return access.adminClient.rpc(name, { ...input, p_actor_id: access.user.id })
}
export async function navbarMutation<K extends NavbarCommand>(access: CatalogAccess, name: K, input: NavbarArguments[K]) {
  if ('provider' in access) return { data: await access.navbar.execute(name, input), error: null }
  return access.adminClient.rpc(name, { ...input, p_actor_id: access.user.id })
}

import 'server-only'
import { NextResponse } from 'next/server'
import { assertAdmin } from '@/lib/cms-auth'
import { loadCatalogMasterList } from '@/lib/catalog-master-save'
import { loadCatalogRingSnapshot } from '@/lib/catalog-ring-save'
import { loadCatalogHierarchyList } from '@/lib/catalog-hierarchy-save'
import { loadCatalogMetalList } from '@/lib/catalog-metal-save'

type CatalogClient = { from: (table: string) => { select: (columns: string) => { order: (column: string, options: { ascending: boolean }) => PromiseLike<{ data: unknown[] | null; error: unknown }> } } }

async function loadOptionalTable(adminClient: CatalogClient, table: string, columns = '*') {
  const result = await adminClient.from(table).select(columns).order('display_order', { ascending: true })
  if (result.error) return []
  return result.data ?? []
}

export async function loadLegacyCatalogBootstrap(request: Request) {

  const access = await assertAdmin(request)
  if ('error' in access) return access.error

  const { adminClient } = access
  const { searchParams } = new URL(request.url)
  const scope = searchParams.get('scope') ?? 'all'
  const includeBasics = scope === 'all' || scope === 'basics'
  const includePricing = scope === 'all' || scope === 'pricing'
  const includeAttributes = scope === 'all' || scope === 'attributes'
  const includeContent = scope === 'all' || scope === 'content'

  const [categories, subcategories, options, metalsResult, materialValues, stoneShapesResult, ringSizes, ringCategories, certificates, styles, productContentRules, gstSlabs, navbarItemsResult] = await Promise.all([
    includeBasics ? loadCatalogHierarchyList(adminClient, 'category') : Promise.resolve([]),
    includeBasics ? loadCatalogHierarchyList(adminClient, 'subcategory') : Promise.resolve([]),
    includeBasics ? loadCatalogHierarchyList(adminClient, 'option') : Promise.resolve([]),
    (includePricing || includeAttributes) ? loadCatalogMetalList(adminClient) : Promise.resolve([]),
    includeAttributes ? loadOptionalTable(adminClient, 'catalog_material_values', 'id, name, slug, display_order, status') : Promise.resolve([]),
    includeAttributes ? adminClient.from('catalog_stone_shapes').select('id, name, slug, svg_asset_url, display_order, status').order('display_order', { ascending: true }) : Promise.resolve({ data: [], error: null }),
    includeAttributes ? loadOptionalTable(adminClient, 'catalog_ring_sizes', 'id, name, slug, display_order, status') : Promise.resolve([]),
    includeAttributes ? loadCatalogRingSnapshot(adminClient) : Promise.resolve({ categories: [], sizes: [], revision: '' }),
    (includePricing || includeAttributes) ? loadOptionalTable(adminClient, 'catalog_certificates', 'id, name, code, slug, display_order, status') : Promise.resolve([]),
    includeBasics ? loadOptionalTable(adminClient, 'catalog_styles', 'id, name, icon_svg_path, display_order, status') : Promise.resolve([]),
    includeContent ? loadCatalogMasterList(adminClient, 'content_rule') : Promise.resolve([]),
    includePricing ? loadOptionalTable(adminClient, 'catalog_gst_slabs', 'id, name, code, percentage, description, display_order, status') : Promise.resolve([]),
    scope === 'all' ? adminClient.from('navbar_items').select('id, label, slug, item_type, linked_category_id, direct_link_url, status').order('display_order', { ascending: true }) : Promise.resolve({ data: [], error: null }),
  ])

  const error =
    stoneShapesResult.error

  if (error) {
    return NextResponse.json({ error: 'Unable to load the catalog editor data.' }, { status: 503 })
  }

  return NextResponse.json({
    ...(includeBasics
      ? {
          categories,
          subcategories,
          options,
          styles,
        }
      : {}),
    ...(includePricing
      ? {
          metals: metalsResult,
          certificates,
          gstSlabs,
        }
      : {}),
    ...(includeAttributes
      ? {
          metals: metalsResult,
          materialValues,
          stoneShapes: stoneShapesResult.data ?? [],
          ringSizes,
          ringCategories: ringCategories.categories,
          ringCategorySizes: ringCategories.sizes,
          certificates,
        }
      : {}),
    ...(includeContent
      ? {
          productContentRules,
        }
      : {}),
    ...(scope === 'all'
      ? {
          navbarItems: navbarItemsResult.error ? [] : navbarItemsResult.data ?? [],
        }
      : {}),
  })
}

type BlogSlugClient = {
  from: (table: 'blog_posts') => {
    select: (columns: string) => {
      eq: (column: string, value: string) => {
        maybeSingle: () => Promise<{ data: { id: number } | null; error: { message?: string } | null }>
      }
    }
  }
}

export function createBlogSlug(title: string) {
  const slug = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-')

  return slug || `blog-${Date.now()}`
}

export function isCleanBlogSlug(slug: string) {
  return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)
}

export async function createUniqueBlogSlug(
  adminClient: BlogSlugClient,
  title: string,
  currentPostId?: number
) {
  const baseSlug = createBlogSlug(title)
  let slug = baseSlug
  let suffix = 2

  while (true) {
    const { data, error } = await adminClient
      .from('blog_posts')
      .select('id')
      .eq('slug', slug)
      .maybeSingle()

    if (error) throw new Error(error.message ?? 'Unable to validate blog URL.')
    if (!data || data.id === currentPostId) return slug

    slug = `${baseSlug}-${suffix}`
    suffix += 1
  }
}

import 'server-only'
import { z } from 'zod'
import type { CmsRdsAccess } from './cms-command'
import { createBespokeRepository } from './db/admin-repositories/bespoke'
import { bespokeSubmissionQuerySchema } from './admin-read-validation'
import { portfolioCategoryCreateSchema,portfolioCategoryUpdateSchema,portfolioItemCreateSchema,portfolioItemUpdateSchema,portfolioExpectedTimestampSchema,portfolioIdSchema } from './bespoke-portfolio-validation'
const reply=(data:unknown,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store'}})
export async function runBespokeData(request:Request,access:CmsRdsAccess,rawId?:string) {
  const repo=createBespokeRepository(access.db)
  const resource=new URL(request.url).pathname.split('/')[3]
  if(resource==='submissions') {
    if(request.method!=='GET')return reply({error:'Method not allowed.'},405)
    if(rawId){const id=z.string().uuid().safeParse(rawId);if(!id.success)return reply({error:'Invalid submission ID.'},400);const item=await repo.submission(id.data);return item?reply({item}):reply({error:'Submission not found.'},404)}
    const params=new URL(request.url).searchParams
    const filters=bespokeSubmissionQuerySchema.safeParse({from:params.get('from')??undefined,to:params.get('to')??undefined,q:params.get('q')??undefined})
    return filters.success?reply({items:await repo.submissions(filters.data)}):reply({error:filters.error.issues[0]?.message??'Invalid submission filters.'},400)
  }
  const kind=resource==='portfolio-categories'?'category':resource==='portfolio-items'?'item':null
  if(!kind)return reply({error:'Unsupported Bespoke operation.'},400)
  if(request.method==='GET')return reply({items:await repo.list(kind)})
  const id=rawId?portfolioIdSchema.safeParse(rawId):null
  if(id&&!id.success)return reply({error:`Invalid portfolio ${kind} ID.`},400)
  if(request.method==='DELETE'){
    if(!id?.success)return reply({error:'Invalid portfolio ID.'},400)
    const expected=portfolioExpectedTimestampSchema.safeParse(new URL(request.url).searchParams.get('expected_updated_at'))
    if(!expected.success)return reply({error:`A valid ${kind} revision is required.`},400)
    if(await repo.remove(kind,id.data,expected.data))return reply({ok:true})
    const exists=await repo.exists(kind,id.data)
    return reply({error:exists?`This ${kind} was changed by another administrator. Reload it before deleting.`:`Portfolio ${kind} not found.`},exists?409:404)
  }
  if(!['POST','PATCH'].includes(request.method))return reply({error:'Method not allowed.'},405)
  const input=await request.json().catch(()=>null)
  const schema=kind==='category'?(rawId?portfolioCategoryUpdateSchema:portfolioCategoryCreateSchema):(rawId?portfolioItemUpdateSchema:portfolioItemCreateSchema)
  const parsed=schema.safeParse(input)
  if(!parsed.success)return reply({error:parsed.error.issues[0]?.message??'Invalid portfolio details.'},400)
  const expected = 'expected_updated_at' in parsed.data ? String(parsed.data.expected_updated_at) : undefined
  const targetId = id?.success ? id.data : undefined
  let item
  if (kind === 'category') {
    const clean = portfolioCategoryCreateSchema.parse(input && typeof input === 'object' ? Object.fromEntries(Object.entries(input).filter(([key]) => key !== 'expected_updated_at')) : input)
    item = await repo.save('category',clean,targetId,expected)
  } else {
    const clean = portfolioItemCreateSchema.parse(input && typeof input === 'object' ? Object.fromEntries(Object.entries(input).filter(([key]) => key !== 'expected_updated_at')) : input)
    if (!await repo.exists('category',clean.category_id)) return reply({error:'The selected portfolio category was not found.'},404)
    item = await repo.save('item',clean,targetId,expected)
  }
  if(item)return reply({item},rawId?200:201)
  const exists=await repo.exists(kind,targetId!)
  return reply({error:exists?`This ${kind} was changed by another administrator. Reload it before saving.`:`Portfolio ${kind} not found.`},exists?409:404)
}

import { z } from 'zod'

const uuid = z.string().uuid()
const status = z.enum(['active', 'hidden'])
const timestamp = z.string().datetime({ offset: true })
const displayOrder = z.number().int().min(0).max(1_000_000)

function isSafeStoredPathOrUrl(value: string) {
  if (value.startsWith('bespoke/images/')) {
    return /^bespoke\/images\/[0-9a-f-]{36}\.webp$/i.test(value) && !value.includes('..')
  }

  try {
    const url = new URL(value)
    return url.protocol === 'https:' && !url.username && !url.password
  } catch {
    return false
  }
}

const nullableMediaLocation = z.union([
  z.string().trim().max(2_048).refine(isSafeStoredPathOrUrl, 'Use a valid HTTPS URL or an uploaded Bespoke media path.'),
  z.literal('').transform(() => null),
  z.null(),
]).optional().transform((value) => value ?? null)

export const portfolioCategoryCreateSchema = z.object({
  name: z.string().trim().min(1, 'Category name is required.').max(200),
  slug: z.string().trim().min(1, 'Category slug is required.').max(200).regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'Category slug must use lowercase letters, numbers, and hyphens.'),
  image_path: nullableMediaLocation,
  display_order: displayOrder,
  status,
}).strict()

export const portfolioCategoryUpdateSchema = portfolioCategoryCreateSchema.extend({
  expected_updated_at: timestamp,
}).strict()

const portfolioItemShape = {
  title: z.string().trim().min(1, 'Portfolio title is required.').max(300),
  tag: z.string().trim().min(1, 'Portfolio tag is required.').max(150),
  category_id: uuid,
  media_type: z.enum(['image', 'video']),
  media_path: nullableMediaLocation,
  thumbnail_path: nullableMediaLocation,
  gem_style: z.string().trim().max(100).nullable().optional().transform((value) => value || null),
  gem_color: z.string().trim().max(100).nullable().optional().transform((value) => value || null),
  dark_theme: z.boolean(),
  short_description: z.string().trim().max(5_000).nullable().optional().transform((value) => value || null),
  display_order: displayOrder,
  status,
}

function validatePortfolioMedia(value: { media_type: 'image' | 'video'; media_path?: string | null }, context: z.RefinementCtx) {
  if (value.media_type === 'video' && value.media_path && !value.media_path.startsWith('https://')) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['media_path'], message: 'Video media must use a direct HTTPS URL.' })
  }
}

export const portfolioItemCreateSchema = z.object(portfolioItemShape).strict().superRefine(validatePortfolioMedia)
export const portfolioItemUpdateSchema = z.object({ ...portfolioItemShape, expected_updated_at: timestamp }).strict().superRefine(validatePortfolioMedia)
export const portfolioIdSchema = uuid
export const portfolioExpectedTimestampSchema = timestamp

export type PortfolioDatabaseError = { code?: string; message?: string }

export function portfolioMutationError(error: PortfolioDatabaseError, subject: 'category' | 'item', operation: 'save' | 'delete') {
  if (error.code === '23505') {
    return { status: 409, message: subject === 'category' ? 'A portfolio category with this slug already exists.' : 'This portfolio item conflicts with an existing record.' }
  }
  if (error.code === '23503') {
    if (subject === 'category' && operation === 'delete') return { status: 409, message: 'This category still contains portfolio items and cannot be deleted.' }
    return { status: 409, message: 'The selected portfolio category is no longer available.' }
  }
  if (['22023', '22P02', '23502', '23514'].includes(error.code ?? '')) {
    return { status: 400, message: `The portfolio ${subject} details are invalid.` }
  }
  return {
    status: 500,
    message: operation === 'delete' ? `Unable to delete the portfolio ${subject}.` : `Unable to save the portfolio ${subject}. No changes were applied.`,
  }
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { cmsMutation, readCms, type CmsAccess, type CmsReader } from './cms-command'

type Access = CmsAccess
const optionalText = (max: number) => z.string().max(max).nullish().transform((value) => value ?? '')
const slide = z.object({ id: z.string().uuid().optional(), clientId: z.string().max(200).optional(), sort_order: z.coerce.number().int().min(1).max(10_000), image_path: z.string().trim().min(1).max(2_000), mobile_image_path: optionalText(2_000), button_text: z.string().trim().min(1).max(500), button_link: z.string().trim().min(1).max(2_000) }).strict()
const item = z.object({ id: z.string().uuid().optional(), badge_text: optionalText(500), eyebrow: optionalText(500), heading_line_1: z.string().trim().min(1).max(500), heading_line_2: optionalText(500), subtitle: optionalText(10_000), primary_cta_label: optionalText(500), primary_cta_action: optionalText(2_000), secondary_cta_label: optionalText(500), secondary_cta_action: optionalText(2_000), slider_enabled: z.boolean(), status: z.enum(['active', 'hidden']) }).strict()
const envelope = z.object({ request_id: z.string().uuid(), expected_revision: z.string().regex(/^[a-f0-9]{32}$/), item: z.record(z.string(), z.unknown()), items: z.array(z.record(z.string(), z.unknown())).max(100), deleted_ids: z.array(z.string().uuid()).max(100) }).strict()
export type BespokeHeroSnapshot = { item: z.infer<typeof item> | null; items: z.infer<typeof slide>[]; revision: string }

export async function loadBespokeHeroSnapshot(client: CmsReader) {
  const { data, error } = await readCms(client, 'bespoke_hero_snapshot_v1', {})
  if (error) throw new Error(error.code === 'PGRST202' || error.code === '42883' ? 'The Bespoke Hero is awaiting its database migration.' : 'Unable to load the Bespoke Hero.')
  return data as BespokeHeroSnapshot
}

export function errorResponse(error: { code?: string; message?: string }) {
  if (error.code === 'PGRST202' || error.code === '42883') return NextResponse.json({ error: 'The Bespoke Hero is awaiting its database update. Existing content was not changed.' }, { status: 503 })
  if (error.code === '40001') return NextResponse.json({ error: 'The Bespoke Hero changed after you opened it. Reload before saving again.' }, { status: 409 })
  if (['22023', '22P02', '23502', '23503', '23505', '23514'].includes(error.code ?? '')) return NextResponse.json({ error: 'The Bespoke Hero contains invalid or conflicting data.' }, { status: 400 })
  return NextResponse.json({ error: 'Unable to save the Bespoke Hero. No partial changes were committed.' }, { status: 500 })
}

export async function saveBespokeHero(access: Access, input: unknown) {
  const parsed = envelope.safeParse(input)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.issues[0]?.message ?? 'Invalid Bespoke Hero request.' }, { status: 400 })
  const parent = item.safeParse(parsed.data.item), slides = z.array(slide).safeParse(parsed.data.items)
  if (!parent.success) return NextResponse.json({ error: parent.error.issues[0]?.message ?? 'Invalid hero details.' }, { status: 400 })
  if (!slides.success) return NextResponse.json({ error: slides.error.issues[0]?.message ?? 'Invalid hero slide.' }, { status: 400 })
  const ids = slides.data.flatMap((entry) => entry.id ? [entry.id] : [])
  if (new Set(ids).size !== ids.length || new Set(parsed.data.deleted_ids).size !== parsed.data.deleted_ids.length || ids.some((id) => parsed.data.deleted_ids.includes(id))) return NextResponse.json({ error: 'Slide IDs must be unique and cannot also be deleted.' }, { status: 400 })
  const cleanSlides = slides.data.map((slideEntry) => {
    const entry = { ...slideEntry }
    delete entry.clientId
    return entry
  })
  const { data, error } = await cmsMutation(access, 'bespoke_hero_save_v1', { p_request_id: parsed.data.request_id, p_expected_revision: parsed.data.expected_revision, p_item: parent.data, p_items: cleanSlides, p_deleted_ids: parsed.data.deleted_ids })
  if (error) return errorResponse(error)
  return NextResponse.json(data, { headers: { 'Cache-Control': 'no-store' } })
}

type Slide = { id?: string }

export function bespokeHeroSaveBody(item: Record<string, unknown>, items: Slide[], originalItems: Slide[], expectedRevision: string, requestId = crypto.randomUUID()) {
  const retained = new Set(items.flatMap((entry) => entry.id ? [entry.id] : []))
  return JSON.stringify({ request_id: requestId, expected_revision: expectedRevision, item, items, deleted_ids: originalItems.flatMap((entry) => entry.id && !retained.has(entry.id) ? [entry.id] : []) })
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { cmsMutation, readCms, type CmsAccess, type CmsReader } from './cms-command'

type Access = CmsAccess


const optionalText = (max: number) => z.string().max(max).nullish().transform((value) => value ?? '')
const uuid = z.string().uuid()
const status = z.enum(['active', 'hidden'])

const settingsSchema = z.object({
  id: uuid.optional(),
  intro_heading: optionalText(500),
  intro_subtitle: optionalText(10_000),
  footer_note: optionalText(10_000),
  status,
}).strict()

const rowSchema = z.object({
  id: uuid.optional(),
  label: z.string().trim().min(1).max(500),
  display_order: z.coerce.number().int().min(0).max(1_000_000),
  status,
}).strict()

const listsSchema = z.object({
  guarantees: z.array(rowSchema).max(500),
  pieceTypes: z.array(rowSchema).max(500),
  stoneOptions: z.array(rowSchema).max(500),
  caratOptions: z.array(rowSchema).max(500),
  metalOptions: z.array(rowSchema).max(500),
}).strict()

const deletedSchema = z.object({
  guarantees: z.array(uuid).max(500),
  pieceTypes: z.array(uuid).max(500),
  stoneOptions: z.array(uuid).max(500),
  caratOptions: z.array(uuid).max(500),
  metalOptions: z.array(uuid).max(500),
}).strict()

const envelopeSchema = z.object({
  request_id: uuid,
  expected_revision: z.string().regex(/^[a-f0-9]{32}$/),
  settings: z.record(z.string(), z.unknown()),
  lists: z.record(z.string(), z.unknown()),
  deleted_ids: z.record(z.string(), z.unknown()),
}).strict()

export type BespokeFormRow = z.infer<typeof rowSchema>
export type BespokeFormSettings = z.infer<typeof settingsSchema>
export type BespokeFormSnapshot = z.infer<typeof listsSchema> & {
  settings: BespokeFormSettings
  revision: string
}

export async function loadBespokeFormSnapshot(client: CmsReader) {
  const { data, error } = await readCms(client, 'bespoke_form_snapshot_v1', {})
  if (error) {
    throw new Error(
      error.code === 'PGRST202' || error.code === '42883'
        ? 'The Bespoke form is awaiting its database migration.'
        : 'Unable to load the Bespoke form configuration.'
    )
  }
  return data as BespokeFormSnapshot
}

export function saveErrorResponse(error: { code?: string; message?: string }) {
  if (error.code === 'PGRST202' || error.code === '42883') {
    return NextResponse.json(
      { error: 'The Bespoke form is awaiting its database update. Existing content was not changed.' },
      { status: 503 }
    )
  }
  if (error.code === '40001') return NextResponse.json({ error: 'The Bespoke form changed after you opened it. Reload before saving again.' }, { status: 409 })
  if (error.code === '42501') return NextResponse.json({ error: 'Administrator access is required.' }, { status: 403 })
  if (['22023', '22P02', '23502', '23503', '23505', '23514'].includes(error.code ?? '')) {
    return NextResponse.json({ error: 'The Bespoke form contains invalid or conflicting data.' }, { status: 400 })
  }
  return NextResponse.json(
    { error: 'Unable to save the Bespoke form. No partial changes were committed.' },
    { status: 500 }
  )
}

export async function saveBespokeForm(access: Access, input: unknown) {
  const envelope = envelopeSchema.safeParse(input)
  if (!envelope.success) {
    return NextResponse.json(
      { error: envelope.error.issues[0]?.message ?? 'Invalid Bespoke form request.' },
      { status: 400 }
    )
  }

  const settings = settingsSchema.safeParse(envelope.data.settings)
  if (!settings.success) {
    return NextResponse.json(
      { error: settings.error.issues[0]?.message ?? 'Invalid Bespoke form settings.' },
      { status: 400 }
    )
  }
  const lists = listsSchema.safeParse(envelope.data.lists)
  if (!lists.success) {
    return NextResponse.json(
      { error: lists.error.issues[0]?.message ?? 'Invalid Bespoke form option.' },
      { status: 400 }
    )
  }
  const deletedIds = deletedSchema.safeParse(envelope.data.deleted_ids)
  if (!deletedIds.success) {
    return NextResponse.json(
      { error: deletedIds.error.issues[0]?.message ?? 'Invalid deleted option ID.' },
      { status: 400 }
    )
  }

  for (const key of Object.keys(lists.data) as Array<keyof typeof lists.data>) {
    const retained = lists.data[key].flatMap((row) => row.id ? [row.id] : [])
    const deleted = deletedIds.data[key]
    if (
      new Set(retained).size !== retained.length
      || new Set(deleted).size !== deleted.length
      || retained.some((id) => deleted.includes(id))
    ) {
      return NextResponse.json(
        { error: 'Option IDs must be unique and cannot also be deleted.' },
        { status: 400 }
      )
    }
  }

  const { data, error } = await cmsMutation(access, 'bespoke_form_save_v1', {
    p_request_id: envelope.data.request_id,
    p_expected_revision: envelope.data.expected_revision,
    p_settings: settings.data,
    p_lists: lists.data,
    p_deleted_ids: deletedIds.data,
  })
  if (error) return saveErrorResponse(error)

  return NextResponse.json(data, { headers: { 'Cache-Control': 'no-store' } })
}

import type { BespokeFormSnapshot } from './bespoke-form-save'

const listKeys = ['guarantees', 'pieceTypes', 'stoneOptions', 'caratOptions', 'metalOptions'] as const

export function bespokeFormSaveBody(current: BespokeFormSnapshot, original: BespokeFormSnapshot, requestId = crypto.randomUUID()) {
  const deletedIds = Object.fromEntries(listKeys.map((key) => {
    const retained = new Set(current[key].flatMap((row) => row.id ? [row.id] : []))
    return [key, original[key].flatMap((row) => row.id && !retained.has(row.id) ? [row.id] : [])]
  }))

  return JSON.stringify({
    request_id: requestId,
    expected_revision: original.revision,
    settings: current.settings ?? { intro_heading: '', intro_subtitle: '', footer_note: '', status: 'active' },
    lists: Object.fromEntries(listKeys.map((key) => [key, current[key]])),
    deleted_ids: deletedIds,
  })
}

