import 'server-only'
import type { AdminActor, AdminIdentityPolicy, AdminIdentityRecord, VerifiedAdminSession } from './admin-identity-core'
import { authorizeMappedAdmin } from './admin-identity-core'
import type { AuthConfig } from './config'
import type { KeycloakAdapter, TokenSet } from './keycloak'
import { digest, randomSecret } from './keycloak'
import { assertMutation, cookieValue, SESSION_COOKIE } from './request-security'

export type Flow = { state: string; nonce: string; verifier: string; returnPath: string; expiresAt: number }
export type Session = {
  claims: VerifiedAdminSession; tokens: TokenSet; csrf: string
  createdAt: number; lastSeen: number; checkedAt: number; expiresAt: number; refreshing: boolean
}
export type Stored<T> = { version: string; data: T }
/** All mutations MUST be atomic across instances. CAS must never recreate a deleted key.
 * Implementations encrypt token/verifier data and bound TTL. No live memory adapter is allowed.
 */
export interface SessionStore {
  create<T>(key: string, data: T, ttlSeconds: number): Promise<boolean>
  get<T>(key: string): Promise<Stored<T> | null>
  consume<T>(key: string, version: string): Promise<T | null>
  replace<T>(key: string, version: string, data: T, ttlSeconds: number): Promise<boolean>
  delete(key: string): Promise<void>
}
export type IdentityLookup = (issuer: string, subject: string) => Promise<readonly AdminIdentityRecord[]>
export type AuthDependencies = { config: AuthConfig; store: SessionStore; oidc: KeycloakAdapter; lookup: IdentityLookup; now?: () => number }

export function createSessions(deps: AuthDependencies) {
  const { config, store, oidc, lookup } = deps
  const now = () => Math.floor((deps.now ?? Date.now)() / 1000)
  const policy: AdminIdentityPolicy = config
  const sessionKey = (cookie: string) => `session:${digest(cookie)}`
  const flowKey = (cookie: string) => `flow:${digest(cookie)}`
  const ttl = (s: Session) => Math.max(0, Math.min(s.expiresAt - now(), config.sessionIdleSeconds))
  async function mapped(claims: VerifiedAdminSession): Promise<AdminActor> {
    const actor = authorizeMappedAdmin(claims, await lookup(claims.issuer, claims.subject), policy, now())
    if (!actor) throw new Error('Admin identity denied')
    return actor
  }
  return {
    flowKey, sessionKey, mapped,
    async begin(returnPath: string) {
      const cookie = randomSecret()
      const flow: Flow = { state: randomSecret(), nonce: randomSecret(), verifier: randomSecret(), returnPath, expiresAt: now() + 300 }
      if (!await store.create(flowKey(cookie), flow, 300)) throw new Error('Flow storage failed')
      return { cookie, flow }
    },
    async establish(tokens: TokenSet, nonce: string) {
      const claims = await oidc.validate(tokens, nonce)
      await mapped(claims)
      const seconds = now()
      if (claims.expiresAt <= seconds) throw new Error('Expired session')
      const session: Session = { claims, tokens, csrf: randomSecret(), createdAt: seconds, lastSeen: seconds,
        checkedAt: seconds, expiresAt: seconds + config.sessionMaxSeconds, refreshing: false }
      const cookie = randomSecret()
      if (!await store.create(sessionKey(cookie), session, ttl(session))) throw new Error('Session storage failed')
      return { cookie, session }
    },
    async authorize(request: Request, mutation = false) {
      const cookie = cookieValue(request, SESSION_COOKIE)
      if (!cookie) throw new Error('Session missing')
      const key = sessionKey(cookie)
      const stored = await store.get<Session>(key)
      if (!stored) throw new Error('Session missing')
      let session = stored.data
      if (mutation) assertMutation(request, config.origin, session.csrf)
      if (session.refreshing) throw new Error('Refresh in progress')
      if (session.expiresAt <= now() || session.lastSeen + config.sessionIdleSeconds <= now()) {
        await store.consume(key, stored.version)
        throw new Error('Session expired')
      }
      // Refresh is claimed through distributed CAS before using a rotating token, no retries.
      if (session.claims.expiresAt <= now() + 15 || session.checkedAt + config.revalidateSeconds <= now()) {
        const claimed = { ...session, refreshing: true }
        if (!await store.replace(key, stored.version, claimed, ttl(session))) throw new Error('Concurrent session update')
        const current = await store.get<Session>(key)
        if (!current || !current.data.refreshing) throw new Error('Session revoked')
        try {
          const tokens = await oidc.refresh(session.tokens.refreshToken)
          // Refresh responses must supply a freshly signed ID token and rotated refresh token.
          if (tokens.refreshToken === session.tokens.refreshToken) throw new Error('Refresh rotation missing')
          const claims = await oidc.validate(tokens, undefined, session.claims.subject)
          await mapped(claims)
          session = { ...session, tokens, claims, checkedAt: now(), lastSeen: now(), refreshing: false }
          if (ttl(session) <= 0 || !await store.replace(key, current.version, session, ttl(session))) throw new Error('Session revoked')
        } catch {
          await store.consume(key, current.version)
          throw new Error('Refresh failed')
        }
      }
      const boundedClaims = { ...session.claims, expiresAt: Math.min(session.claims.expiresAt, session.expiresAt) }
      const actor = await mapped(boundedClaims)
      // Sliding idle TTL and final CAS also detect logout during lookup; never restore a deleted session.
      const latest = await store.get<Session>(key)
      if (!latest || latest.data.refreshing || latest.data.csrf !== session.csrf
        || latest.data.tokens.accessToken !== session.tokens.accessToken) throw new Error('Session revoked')
      if (session.claims.expiresAt <= now() || session.lastSeen + config.sessionIdleSeconds <= now()
        || ttl(session) <= 0 || !await store.replace(key, latest.version, { ...latest.data, lastSeen: now() }, ttl(session))) throw new Error('Concurrent session update')
      return { actor, csrf: session.csrf }
    },
  }
}

import 'server-only'
import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto'
import { AuthUnavailable } from './config'
import { randomSecret } from './keycloak'
import type { SessionStore, Stored } from './session'

type Envelope = { version: string; sealed: string }
/** Adapter is opt-in only after server configuration, Redis EVAL and namespace are verified.
 * Uses existing REST service; never provisions or starts Redis. Values are AES-256-GCM sealed.
 */
export function createSessionStore(env: NodeJS.ProcessEnv = process.env, fetcher: typeof fetch = fetch): SessionStore {
  const url = env.UPSTASH_REDIS_REST_URL
  const token = env.UPSTASH_REDIS_REST_TOKEN
  const encodedKey = env.ADMIN_SESSION_ENCRYPTION_KEY
  const namespace = env.ADMIN_SESSION_NAMESPACE
  if (env.ADMIN_SESSION_STORAGE_VERIFIED !== 'true' || !url || !token || !encodedKey
    || !namespace || !/^hod-admin:[a-z0-9-]{1,40}$/.test(namespace)) throw new AuthUnavailable()
  let target: URL
  try { target = new URL(url) } catch { throw new AuthUnavailable() }
  if (target.protocol !== 'https:' || target.username || target.password || target.search || target.hash
    || target.pathname !== '/' || !target.hostname.endsWith('.upstash.io')) throw new AuthUnavailable()
  const key = Buffer.from(encodedKey, 'base64')
  if (key.length !== 32 || key.toString('base64') !== encodedKey) throw new AuthUnavailable()
  const redisKey = (name: string) => {
    if (!/^(session|flow):[A-Za-z0-9_-]{43}$/.test(name)) throw new Error('Invalid storage key')
    return `${namespace}:${name}`
  }
  function seal<T>(name: string, data: T): Envelope {
    const version = randomSecret()
    const iv = randomBytes(12)
    const cipher = createCipheriv('aes-256-gcm', key, iv)
    cipher.setAAD(Buffer.from(`${redisKey(name)}:${version}`))
    const encrypted = Buffer.concat([cipher.update(JSON.stringify(data), 'utf8'), cipher.final()])
    return { version, sealed: Buffer.concat([iv, cipher.getAuthTag(), encrypted]).toString('base64') }
  }
  function open<T>(name: string, raw: string): Stored<T> {
    if (raw.length > 180000) throw new Error('Invalid session data')
    const envelope: Envelope = JSON.parse(raw)
    if (!/^[A-Za-z0-9_-]{43}$/.test(envelope.version) || typeof envelope.sealed !== 'string') throw new Error('Invalid session data')
    const bytes = Buffer.from(envelope.sealed, 'base64')
    const cipher = createDecipheriv('aes-256-gcm', key, bytes.subarray(0, 12))
    cipher.setAAD(Buffer.from(`${redisKey(name)}:${envelope.version}`))
    cipher.setAuthTag(bytes.subarray(12, 28))
    return { version: envelope.version, data: JSON.parse(Buffer.concat([cipher.update(bytes.subarray(28)), cipher.final()]).toString('utf8')) }
  }
  async function command(args: (string | number)[]) {
    const response = await fetcher(target, { method: 'POST', redirect: 'error', cache: 'no-store', signal: AbortSignal.timeout(5000),
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: JSON.stringify(args) })
    if (!response.ok) throw new AuthUnavailable()
    if (!response.body) throw new AuthUnavailable()
    const reader = response.body.getReader()
    const chunks: Uint8Array[] = []
    let size = 0
    try {
      for (;;) {
        const { done, value } = await reader.read()
        if (done) break
        size += value.length
        if (size > 200000) throw new AuthUnavailable()
        chunks.push(value)
      }
    } finally { await reader.cancel() }
    const body = JSON.parse(Buffer.concat(chunks).toString('utf8'))
    if (body.error || !Object.hasOwn(body, 'result')) throw new AuthUnavailable()
    return body.result
  }
  function ttl(seconds: number) {
    if (!Number.isSafeInteger(seconds) || seconds < 1 || seconds > 86400) throw new Error('Invalid storage TTL')
    return seconds
  }
  const compare = "local v=redis.call('GET',KEYS[1]); if not v then return false end; local e=cjson.decode(v); if e.version~=ARGV[1] then return false end; "
  return {
    async create(name, data, seconds) { return await command(['SET', redisKey(name), JSON.stringify(seal(name, data)), 'EX', ttl(seconds), 'NX']) === 'OK' },
    async get<T>(name: string) {
      const raw = await command(['GET', redisKey(name)])
      return raw === null ? null : open<T>(name, raw)
    },
    async consume<T>(name: string, version: string) {
      const raw = await command(['EVAL', `${compare}redis.call('DEL',KEYS[1]); return v`, 1, redisKey(name), version])
      return raw === null || raw === false ? null : open<T>(name, raw).data
    },
    async replace(name, version, data, seconds) {
      return await command(['EVAL', `${compare}redis.call('SET',KEYS[1],ARGV[2],'EX',ARGV[3]); return 1`, 1,
        redisKey(name), version, JSON.stringify(seal(name, data)), ttl(seconds)]) === 1
    },
    async delete(name) { await command(['DEL', redisKey(name)]) },
  }
}

import 'server-only'
import { readAuthConfig } from './config'
import { createKeycloak } from './keycloak'
import { createSessionStore } from './session-store'
import { createAuthHandlers } from './handlers'
import { lookupAdminIdentity } from '../db/admin-repositories/identity'
import { NO_STORE } from './request-security'

let handlers: ReturnType<typeof createAuthHandlers> | undefined
export async function runAuthRoute(action: keyof ReturnType<typeof createAuthHandlers>, request: Request): Promise<Response> {
  try {
    if (!handlers) {
      const config = readAuthConfig()
      handlers = createAuthHandlers({ config, oidc: createKeycloak(config), store: createSessionStore(), lookup: lookupAdminIdentity })
    }
    return await handlers[action](request)
  } catch { return Response.json({ error: 'Authentication unavailable' }, { status: 503, headers: NO_STORE }) }
}

import 'server-only'
import { timingSafeEqual } from 'node:crypto'

export const SESSION_COOKIE = '__Host-hod_admin_session'
export const FLOW_COOKIE = '__Host-hod_admin_flow'
export const NO_STORE = { 'Cache-Control': 'no-store', Pragma: 'no-cache', 'Referrer-Policy': 'no-referrer' }

export function equalSecret(a: string, b: string): boolean {
  const x = Buffer.from(a), y = Buffer.from(b)
  return x.length > 0 && x.length === y.length && timingSafeEqual(x, y)
}

export function safeReturnPath(value: string | null): string {
  const path = value ?? '/dashboard'
  // Reject encoded paths, dot segments, backslashes and control characters rather than normalizing them.
  if (path.length > 1024 || !/^\/dashboard(?:\/[a-zA-Z0-9_-]+)*\/?$/.test(path)) throw new Error('Invalid redirect')
  return path
}

export function cookieValue(request: Request, name: string): string | null {
  const values = (request.headers.get('cookie') ?? '').split(';').map(v => v.trim())
    .filter(v => v.startsWith(`${name}=`)).map(v => v.slice(name.length + 1))
  return values.length === 1 && /^[A-Za-z0-9_-]{43}$/.test(values[0]) ? values[0] : null
}

export function secureCookie(name: string, value: string, seconds: number): string {
  if (![SESSION_COOKIE, FLOW_COOKIE].includes(name) || (value && !/^[A-Za-z0-9_-]{43}$/.test(value))) throw new Error('Invalid cookie')
  return `${name}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${Math.max(0, Math.floor(seconds))}`
}

export function assertSameOrigin(request: Request, origin: string): void {
  if (new URL(request.url).origin !== origin || request.headers.get('origin') !== origin
    || (request.headers.get('sec-fetch-site') && request.headers.get('sec-fetch-site') !== 'same-origin')) throw new Error('Invalid origin')
}

export function assertMutation(request: Request, origin: string, csrf: string): void {
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(request.method)) throw new Error('Invalid method')
  assertSameOrigin(request, origin)
  if (!equalSecret(request.headers.get('x-admin-csrf') ?? '', csrf)) throw new Error('Invalid CSRF')
}

import 'server-only'
import { createHash, randomBytes } from 'node:crypto'
import { createRemoteJWKSet, customFetch, jwtVerify } from 'jose'
import type { JWTPayload } from 'jose'
import type { AuthConfig } from './config'
import type { VerifiedAdminSession } from './admin-identity-core'
import { equalSecret } from './request-security'

export const randomSecret = () => randomBytes(32).toString('base64url')
export const digest = (value: string) => createHash('sha256').update(value).digest('base64url')
export type FetchAdapter = typeof fetch
export type TokenSet = { accessToken: string; idToken: string; refreshToken: string }

/** No discovered or JWT-provided URLs: fixed issuer endpoints, bounded response sizes, no redirects. */
export function createKeycloak(config: AuthConfig, fetcher: FetchAdapter = fetch, now = () => Date.now()) {
  const endpoint = (name: string) => `${config.issuer}/protocol/openid-connect/${name}`
  function clientAuthentication(parameters: Record<string, string>) {
    const body = new URLSearchParams(parameters)
    const headers: Record<string, string> = { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' }
    if (config.tokenAuthMethod === 'client_secret_post') {
      body.set('client_id', config.clientId)
      body.set('client_secret', config.clientSecret)
    } else {
      const encode = (value: string) => new URLSearchParams({ v: value }).toString().slice(2)
      headers.Authorization = `Basic ${Buffer.from(`${encode(config.clientId)}:${encode(config.clientSecret)}`).toString('base64')}`
    }
    return { body, headers }
  }
  async function boundedFetch(input: string | URL | Request, init?: RequestInit): Promise<Response> {
    const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url
    if (![endpoint('certs'), endpoint('token'), endpoint('logout')].includes(url)) throw new Error('Invalid OIDC endpoint')
    const response = await fetcher(input, { ...init, redirect: 'error', cache: 'no-store', signal: AbortSignal.timeout(5000) })
    if (!response.ok || (response.url && response.url !== url)) throw new Error('OIDC request failed')
    if (!response.headers.get('content-type')?.includes('application/json') && url !== endpoint('logout')) throw new Error('Invalid OIDC response')
    if (url === endpoint('logout')) return response
    if (!response.body) throw new Error('Empty OIDC response')
    const reader = response.body.getReader()
    const chunks: Uint8Array[] = []
    let size = 0
    try {
      for (;;) {
        const { done, value } = await reader.read()
        if (done) break
        size += value.length
        if (size > 131072) throw new Error('OIDC response too large')
        chunks.push(value)
      }
    } finally { await reader.cancel() }
    return new Response(Buffer.concat(chunks), { status: response.status, headers: response.headers })
  }
  const keys = createRemoteJWKSet(new URL(endpoint('certs')), {
    cooldownDuration: 30000, cacheMaxAge: 300000, timeoutDuration: 5000,
    [customFetch]: boundedFetch,
  })
  async function verify(token: string, kind: 'ID' | 'Bearer'): Promise<JWTPayload> {
    if (token.length > 32768) throw new Error('Invalid token')
    const { payload, protectedHeader } = await jwtVerify(token, keys, {
      issuer: config.issuer, audience: config.clientId, algorithms: ['RS256'], clockTolerance: 0,
      requiredClaims: ['iss', 'sub', 'aud', 'exp', 'iat'], currentDate: new Date(now()),
    })
    const seconds = Math.floor(now() / 1000)
    if (!protectedHeader.kid || payload.typ !== kind || typeof payload.sub !== 'string' || !payload.sub
      || payload.sub.length > 512 || payload.azp !== config.clientId
      || typeof payload.iat !== 'number' || payload.iat > seconds
      || typeof payload.exp !== 'number' || payload.exp <= seconds || payload.exp <= payload.iat) throw new Error('Invalid token claims')
    return payload
  }
  async function validate(tokens: TokenSet, nonce?: string, expectedSubject?: string) {
    const [id, access] = await Promise.all([verify(tokens.idToken, 'ID'), verify(tokens.accessToken, 'Bearer')])
    if (id.sub !== access.sub || (expectedSubject && access.sub !== expectedSubject)
      || (nonce !== undefined && (typeof id.nonce !== 'string' || !equalSecret(id.nonce, nonce)))) throw new Error('Invalid OIDC binding')
    if (id.at_hash !== undefined) {
      const hash = createHash('sha256').update(tokens.accessToken).digest().subarray(0, 16).toString('base64url')
      if (typeof id.at_hash !== 'string' || !equalSecret(id.at_hash, hash)) throw new Error('Invalid access token binding')
    }
    const container = config.roleLocation === 'realm' ? access.realm_access
      : (access.resource_access as Record<string, unknown> | undefined)?.[config.clientId]
    const roles = (container as { roles?: unknown } | undefined)?.roles
    if (!Array.isArray(roles) || !roles.every(r => typeof r === 'string') || !roles.includes(config.requiredClientRole)) throw new Error('Admin role missing')
    const session: VerifiedAdminSession = {
      issuer: config.issuer, subject: access.sub!, clientId: config.clientId,
      audiences: typeof access.aud === 'string' ? [access.aud] : access.aud!, clientRoles: roles,
      expiresAt: Math.min(id.exp!, access.exp!),
    }
    return session
  }
  async function tokenRequest(parameters: Record<string, string>): Promise<TokenSet> {
    const response = await boundedFetch(endpoint('token'), { method: 'POST', ...clientAuthentication(parameters) })
    const value = await response.json()
    if (value.token_type?.toLowerCase() !== 'bearer' || typeof value.access_token !== 'string'
      || typeof value.id_token !== 'string' || typeof value.refresh_token !== 'string'
      || !value.refresh_token || value.refresh_token.length > 32768) throw new Error('Invalid token response')
    return { accessToken: value.access_token, idToken: value.id_token, refreshToken: value.refresh_token }
  }
  return {
    validate,
    authorizationUrl(state: string, nonce: string, verifier: string) {
      const url = new URL(endpoint('auth'))
      url.search = new URLSearchParams({ client_id: config.clientId, redirect_uri: `${config.origin}/api/auth/callback`,
        response_type: 'code', scope: 'openid', state, nonce, code_challenge: digest(verifier), code_challenge_method: 'S256' }).toString()
      return url.href
    },
    exchange: (code: string, verifier: string) => tokenRequest({ grant_type: 'authorization_code', code,
      code_verifier: verifier, redirect_uri: `${config.origin}/api/auth/callback` }),
    refresh: (refreshToken: string) => tokenRequest({ grant_type: 'refresh_token', refresh_token: refreshToken }),
    async logout(refreshToken: string) {
      await boundedFetch(endpoint('logout'), { method: 'POST', ...clientAuthentication({ refresh_token: refreshToken }) })
    },
  }
}
export type KeycloakAdapter = ReturnType<typeof createKeycloak>

import 'server-only'

export type AdminAuthProvider = 'supabase' | 'keycloak'

/** Global UI/gate selection does not activate any data or media provider. */
export function readAdminAuthProvider(env: Record<string, string | undefined> = process.env): AdminAuthProvider {
  const value = env.ADMIN_AUTH_PROVIDER
  if (value === undefined || value === '' || value === 'supabase') return 'supabase'
  if (value !== 'keycloak') throw new Error('Admin integration unavailable')
  for (const name of ['ADMIN_PRODUCT_DATA_PROVIDER', 'ADMIN_CATALOG_DATA_PROVIDER', 'ADMIN_CMS_DATA_PROVIDER', 'ADMIN_OPERATIONS_DATA_PROVIDER']) {
    if (env[name] !== 'rds') throw new Error('Admin integration requires migrated data providers')
  }
  for (const name of ['ADMIN_IMAGE_PROVIDER', 'ADMIN_VIDEO_PROVIDER']) {
    if (env[name] !== 'aws') throw new Error('Admin integration requires migrated media providers')
  }
  return 'keycloak'
}

export function assertLegacyAdminAuth() {
  if (readAdminAuthProvider() !== 'supabase') throw new Error('Legacy admin authentication disabled')
}

import 'server-only'
import { authorizeMappedAdmin, hasValidAdminSession } from './admin-identity-core'
import type { AdminActor, AdminIdentityPolicy, AdminIdentityRecord, VerifiedAdminSession } from './admin-identity-core'

export type IdentityLookup = (issuer: string, subject: string) => Promise<readonly AdminIdentityRecord[]>

/** RDS adapter calls the scoped identity projection with issuer/subject parameters.
 * No email enrollment, customer fallback, or request-supplied actor is permitted.
 * Database errors propagate: callers must return a generic failure, never authorize.
 */
export async function resolveAdminActor(
  session: VerifiedAdminSession | null,
  policy: AdminIdentityPolicy,
  lookup: IdentityLookup,
  nowSeconds = Math.floor(Date.now() / 1000),
): Promise<AdminActor | null> {
  if (!hasValidAdminSession(session, policy, nowSeconds)) return null
  const identities = await lookup(session.issuer, session.subject)
  // Recheck expiry after database access, including delayed queries.
  return authorizeMappedAdmin(session, identities, policy, Math.max(nowSeconds, Math.floor(Date.now() / 1000)))
}

import 'server-only'
import type { AuthDependencies, Flow, Session } from './session'
import { createSessions } from './session'
import { assertMutation, assertSameOrigin, cookieValue, equalSecret, FLOW_COOKIE, NO_STORE, safeReturnPath, secureCookie, SESSION_COOKIE } from './request-security'

/** Web-standard handlers allow complete protocol tests without a listener. */
export function createAuthHandlers(deps: AuthDependencies) {
  const { config, store, oidc } = deps
  const sessions = createSessions(deps)
  const now = () => Math.floor((deps.now ?? Date.now)() / 1000)
  const response = (value: unknown, status = 200) => Response.json(value, { status, headers: NO_STORE })
  const redirect = (location: string) => new Response(null, { status: 303, headers: { ...NO_STORE, Location: location } })
  return {
    async login(request: Request) {
      try {
        if (request.method !== 'POST') return response({ error: 'Method not allowed' }, 405)
        assertSameOrigin(request, config.origin)
        const path = safeReturnPath(new URL(request.url).searchParams.get('returnTo'))
        const { cookie, flow } = await sessions.begin(path)
        const result = redirect(oidc.authorizationUrl(flow.state, flow.nonce, flow.verifier))
        result.headers.append('Set-Cookie', secureCookie(FLOW_COOKIE, cookie, 300))
        return result
      } catch { return response({ error: 'Authentication unavailable' }, 503) }
    },
    async callback(request: Request) {
      const clear = (result: Response) => { result.headers.append('Set-Cookie', secureCookie(FLOW_COOKIE, '', 0)); return result }
      try {
        const url = new URL(request.url)
        if (request.method !== 'GET' || url.origin !== config.origin) throw new Error('Invalid callback')
        const cookie = cookieValue(request, FLOW_COOKIE)
        if (!cookie) throw new Error('Flow missing')
        const key = sessions.flowKey(cookie)
        const stored = await store.get<Flow>(key)
        const state = url.searchParams.getAll('state'), code = url.searchParams.getAll('code')
        if (!stored || stored.data.expiresAt <= now() || state.length !== 1 || !equalSecret(state[0], stored.data.state)) throw new Error('Invalid state')
        const flow = await store.consume<Flow>(key, stored.version)
        if (!flow || url.searchParams.has('error') || code.length !== 1 || !code[0] || code[0].length > 4096
          || (url.searchParams.has('iss') && (url.searchParams.getAll('iss').length !== 1 || url.searchParams.get('iss') !== config.issuer))) throw new Error('Invalid code')
        const tokens = await oidc.exchange(code[0], flow.verifier)
        const { cookie: sessionCookie } = await sessions.establish(tokens, flow.nonce)
        // Delete any previous browser session only after the new login has succeeded.
        const previous = cookieValue(request, SESSION_COOKIE)
        if (previous) await store.delete(sessions.sessionKey(previous))
        const result = redirect(`${config.origin}${safeReturnPath(flow.returnPath)}`)
        result.headers.append('Set-Cookie', secureCookie(SESSION_COOKIE, sessionCookie, config.sessionMaxSeconds))
        return clear(result)
      } catch { return clear(response({ error: 'Login failed' }, 401)) }
    },
    async session(request: Request) {
      try {
        if (request.method !== 'GET' || new URL(request.url).origin !== config.origin) return response({ error: 'Unauthorized' }, 401)
        const { actor, csrf } = await sessions.authorize(request)
        return response({ authenticated: true, actor: { profileId: actor.profileId }, csrfToken: csrf })
      } catch { return response({ error: 'Unauthorized' }, 401) }
    },
    async logout(request: Request) {
      try {
        const cookie = cookieValue(request, SESSION_COOKIE)
        if (!cookie) throw new Error('Session missing')
        const key = sessions.sessionKey(cookie)
        const stored = await store.get<Session>(key)
        if (!stored) throw new Error('Session missing')
        assertMutation(request, config.origin, stored.data.csrf)
        // Atomic deletion first: upstream failure never retains local authorization.
        const removed = await store.consume<Session>(key, stored.version)
        if (!removed) throw new Error('Concurrent logout')
        let upstreamLogout = true
        try { await oidc.logout(removed.tokens.refreshToken) } catch { upstreamLogout = false }
        const result = response({ authenticated: false, upstreamLogout }, upstreamLogout ? 200 : 502)
        result.headers.append('Set-Cookie', secureCookie(SESSION_COOKIE, '', 0))
        result.headers.append('Set-Cookie', secureCookie(FLOW_COOKIE, '', 0))
        return result
      } catch { return response({ error: 'Logout denied' }, 403) }
    },
  }
}

import 'server-only'

export type AuthConfig = Readonly<{
  issuer: string; clientId: string; clientSecret: string; origin: string
  tokenAuthMethod: 'client_secret_post' | 'client_secret_basic'
  roleLocation: 'realm' | 'client'; requiredClientRole: string
  sessionMaxSeconds: number; sessionIdleSeconds: number; revalidateSeconds: number
}>

export class AuthUnavailable extends Error {
  constructor() { super('Admin authentication unavailable') }
}

/** Explicit policy values are required; realm capabilities are not client policy evidence. */
export function readAuthConfig(env: NodeJS.ProcessEnv = process.env): AuthConfig {
  const issuer = env.ADMIN_OIDC_ISSUER
  const clientId = env.ADMIN_OIDC_CLIENT_ID
  const clientSecret = env.ADMIN_OIDC_CLIENT_SECRET
  const origin = env.ADMIN_AUTH_ORIGIN
  const roleLocation = env.ADMIN_OIDC_ROLE_LOCATION
  const tokenAuthMethod = env.ADMIN_OIDC_TOKEN_AUTH_METHOD
  if (env.ADMIN_AUTH_POLICY_VERIFIED !== 'true'
    || issuer !== 'https://auth-uat.houseofdiams.com/realms/houseofdiams'
    || clientId !== 'hod-admin' || !clientSecret || !origin
    || (roleLocation !== 'realm' && roleLocation !== 'client')
    || (tokenAuthMethod !== 'client_secret_post' && tokenAuthMethod !== 'client_secret_basic')
    || env.ADMIN_OIDC_REQUIRED_ROLE !== 'hod-admin') throw new AuthUnavailable()
  let url: URL
  try { url = new URL(origin) } catch { throw new AuthUnavailable() }
  if (url.protocol !== 'https:' || url.origin !== origin || url.username || url.password) throw new AuthUnavailable()
  function seconds(name: string, maximum: number) {
    const raw = env[name]
    const value = Number(raw)
    if (!raw || !/^\d+$/.test(raw) || !Number.isSafeInteger(value) || value < 1 || value > maximum) throw new AuthUnavailable()
    return value
  }
  const sessionMaxSeconds = seconds('ADMIN_SESSION_MAX_SECONDS', 86400)
  const sessionIdleSeconds = seconds('ADMIN_SESSION_IDLE_SECONDS', sessionMaxSeconds)
  const revalidateSeconds = seconds('ADMIN_SESSION_REVALIDATE_SECONDS', Math.min(300, sessionIdleSeconds))
  return Object.freeze({ issuer, clientId, clientSecret, origin, roleLocation, tokenAuthMethod,
    requiredClientRole: 'hod-admin', sessionMaxSeconds, sessionIdleSeconds, revalidateSeconds })
}

import 'server-only'
import { readAdminAuthProvider } from './integration'
import type { authorizeProductPage } from '../product-server-request'

export type AdminServerSession = { userId: string; email: string | null; role: string }

/** No fabricated Supabase user: only the mapped internal profile UUID crosses this boundary. */
export async function resolveAdminServerSession(deps: {
  provider: typeof readAdminAuthProvider
  authorize: typeof authorizeProductPage
  legacy: () => Promise<AdminServerSession | null>
}): Promise<AdminServerSession | null> {
  if (deps.provider() === 'supabase') return deps.legacy()
  const { actor } = await deps.authorize()
  return { userId: actor.profileId, email: null, role: 'admin' }
}

/** Server authorization policy; accepts only claims from a validated OIDC session.
 * This does not verify JWTs. Never pass decoded tokens or request JSON here.
 */
export type VerifiedAdminSession = {
  issuer: string
  subject: string
  audiences: readonly string[]
  clientId: string
  clientRoles: readonly string[]
  expiresAt: number // Unix seconds; bounded by both token and server session expiry.
}

export type AdminIdentityPolicy = {
  issuer: string
  clientId: string
  requiredClientRole: string
}

export type AdminIdentityRecord = {
  issuer: string
  subject: string
  profileId: string
  enabled: boolean // Mapping state: profiles currently has no enabled column.
  revokedAt: string | null
  profileRole: string
}

export type AdminActor = Readonly<{ profileId: string; issuer: string; subject: string }>

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export function hasValidAdminSession(
  session: VerifiedAdminSession | null,
  policy: AdminIdentityPolicy,
  nowSeconds: number,
): session is VerifiedAdminSession {
  return Boolean(session && policy.issuer && policy.clientId && policy.requiredClientRole
    && Number.isFinite(nowSeconds) && Number.isFinite(session.expiresAt)
    && session.expiresAt > nowSeconds && session.subject.length > 0
    && session.issuer === policy.issuer && session.clientId === policy.clientId
    && session.audiences.includes(policy.clientId)
    && session.clientRoles.includes(policy.requiredClientRole))
}

export function authorizeMappedAdmin(
  session: VerifiedAdminSession | null,
  identities: readonly AdminIdentityRecord[],
  policy: AdminIdentityPolicy,
  nowSeconds: number,
): AdminActor | null {
  if (!hasValidAdminSession(session, policy, nowSeconds) || identities.length !== 1) return null
  const mapping = identities[0]
  if (mapping.issuer !== session.issuer || mapping.subject !== session.subject
    || mapping.enabled !== true || mapping.revokedAt !== null
    || mapping.profileRole !== 'admin' || !uuid.test(mapping.profileId)) return null
  return Object.freeze({ profileId: mapping.profileId, issuer: mapping.issuer, subject: mapping.subject })
}

import 'server-only'
import { NO_STORE } from './request-security'
import type { authorizeProductRequest } from '../product-session-runtime'
import { ProductSessionError } from '../product-session-error'

/** Account console owns password collection/reauthentication. No privileged admin API. */
export function accountConsoleUrl(env: Record<string, string | undefined>): string | null {
  if (env.ADMIN_KEYCLOAK_ACCOUNT_VERIFIED !== 'true') return null
  const issuer = env.ADMIN_OIDC_ISSUER
  if (issuer !== 'https://auth-uat.houseofdiams.com/realms/houseofdiams') throw new Error('Account configuration unavailable')
  // Explicit operator-reviewed URL; do not derive an unverified capability from discovery.
  const value = env.ADMIN_KEYCLOAK_ACCOUNT_URL
  if (value !== `${issuer}/account/`) throw new Error('Account configuration unavailable')
  return value
}

export function createAccountHandler(deps: {
  provider: () => 'supabase' | 'keycloak'
  authorize: typeof authorizeProductRequest
  env: () => Record<string, string | undefined>
}) {
  return async (request: Request) => {
    try {
      if (deps.provider() !== 'keycloak') return Response.json({ error: 'Keycloak account management is not selected.' }, { status: 409, headers: NO_STORE })
      if (request.method !== 'POST') return Response.json({ error: 'Method not allowed' }, { status: 405, headers: NO_STORE })
      await deps.authorize(request, true)
      const url = accountConsoleUrl(deps.env())
      if (!url) return Response.json({ error: 'Keycloak account management awaits verified account-console policy.' }, { status: 503, headers: NO_STORE })
      return Response.json({ action: 'account-console', url }, { headers: NO_STORE })
    } catch (error) {
      const status = error instanceof ProductSessionError ? error.status : 503
      return Response.json({ error: 'Account management unavailable.' }, { status, headers: NO_STORE })
    }
  }
}

import { readOperationsProvider } from './operations-provider'
import { operationsPage } from './operations-page-data'
import { createCustomersRepository } from './db/admin-repositories/customers'
import { createSupabaseAdminClient } from '@/lib/admin-supabase'

export type AdminCustomerUser = {
  id: string
  email: string | null
  name: string
  createdAt: string
  confirmed: boolean
}

export async function getAdminCustomerUsers(): Promise<AdminCustomerUser[]> {
  if(readOperationsProvider(process.env)==='rds') throw new Error('Historical Supabase registrations are unavailable in RDS mode. Use the customer identity read model.')
  const supabase = createSupabaseAdminClient()
  const users: AdminCustomerUser[] = []
  let page = 1
  const perPage = 1000

  while (true) {
    const { data, error } = await supabase.auth.admin.listUsers({
      page,
      perPage,
    })

    if (error) {
      throw new Error(error.message)
    }

    const batch = (data.users ?? []).map((user) => {
      const metadata = user.user_metadata ?? {}
      const rawUsername = typeof metadata.username === 'string' ? metadata.username.trim() : ''
      const rawFullName = typeof metadata.full_name === 'string' ? metadata.full_name.trim() : ''
      const fallbackName = user.email?.split('@')[0] ?? 'Unnamed user'

      return {
        id: user.id,
        email: user.email ?? null,
        name: rawUsername || rawFullName || fallbackName,
        createdAt: user.created_at ?? new Date().toISOString(),
        confirmed: Boolean(user.email_confirmed_at),
      }
    })

    users.push(...batch)

    if (batch.length < perPage) break
    page += 1
  }

  return users
}

export function getCustomerIdentities() { return operationsPage(db=>createCustomersRepository(db).list(),async()=>{throw new Error('Customer identity view requires RDS mode.')}) }
export function getCustomerMetrics() { return operationsPage(db=>createCustomersRepository(db).metrics(),async()=>({persistedCustomerIdentities:null,guestOrders:null,legacyAccountOrders:null,historicalRegistrations:(await getAdminCustomerUsers()).length})) }

export function validateSafeSvg(buffer: Buffer) {
  const text = buffer.toString('utf8').trim()
  if (!text || buffer.includes(0) || !/^<\?xml[\s\S]*?\?>\s*<svg\b|^<svg\b/i.test(text)) return false
  const unsafe = /<!doctype|<!entity|<script\b|<foreignObject\b|<iframe\b|<object\b|<embed\b|<audio\b|<video\b|<style\b|\son[a-z]+\s*=|javascript:|data:text\/html|(?:href|xlink:href)\s*=\s*["'](?!#)|url\(\s*["']?(?!#)/i
  return !unsafe.test(text)
}

import { createClient } from '@supabase/supabase-js'
import { assertLegacyAdminAuth } from './auth/integration'

function requireEnv(value: string | undefined, name: string) {
  if (!value) {
    throw new Error(`Missing ${name} environment variable for the admin app.`)
  }
  return value
}

export function createSupabaseAdminClient() {
  assertLegacyAdminAuth()
  const supabaseUrl = requireEnv(process.env.NEXT_PUBLIC_SUPABASE_URL, 'NEXT_PUBLIC_SUPABASE_URL')
  const supabaseServiceRoleKey = requireEnv(process.env.SUPABASE_SERVICE_ROLE_KEY, 'SUPABASE_SERVICE_ROLE_KEY')
  return createClient(supabaseUrl, supabaseServiceRoleKey, {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
    },
  })
}

import { cache } from 'react'
import { createSupabaseServerSessionClient } from '@/lib/server-supabase'
import { createSupabaseAdminClient } from '@/lib/admin-supabase'
import { readAdminAuthProvider } from './auth/integration'
import { resolveAdminServerSession } from './auth/admin-session'
import { authorizeProductPage } from './product-server-request'
import { ProductSessionError } from './product-session-error'

export type AdminServerSession = {
  userId: string
  email: string | null
  role: string
}

async function legacyAdminSession(): Promise<AdminServerSession | null> {
  const supabase = await createSupabaseServerSessionClient()

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser()

  if (userError || !user) {
    return null
  }

  const { data: profile, error: profileError } = await createSupabaseAdminClient()
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single()

  if (profileError || profile?.role !== 'admin') {
    return null
  }

  return {
    userId: user.id,
    email: user.email ?? null,
    role: profile.role,
  }
}

export const getAdminServerSession = cache(async (): Promise<AdminServerSession | null> => {
  try {
    return await resolveAdminServerSession({ provider: readAdminAuthProvider, authorize: authorizeProductPage, legacy: legacyAdminSession })
  } catch (error) {
    if (error instanceof ProductSessionError && [401, 403].includes(error.status)) return null
    throw new Error('Admin authentication unavailable')
  }
})

import { z } from 'zod'

const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Dates must use YYYY-MM-DD format.').refine((value) => {
  const date = new Date(`${value}T00:00:00.000Z`)
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value
}, 'Enter a valid calendar date.')

export const notificationReadSchema = z.object({
  notificationKey: z.string().trim().max(100).regex(/^(order|bespoke|contact|product|newsletter):[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i, 'Invalid notification key.'),
}).strict()

export const bespokeSubmissionQuerySchema = z.object({
  from: z.union([isoDate, z.literal('')]).optional(),
  to: z.union([isoDate, z.literal('')]).optional(),
  q: z.string().trim().max(200).optional(),
}).strict().superRefine((value, context) => {
  if (value.from && value.to && value.from > value.to) {
    context.addIssue({ code: z.ZodIssueCode.custom, path: ['to'], message: 'The end date must be on or after the start date.' })
  }
})

export function notificationWriteError(error: { code?: string; message?: string } | null) {
  if (error?.code === 'PGRST205' || error?.message?.includes('schema cache') || error?.message?.includes('does not exist')) {
    return { status: 503, message: 'Notification read-tracking is not enabled yet.' }
  }
  if (['22023', '22P02', '23502', '23503', '23505', '23514'].includes(error?.code ?? '')) {
    return { status: 400, message: 'Unable to update this notification.' }
  }
  return { status: 500, message: 'Unable to update notification status.' }
}

import { NextResponse } from 'next/server'
import sharp from 'sharp'
import type { assertAdmin } from './cms-auth'
import { validateSafeSvg } from './admin-upload-validation'
import { isS3MediaConfigured, uploadMediaToS3 } from './s3-media'
import type { AdminActor } from './auth/admin-identity-core'
import { boundedImageForm, ImageBodyTooLarge, validateAwsSvg } from './image-validation'

type Access = Exclude<Awaited<ReturnType<typeof assertAdmin>>, { error: NextResponse }>
export type UploadConfig = {
  bucket: string
  maxBytes: number
  rasterWidth: number | ((form: FormData) => number)
  rasterHeight?: number
  rasterFit?: 'inside' | 'cover'
  preserveAspectRatio?: boolean
  allowSvg?: boolean
  svgOnly?: boolean
  quality?: number
  successStatus?: 200 | 201
  validateForm?: (form: FormData) => string | null
  buildPath: (extension: 'webp' | 'svg', form: FormData) => string
}

const rasterFormats = new Map<string, Set<string>>([
  ['image/jpeg', new Set(['jpeg'])],
  ['image/png', new Set(['png'])],
  ['image/webp', new Set(['webp'])],
  ['image/avif', new Set(['avif', 'heif'])],
])

type AwsAccess = { provider: 'aws'; actor: AdminActor; target: { bucket: string; baseUrl: string } }
export async function handleAdminImageUpload(request: Request, access: Access | AwsAccess, config: UploadConfig) {
  const contentLength = Number(request.headers.get('content-length'))
  if (!Number.isFinite(contentLength) || contentLength <= 0) return NextResponse.json({ error: 'A valid upload size is required.' }, { status: 411 })
  if (contentLength > config.maxBytes + 1024 * 1024) return NextResponse.json({ error: 'The upload request is too large.' }, { status: 413 })

  let form: FormData | null
  try {
    form = 'provider' in access ? await boundedImageForm(request, config.maxBytes + 1024 * 1024) : await request.formData().catch(() => null)
  } catch (error) {
    return NextResponse.json({ error: error instanceof ImageBodyTooLarge ? 'The upload request is too large.' : 'Invalid image request.' }, { status: error instanceof ImageBodyTooLarge ? 413 : 400 })
  }
  const file = form?.get('file')
  if (!form || !(file instanceof File)) return NextResponse.json({ error: 'Missing image file.' }, { status: 400 })
  const formError = config.validateForm?.(form)
  if (formError) return NextResponse.json({ error: formError }, { status: 400 })
  if (file.size < 1 || file.size > config.maxBytes) return NextResponse.json({ error: `Images must be ${Math.floor(config.maxBytes / 1024 / 1024)} MB or smaller.` }, { status: file.size > 0 ? 413 : 400 })

  const input = Buffer.from(await file.arrayBuffer())
  let output: Buffer
  let extension: 'webp' | 'svg'
  let contentType: 'image/webp' | 'image/svg+xml'
  if (file.type === 'image/svg+xml') {
    if (!config.allowSvg || !validateSafeSvg(input) || ('provider' in access && !validateAwsSvg(input))) return NextResponse.json({ error: config.allowSvg ? 'The SVG contains unsupported or unsafe content.' : 'SVG images are not allowed here.' }, { status: 400 })
    output = input
    extension = 'svg'
    contentType = 'image/svg+xml'
  } else {
    if (config.svgOnly) return NextResponse.json({ error: 'Only safe SVG files are allowed.' }, { status: 400 })
    const formats = rasterFormats.get(file.type)
    if (!formats) return NextResponse.json({ error: 'Only JPG, PNG, WebP, or AVIF images are allowed.' }, { status: 400 })
    try {
      const image = sharp(input, { failOn: 'warning', limitInputPixels: 40_000_000 })
      const metadata = await image.metadata()
      if (!metadata.format || !formats.has(metadata.format)) return NextResponse.json({ error: 'The file contents do not match the selected image type.' }, { status: 400 })
      const width = typeof config.rasterWidth === 'function' ? config.rasterWidth(form) : config.rasterWidth
      output = await image.rotate().resize({ width, height: config.rasterHeight ?? (config.preserveAspectRatio ? undefined : width), fit: config.rasterFit ?? 'inside', withoutEnlargement: true }).webp({ quality: config.quality ?? 84 }).toBuffer()
      extension = 'webp'
      contentType = 'image/webp'
    } catch {
      return NextResponse.json({ error: 'The uploaded file is not a valid supported image.' }, { status: 400 })
    }
  }

  const path = config.buildPath(extension, form)
  if ('provider' in access) {
    try {
      const stored = await uploadMediaToS3(path, output, contentType, access.target)
      return NextResponse.json({ provider: 's3', path: stored.url, url: stored.url }, { status: config.successStatus ?? 201, headers: { 'Cache-Control': 'no-store' } })
    } catch {
      return NextResponse.json({ error: 'Unable to store the uploaded image.' }, { status: 500 })
    }
  }
  if (isS3MediaConfigured()) {
    try {
      const stored = await uploadMediaToS3(path, output, contentType)
      // Keep relative-path admin previews working until their URL builders move to the CDN.
      const { error: mirrorError } = await access.adminClient.storage.from(config.bucket).upload(path, output, { contentType, upsert: false, cacheControl: '86400' })
      if (mirrorError) throw mirrorError
      return NextResponse.json({ provider: 's3', ...stored }, { status: 201, headers: { 'Cache-Control': 'no-store' } })
    } catch {
      return NextResponse.json({ error: 'Unable to store the uploaded image.' }, { status: 500 })
    }
  }
  const { error } = await access.adminClient.storage.from(config.bucket).upload(path, output, { contentType, upsert: false, cacheControl: '31536000' })
  if (error) return NextResponse.json({ error: 'Unable to store the uploaded image.' }, { status: 500 })
  const { data } = access.adminClient.storage.from(config.bucket).getPublicUrl(path)
  return NextResponse.json({ path, url: data.publicUrl }, { status: 201, headers: { 'Cache-Control': 'no-store' } })
}

'use client'

export async function adminAuthProvider(): Promise<'supabase' | 'keycloak'> {
  const response = await fetch('/api/auth/provider', { credentials: 'same-origin', cache: 'no-store' })
  const data = await response.json()
  if (!response.ok || !['supabase', 'keycloak'].includes(data?.provider)) throw new Error('Admin authentication unavailable.')
  return data.provider
}

export async function adminCookieSession() {
  const response = await fetch('/api/auth/session', { credentials: 'same-origin', cache: 'no-store' })
  const data = await response.json()
  if (!response.ok || data?.authenticated !== true || typeof data.actor?.profileId !== 'string'
    || typeof data.csrfToken !== 'string' || !data.csrfToken) throw new Error('Please sign in again.')
  return { profileId: data.actor.profileId as string, csrfToken: data.csrfToken as string }
}

/** The response is a handoff, never evidence that a password was changed. */
export async function openAdminAccount(): Promise<string> {
  if (await adminAuthProvider() !== 'keycloak') throw new Error('Keycloak account management is not selected.')
  const session = await adminCookieSession()
  const response = await fetch('/api/auth/account', { method: 'POST', credentials: 'same-origin', cache: 'no-store', headers: { 'x-admin-csrf': session.csrfToken } })
  const data = await response.json()
  if (!response.ok) throw new Error(data?.error ?? 'Account management unavailable.')
  if (data?.action !== 'account-console' || data.url !== 'https://auth-uat.houseofdiams.com/realms/houseofdiams/account/') throw new Error('Invalid account destination.')
  return data.url
}

export async function logoutAdmin(): Promise<{ upstreamLogout: boolean }> {
  if (await adminAuthProvider() === 'supabase') {
    const { supabase } = await import('./supabase')
    const { error } = await supabase.auth.signOut()
    if (error) throw new Error('Unable to sign out.')
    return { upstreamLogout: true }
  }
  const session = await adminCookieSession()
  const response = await fetch('/api/auth/logout', { method: 'POST', credentials: 'same-origin', cache: 'no-store', headers: { 'x-admin-csrf': session.csrfToken } })
  const data = await response.json()
  // B1 deletes local authorization before upstream logout; a 502 must be shown honestly.
  if (data?.authenticated === false && (response.ok || response.status === 502) && typeof data.upstreamLogout === 'boolean') return { upstreamLogout: data.upstreamLogout }
  throw new Error('Unable to confirm sign-out. Please retry.')
}

