'use client'

import Link from 'next/link'
import { Bell, ExternalLink, Mail, ShoppingCart, Sparkles, Newspaper, ShoppingBag } from 'lucide-react'
import { useMemo, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import type { AdminNotificationItem, AdminNotificationType, NotificationsPageData } from '@/lib/notifications'
import { operationsFetch } from '@/lib/operations-transport'
import { useToast } from '@/hooks/use-toast'

type NotificationTab = 'all' | AdminNotificationType

const TAB_ORDER: Array<{ id: NotificationTab; label: string }> = [
  { id: 'all', label: 'All' },
  { id: 'order', label: 'Orders' },
  { id: 'bespoke', label: 'Bespoke' },
  { id: 'contact', label: 'Contact' },
  { id: 'product', label: 'Product' },
  { id: 'newsletter', label: 'Newsletter' },
]

function normalizeTab(value: string | null): NotificationTab {
  if (value === 'order' || value === 'bespoke' || value === 'contact' || value === 'product' || value === 'newsletter') return value
  return 'all'
}

function getIcon(type: AdminNotificationItem['type']) {
  switch (type) {
    case 'order':
      return ShoppingCart
    case 'bespoke':
      return Sparkles
    case 'product':
      return ShoppingBag
    case 'newsletter':
      return Newspaper
    default:
      return Mail
  }
}

export function NotificationsClient({ initialData }: { initialData: NotificationsPageData }) {
  const { toast } = useToast()
  const searchParams = useSearchParams()
  const activeTab = normalizeTab(searchParams.get('tab'))
  const [data, setData] = useState(initialData)
  const [markingKey, setMarkingKey] = useState<string | null>(null)
  const [markingAll, setMarkingAll] = useState(false)
  const [exitingKeys, setExitingKeys] = useState<string[]>([])

  const items = useMemo(() => {
    const unreadItems = data.items.filter((item) => !item.read)
    if (activeTab === 'all') return unreadItems
    return unreadItems.filter((item) => item.type === activeTab)
  }, [activeTab, data.items])

  const applyReadLocally = (notificationKey: string) => {
    setData((current) => {
      const nextItems = current.items.filter((item) => item.notificationKey !== notificationKey)

      return {
        ...current,
        items: nextItems,
        unreadCounts: {
          all: nextItems.filter((item) => !item.read).length,
          order: nextItems.filter((item) => item.type === 'order' && !item.read).length,
          bespoke: nextItems.filter((item) => item.type === 'bespoke' && !item.read).length,
          contact: nextItems.filter((item) => item.type === 'contact' && !item.read).length,
          product: nextItems.filter((item) => item.type === 'product' && !item.read).length,
          newsletter: nextItems.filter((item) => item.type === 'newsletter' && !item.read).length,
        },
      }
    })
  }

  const animateAndRemove = async (notificationKey: string, action: () => Promise<void>, afterRemove?: () => void) => {
    setMarkingKey(notificationKey)
    try {
      await action()
      setExitingKeys((current) => (current.includes(notificationKey) ? current : [...current, notificationKey]))
      window.setTimeout(() => {
        applyReadLocally(notificationKey)
        setExitingKeys((current) => current.filter((key) => key !== notificationKey))
        afterRemove?.()
      }, 260)
    } catch (error) {
      toast({ title: 'Update failed', description: error instanceof Error ? error.message : 'Unable to mark as read.', variant: 'destructive' })
    } finally {
      setMarkingKey(null)
    }
  }

  async function markRead(notificationKey: string) {

    const response = await operationsFetch('/api/notifications/read', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
      },
      body: JSON.stringify({ notificationKey }),
    })

    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(payload?.error ?? 'Unable to mark notification as read.')
    }
  }

  async function handleMarkAllRead() {
    setMarkingAll(true)
    try {

      const response = await operationsFetch('/api/notifications/read-all', {
        method: 'POST',
        headers: { },
      })

      const payload = await response.json().catch(() => null)
      if (!response.ok) {
        throw new Error(payload?.error ?? 'Unable to mark notifications as read.')
      }

      setData((current) => ({
        ...current,
        items: current.items.map((item) => ({ ...item, read: true })),
        unreadCounts: {
          all: 0,
          order: 0,
          bespoke: 0,
          contact: 0,
          product: 0,
          newsletter: 0,
        },
      }))
      toast({ title: 'Notifications updated', description: 'All current notifications were marked as read.' })
    } catch (error) {
      toast({ title: 'Update failed', description: error instanceof Error ? error.message : 'Unable to mark all as read.', variant: 'destructive' })
    } finally {
      setMarkingAll(false)
    }
  }

  return (
    <div className="p-8">
      <div className="mb-8">
        <h1 className="font-jakarta text-3xl font-semibold text-foreground">Notifications</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Real-time admin alerts from pending orders and new submissions.
        </p>
      </div>

      <div className="mb-6 flex flex-wrap gap-2">
        {TAB_ORDER.map((tab) => {
          const isActive = activeTab === tab.id
          const count = data.unreadCounts[tab.id]

          return (
            <Link
              key={tab.id}
              href={tab.id === 'all' ? '/dashboard/notifications' : `/dashboard/notifications?tab=${tab.id}`}
              className={`inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-semibold transition-colors ${
                isActive ? 'border-primary bg-primary text-white' : 'border-border bg-white text-foreground hover:bg-secondary'
              }`}
            >
              <span>{tab.label}</span>
              <span className={`inline-flex min-w-6 items-center justify-center rounded-full px-1.5 text-[11px] ${isActive ? 'bg-white/20 text-white' : 'bg-secondary text-foreground'}`}>
                {count}
              </span>
            </Link>
          )
        })}
      </div>

      <div className="mb-6 flex items-center justify-between gap-4 rounded-2xl border border-border bg-white px-5 py-4">
        <div className="flex items-center gap-3">
          <div className="rounded-full bg-secondary p-2 text-foreground">
            <Bell size={16} />
          </div>
          <div>
            <div className="text-sm font-semibold text-foreground">{data.unreadCounts.all} unread notification{data.unreadCounts.all === 1 ? '' : 's'}</div>
            <div className="text-xs text-muted-foreground">Reading them removes them from the bell count without changing order or enquiry workflow status.</div>
          </div>
        </div>
        <button
          type="button"
          onClick={() => void handleMarkAllRead()}
          disabled={markingAll || data.unreadCounts.all === 0}
          className="rounded-lg border border-border px-4 py-2 text-sm font-semibold text-foreground hover:bg-secondary disabled:cursor-not-allowed disabled:opacity-50"
        >
          {markingAll ? 'Updating...' : 'Mark all read'}
        </button>
      </div>

      {!data.newsletterEnabled ? (
        <div className="mb-6 rounded-2xl border border-amber-200 bg-amber-50 px-5 py-4 text-sm text-amber-900">
          Newsletter alerts will appear here after newsletter storage is enabled in the database.
        </div>
      ) : null}

      <div className="space-y-4">
        {items.map((item) => {
          const Icon = getIcon(item.type)
          const isExiting = exitingKeys.includes(item.notificationKey)
          return (
            <article
              key={item.id}
              className={`rounded-2xl border border-border bg-white p-5 shadow-xs transition-all duration-300 ease-out ${
                isExiting ? 'translate-x-16 opacity-0 blur-[1px]' : 'translate-x-0 opacity-100'
              }`}
            >
              <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
                <div className="min-w-0 flex-1">
                  <div className="mb-3 flex flex-wrap items-center gap-2">
                    <span className="inline-flex items-center gap-2 rounded-full bg-secondary px-3 py-1 text-xs font-semibold uppercase tracking-wide text-foreground">
                      <Icon size={12} />
                      {item.type}
                    </span>
                    <span className="inline-flex rounded-full border border-border px-3 py-1 text-xs font-medium text-muted-foreground">
                      {item.status}
                    </span>
                    <span className="text-xs text-muted-foreground">{new Date(item.createdAt).toLocaleString()}</span>
                  </div>
                  <h2 className="font-jakarta text-lg font-semibold text-foreground">{item.title}</h2>
                  <p className="mt-2 text-sm leading-6 text-muted-foreground">{item.summary}</p>
                </div>

                <div className="flex gap-2">
                  <button
                    type="button"
                    disabled={markingKey === item.notificationKey}
                    onClick={() => void animateAndRemove(item.notificationKey, () => markRead(item.notificationKey))}
                    className="inline-flex items-center gap-2 rounded-lg border border-border px-4 py-2 text-sm font-semibold text-foreground hover:bg-secondary disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {markingKey === item.notificationKey ? 'Updating...' : 'Mark read'}
                  </button>
                  <Link
                    href={item.href}
                    onClick={async (event) => {
                      event.preventDefault()
                      await animateAndRemove(item.notificationKey, () => markRead(item.notificationKey), () => {
                        window.location.href = item.href
                      })
                    }}
                    className="inline-flex items-center gap-2 rounded-lg border border-border px-4 py-2 text-sm font-semibold text-foreground hover:bg-secondary"
                  >
                    Open
                    <ExternalLink size={14} />
                  </Link>
                </div>
              </div>
            </article>
          )
        })}

        {items.length === 0 ? (
          <div className="rounded-2xl border border-border bg-white px-6 py-10 text-sm text-muted-foreground">
            No notifications found for this view.
          </div>
        ) : null}
      </div>
    </div>
  )
}

'use client'

import { cmsFetch } from '@/lib/cms-transport'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useMemo, useRef, useState } from 'react'
import { ArrowDown, ArrowLeft, ArrowUp, ExternalLink, Plus, Trash2, X } from 'lucide-react'
import { CmsSaveAction } from '@/components/cms-save-action'
import { useToast } from '@/hooks/use-toast'
import { canonicalizeInstagramUrl } from '@/lib/instagram-url'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { useUnsavedChanges } from '@/hooks/use-unsaved-changes'

type Reel = {
  clientId: string
  id?: string
  instagram_url: string
  title: string
  display_order: number
  is_enabled: boolean
}

type ReelDraft = {
  instagram_url: string
  title: string
  is_enabled: boolean
}

export type ReelsInitialData = {
  revision: string | null
  heading: string
  subtitle: string
  is_enabled: boolean
  marquee_duration_seconds: number
  pause_on_hover: boolean
  items: Array<Omit<Reel, 'clientId'>>
}

const emptyDraft: ReelDraft = {
  instagram_url: '',
  title: '',
  is_enabled: true,
}

function normalizeInitialItem(item: Omit<Reel, 'clientId'>): Reel {
  return {
    ...item,
    clientId: item.id ?? crypto.randomUUID(),
  }
}

function saveState(data: Omit<ReelsInitialData, 'revision'>) {
  return {
    heading: data.heading.trim(), subtitle: data.subtitle.trim(),
    is_enabled: data.is_enabled, marquee_duration_seconds: data.marquee_duration_seconds,
    pause_on_hover: data.pause_on_hover,
    items: data.items.map(({ id, instagram_url, title, is_enabled }) => ({
      ...(id ? { id } : {}), instagram_url: canonicalizeInstagramUrl(instagram_url) ?? instagram_url,
      title: title.trim(), is_enabled,
    })),
  }
}

export function ReelsEditorClient({ initialData }: { initialData: ReelsInitialData }) {
  const { toast } = useToast()
  const router = useRouter()
  const [heading, setHeading] = useState(initialData.heading)
  const [subtitle, setSubtitle] = useState(initialData.subtitle)
  const [enabled, setEnabled] = useState(initialData.is_enabled)
  const [duration, setDuration] = useState(initialData.marquee_duration_seconds)
  const [pauseOnHover, setPauseOnHover] = useState(initialData.pause_on_hover)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [items, setItems] = useState<Reel[]>(initialData.items.map(normalizeInitialItem))
  const [addOpen, setAddOpen] = useState(false)
  const [draft, setDraft] = useState<ReelDraft>(emptyDraft)
  const [draftError, setDraftError] = useState('')
  const ordered = useMemo(() => items.map((item, index) => ({ ...item, display_order: index })), [items])
  const [revision, setRevision] = useState(initialData.revision)
  const [savedState, setSavedState] = useState(() => saveState(initialData))
  const [conflict, setConflict] = useState(false)
  const inFlight = useRef(false)
  const pendingRequest = useRef<{ fingerprint: string; id: string } | null>(null)
  const currentState = saveState({ heading, subtitle, is_enabled: enabled, marquee_duration_seconds: duration, pause_on_hover: pauseOnHover, items: ordered })
  const dirty = JSON.stringify(currentState) !== JSON.stringify(savedState)
  const unsaved = useUnsavedChanges(dirty)

  const update = (clientId: string, patch: Partial<Reel>) => {
    setItems((current) => current.map((item) => item.clientId === clientId ? { ...item, ...patch } : item))
  }

  const move = (index: number, delta: number) => {
    setItems((current) => {
      const next = [...current]
      const target = index + delta
      if (target < 0 || target >= next.length) return current
      ;[next[index], next[target]] = [next[target], next[index]]
      return next
    })
  }

  const openAddDialog = () => {
    setDraft(emptyDraft)
    setDraftError('')
    setAddOpen(true)
  }

  const closeAddDialog = () => {
    if (saving) return
    setAddOpen(false)
    setDraftError('')
  }

  const addDraftToList = () => {
    const instagramUrl = canonicalizeInstagramUrl(draft.instagram_url)
    if (!instagramUrl) { setDraftError('Add a valid public Instagram Reel or post URL.'); return }
    if (ordered.some((item) => canonicalizeInstagramUrl(item.instagram_url) === instagramUrl)) { setDraftError('This Instagram URL is already in the marquee.'); return }
    if (draft.title.trim().length > 100) { setDraftError('Display title must be 100 characters or less.'); return }

    setItems((current) => [...current, {
      clientId: crypto.randomUUID(),
      instagram_url: instagramUrl,
      title: draft.title.trim(),
      display_order: current.length,
      is_enabled: draft.is_enabled,
    }])
    setAddOpen(false)
    setDraft(emptyDraft)
    setDraftError('')
  }

  const save = async () => {
    if (inFlight.current || !dirty || !revision || conflict) return
    setError('')
    const canonical = ordered.map((item) => canonicalizeInstagramUrl(item.instagram_url))
    if (!heading.trim()) { setError('Add a section heading before saving.'); return }
    if (canonical.some((url) => !url) || new Set(canonical).size !== canonical.length) { setError('Use unique public Instagram Reel or post URLs.'); return }

    const retainedIds = new Set(currentState.items.map((item) => item.id).filter(Boolean))
    const deletedIds = savedState.items.flatMap((item) => item.id && !retainedIds.has(item.id) ? [item.id] : [])
    const body = { ...currentState, expected_revision: revision, deleted_ids: deletedIds }
    const fingerprint = JSON.stringify(body)
    if (pendingRequest.current?.fingerprint !== fingerprint) {
      pendingRequest.current = { fingerprint, id: crypto.randomUUID() }
    }
    inFlight.current = true
    setSaving(true)
    try {


      const response = await cmsFetch('/api/cms/home/reels', {
        method: 'POST',
        headers: { 'content-type': 'application/json',  },
        body: JSON.stringify({ ...body, request_id: pendingRequest.current.id }),
      })
      const payload = await response.json().catch(() => null)
      if (!response.ok) {
        if (response.status === 409) setConflict(true)
        throw new Error(payload?.error ?? 'Unable to save Instagram Reels.')
      }
      if (!Array.isArray(payload?.items) || typeof payload.revision !== 'string') throw new Error('Save response was interrupted. Retry to confirm the same save.')
      const next = saveState({ ...currentState, items: payload.items })
      setItems(payload.items.map((item: Omit<Reel, 'clientId'>) => normalizeInitialItem(item)))
      setHeading(next.heading)
      setSubtitle(next.subtitle)
      setSavedState(next)
      setRevision(payload.revision)
      pendingRequest.current = null
      toast({ title: 'Saved', description: 'Instagram Reels section updated.' })
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Connection interrupted. Retry to confirm your save.')
    } finally {
      inFlight.current = false
      setSaving(false)
    }
  }

  return <main className="p-8">
    <div className="mb-8 flex items-center justify-between gap-4"><Link href="/dashboard/cms/home" onClick={(event) => { event.preventDefault(); unsaved.confirmNavigation(() => router.push('/dashboard/cms/home')) }} className="inline-flex items-center gap-2 text-sm font-semibold text-primary"><ArrowLeft size={16}/>Back to Home</Link><CmsSaveAction onClick={save} isSaving={saving} disabled={!dirty || !revision || conflict} position="inline"/></div>
    <header className="mb-8"><p className="text-xs font-semibold uppercase tracking-[.2em] text-primary">Homepage / Social</p><h1 className="mt-2 font-jakarta text-3xl font-semibold">Instagram Reels</h1><p className="mt-1 text-sm text-muted-foreground">Curate up to 30 public Instagram posts for the homepage marquee. Each card displays the reel frame directly from Instagram.</p></header>
    {error ? <div role="alert" className="mb-6 max-w-6xl rounded-md border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div> : null}
    {!revision ? <p role="status" className="mb-6 text-sm text-amber-800">Reels are available to view. Saving will be enabled after the database update is installed and this page is reloaded.</p> : null}
    {conflict ? <p className="mb-6 text-sm text-amber-800">Keep a copy of your changes, then reload this page to see the latest saved reels.</p> : null}
    <fieldset disabled={saving || !revision || conflict} className="min-w-0">
    <section className="mb-8 grid max-w-6xl gap-5 rounded-lg border bg-white p-6 shadow-xs md:grid-cols-2">
      <label className="text-sm font-semibold">Heading<input maxLength={120} value={heading} onChange={(e)=>setHeading(e.target.value)} className="mt-2 w-full rounded-md border px-3 py-2 font-normal"/></label>
      <label className="text-sm font-semibold">Subtitle<input maxLength={240} value={subtitle} onChange={(e)=>setSubtitle(e.target.value)} className="mt-2 w-full rounded-md border px-3 py-2 font-normal"/></label>
      <label className="text-sm font-semibold">Marquee duration (seconds)<input type="number" min={10} max={180} value={duration} onChange={(e)=>setDuration(Number(e.target.value))} className="mt-2 w-full rounded-md border px-3 py-2 font-normal"/></label>
      <div className="flex items-end gap-6 pb-2"><label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={enabled} onChange={(e)=>setEnabled(e.target.checked)}/>Section enabled</label><label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={pauseOnHover} onChange={(e)=>setPauseOnHover(e.target.checked)}/>Pause on hover</label></div>
    </section>
    <section className="max-w-6xl overflow-hidden rounded-lg border bg-white shadow-xs">
      <div className="flex items-center justify-between border-b bg-secondary/40 px-5 py-4"><div><h2 className="font-semibold">Marquee entries</h2><p className="text-xs text-muted-foreground">Enabled rows appear on the homepage in this order.</p></div><button type="button" disabled={items.length >= 30} onClick={openAddDialog} className="inline-flex items-center gap-2 rounded-md bg-primary px-3 py-2 text-sm font-semibold text-white disabled:opacity-50"><Plus size={15}/>Add Reel</button></div>
      {ordered.length === 0 ? <p className="px-5 py-12 text-center text-sm text-muted-foreground">No reels yet. Add a public Instagram URL to begin.</p> : <div className="overflow-x-auto">
        <table className="w-full min-w-[980px] table-fixed border-collapse text-left">
          <thead className="border-b bg-secondary/20 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            <tr>
              <th scope="col" className="w-36 px-5 py-3">Order</th>
              <th scope="col" className="w-[38%] px-4 py-3">Instagram URL</th>
              <th scope="col" className="w-[28%] px-4 py-3">Display title</th>
              <th scope="col" className="w-28 px-4 py-3">Status</th>
              <th scope="col" className="w-52 px-5 py-3 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {ordered.map((item,index)=><tr key={item.clientId} className="align-middle transition-colors hover:bg-secondary/10">
              <td className="px-5 py-4">
                <div className="flex items-center gap-3">
                  <span className="w-5 text-center text-sm font-semibold tabular-nums text-foreground">{index + 1}</span>
                  <div className="flex gap-1">
                    <button type="button" aria-label={`Move reel ${index + 1} up`} disabled={!index} onClick={()=>move(index,-1)} className="rounded-md border border-border bg-white p-2 text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground disabled:cursor-not-allowed disabled:opacity-30"><ArrowUp size={15}/></button>
                    <button type="button" aria-label={`Move reel ${index + 1} down`} disabled={index===ordered.length-1} onClick={()=>move(index,1)} className="rounded-md border border-border bg-white p-2 text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground disabled:cursor-not-allowed disabled:opacity-30"><ArrowDown size={15}/></button>
                  </div>
                </div>
              </td>
              <td className="px-4 py-4"><label className="sr-only" htmlFor={`reel-url-${item.clientId}`}>Instagram URL for reel {index + 1}</label><input id={`reel-url-${item.clientId}`} value={item.instagram_url} onChange={(e)=>update(item.clientId,{instagram_url:e.target.value})} onBlur={()=>{const url=canonicalizeInstagramUrl(item.instagram_url);if(url)update(item.clientId,{instagram_url:url})}} placeholder="https://www.instagram.com/reel/SHORTCODE/" className="w-full rounded-md border px-3 py-2 text-sm font-normal"/></td>
              <td className="px-4 py-4"><label className="sr-only" htmlFor={`reel-title-${item.clientId}`}>Display title for reel {index + 1}</label><input id={`reel-title-${item.clientId}`} maxLength={100} value={item.title} onChange={(e)=>update(item.clientId,{title:e.target.value})} className="w-full rounded-md border px-3 py-2 text-sm font-normal"/></td>
              <td className="px-4 py-4"><label className="inline-flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={item.is_enabled} onChange={(e)=>update(item.clientId,{is_enabled:e.target.checked})}/>Enabled</label></td>
              <td className="px-5 py-4">
                <div className="flex items-center justify-end gap-2">
                  {canonicalizeInstagramUrl(item.instagram_url)?<a href={canonicalizeInstagramUrl(item.instagram_url)!} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 rounded-md border border-border px-3 py-2 text-sm font-semibold text-foreground transition-colors hover:bg-secondary"><ExternalLink size={15}/>Open Instagram</a>:null}
                  <button type="button" aria-label={`Delete reel ${index + 1}`} onClick={()=>setItems((v)=>v.filter((x)=>x.clientId!==item.clientId))} className="inline-flex items-center gap-2 rounded-md border border-red-200 px-3 py-2 text-sm font-semibold text-red-600 transition-colors hover:bg-red-50"><Trash2 size={15}/>Delete</button>
                </div>
              </td>
            </tr>)}
          </tbody>
        </table>
      </div>}
    </section>

    {addOpen ? <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/45 px-4 py-6" role="dialog" aria-modal="true" aria-labelledby="add-reel-title">
      <div className="w-full max-w-2xl rounded-lg border bg-white shadow-2xl">
        <div className="flex items-start justify-between gap-4 border-b px-6 py-5"><div><h2 id="add-reel-title" className="text-xl font-semibold">Add Instagram Reel</h2><p className="mt-1 text-sm text-muted-foreground">Paste a public Instagram URL.</p></div><button type="button" onClick={closeAddDialog} className="rounded border p-2 text-muted-foreground hover:text-foreground" aria-label="Close add reel dialog"><X size={16}/></button></div>
        <div className="space-y-5 px-6 py-5">
          {draftError ? <div role="alert" className="rounded-md border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{draftError}</div> : null}
          <label className="block text-sm font-semibold">Instagram URL<input autoFocus value={draft.instagram_url} onChange={(e)=>setDraft((current)=>({...current, instagram_url:e.target.value}))} onBlur={()=>{const url=canonicalizeInstagramUrl(draft.instagram_url);if(url)setDraft((current)=>({...current, instagram_url:url}))}} placeholder="https://www.instagram.com/reel/SHORTCODE/" className="mt-2 w-full rounded-md border px-3 py-2 font-normal"/></label>
          <label className="block text-sm font-semibold">Display title<input maxLength={100} value={draft.title} onChange={(e)=>setDraft((current)=>({...current, title:e.target.value}))} placeholder="Optional title shown on the cover" className="mt-2 w-full rounded-md border px-3 py-2 font-normal"/></label>
          <label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={draft.is_enabled} onChange={(e)=>setDraft((current)=>({...current, is_enabled:e.target.checked}))}/>Enabled on homepage</label>
        </div>
        <div className="flex justify-end gap-3 border-t px-6 py-4"><button type="button" onClick={closeAddDialog} className="rounded-md border px-4 py-2 text-sm font-semibold">Cancel</button><button type="button" onClick={addDraftToList} className="rounded-md bg-primary px-4 py-2 text-sm font-semibold text-white">Add Reel</button></div>
      </div>
    </div> : null}
    </fieldset>
    <ConfirmDialog isOpen={unsaved.showWarning} title="Discard unsaved Instagram Reels changes?" description="Your changes have not been saved." confirmText="Discard changes" cancelText="Keep editing" type="warning" onConfirm={unsaved.handleDiscard} onCancel={() => unsaved.setShowWarning(false)}/>
  </main>
}

import { cmsPageReader } from '@/lib/cms-page-data'
import { readCms } from '@/lib/cms-command'
﻿import { createSupabaseAdminClient } from '@/lib/admin-supabase'
import { ReelsEditorClient, type ReelsInitialData } from './reels-editor-client'

const SECTION_KEY = 'home_instagram_reels'

type ReelItemRow = { id?: string; instagram_url: string; title: string; display_order: number; is_enabled: boolean }

async function loadReelItems(client: ReturnType<typeof createSupabaseAdminClient>) {
  const result = await client
    .from('home_instagram_reels')
    .select('id, instagram_url, title, display_order, is_enabled')
    .eq('section_key', SECTION_KEY)
    .order('display_order')
    .limit(30)

  if (!result.error) return result
  if (!result.error.message?.includes('cover_image_url')) return result

  return client
    .from('home_instagram_reels')
    .select('id, instagram_url, title, display_order, is_enabled')
    .eq('section_key', SECTION_KEY)
    .order('display_order')
    .limit(30)
}

async function getInitialData(): Promise<ReelsInitialData> {
  const reader = await cmsPageReader()
  const snapshot = await readCms(reader, 'cms_reels_snapshot_v1', {})
  const client = 'execute' in reader ? null : reader as ReturnType<typeof createSupabaseAdminClient>
  if (!snapshot.error) {
    const data = snapshot.data as {section: Omit<ReelsInitialData,'items'|'revision'>;items:ReelsInitialData['items'];revision:string}
    return {
      heading: data.section?.heading ?? 'Follow Us on Instagram',
      subtitle: data.section?.subtitle ?? '',
      is_enabled: data.section?.is_enabled ?? true,
      marquee_duration_seconds: data.section?.marquee_duration_seconds ?? 40,
      pause_on_hover: data.section?.pause_on_hover ?? true,
      items: data.items,
      revision: data.revision,
    }
  }
  // During deployment, keep existing content readable but disable unsafe saves.
  if (!['PGRST202', '42883'].includes(snapshot.error.code ?? '')) throw new Error('Unable to load reels. Please reload this page.')
  if (!client) throw new Error('Unable to load reels.')
  const [section, items] = await Promise.all([
    client.from('home_instagram_reels_section').select('heading, subtitle, is_enabled, marquee_duration_seconds, pause_on_hover').eq('section_key', SECTION_KEY).maybeSingle(),
    loadReelItems(client),
  ])

  if (section.error || items.error) throw new Error(section.error?.message ?? items.error?.message)

  return {
    revision: null,
    heading: section.data?.heading ?? 'Follow Us on Instagram',
    subtitle: section.data?.subtitle ?? 'Discover the latest from House of Diams',
    is_enabled: section.data?.is_enabled ?? true,
    marquee_duration_seconds: section.data?.marquee_duration_seconds ?? 40,
    pause_on_hover: section.data?.pause_on_hover ?? true,
    items: ((items.data ?? []) as ReelItemRow[]).map((item) => ({ ...item })),
  }
}

export default async function ReelsEditorPage() {
  return <ReelsEditorClient initialData={await getInitialData()} />
}

export default function Layout({ children }: { children: React.ReactNode }) {
  return <>{children}</>
}

import { readCmsId } from '@/lib/cms-id-safety'
import { cmsPageReader } from '@/lib/cms-page-data'
import { loadCmsContentListSnapshot } from '@/lib/cms-content-list-save'
import {
  BespokeManufacturingEditorClient,
  type BespokeManufacturingInitialData,
} from './bespoke-manufacturing-editor-client'

async function getBespokeManufacturingInitialData(): Promise<BespokeManufacturingInitialData> {
  const adminClient = await cmsPageReader()
  const snapshot = await loadCmsContentListSnapshot(adminClient, 'bespoke_manufacturing')

  return {
    revision: snapshot.revision,
    items: snapshot.items.map((item) => ({ id: readCmsId(item.id), sort_order: Number(item.sort_order), step: String(item.step ?? ''), eyebrow: String(item.eyebrow ?? ''), title: String(item.title ?? ''), description: String(item.description ?? ''), image_path: String(item.image_path ?? ''), media_type: item.media_type === 'video' ? 'video' : 'image', media_path: String(item.media_path ?? '') })),
  }
}

export default async function BespokeManufacturingPage() {
  const initialData = await getBespokeManufacturingInitialData()
  return <BespokeManufacturingEditorClient initialData={initialData} />
}

'use client'
import { tryUploadAwsImage } from '@/lib/image-transport'
import { compareCmsIds } from '@/lib/cms-id-safety'


import { cmsFetch } from '@/lib/cms-transport'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useMemo, useState, type ChangeEvent } from 'react'
import { ArrowLeft, Edit2, Plus, Trash2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { CmsSaveAction } from '@/components/cms-save-action'
import { useToast } from '@/hooks/use-toast'
import { useCmsAtomicListSave } from '@/hooks/use-cms-atomic-list-save'
import { useUnsavedChanges } from '@/hooks/use-unsaved-changes'

type ManufacturingItem = {
  clientId: string
  id?: number | string
  sort_order: number
  step: string
  eyebrow: string
  title: string
  description: string
  media_type: 'image' | 'video'
  media_path: string
  image_path: string
}

type EditorItem = ManufacturingItem

export type BespokeManufacturingInitialData = {
  revision: string
  items: Array<{
    id: number | string
    sort_order: number
    step: string
    eyebrow: string
    title: string
    description: string
    media_type?: 'image' | 'video' | null
    media_path?: string | null
    image_path: string
  }>
}

type EditorCopy = {
  backHref?: string
  backLabel?: string
  title?: string
  description?: string
  loadedStatus?: string
  emptyStatus?: string
  savedStatus?: string
  confirmTitle?: string
  confirmDescription?: string
  hideMetaFields?: boolean
}

const empty = (sortOrder: number): EditorItem => ({
  clientId: `draft-${Date.now()}`,
  sort_order: sortOrder,
  step: '',
  eyebrow: '',
  title: '',
  description: '',
  media_type: 'image',
  media_path: '',
  image_path: '',
})

export function BespokeManufacturingEditorClient({
  initialData,
  copy = {},
}: {
  initialData: BespokeManufacturingInitialData
  copy?: EditorCopy
}) {
  const { toast } = useToast()
  const router = useRouter()
  const resolvedCopy = {
    backHref: '/dashboard/cms/bespoke',
    backLabel: 'Back to Bespoke',
    title: 'Manufacturing',
    description: 'Manage the workshop cards with images',
    loadedStatus: 'Bespoke manufacturing loaded',
    emptyStatus: 'No workshop cards found yet',
    savedStatus: 'Bespoke manufacturing saved',
    confirmTitle: 'Save Bespoke Manufacturing?',
    confirmDescription: 'This will update the Bespoke manufacturing section on the live site.',
    ...copy,
  }
  const [items, setItems] = useState<ManufacturingItem[]>(
    initialData.items.map((item) => ({
      clientId: `id-${item.id}`,
      ...item,
      media_type: item.media_type === 'video' ? 'video' : 'image',
      media_path: item.media_path ?? item.image_path ?? '',
      image_path: item.image_path ?? item.media_path ?? '',
    }))
  )
  const [status, setStatus] = useState(initialData.items.length ? resolvedCopy.loadedStatus : resolvedCopy.emptyStatus)
  const [isSaving, setIsSaving] = useState(false)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [editorOpen, setEditorOpen] = useState(false)
  const [editorItem, setEditorItem] = useState<EditorItem>(empty(1))
  const [uploading, setUploading] = useState(false)
  const [savedState, setSavedState] = useState(() => JSON.stringify(
    [...initialData.items].sort((a, b) => a.sort_order - b.sort_order || compareCmsIds(a.id, b.id)).map((item) => ({
      id: item.id, step: item.step, eyebrow: item.eyebrow, title: item.title, description: item.description,
      media_type: item.media_type === 'video' ? 'video' : 'image', media_path: item.media_path ?? item.image_path ?? '',
      image_path: item.media_type === 'video' ? '' : (item.media_path ?? item.image_path ?? ''),
    }))
  ))
  const { prepareSave, acceptSave } = useCmsAtomicListSave(initialData.items, initialData.revision)

  const sorted = useMemo(
    () => [...items].sort((a, b) => a.sort_order - b.sort_order || a.clientId.localeCompare(b.clientId)),
    [items]
  )
  const saveItems = sorted.map(({ id, step, eyebrow, title, description, media_type, media_path, image_path }) => ({
    ...(id ? { id } : {}), step, eyebrow, title, description, media_type, media_path,
    image_path: media_type === 'image' ? (media_path || image_path) : '',
  }))
  const dirty = JSON.stringify(saveItems) !== savedState
  const unsaved = useUnsavedChanges(dirty || editorOpen)
  const nextOrder = Math.max(...items.map((item) => item.sort_order), 0) + 1

  const uploadImage = async (file: File) => {

    try {
      const awsPath = await tryUploadAwsImage(file, '/api/cms/uploads/bespoke-process', {},{start:()=>setUploading(true),finish:()=>setUploading(false)})
      if (awsPath) { setEditorItem(prev => ({...prev,media_type:'image',media_path:awsPath,image_path:awsPath})); setStatus('Image uploaded successfully'); return }
    } catch (error) { setStatus(error instanceof Error ? error.message : 'Upload failed.'); return }


    const { supabase } = await import('@/lib/supabase')
    const { data: sessionData } = await supabase.auth.getSession()
    const accessToken = sessionData.session?.access_token
    if (!accessToken) {
      setStatus('You are not signed in.')
      return
    }

    if (file.size > 5 * 1024 * 1024) {
      setStatus('File too large. Max size is 5MB.')
      return
    }

    setUploading(true)
    try {
      let uploadedPath = ''
      try {
        const preparedFile = await prepareManufacturingImage(file)
        const signResponse = await fetch('/api/cms/uploads/bespoke-process/sign', {
          method: 'POST',
          headers: { authorization: `Bearer ${accessToken}`, 'content-type': 'application/json' },
        body: JSON.stringify({ contentType: preparedFile.type, declaredSize: preparedFile.size }),
        })
        const signed = await signResponse.json().catch(() => null) as { bucket?: string; path?: string; token?: string; error?: string } | null
        if (!signResponse.ok || !signed?.bucket || !signed.path || !signed.token) throw new Error(signed?.error ?? 'Unable to prepare upload.')
        const { error } = await supabase.storage.from(signed.bucket)
          .uploadToSignedUrl(signed.path, signed.token, preparedFile, { contentType: preparedFile.type })
        if (error) throw error
        uploadedPath = signed.path
      } catch {
        const formData = new FormData()
        formData.append('file', file)
        const response = await fetch('/api/cms/uploads/bespoke-process', {
          method: 'POST', headers: { authorization: `Bearer ${accessToken}` }, body: formData,
        })
        const payload = await response.json().catch(() => null) as { path?: string; error?: string } | null
        if (!response.ok || !payload?.path) {
          setStatus(payload?.error ?? 'Unable to upload manufacturing image.')
          return
        }
        uploadedPath = payload.path
      }
      setEditorItem((prev) => ({ ...prev, media_type: 'image', media_path: uploadedPath, image_path: uploadedPath }))
      setStatus('Manufacturing image uploaded')
    } catch {
      setStatus('Unable to upload manufacturing image.')
    } finally {
      setUploading(false)
    }
  }

  const saveAll = async () => {
    setIsSaving(true)
    try {



      const response = await cmsFetch('/api/cms/bespoke/manufacturing', {
        method: 'POST', headers: { 'content-type': 'application/json',  },
        body: JSON.stringify(prepareSave({ items: saveItems }, saveItems)),
      })
      const payload = (await response.json().catch(() => null)) as { items?: BespokeManufacturingInitialData['items']; revision?: string; error?: string } | null
      if (!response.ok) throw new Error(payload?.error ?? 'Unable to save bespoke manufacturing.')
      if (!Array.isArray(payload?.items) || typeof payload.revision !== 'string') throw new Error('Save response was interrupted. Retry to confirm the same save.')
      setItems(payload.items.map((item) => ({ clientId: `id-${item.id}`, ...item, media_type: item.media_type === 'video' ? 'video' : 'image', media_path: item.media_path ?? item.image_path ?? '', image_path: item.image_path ?? item.media_path ?? '' })))
      setSavedState(JSON.stringify(payload.items.map((item) => ({ id: item.id, step: item.step, eyebrow: item.eyebrow, title: item.title, description: item.description, media_type: item.media_type === 'video' ? 'video' : 'image', media_path: item.media_path ?? item.image_path ?? '', image_path: item.media_type === 'video' ? '' : (item.media_path ?? item.image_path ?? '') }))))
      acceptSave(payload.items, payload.revision)
      setConfirmOpen(false)
      setStatus(resolvedCopy.savedStatus)
      toast({ title: 'Saved', description: resolvedCopy.savedStatus })
    } catch (error) {
      setStatus(error instanceof Error ? error.message : 'Unable to save bespoke manufacturing.')
    } finally { setIsSaving(false) }
  }

  return (
    <div className="min-h-screen bg-background p-8">
      <div className="mb-8 flex items-center justify-between">
        <Link href={resolvedCopy.backHref} onClick={(event) => { event.preventDefault(); unsaved.confirmNavigation(() => router.push(resolvedCopy.backHref)) }} className="inline-flex items-center gap-2 text-sm font-semibold text-primary">
          <ArrowLeft size={16} />
          {resolvedCopy.backLabel}
        </Link>
        <CmsSaveAction onClick={() => setConfirmOpen(true)} isSaving={isSaving} disabled={!dirty || uploading} position="inline" />
      </div>

      <div className="mb-10">
        <h1 className="text-3xl font-semibold">{resolvedCopy.title}</h1>
        <p className="text-sm text-muted-foreground">{resolvedCopy.description}</p>
        <p className="mt-2 text-xs text-muted-foreground">{status}</p>
      </div>

      <div className="overflow-hidden rounded-lg border bg-white">
        <table className="w-full">
          <thead>
            <tr className="border-b bg-secondary/40">
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase">Order</th>
              {!resolvedCopy.hideMetaFields ? <th className="px-5 py-3 text-left text-xs font-semibold uppercase">Step</th> : null}
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase">Title</th>
              <th className="px-5 py-3 text-right text-xs font-semibold uppercase">Actions</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((item) => (
              <tr key={item.clientId} className="border-b">
                <td className="px-5 py-4 text-sm">{item.sort_order}</td>
                {!resolvedCopy.hideMetaFields ? <td className="px-5 py-4 text-sm">{item.step}</td> : null}
                <td className="px-5 py-4 text-sm">{item.title}</td>
                <td className="px-5 py-4 text-right">
                  <div className="inline-flex gap-2">
                    <button onClick={() => { setEditorItem(item); setEditorOpen(true) }} className="rounded-md border px-3 py-2 text-sm"><Edit2 size={14} /></button>
                    <button onClick={() => { setItems((prev) => prev.filter((x) => x.clientId !== item.clientId)); setStatus('Manufacturing step removed locally. Save changes to publish.') }} className="rounded-md border px-3 py-2 text-sm"><Trash2 size={14} /></button>
                  </div>
                </td>
              </tr>
            ))}
            {sorted.length === 0 ? (
              <tr><td colSpan={resolvedCopy.hideMetaFields ? 3 : 4} className="px-5 py-8 text-sm text-muted-foreground">No workshop cards found yet.</td></tr>
            ) : null}
          </tbody>
        </table>
      </div>

      <button onClick={() => { setEditorItem(empty(nextOrder)); setEditorOpen(true) }} className="mt-4 inline-flex items-center gap-2 text-sm font-semibold text-primary">
        <Plus size={16} />
        Add Step
      </button>

      <ConfirmDialog isOpen={confirmOpen} title={resolvedCopy.confirmTitle} description={resolvedCopy.confirmDescription} confirmText="Save" cancelText="Cancel" type="confirm" isLoading={isSaving} onConfirm={saveAll} onCancel={() => setConfirmOpen(false)} />
      <ConfirmDialog isOpen={unsaved.showWarning} title="Discard unsaved Manufacturing changes?" description="Your manufacturing changes have not been saved." confirmText="Discard changes" cancelText="Keep editing" type="warning" onConfirm={unsaved.handleDiscard} onCancel={() => unsaved.setShowWarning(false)} />

      <Dialog open={editorOpen} onOpenChange={setEditorOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit Step</DialogTitle>
            <DialogDescription>Update step number, title, description, and media.</DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            {!resolvedCopy.hideMetaFields ? (
              <div className="grid grid-cols-2 gap-4">
                <input value={editorItem.step} onChange={(e) => setEditorItem((p) => ({ ...p, step: e.target.value }))} placeholder="Step 01" className="w-full rounded-lg border px-3 py-2" />
                <input value={editorItem.eyebrow} onChange={(e) => setEditorItem((p) => ({ ...p, eyebrow: e.target.value }))} placeholder="Eyebrow" className="w-full rounded-lg border px-3 py-2" />
              </div>
            ) : null}
            <input value={editorItem.title} onChange={(e) => setEditorItem((p) => ({ ...p, title: e.target.value }))} placeholder="Title" className="w-full rounded-lg border px-3 py-2" />
            <textarea value={editorItem.description} onChange={(e) => setEditorItem((p) => ({ ...p, description: e.target.value }))} rows={4} placeholder="Description" className="w-full rounded-lg border px-3 py-2" />
            <div>
              <label className="mb-2 block text-sm font-semibold">Media Type</label>
              <select
                value={editorItem.media_type}
                onChange={(e) => setEditorItem((p) => ({ ...p, media_type: e.target.value as 'image' | 'video', media_path: '', image_path: '' }))}
                className="w-full rounded-lg border px-3 py-2"
              >
                <option value="image">Image</option>
                <option value="video">Video URL</option>
              </select>
            </div>
            <div>
              <label className="mb-2 block text-sm font-semibold">{editorItem.media_type === 'video' ? 'Video URL' : 'Image URL or Upload'}</label>
              <input
                value={editorItem.media_path || editorItem.image_path || ''}
                onChange={(e) => setEditorItem((p) => ({ ...p, media_path: e.target.value, image_path: p.media_type === 'image' ? e.target.value : '' }))}
                placeholder={editorItem.media_type === 'video' ? 'https://cdn.example.com/workshop-video.mp4' : 'https://cdn.example.com/workshop-image.jpg'}
                className="mb-3 w-full rounded-lg border px-3 py-2"
              />
              {editorItem.media_type === 'image' ? (
                <div className="flex items-center gap-3">
                  <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border px-4 py-2 text-sm font-semibold">
                    <Plus size={14} />
                    {uploading ? 'Uploading...' : 'Upload Image'}
                    <input type="file" accept="image/*,.svg" className="hidden" disabled={uploading} onChange={(e: ChangeEvent<HTMLInputElement>) => { const file = e.target.files?.[0]; if (file) void uploadImage(file) }} />
                  </label>
                  <span className="text-xs text-muted-foreground">{editorItem.media_path || editorItem.image_path || 'No image uploaded yet'}</span>
                </div>
              ) : (
                <p className="text-xs text-muted-foreground">Paste a direct public video URL. Video upload is disabled for this section.</p>
              )}
            </div>
          </div>
          <DialogFooter>
            <button onClick={() => setEditorOpen(false)} className="rounded-lg border px-4 py-2.5 text-sm">Cancel</button>
            <button onClick={() => { setItems((prev) => { const idx = prev.findIndex((x) => x.clientId === editorItem.clientId); if (idx >= 0) { const copy = [...prev]; copy[idx] = editorItem; return copy } return [...prev, editorItem] }); setStatus('Draft updated locally. Save changes to publish.'); setEditorOpen(false) }} className="rounded-lg bg-primary px-4 py-2.5 text-sm text-white">Update</button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

async function prepareManufacturingImage(file: File) {
  if (file.type === 'image/svg+xml') return file
  if (!['image/jpeg', 'image/png', 'image/webp', 'image/avif'].includes(file.type)) throw new Error('Invalid image type.')
  const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' })
  try {
    const width = Math.min(bitmap.width, 1400)
    const height = Math.max(1, Math.round(bitmap.height * (width / bitmap.width)))
    const canvas = document.createElement('canvas')
    canvas.width = width
    canvas.height = height
    canvas.getContext('2d')?.drawImage(bitmap, 0, 0, width, height)
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/webp', 0.82))
    if (!blob) throw new Error('Unable to optimize image.')
    return new File([blob], `${crypto.randomUUID()}.webp`, { type: 'image/webp' })
  } finally {
    bitmap.close()
  }
}

