'use client'

import { tryUploadAwsImage } from '@/lib/image-transport'
import { cmsFetch } from '@/lib/cms-transport'

import Link from 'next/link'
import { useMemo, useState, type ChangeEvent } from 'react'
import { ArrowDown, ArrowLeft, ArrowUp, Edit2, Plus, Trash2, Upload } from 'lucide-react'
import { CmsSaveAction } from '@/components/cms-save-action'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { useToast } from '@/hooks/use-toast'

type HipHopSection = {
  eyebrow: string
  headline: string
  subtitle: string
  slider_enabled: boolean
}

type SlideItem = {
  clientId: string
  id?: number | string
  sort_order: number
  image_path: string
  mobile_image_path: string
  button_text: string
  button_link: string
}

type ApiPayload = {
  section?: HipHopSection
  items?: Array<{
    id?: number | string
    sort_order: number
    image_path: string
    mobile_image_path?: string
    button_text: string
    button_link: string
  }>
  path?: string
  error?: string
}

export type HipHopInitialData = {
  section: HipHopSection
  items: Array<{
    id?: number | string
    sort_order: number
    image_path: string
    mobile_image_path?: string
    button_text: string
    button_link: string
  }>
}

const emptySlide = (sortOrder: number): SlideItem => ({
  clientId: `draft-${Date.now()}-${sortOrder}`,
  sort_order: sortOrder,
  image_path: '',
  mobile_image_path: '',
  button_text: '',
  button_link: '',
})

export function HipHopEditorClient({ initialData }: { initialData: HipHopInitialData }) {
  const { toast } = useToast()
  const [section, setSection] = useState<HipHopSection>(initialData.section)
  const [slides, setSlides] = useState<SlideItem[]>(
    initialData.items.map((item, index) => ({
      clientId: `slide-${item.id ?? index}`,
      ...item,
      mobile_image_path: item.mobile_image_path ?? '',
    }))
  )
  const [loadStatus, setLoadStatus] = useState('Hip Hop page hero loaded')
  const [uploadState, setUploadState] = useState<'idle' | 'uploading' | 'done' | 'error'>('idle')
  const [isSaving, setIsSaving] = useState(false)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [editorOpen, setEditorOpen] = useState(false)
  const [editorItem, setEditorItem] = useState<SlideItem>(emptySlide(1))

  const sortedSlides = useMemo(
    () => [...slides].sort((a, b) => a.sort_order - b.sort_order || a.clientId.localeCompare(b.clientId)),
    [slides]
  )

  const nextSortOrder = Math.max(...slides.map((item) => item.sort_order), 0) + 1

  const resequenceSlides = (items: SlideItem[]) => items.map((item, index) => ({ ...item, sort_order: index + 1 }))

  const moveSlide = (clientId: string, direction: -1 | 1) => {
    setSlides((prev) => {
      const nextSlides = [...prev].sort((a, b) => a.sort_order - b.sort_order || a.clientId.localeCompare(b.clientId))
      const currentIndex = nextSlides.findIndex((item) => item.clientId === clientId)
      const targetIndex = currentIndex + direction

      if (currentIndex < 0 || targetIndex < 0 || targetIndex >= nextSlides.length) {
        return prev
      }

      ;[nextSlides[currentIndex], nextSlides[targetIndex]] = [nextSlides[targetIndex], nextSlides[currentIndex]]
      return resequenceSlides(nextSlides)
    })
    setLoadStatus('Hip Hop slide order updated. Save changes to publish.')
  }

  const removeSlide = (clientId: string) => {
    setSlides((prev) => resequenceSlides([...prev].sort((a, b) => a.sort_order - b.sort_order || a.clientId.localeCompare(b.clientId)).filter((item) => item.clientId !== clientId)))
    setLoadStatus('Hip Hop slide removed. Save changes to publish.')
  }

  const uploadAsset = async (file: File, field: 'image_path' | 'mobile_image_path') => {

    try {
      const awsPath = await tryUploadAwsImage(file, '/api/cms/uploads/hiphop-hero', {},{start:()=>setUploadState('uploading'),finish:ok=>setUploadState(ok?'done':'error')})
      if (awsPath) { setEditorItem(prev => ({...prev,[field]:awsPath})); setLoadStatus('Image uploaded successfully'); return }
    } catch (error) { setLoadStatus(error instanceof Error ? error.message : 'Upload failed.'); return }


    const { supabase } = await import('@/lib/supabase')
    const { data: sessionData } = await supabase.auth.getSession()
    const accessToken = sessionData.session?.access_token
    if (!accessToken) {
      setLoadStatus('You are not signed in.')
      return
    }

    if (file.size > 5 * 1024 * 1024) {
      setUploadState('error')
      setLoadStatus('File too large. Max size is 5MB.')
      return
    }

    setUploadState('uploading')
    setLoadStatus(field === 'mobile_image_path' ? 'Uploading mobile image...' : 'Uploading desktop image...')

    let uploadedPath = ''
    try {
      const preparedFile = await prepareHipHopHeroImage(file)
      const signResponse = await fetch('/api/cms/uploads/hiphop-hero/sign', {
        method: 'POST',
        headers: {
          authorization: `Bearer ${accessToken}`,
          'content-type': 'application/json',
        },
        body: JSON.stringify({ contentType: preparedFile.type, declaredSize: preparedFile.size }),
      })
      const signed = (await signResponse.json().catch(() => null)) as { bucket?: string; path?: string; token?: string; error?: string } | null
      if (!signResponse.ok || !signed?.bucket || !signed.path || !signed.token) {
        throw new Error(signed?.error ?? 'Unable to prepare upload.')
      }

      const { error } = await supabase.storage.from(signed.bucket)
        .uploadToSignedUrl(signed.path, signed.token, preparedFile, { contentType: preparedFile.type })
      if (error) throw error
      uploadedPath = signed.path
    } catch {
      const fallbackFormData = new FormData()
      fallbackFormData.append('file', file)
      const fallbackResponse = await fetch('/api/cms/uploads/hiphop-hero', {
        method: 'POST',
        headers: { authorization: `Bearer ${accessToken}` },
        body: fallbackFormData,
      })
      const fallbackPayload = (await fallbackResponse.json().catch(() => null)) as ApiPayload | null
      if (!fallbackResponse.ok || !fallbackPayload?.path) {
        setUploadState('error')
        setLoadStatus(fallbackPayload?.error ?? 'Unable to upload image.')
        return
      }
      uploadedPath = fallbackPayload.path
    }

    if (!uploadedPath) {
      setUploadState('error')
      setLoadStatus('Unable to upload image.')
      return
    }

    setEditorItem((prev) => ({ ...prev, [field]: uploadedPath }))
    setUploadState('done')
    setLoadStatus(field === 'mobile_image_path' ? 'Mobile image uploaded successfully' : 'Desktop image uploaded successfully')
    toast({
      title: 'Uploaded',
      description: field === 'mobile_image_path' ? 'Mobile hero image uploaded successfully.' : 'Desktop hero image uploaded successfully.',
    })
  }

  const saveEditor = () => {
    setSlides((prev) => {
      const existingIndex = prev.findIndex((item) => item.clientId === editorItem.clientId)
      if (existingIndex >= 0) {
        const copy = [...prev]
        copy[existingIndex] = editorItem
        return resequenceSlides([...copy].sort((a, b) => a.sort_order - b.sort_order || a.clientId.localeCompare(b.clientId)))
      }

      return resequenceSlides([...prev, editorItem].sort((a, b) => a.sort_order - b.sort_order || a.clientId.localeCompare(b.clientId)))
    })

    setEditorOpen(false)
    setUploadState('idle')
  }

  const handleSave = () => setConfirmOpen(true)

  const confirmSave = async () => {
    setIsSaving(true)





    const response = await cmsFetch('/api/cms/home/hiphop', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',

      },
      body: JSON.stringify({
        ...section,
        items: sortedSlides.map(({ image_path, mobile_image_path, button_text, button_link }, index) => ({
          sort_order: index + 1,
          image_path,
          mobile_image_path,
          button_text,
          button_link,
        })),
      }),
    })

