'use client'

import { tryUploadAwsImage } from '@/lib/image-transport'
import { catalogFetch } from '@/lib/catalog-transport'

import { useState } from 'react'
import { Edit2, Plus, Trash2 } from 'lucide-react'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { useToast } from '@/hooks/use-toast'
import { catalogMasterDeleteBody, catalogMasterSaveBody } from '@/lib/catalog-master-client'

export type CatalogStyleItem = {
  id: string
  _revision?: string
  name: string
  iconSvgPath: string
  displayOrder: number
  status: 'Active' | 'Hidden'
}

async function getAccessToken() {
  const { supabase } = await import('@/lib/supabase')
    const { data } = await supabase.auth.getSession()
  return data.session?.access_token ?? null
}

async function uploadStyleSvg(file: File) {


      const awsPath = await tryUploadAwsImage(file, '/api/catalog/styles/upload', {})
      if (awsPath) { return awsPath }



  const accessToken = await getAccessToken()
  if (!accessToken) {
    throw new Error('You must be signed in to upload SVG files.')
  }

  const payload = new FormData()
  payload.append('file', file)

  const response = await fetch('/api/catalog/styles/upload', {
    method: 'POST',
    headers: { authorization: `Bearer ${accessToken}` },
    body: payload,
  })

  const data = await response.json().catch(() => null)
  if (!response.ok || !data?.path) {
    throw new Error(data?.error ?? 'Unable to upload SVG.')
  }

  return data.path as string
}

function resolveStyleIconUrl(path: string | null | undefined) {
  if (!path) return null
  if (/^https?:\/\//i.test(path)) return path

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
  const collectionBucket = process.env.NEXT_PUBLIC_SUPABASE_COLLECTION_BUCKET || 'hod'
  if (!supabaseUrl) return path

  return `${supabaseUrl}/storage/v1/object/public/${collectionBucket}/${path}`
}

export function StylesClient({ initialItems }: { initialItems: CatalogStyleItem[] }) {
  const { toast } = useToast()
  const [items, setItems] = useState<CatalogStyleItem[]>(initialItems)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [formOpen, setFormOpen] = useState(false)
  const [saveConfirmOpen, setSaveConfirmOpen] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<CatalogStyleItem | null>(null)
  const [saving, setSaving] = useState(false)
  const [loading, setLoading] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    iconSvgPath: '',
    displayOrder: 1,
    status: 'Active' as 'Active' | 'Hidden',
  })

  const loadItems = async () => {
    setLoading(true)
    try {

      const response = await catalogFetch('/api/catalog/styles')
      const payload = await response.json().catch(() => null)
      if (!response.ok || !payload?.items) return

      setItems(
        payload.items.map((item: { id: string; _revision: string; name: string; icon_svg_path?: string | null; display_order: number; status: 'active' | 'hidden' }) => ({
          id: item.id,
          _revision: item._revision,
          name: item.name,
          iconSvgPath: item.icon_svg_path ?? '',
          displayOrder: item.display_order,
          status: item.status === 'hidden' ? 'Hidden' : 'Active',
        }))
      )
    } finally {
      setLoading(false)
    }
  }

  const openNew = () => {
    setEditingId(null)
    setFormData({ name: '', iconSvgPath: '', displayOrder: items.length + 1, status: 'Active' })
    setFormOpen(true)
  }

  const openEdit = (item: CatalogStyleItem) => {
    setEditingId(item.id)
    setFormData({ name: item.name, iconSvgPath: item.iconSvgPath ?? '', displayOrder: item.displayOrder, status: item.status })
    setFormOpen(true)
  }

  const handleSvgUpload = async (file: File) => {
    setUploading(true)
    try {
      const path = await uploadStyleSvg(file)
      setFormData((current) => ({ ...current, iconSvgPath: path }))
      toast({ title: 'SVG uploaded', description: 'Style icon uploaded successfully.' })
    } catch (error) {
      toast({ title: 'Upload failed', description: error instanceof Error ? error.message : 'Unable to upload SVG.' })
    } finally {
      setUploading(false)
    }
  }

  const saveItem = async () => {
    setSaving(true)

    const response = await catalogFetch(editingId ? `/api/catalog/styles/${editingId}` : '/api/catalog/styles', {
      method: editingId ? 'PATCH' : 'POST',
      headers: {
        'content-type': 'application/json',
      },
      body: catalogMasterSaveBody({
        name: formData.name,
        icon_svg_path: formData.iconSvgPath || null,
        display_order: formData.displayOrder,
        status: formData.status === 'Hidden' ? 'hidden' : 'active',
      }, editingId ? items.find((item) => item.id === editingId)?._revision : null),
    })

    if (response.ok) {
      await loadItems()
      setFormOpen(false)
      setEditingId(null)
      setSaveConfirmOpen(false)
      toast({ title: 'Style saved', description: `${formData.name} was updated successfully.` })
    } else {
      const payload = await response.json().catch(() => null)
      toast({ title: 'Save failed', description: payload?.error ?? 'Unable to save style.' })
    }

    setSaving(false)
  }

  const deleteItem = async (id: string) => {

    const revision = items.find((item) => item.id === id)?._revision
    if (!revision) return
    const response = await catalogFetch(`/api/catalog/styles/${id}`, {
      method: 'DELETE',
      headers: { 'content-type': 'application/json' },
      body: catalogMasterDeleteBody(revision),
    })

    if (response.ok) {
      await loadItems()
      setDeleteTarget(null)
      toast({ title: 'Style deleted', description: 'The style was removed successfully.' })
    } else {
      const payload = await response.json().catch(() => null)
      toast({ title: 'Delete failed', description: payload?.error ?? 'Unable to delete style.' })
    }
  }

  return (
    <div className="p-8">
      <div className="mb-10 flex items-start justify-between gap-4">
        <div>
          <h1 className="font-jakarta text-3xl font-semibold text-foreground">Styles</h1>
          <p className="mt-1 text-sm text-muted-foreground">Manage global style values used across products and navbar setup.</p>
        </div>

        <button
          type="button"
          onClick={openNew}
          className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary/90"
        >
          <Plus size={16} />
          Add New Style
        </button>
      </div>

      <div className="rounded-lg border border-border bg-white shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-border bg-secondary/30">
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Name</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Icon</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Display Order</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Status</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Edit</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Delete</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item) => (
                <tr key={item.id} className="border-b border-border hover:bg-secondary/20 transition-colors">
                  <td className="px-6 py-3.5 text-sm font-medium text-foreground">{item.name}</td>
                  <td className="px-6 py-3.5 text-sm text-foreground">
                    {item.iconSvgPath ? (
                      // Native img preserves uploaded SVG behavior for admin-managed runtime URLs.
                      // eslint-disable-next-line @next/next/no-img-element
                      <img src={resolveStyleIconUrl(item.iconSvgPath) ?? item.iconSvgPath} alt={item.name} className="h-8 w-8 object-contain" />
                    ) : (
                      <span className="text-muted-foreground">No icon</span>
                    )}
                  </td>
                  <td className="px-6 py-3.5 text-sm text-foreground">{item.displayOrder}</td>
                  <td className="px-6 py-3.5 text-sm">
                    <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${item.status === 'Active' ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-700'}`}>
                      {item.status}
                    </span>
                  </td>
                  <td className="px-6 py-3.5">
                    <button type="button" onClick={() => openEdit(item)} className="rounded p-1.5 hover:bg-secondary transition-colors">
                      <Edit2 size={14} className="text-muted-foreground" />
                    </button>
                  </td>
                  <td className="px-6 py-3.5">
                    <button type="button" onClick={() => setDeleteTarget(item)} className="rounded p-1.5 hover:bg-red-100 transition-colors">
                      <Trash2 size={14} className="text-red-600" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {loading ? (
        <div className="mt-8 text-sm text-muted-foreground">Updating styles...</div>
      ) : null}

      <Dialog open={formOpen} onOpenChange={setFormOpen}>
        <DialogContent className="sm:max-w-xl">
          <DialogHeader>
            <DialogTitle className="font-jakarta text-lg font-semibold text-foreground">{editingId ? 'Edit Style' : 'Add Style'}</DialogTitle>
            <DialogDescription>Create or update a reusable style value.</DialogDescription>
          </DialogHeader>
          <div className="space-y-5">
            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">Name</label>
              <input
                value={formData.name}
                onChange={(e) => setFormData((prev) => ({ ...prev, name: e.target.value }))}
                className="w-full rounded-lg border border-border bg-white px-4 py-2.5 text-sm"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">Display Order</label>
              <input
                type="number"
                value={formData.displayOrder}
                onChange={(e) => setFormData((prev) => ({ ...prev, displayOrder: Number(e.target.value) || 0 }))}
                className="w-full rounded-lg border border-border bg-white px-4 py-2.5 text-sm"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">SVG Icon</label>
              <div className="space-y-3">
                <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-border px-4 py-2 text-sm font-semibold text-foreground hover:bg-secondary">
                  Upload SVG
                  <input
                    type="file"
                    accept=".svg,image/svg+xml"
                    className="hidden"
                    onChange={(event) => {
                      const file = event.target.files?.[0]
                      if (file) {
                        void handleSvgUpload(file)
                      }
                      event.currentTarget.value = ''
                    }}
                  />
                </label>
                {formData.iconSvgPath ? (
                  <button
                    type="button"
                    onClick={() => setFormData((current) => ({ ...current, iconSvgPath: '' }))}
                    className="rounded-lg border border-red-200 px-4 py-2 text-sm font-semibold text-red-600 hover:bg-red-50"
                  >
                    Remove SVG
                  </button>
                ) : null}
                <p className="text-xs text-muted-foreground">{uploading ? 'Uploading SVG...' : formData.iconSvgPath || 'No SVG uploaded yet'}</p>
                {formData.iconSvgPath ? (
                  // Native img preserves uploaded SVG behavior for admin-managed runtime URLs.
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={resolveStyleIconUrl(formData.iconSvgPath) ?? formData.iconSvgPath} alt="Style icon preview" className="h-12 w-12 object-contain" />
                ) : null}
              </div>
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">Status</label>
              <div className="flex flex-wrap gap-2">
                {(['Active', 'Hidden'] as const).map((status) => (
                  <button
                    key={status}
                    type="button"
                    onClick={() => setFormData((prev) => ({ ...prev, status }))}
                    className={`rounded-full px-4 py-2 text-sm font-semibold ${formData.status === status ? 'bg-primary text-white' : 'border border-border text-foreground hover:bg-secondary'}`}
                  >
                    {status}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex gap-3">
              <button type="button" onClick={() => setSaveConfirmOpen(true)} disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-white hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-60">
                {saving ? 'Saving...' : 'Save'}
              </button>
              <button type="button" onClick={() => setFormOpen(false)} disabled={saving} className="rounded-lg border border-border px-4 py-2 text-sm font-semibold text-foreground hover:bg-secondary disabled:cursor-not-allowed disabled:opacity-60">
                Cancel
              </button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        isOpen={saveConfirmOpen}
        title={editingId ? 'Update style?' : 'Create style?'}
        description="This will save the style changes."
        confirmText="Save"
        isLoading={saving}
        onConfirm={() => void saveItem()}
        onCancel={() => setSaveConfirmOpen(false)}
      />

      <ConfirmDialog
        isOpen={Boolean(deleteTarget)}
        title="Delete style?"
        description={`Are you sure you want to delete "${deleteTarget?.name ?? ''}"?`}
        confirmText="Delete"
        type="delete"
        onConfirm={() => {
          if (!deleteTarget) return
          void deleteItem(deleteTarget.id)
        }}
        onCancel={() => setDeleteTarget(null)}
      />
    </div>
  )
}

'use client'

import { tryUploadAwsImage } from '@/lib/image-transport'
import { cmsFetch } from '@/lib/cms-transport'

import Link from 'next/link'
import { useState, type ChangeEvent } from 'react'
import { ArrowLeft, Edit2, Trash2, Upload } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { CmsSaveAction } from '@/components/cms-save-action'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { useToast } from '@/hooks/use-toast'

type CollectionItem = {
  id: string
  sort_order: number
  label: string
  title: string
  description: string
  image_path: string
  link: string
}

type ApiPayload = {
  items?: CollectionItem[]
  path?: string
  url?: string
  error?: string
}

export type CollectionEditorInitialData = {
  items: CollectionItem[]
}

function createCollectionItem(overrides?: Partial<CollectionItem>): CollectionItem {
  return {
    id: overrides?.id ?? crypto.randomUUID(),
    sort_order: overrides?.sort_order ?? 1,
    label: overrides?.label ?? '',
    title: overrides?.title ?? '',
    description: overrides?.description ?? '',
    image_path: overrides?.image_path ?? '',
    link: overrides?.link ?? '',
  }
}

function normalizeCollectionItems(items: CollectionItem[]) {
  return items
    .slice()
    .sort((left, right) => left.sort_order - right.sort_order || left.title.localeCompare(right.title))
    .map((item, index) => ({
      ...item,
      sort_order: index + 1,
    }))
}

export function CollectionEditorClient({ initialData }: { initialData: CollectionEditorInitialData }) {
  const { toast } = useToast()
  const [items, setItems] = useState<CollectionItem[]>(normalizeCollectionItems(initialData.items.map((item) => createCollectionItem(item))))
  const [loadStatus, setLoadStatus] = useState(initialData.items.length ? 'Collection loaded' : 'No collection items found yet')
  const [uploadState, setUploadState] = useState<'idle' | 'uploading' | 'done' | 'error'>('idle')
  const [isSaving, setIsSaving] = useState(false)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [removeConfirmOpen, setRemoveConfirmOpen] = useState(false)
  const [removeTarget, setRemoveTarget] = useState<CollectionItem | null>(null)
  const [editorOpen, setEditorOpen] = useState(false)
  const [editorItem, setEditorItem] = useState<CollectionItem | null>(null)

  const handleOpenEditor = (item?: CollectionItem) => {
    setEditorItem(item ? { ...item } : createCollectionItem({ sort_order: items.length + 1 }))
    setEditorOpen(true)
  }

  const saveEditor = () => {
    if (!editorItem) return
    setItems((prev) => {
      const nextItems = prev.some((item) => item.id === editorItem.id)
        ? prev.map((item) => (item.id === editorItem.id ? editorItem : item))
        : [...prev, editorItem]
      return normalizeCollectionItems(nextItems)
    })
    setEditorOpen(false)
  }

  const uploadImage = async (file: File) => {

    try {
      const awsPath = await tryUploadAwsImage(file, '/api/cms/uploads/collection', {},{start:()=>setUploadState('uploading'),finish:ok=>setUploadState(ok?'done':'error')})
      if (awsPath) { setEditorItem(prev => prev ? {...prev,image_path:awsPath}:prev); setLoadStatus('Image uploaded successfully'); return }
    } catch (error) { setLoadStatus(error instanceof Error ? error.message : 'Upload failed.'); return }


    const { supabase } = await import('@/lib/supabase')
    const { data: sessionData } = await supabase.auth.getSession()
    const accessToken = sessionData.session?.access_token

    if (!accessToken) {
      setLoadStatus('You are not signed in.')
      return
    }

    if (file.size > 5 * 1024 * 1024) {
      setUploadState('error')
      setLoadStatus('File too large. Max size is 5MB.')
      return
    }

    setUploadState('uploading')
    setLoadStatus('Uploading image...')

    let uploadedPath = ''
    try {
      const preparedFile = await prepareCollectionCardImage(file)
      const signResponse = await fetch('/api/cms/uploads/collection/sign', {
        method: 'POST',
        headers: {
          authorization: `Bearer ${accessToken}`,
          'content-type': 'application/json',
        },
        body: JSON.stringify({ contentType: preparedFile.type, declaredSize: preparedFile.size }),
      })
      const signed = (await signResponse.json().catch(() => null)) as { bucket?: string; path?: string; token?: string; error?: string } | null
      if (!signResponse.ok || !signed?.bucket || !signed.path || !signed.token) {
        throw new Error(signed?.error ?? 'Unable to prepare upload.')
      }

      const { error } = await supabase.storage.from(signed.bucket)
        .uploadToSignedUrl(signed.path, signed.token, preparedFile, { contentType: preparedFile.type })
      if (error) throw error
      uploadedPath = signed.path
    } catch {
      const fallbackFormData = new FormData()
      fallbackFormData.append('file', file)
      const fallbackResponse = await fetch('/api/cms/uploads/collection', {
        method: 'POST',
        headers: { authorization: `Bearer ${accessToken}` },
        body: fallbackFormData,
      })
      const fallbackPayload = (await fallbackResponse.json().catch(() => null)) as ApiPayload | null
      if (!fallbackResponse.ok || !fallbackPayload?.path) {
        setUploadState('error')
        setLoadStatus(fallbackPayload?.error ?? 'Unable to upload image.')
        return
      }
      uploadedPath = fallbackPayload.path
    }

    if (!uploadedPath) {
      setUploadState('error')
      setLoadStatus('Unable to upload image.')
      return
    }

    setEditorItem((prev) => (prev ? { ...prev, image_path: uploadedPath } : prev))
    setUploadState('done')
    setLoadStatus('Image uploaded successfully')
    toast({
      title: 'Uploaded',
      description: 'Collection image uploaded successfully.',
    })
  }

  const handleSave = () => setConfirmOpen(true)

  const handleRemoveRequest = (item: CollectionItem) => {
    setRemoveTarget(item)
    setRemoveConfirmOpen(true)
  }

  const confirmRemove = () => {
    if (!removeTarget) return
    setItems((prev) => normalizeCollectionItems(prev.filter((item) => item.id !== removeTarget.id)))
    setLoadStatus('Collection item removed. Save changes to publish.')
    setRemoveTarget(null)
    setRemoveConfirmOpen(false)
    toast({
      title: 'Removed',
      description: 'Collection item removed from this draft. Save changes to publish.',
    })
  }

  const confirmSave = async () => {
    setIsSaving(true)





    const response = await cmsFetch('/api/cms/home/collection', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',

      },
      body: JSON.stringify({
        items: items.map((collectionItem) => ({
          sort_order: collectionItem.sort_order,
          label: collectionItem.label,
          title: collectionItem.title,
          description: collectionItem.description,
          image_path: collectionItem.image_path,
          link: collectionItem.link,
        })),
      }),
    })

    const payload = (await response.json().catch(() => null)) as ApiPayload | null
    setIsSaving(false)

    if (!response.ok) {
      setLoadStatus(payload?.error ?? 'Unable to save Collection.')
      return
    }

    if (payload?.items) {
      setItems(normalizeCollectionItems(payload.items.map((item) => createCollectionItem(item))))
    }

    setConfirmOpen(false)
    setLoadStatus('Collection saved')
    toast({ title: 'Saved', description: 'Collection updated successfully.' })
  }

  return (
    <div className="p-8">
      <div className="mb-8 flex items-center gap-4">
        <Link href="/dashboard/cms/home" className="inline-flex items-center gap-2 text-sm font-semibold text-primary hover:text-primary/80">
          <ArrowLeft size={16} />
          Back to Home
        </Link>
      </div>

      <div className="mb-10">
        <h1 className="font-jakarta text-3xl font-semibold text-foreground">Collection</h1>
        <p className="mt-1 text-sm text-muted-foreground">Edit collection cards, images, and links</p>
        <p className="mt-2 text-xs text-muted-foreground">{loadStatus}</p>
      </div>

      <div className="mb-6 flex justify-end">
        <button
          onClick={() => handleOpenEditor()}
          className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary/90"
        >
          <Edit2 size={16} />
          Add Collection
        </button>
      </div>

      <div className="overflow-hidden rounded-lg border border-border bg-white shadow-xs">
        <table className="w-full">
          <thead>
            <tr className="border-b border-border bg-secondary/40">
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-foreground">Order</th>
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-foreground">Label</th>
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-foreground">Title</th>
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-foreground">Image</th>
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-foreground">Link</th>
              <th className="px-5 py-3 text-right text-xs font-semibold uppercase tracking-wider text-foreground">Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((item) => (
              <tr key={item.id} className="border-b border-border last:border-b-0">
                <td className="px-5 py-4 text-sm">{item.sort_order}</td>
                <td className="px-5 py-4 text-sm">{item.label}</td>
                <td className="px-5 py-4 text-sm">{item.title}</td>
                <td className="px-5 py-4 text-sm">{item.image_path}</td>
                <td className="px-5 py-4 text-sm">{item.link}</td>
                <td className="px-5 py-4 text-right">
                  <div className="inline-flex items-center gap-2">
                  <button
                    onClick={() => handleOpenEditor(item)}
                    className="inline-flex items-center gap-2 rounded-md border border-border px-3 py-2 text-sm font-medium text-foreground hover:bg-secondary"
                  >
                    <Edit2 size={14} />
                    Edit
                  </button>
                    <button
                      onClick={() => handleRemoveRequest(item)}
                      className="inline-flex items-center gap-2 rounded-md border border-red-200 px-3 py-2 text-sm font-medium text-red-600 hover:bg-red-50"
                    >
                      <Trash2 size={14} />
                      Remove
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <CmsSaveAction onClick={handleSave} isSaving={isSaving} />

      <ConfirmDialog
        isOpen={confirmOpen}
        title="Save Collection?"
        description="This will update the collection cards on the homepage."
        confirmText="Save"
        cancelText="Cancel"
        type="confirm"
        isLoading={isSaving}
        onConfirm={confirmSave}
        onCancel={() => setConfirmOpen(false)}
      />

      <ConfirmDialog
        isOpen={removeConfirmOpen}
        title="Remove Collection Item?"
        description={`This will remove "${removeTarget?.title || removeTarget?.label || 'this item'}" from the collection list. Uploaded images will not be deleted.`}
        confirmText="Remove"
        cancelText="Cancel"
        type="delete"
        onConfirm={confirmRemove}
        onCancel={() => {
          setRemoveTarget(null)
          setRemoveConfirmOpen(false)
        }}
      />

      <Dialog open={editorOpen} onOpenChange={setEditorOpen}>
        <DialogContent className="sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>Edit Collection</DialogTitle>
            <DialogDescription>Update label, title, description, image, and link.</DialogDescription>
          </DialogHeader>

          {editorItem && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                <div>
                  <label className="mb-2 block text-sm font-semibold text-foreground">Order</label>
                  <input
                    type="number"
                    value={editorItem.sort_order}
                    onChange={(e) =>
                      setEditorItem((prev) => (prev ? { ...prev, sort_order: Number(e.target.value) } : prev))
                    }
                    className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-semibold text-foreground">Label</label>
                  <input
                    type="text"
                    value={editorItem.label}
                    onChange={(e) =>
                      setEditorItem((prev) => (prev ? { ...prev, label: e.target.value } : prev))
                    }
                    className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm"
                  />
                </div>
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-foreground">Title</label>
                <input
                  type="text"
                  value={editorItem.title}
                  onChange={(e) =>
                    setEditorItem((prev) => (prev ? { ...prev, title: e.target.value } : prev))
                  }
                  className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-foreground">Description</label>
                <textarea
                  value={editorItem.description}
                  onChange={(e) =>
                    setEditorItem((prev) => (prev ? { ...prev, description: e.target.value } : prev))
                  }
                  rows={4}
                  className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-foreground">Image</label>
                <div className="flex items-center gap-3">
                  <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-border px-4 py-2 text-sm font-semibold text-foreground hover:bg-secondary">
                    <Upload size={14} />
                    {uploadState === 'uploading' ? 'Uploading...' : 'Upload Image'}
                    <input
                      type="file"
                      accept="image/*"
                      className="hidden"
                      disabled={uploadState === 'uploading'}
                      onChange={(e: ChangeEvent<HTMLInputElement>) => {
                        const file = e.target.files?.[0]
                        if (file) void uploadImage(file)
                      }}
                    />
                  </label>
                  <span className="text-xs text-muted-foreground">{editorItem.image_path || 'No image uploaded yet'}</span>
                </div>
                <div className="mt-3 overflow-hidden rounded-md border border-border bg-secondary/30">
                  <div
                    className={`h-1.5 transition-all ${
                      uploadState === 'uploading'
                        ? 'w-2/3 animate-pulse bg-primary'
                        : uploadState === 'done'
                          ? 'w-full bg-emerald-500'
                          : uploadState === 'error'
                            ? 'w-full bg-red-500'
                            : 'w-0 bg-primary'
                    }`}
                  />
                </div>
                <p className="mt-2 text-xs text-muted-foreground">
                  {uploadState === 'uploading'
                    ? 'Uploading and validating image...'
                    : uploadState === 'done'
                      ? 'Upload complete. You can now save the item.'
                      : uploadState === 'error'
                        ? 'Upload failed. Please try another image.'
                        : 'Choose a JPG, PNG, WebP, or AVIF image up to 5MB.'}
                </p>
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-foreground">Link</label>
                <input
                  type="text"
                  value={editorItem.link}
                  onChange={(e) =>
                    setEditorItem((prev) => (prev ? { ...prev, link: e.target.value } : prev))
                  }
                  className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm"
                />
              </div>
            </div>
          )}

          <DialogFooter>
            <button
              onClick={() => setEditorOpen(false)}
              className="rounded-lg border border-border px-4 py-2.5 text-sm font-semibold text-foreground hover:bg-secondary"
            >
              Cancel
            </button>
            <button
              onClick={saveEditor}
              className="rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary/90"
            >
              Update Item
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

async function prepareCollectionCardImage(file: File) {
  if (file.type === 'image/svg+xml') return file
  if (!['image/jpeg', 'image/png', 'image/webp', 'image/avif'].includes(file.type)) {
    throw new Error('Invalid image type.')
  }

  const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' })
  try {
    const width = Math.min(bitmap.width, 1600)
    const height = Math.max(1, Math.round(bitmap.height * (width / bitmap.width)))
    const canvas = document.createElement('canvas')
    canvas.width = width
    canvas.height = height
    canvas.getContext('2d')?.drawImage(bitmap, 0, 0, width, height)
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/webp', 0.82))
    if (!blob) throw new Error('Unable to optimize image.')
    return new File([blob], `${crypto.randomUUID()}.webp`, { type: 'image/webp' })
  } finally {
    bitmap.close()
  }
}

import { catalogPageReader } from '@/lib/catalog-page-data'
import { loadCatalogMasterList, type CatalogMasterRow } from '@/lib/catalog-master-save'
import { StylesClient, type CatalogStyleItem } from './styles-client'

async function getStyles(): Promise<CatalogStyleItem[]> {
  const adminClient = await catalogPageReader()
  const data = await loadCatalogMasterList(adminClient, 'style')
  const rows = data as Array<CatalogMasterRow & { name: string; icon_svg_path?: string | null; display_order: number; status: string }>
  return rows.map((item) => ({
    id: item.id,
    _revision: item._revision,
    name: item.name,
    iconSvgPath: item.icon_svg_path ?? '',
    displayOrder: item.display_order,
    status: item.status === 'hidden' ? 'Hidden' : 'Active',
  }))
}

export default async function StylesPage() {
  const initialItems = await getStyles()
  return <StylesClient initialItems={initialItems} />
}

