'use client'

import { tryUploadAwsImage } from '@/lib/image-transport'
import { catalogFetch } from '@/lib/catalog-transport'

import { useState } from 'react'
import { Edit2, Plus, Trash2 } from 'lucide-react'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { useToast } from '@/hooks/use-toast'
import { slugify } from '@/lib/product-catalog'
import { catalogMasterDeleteBody, catalogMasterSaveBody } from '@/lib/catalog-master-client'

export type StoneShape = {
  id: string
  _revision?: string
  name: string
  slug: string
  svgName: string | null
  displayOrder: number
  status: 'Active' | 'Hidden'
}

async function getAccessToken() {
  const { supabase } = await import('@/lib/supabase')
    const { data } = await supabase.auth.getSession()
  return data.session?.access_token ?? null
}

export function StoneShapesClient({ initialShapes }: { initialShapes: StoneShape[] }) {
  const { toast } = useToast()
  const [shapes, setShapes] = useState<StoneShape[]>(initialShapes)
  const [isFormOpen, setIsFormOpen] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [saveConfirmOpen, setSaveConfirmOpen] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<StoneShape | null>(null)
  const [saving, setSaving] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [loading, setLoading] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    slug: '',
    svgName: '' as string | null,
    displayOrder: 1,
    status: 'Active' as 'Active' | 'Hidden',
  })

  const loadShapes = async () => {
    setLoading(true)
    try {

      const response = await catalogFetch('/api/catalog/stone-shapes')
      const payload = await response.json().catch(() => null)
      if (!response.ok || !payload?.items) return

      setShapes(
        payload.items.map((item: { id: string; _revision: string; name: string; slug: string; svg_asset_url: string | null; display_order: number; status: 'active' | 'hidden' }) => ({
          id: item.id,
          _revision: item._revision,
          name: item.name,
          slug: item.slug,
          svgName: item.svg_asset_url,
          displayOrder: item.display_order,
          status: item.status === 'hidden' ? 'Hidden' : 'Active',
        }))
      )
    } finally {
      setLoading(false)
    }
  }

  const openNew = () => {
    setEditingId(null)
    setFormData({ name: '', slug: '', svgName: '', displayOrder: shapes.length + 1, status: 'Active' })
    setIsFormOpen(true)
  }

  const openEdit = (shape: StoneShape) => {
    setEditingId(shape.id)
    setFormData({
      name: shape.name,
      slug: shape.slug,
      svgName: shape.svgName,
      displayOrder: shape.displayOrder,
      status: shape.status,
    })
    setIsFormOpen(true)
  }

  const saveShape = async () => {
    setSaving(true)

    const response = await catalogFetch(editingId ? `/api/catalog/stone-shapes/${editingId}` : '/api/catalog/stone-shapes', {
      method: editingId ? 'PATCH' : 'POST',
      headers: {
        'content-type': 'application/json',
      },
      body: catalogMasterSaveBody({
        name: formData.name,
        slug: formData.slug,
        svg_asset_url: formData.svgName || null,
        display_order: formData.displayOrder,
        status: formData.status === 'Hidden' ? 'hidden' : 'active',
      }, editingId ? shapes.find((shape) => shape.id === editingId)?._revision : null),
    })

    if (response.ok) {
      await loadShapes()
      setIsFormOpen(false)
      setEditingId(null)
      setSaveConfirmOpen(false)
      toast({ title: 'Stone shape saved', description: `${formData.name} was updated successfully.` })
    } else {
      const payload = await response.json().catch(() => null)
      toast({ title: 'Save failed', description: payload?.error ?? 'Unable to save stone shape.' })
    }

    setSaving(false)
  }

  const deleteShape = async (id: string) => {

    const revision = shapes.find((shape) => shape.id === id)?._revision
    if (!revision) return
    const response = await catalogFetch(`/api/catalog/stone-shapes/${id}`, {
      method: 'DELETE',
      headers: { 'content-type': 'application/json' },
      body: catalogMasterDeleteBody(revision),
    })

    if (response.ok) {
      await loadShapes()
      setDeleteTarget(null)
      toast({ title: 'Stone shape deleted', description: 'The stone shape was removed successfully.' })
    } else {
      const payload = await response.json().catch(() => null)
      toast({ title: 'Delete failed', description: payload?.error ?? 'Unable to delete stone shape.' })
    }
  }

  const uploadSvg = async (file: File) => {

    try {
      const awsPath = await tryUploadAwsImage(file, '/api/catalog/stone-shapes/upload', {},{start:()=>setUploading(true),finish:()=>setUploading(false)})
      if (awsPath) { setFormData(prev => ({...prev, svgName: awsPath})); return }
    } catch (error) { toast({title:'Upload failed',description:error instanceof Error ? error.message : 'Upload failed.'}); return }


    setUploading(true)
    const accessToken = await getAccessToken()
    if (!accessToken) {
      setUploading(false)
      return
    }

    const uploadData = new FormData()
    uploadData.append('file', file)

    const response = await fetch('/api/catalog/stone-shapes/upload', {
      method: 'POST',
      headers: { authorization: `Bearer ${accessToken}` },
      body: uploadData,
    })

    const payload = await response.json().catch(() => null)
    if (response.ok && payload?.path) {
      setFormData((prev) => ({ ...prev, svgName: payload.path }))
      toast({ title: 'SVG uploaded', description: 'Stone shape SVG uploaded successfully.' })
    } else {
      toast({ title: 'Upload failed', description: payload?.error ?? 'Unable to upload SVG.' })
    }

    setUploading(false)
  }

  return (
    <div className="p-8">
      <div className="mb-10 flex items-start justify-between gap-4">
        <div>
          <h1 className="font-jakarta text-3xl font-semibold text-foreground">Stone Shapes</h1>
          <p className="mt-1 text-sm text-muted-foreground">Manage the shape options shown in ring and stone selectors.</p>
        </div>

        <button
          type="button"
          onClick={openNew}
          className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary/90"
        >
          <Plus size={16} />
          Add New Shape
        </button>
      </div>

      <div className="rounded-lg border border-border bg-white shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-border bg-secondary/30">
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Name</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Slug</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">SVG</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Display Order</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Status</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Edit</th>
                <th className="px-6 py-3.5 text-left text-xs font-semibold text-foreground">Delete</th>
              </tr>
            </thead>
            <tbody>
              {shapes.map((shape) => (
                <tr key={shape.id} className="border-b border-border hover:bg-secondary/20 transition-colors">
                  <td className="px-6 py-3.5 text-sm font-medium text-foreground">{shape.name}</td>
                  <td className="px-6 py-3.5 text-sm text-muted-foreground">{shape.slug}</td>
                  <td className="px-6 py-3.5 text-sm text-muted-foreground">{shape.svgName || 'No SVG selected'}</td>
                  <td className="px-6 py-3.5 text-sm text-foreground">{shape.displayOrder}</td>
                  <td className="px-6 py-3.5 text-sm">
                    <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${shape.status === 'Active' ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-700'}`}>
                      {shape.status}
                    </span>
                  </td>
                  <td className="px-6 py-3.5">
                    <button type="button" onClick={() => openEdit(shape)} className="rounded p-1.5 hover:bg-secondary transition-colors">
                      <Edit2 size={14} className="text-muted-foreground" />
                    </button>
                  </td>
                  <td className="px-6 py-3.5">
                    <button
                      type="button"
                      onClick={() => setDeleteTarget(shape)}
                      className="rounded p-1.5 hover:bg-red-100 transition-colors"
                    >
                      <Trash2 size={14} className="text-red-600" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {loading ? (
        <div className="mt-8 text-sm text-muted-foreground">Updating stone shapes...</div>
      ) : null}

      <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
        <DialogContent className="max-h-[85vh] overflow-y-auto sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle className="font-jakarta text-lg font-semibold text-foreground">{editingId ? 'Edit Stone Shape' : 'Add Stone Shape'}</DialogTitle>
            <DialogDescription>Manage the stone shape record and upload its SVG icon.</DialogDescription>
          </DialogHeader>
          <div className="space-y-5">
            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">Name</label>
              <input
                value={formData.name}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    name: e.target.value,
                    slug: prev.slug === '' || prev.slug === slugify(prev.name) ? slugify(e.target.value) : prev.slug,
                  }))
                }
                className="w-full rounded-lg border border-border bg-white px-4 py-2.5 text-sm"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">Slug</label>
              <input
                value={formData.slug}
                onChange={(e) => setFormData((prev) => ({ ...prev, slug: e.target.value }))}
                className="w-full rounded-lg border border-border bg-white px-4 py-2.5 text-sm"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">SVG Image</label>
              <div className="rounded-lg border-2 border-dashed border-border p-4 text-sm text-muted-foreground">
                <p>Upload SVG</p>
                <p className="mt-1 text-xs">Uploads to the `catalog/stone-shapes/` folder in your storage bucket.</p>
                <input
                  type="file"
                  accept=".svg,image/svg+xml"
                  disabled={uploading}
                  onChange={(e) => {
                    const file = e.target.files?.[0]
                    if (file) void uploadSvg(file)
                  }}
                  className="mt-3 block w-full text-sm"
                />
                {uploading ? <p className="mt-2 text-xs font-medium text-foreground">Uploading SVG...</p> : null}
              </div>
              {formData.svgName && <p className="mt-2 text-xs text-muted-foreground">Selected: {formData.svgName}</p>}
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">Display Order</label>
              <input
                type="number"
                value={formData.displayOrder}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    displayOrder: Number(e.target.value) || 0,
                  }))
                }
                className="w-full rounded-lg border border-border bg-white px-4 py-2.5 text-sm"
              />
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium text-foreground">Status</label>
              <div className="flex flex-wrap gap-2">
                {(['Active', 'Hidden'] as const).map((status) => (
                  <button
                    key={status}
                    type="button"
                    onClick={() => setFormData((prev) => ({ ...prev, status }))}
                    className={`rounded-full px-4 py-2 text-sm font-semibold ${formData.status === status ? 'bg-primary text-white' : 'border border-border text-foreground hover:bg-secondary'}`}
                  >
                    {status}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex gap-3">
              <button type="button" onClick={() => setSaveConfirmOpen(true)} disabled={saving || uploading} className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-white hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-60">
                {saving ? 'Saving...' : 'Save'}
              </button>
              <button type="button" onClick={() => setIsFormOpen(false)} disabled={saving || uploading} className="rounded-lg border border-border px-4 py-2 text-sm font-semibold text-foreground hover:bg-secondary disabled:cursor-not-allowed disabled:opacity-60">
                Cancel
              </button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      <ConfirmDialog
        isOpen={saveConfirmOpen}
        title={editingId ? 'Update stone shape?' : 'Create stone shape?'}
        description="This will save the stone shape changes."
        confirmText="Save"
        isLoading={saving}
        onConfirm={() => void saveShape()}
        onCancel={() => setSaveConfirmOpen(false)}
      />
      <ConfirmDialog
        isOpen={Boolean(deleteTarget)}
        title="Delete stone shape?"
        description={`Are you sure you want to delete "${deleteTarget?.name ?? ''}"?`}
        confirmText="Delete"
        type="delete"
        onConfirm={() => {
          if (!deleteTarget) return
          void deleteShape(deleteTarget.id)
        }}
        onCancel={() => setDeleteTarget(null)}
      />
    </div>
  )
}

'use client'

import { cmsFetch } from '@/lib/cms-transport'

import Link from 'next/link'
import { useRef, useState, type ChangeEvent } from 'react'
import { ArrowLeft, Edit2, Plus, Trash2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { CmsSaveAction } from '@/components/cms-save-action'
import { useToast } from '@/hooks/use-toast'
import { uploadCmsAssetDirectWithFallback } from '@/lib/cms-direct-upload-client'

type CertificationItem = {
  clientId: string
  id?: number | string
  sort_order: number
  title: string
  description: string
  badge: string
  icon_path: string
}

type ApiPayload = {
  section?: {
    eyebrow: string
    heading: string
  }
  items?: Array<{
    id?: number | string
    sort_order: number
    title: string
    description: string
    badge: string
    icon_path: string
  }>
  error?: string
}

export type CertificationsInitialData = {
  revision: string
  section: {
    eyebrow: string
    heading: string
  }
  items: Array<{
    id?: number | string
    sort_order: number
    title: string
    description: string
    badge: string
    icon_path: string
  }>
}

const emptyItem = (sortOrder: number): CertificationItem => ({
  clientId: `draft-${Date.now()}-${sortOrder}`,
  sort_order: sortOrder,
  title: '',
  description: '',
  badge: '',
  icon_path: '',
})

export function CertificationsEditorClient({ initialData }: { initialData: CertificationsInitialData }) {
  const { toast } = useToast()
  const [items, setItems] = useState<CertificationItem[]>(
    initialData.items.map((item) => ({
      clientId: `id-${item.id ?? item.sort_order}`,
      ...item,
      title: item.title || item.description || '',
      description: item.description || '',
      badge: item.badge || '',
    }))
  )
  const [loadStatus, setLoadStatus] = useState(initialData.items.length ? 'Why Choose items loaded' : 'No Why Choose rows found yet')
  const [isSaving, setIsSaving] = useState(false)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [editorOpen, setEditorOpen] = useState(false)
  const [editorItem, setEditorItem] = useState<CertificationItem | null>(null)
  const [revision, setRevision] = useState(initialData.revision)
  const [savedItemIds, setSavedItemIds] = useState(() => initialData.items.flatMap((item) => item.id ? [String(item.id)] : []))
  const pendingSave = useRef<{ fingerprint: string; id: string } | null>(null)

  const openEditor = (item?: CertificationItem) => {
    setEditorItem(item ?? emptyItem(items.length + 1))
    setEditorOpen(true)
  }

  const uploadIcon = async (file: File) => {




    try {
      const path = await uploadCmsAssetDirectWithFallback({
        file, accessToken: undefined,
        signEndpoint: '/api/cms/uploads/certifications/sign',
        fallbackEndpoint: '/api/cms/uploads/certifications',
        maxInputBytes: 5 * 1024 * 1024, rasterWidth: 800, webpQuality: 82,
      })
      setEditorItem((prev) => (prev ? { ...prev, icon_path: path } : prev))
    } catch (error) {
      setLoadStatus(error instanceof Error ? error.message : 'Unable to upload icon.')
      return
    }
    setLoadStatus('Icon uploaded')
    toast({ title: 'Uploaded', description: 'Why Choose icon uploaded successfully.' })
  }

  const handleSaveEditor = () => {
    if (!editorItem) return
    setItems((prev) => {
      const exists = prev.some((item) => item.clientId === editorItem.clientId)
      const normalized = {
        ...editorItem,
        description: '',
        badge: '',
      }
      return exists ? prev.map((item) => (item.clientId === editorItem.clientId ? normalized : item)) : [...prev, normalized]
    })
    setEditorOpen(false)
  }

  const handleSave = () => setConfirmOpen(true)

  const confirmSave = async () => {
    setIsSaving(true)
    setConfirmOpen(false)





    const retainedIds = new Set(items.flatMap((item) => item.id ? [String(item.id)] : []))
    const saveBody = {
      expected_revision: revision,
      deleted_ids: savedItemIds.filter((id) => !retainedIds.has(id)),
      section: { eyebrow: 'Our Promise', heading: 'Why Choose House of Diams' },
      items: items.map(({ id, title, icon_path }) => ({ ...(id ? { id } : {}), title, description: '', badge: '', icon_path })),
    }
    const fingerprint = JSON.stringify(saveBody)
    if (pendingSave.current?.fingerprint !== fingerprint) pendingSave.current = { fingerprint, id: crypto.randomUUID() }
    const response = await cmsFetch('/api/cms/home/certifications', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',

      },
      body: JSON.stringify({ ...saveBody, request_id: pendingSave.current.id }),
    })

    const payload = (await response.json().catch(() => null)) as ApiPayload | null
    setIsSaving(false)

    if (!response.ok) {
      setLoadStatus(payload?.error ?? 'Unable to save Why Choose content.')
      return
    }

    if (Array.isArray(payload?.items) && typeof (payload as { revision?: unknown }).revision === 'string') {
      const saved = payload.items.map((item, index) => ({ clientId: `id-${item.id}`, ...item, sort_order: index + 1 }))
      setItems(saved)
      setSavedItemIds(saved.map((item) => String(item.id)))
      setRevision((payload as { revision: string }).revision)
      pendingSave.current = null
    }

    setLoadStatus('Why Choose section saved')
    toast({ title: 'Saved', description: 'Why Choose House of Diams updated successfully.' })
  }

  return (
    <div className="p-8">
      <div className="mb-8 flex items-center gap-4">
        <Link href="/dashboard/cms/home" className="inline-flex items-center gap-2 text-sm font-semibold text-primary hover:text-primary/80">
          <ArrowLeft size={16} />
          Back to Home
        </Link>
      </div>

      <div className="mb-10">
        <h1 className="font-jakarta text-3xl font-semibold text-foreground">Why Choose House of Diams</h1>
        <p className="mt-1 text-sm text-muted-foreground">Keep this section simple: each card only needs an icon and one line of text.</p>
        <p className="mt-2 text-xs text-muted-foreground">{loadStatus}</p>
      </div>

      <div className="mb-6 mt-6 flex justify-end">
        <button onClick={() => openEditor()} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary/90">
          <Plus size={16} />
          Add Item
        </button>
      </div>

      <div className="overflow-hidden rounded-lg border border-border bg-white shadow-xs">
        <table className="w-full">
          <thead>
            <tr className="border-b border-border bg-secondary/40">
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-foreground">Order</th>
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-foreground">Text</th>
              <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wider text-foreground">Icon</th>
              <th className="px-5 py-3 text-right text-xs font-semibold uppercase tracking-wider text-foreground">Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((item) => (
              <tr key={item.clientId} className="border-b border-border last:border-b-0">
                <td className="px-5 py-4 text-sm">{item.sort_order}</td>
                <td className="px-5 py-4 text-sm">{item.title}</td>
                <td className="px-5 py-4 text-sm">{item.icon_path || 'No icon yet'}</td>
                <td className="px-5 py-4 text-right">
                  <div className="inline-flex items-center gap-2">
                    <button onClick={() => openEditor(item)} className="inline-flex items-center gap-2 rounded-md border border-border px-3 py-2 text-sm font-medium text-foreground hover:bg-secondary">
                      <Edit2 size={14} />
                      Edit
                    </button>
                    <button
                      onClick={() => setItems((prev) => prev.filter((x) => x.clientId !== item.clientId))}
                      className="inline-flex items-center gap-2 rounded-md border border-border px-3 py-2 text-sm font-medium text-foreground hover:bg-secondary"
                    >
                      <Trash2 size={14} />
                      Delete
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <CmsSaveAction onClick={handleSave} isSaving={isSaving} />

      <ConfirmDialog
        isOpen={confirmOpen}
        title="Save Why Choose section?"
        description="This will update the Why Choose House of Diams section on the homepage."
        confirmText="Save"
        cancelText="Cancel"
        type="confirm"
        isLoading={isSaving}
        onConfirm={confirmSave}
        onCancel={() => setConfirmOpen(false)}
      />

      <Dialog open={editorOpen} onOpenChange={setEditorOpen}>
        <DialogContent className="sm:max-w-xl">
          <DialogHeader>
            <DialogTitle>Edit Why Choose Item</DialogTitle>
            <DialogDescription>Only icon and text are needed here.</DialogDescription>
          </DialogHeader>

          {editorItem && (
            <div className="space-y-4">
              <div>
                <label className="mb-2 block text-sm font-semibold text-foreground">Order</label>
                <input
                  type="number"
                  value={editorItem.sort_order}
                  onChange={(e: ChangeEvent<HTMLInputElement>) =>
                    setEditorItem((prev) => (prev ? { ...prev, sort_order: Number(e.target.value) } : prev))
                  }
                  className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-foreground">Text</label>
                <textarea
                  value={editorItem.title}
                  onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
                    setEditorItem((prev) => (prev ? { ...prev, title: e.target.value } : prev))
                  }
                  rows={3}
                  className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-semibold text-foreground">Icon</label>
                <div className="flex items-center gap-3">
                  <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-border px-4 py-2 text-sm font-semibold text-foreground hover:bg-secondary">
                    <Plus size={14} />
                    Upload Icon
                    <input
                      type="file"
                      accept="image/*,.svg"
                      className="hidden"
                      onChange={(e: ChangeEvent<HTMLInputElement>) => {
                        const file = e.target.files?.[0]
                        if (file) void uploadIcon(file)
                      }}
                    />
                  </label>
                  <span className="text-xs text-muted-foreground">{editorItem.icon_path || 'No icon uploaded yet'}</span>
                </div>
              </div>
            </div>
          )}

          <DialogFooter>
            <button
              onClick={() => setEditorOpen(false)}
              className="rounded-lg border border-border px-4 py-2.5 text-sm font-semibold text-foreground hover:bg-secondary"
            >
              Cancel
            </button>
            <button
              onClick={handleSaveEditor}
              className="rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary/90"
            >
              Update Item
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import { catalogPageReader } from '@/lib/catalog-page-data'
import { loadCatalogMasterList, type CatalogMasterRow } from '@/lib/catalog-master-save'
import { StoneShapesClient, type StoneShape } from './stone-shapes-client'

async function getStoneShapes(): Promise<StoneShape[]> {
  const adminClient = await catalogPageReader()
  const data = await loadCatalogMasterList(adminClient, 'stone_shape')
  const rows = data as Array<CatalogMasterRow & { name: string; slug: string; svg_asset_url: string; display_order: number; status: string }>
  return rows.map((item) => ({
    id: item.id,
    _revision: item._revision,
    name: item.name,
    slug: item.slug,
    svgName: item.svg_asset_url,
    displayOrder: item.display_order,
    status: item.status === 'hidden' ? 'Hidden' : 'Active',
  }))
}

export default async function StoneShapesPage() {
  const initialShapes = await getStoneShapes()
  return <StoneShapesClient initialShapes={initialShapes} />
}

import { cmsPageReader } from '@/lib/cms-page-data'
import { readCmsReference } from '@/lib/cms-reference-data'

import { formatCategoryPath } from '@/lib/product-catalog'
import type {
  CatalogCategory,
  CatalogOption,
  CatalogSubcategory,
  ProductRecord,
} from '@/lib/product-catalog'
import { HomeBestSellersEditorClient, type HomeBestSellersInitialData, type ProductListItem } from './home-bestsellers-editor-client'
import { loadHomeGroup1Snapshot } from '@/lib/cms-home-group1-save'

async function getBestSellersInitialData(): Promise<HomeBestSellersInitialData> {
  const adminClient = await cmsPageReader()

  const [snapshot, { data: products, error: productsError }, { data: categories }, { data: subcategories }, { data: options }] = await Promise.all([
    loadHomeGroup1Snapshot(adminClient, 'bestsellers'),
    readCmsReference(adminClient, 'products'),
    readCmsReference(adminClient, 'categories'),
    readCmsReference(adminClient, 'subcategories'),
    readCmsReference(adminClient, 'options'),
  ])

  if (productsError) {
    throw new Error(productsError.message)
  }

  const section = snapshot.section
  const sectionLinks = snapshot.items
  const categoryRows = (categories ?? []) as CatalogCategory[]
  const subcategoryRows = (subcategories ?? []) as CatalogSubcategory[]
  const optionRows = (options ?? []) as CatalogOption[]

  const productRows = ((products ?? []) as ProductRecord[]).map((product) => {
    const category = categoryRows.find((item) => item.id === product.main_category_id)
    const subcategory = subcategoryRows.find((item) => item.id === product.subcategory_id)
    const option = optionRows.find((item) => item.id === product.option_id)

    return {
      id: product.id,
      name: product.name,
      slug: product.slug,
      categoryPath: formatCategoryPath({ category, subcategory, option }),
      detailTemplate: product.detail_template ?? 'standard',
      status: product.status,
    } as ProductListItem
  })

  return {
    section: {
      eyebrow: String(section?.eyebrow ?? 'House of Diams'),
      heading: String(section?.heading ?? 'Our Best Sellers'),
      cta_label: String(section?.cta_label ?? 'View All Collection'),
      cta_href: String(section?.cta_href ?? '/shop'),
      selected_product_ids: sectionLinks.map((item) => String(item.product_id)),
      selected_products: sectionLinks.map((item) => ({
        id: String(item.id),
        product_id: String(item.product_id),
        display_title: String(item.display_title ?? ''),
        display_image_path: String(item.display_image_path ?? ''),
      })),
    },
    products: productRows,
    revision: snapshot.revision,
  }
}

export default async function HomeBestSellersEditorPage() {
  const initialData = await getBestSellersInitialData()
  return <HomeBestSellersEditorClient initialData={initialData} />
}

'use client'

import { tryUploadAwsImage } from '@/lib/image-transport'
import { cmsFetch } from '@/lib/cms-transport'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useMemo, useRef, useState, type ChangeEvent } from 'react'
import { ArrowLeft, Edit2 } from 'lucide-react'
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { CmsSaveAction } from '@/components/cms-save-action'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { useToast } from '@/hooks/use-toast'
import { useUnsavedChanges } from '@/hooks/use-unsaved-changes'

export type ProductListItem = {
  id: string
  name: string
  slug: string
  categoryPath: string
  detailTemplate: 'standard' | 'hiphop'
  status: string
}

type EditorState = {
  eyebrow: string
  heading: string
  cta_label: string
  cta_href: string
  selected_product_ids: string[]
  selected_products: Array<{ id?: string; product_id: string; display_title: string; display_image_path: string }>
}

type SavedProductOverride = { id: string; product_id: string; display_title: string; display_image_path: string }

function editableState(form: EditorState) { return JSON.stringify(form) }

export type HomeBestSellersInitialData = {
  revision: string
  section: EditorState
  products: ProductListItem[]
}

export function HomeBestSellersEditorClient({ initialData }: { initialData: HomeBestSellersInitialData }) {
  const { toast } = useToast()
  const router = useRouter()
  const [form, setForm] = useState<EditorState>(initialData.section)
  const [products] = useState<ProductListItem[]>(initialData.products)
  const [search, setSearch] = useState('')
  const [status, setStatus] = useState('Best sellers loaded')
  const [isSaving, setIsSaving] = useState(false)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [uploadingProductId, setUploadingProductId] = useState<string | null>(null)
  const [editingProductId, setEditingProductId] = useState<string | null>(null)
  const [revision, setRevision] = useState(initialData.revision)
  const [savedItemIds, setSavedItemIds] = useState(() => initialData.section.selected_products.flatMap((item) => item.id ? [item.id] : []))
  const [savedState, setSavedState] = useState(() => editableState(initialData.section))
  const pendingSave = useRef<{ fingerprint: string; id: string } | null>(null)
  const dirty = editableState(form) !== savedState
  const unsaved = useUnsavedChanges(dirty)

  const filteredProducts = useMemo(() => {
    const query = search.trim().toLowerCase()
    if (!query) return products
    return products.filter((product) =>
      [product.name, product.slug, product.categoryPath, product.detailTemplate]
        .filter(Boolean)
        .some((value) => value.toLowerCase().includes(query))
    )
  }, [products, search])

  const selectedProducts = useMemo(
    () =>
      form.selected_product_ids
        .map((id) => products.find((product) => product.id === id))
        .filter(Boolean) as ProductListItem[],
    [form.selected_product_ids, products]
  )

  const editingProduct = editingProductId ? products.find((product) => product.id === editingProductId) ?? null : null
  const editingOverride = editingProductId ? form.selected_products.find((item) => item.product_id === editingProductId) ?? null : null

  const toggleProduct = (id: string) => {
    setForm((current) => ({
      ...current,
      selected_product_ids: current.selected_product_ids.includes(id)
        ? current.selected_product_ids.filter((value) => value !== id)
        : [...current.selected_product_ids, id],
      selected_products: current.selected_product_ids.includes(id)
        ? current.selected_products.filter((item) => item.product_id !== id)
        : [...current.selected_products, { product_id: id, display_title: '', display_image_path: '' }],
    }))
  }

  const moveSelected = (id: string, direction: -1 | 1) => {
    setForm((current) => {
      const index = current.selected_product_ids.indexOf(id)
      const nextIndex = index + direction
      if (index === -1 || nextIndex < 0 || nextIndex >= current.selected_product_ids.length) return current

      const nextIds = [...current.selected_product_ids]
      const [item] = nextIds.splice(index, 1)
      nextIds.splice(nextIndex, 0, item)
      return { ...current, selected_product_ids: nextIds }
    })
  }

  const updateCardOverride = (productId: string, patch: Partial<{ display_title: string; display_image_path: string }>) => {
    setForm((current) => ({
      ...current,
      selected_products: current.selected_products.map((item) => item.product_id === productId ? { ...item, ...patch } : item),
    }))
  }

  const uploadCardImage = async (productId: string, file: File) => {
    if (file.size > 5 * 1024 * 1024) return setStatus('File too large. Max size is 5MB.')

    try {
      const awsPath = await tryUploadAwsImage(file, '/api/cms/uploads/home-bestsellers', {},{start:()=>setUploadingProductId(productId),finish:()=>setUploadingProductId(null)})
      if (awsPath) { updateCardOverride(productId,{display_image_path:awsPath}); setStatus('Best Seller card image uploaded'); return }
    } catch (error) { setStatus(error instanceof Error ? error.message : 'Upload failed.'); return }


    const { supabase } = await import('@/lib/supabase')
    const { data: sessionData } = await supabase.auth.getSession()
    const accessToken = sessionData.session?.access_token
    if (!accessToken) return setStatus('You are not signed in.')

    setUploadingProductId(productId)
    setStatus('Uploading Best Seller card image...')
    try {
      const upload = new FormData()
      upload.append('file', file)
      const response = await fetch('/api/cms/uploads/home-bestsellers', { method: 'POST', headers: { authorization: `Bearer ${accessToken}` }, body: upload })
      const payload = await response.json().catch(() => null)
      if (!response.ok || !payload?.path) throw new Error(payload?.error ?? 'Unable to upload image.')
      updateCardOverride(productId, { display_image_path: payload.path })
      setStatus('Best Seller card image uploaded')
    } catch (error) {
      setStatus(error instanceof Error ? error.message : 'Unable to upload image.')
    } finally {
      setUploadingProductId(null)
    }
  }

  const handleSave = async () => {
    setIsSaving(true)
    try {




      const retainedIds = new Set(form.selected_products.flatMap((item) => item.id ? [item.id] : []))
      const saveBody = { ...form, expected_revision: revision, deleted_ids: savedItemIds.filter((id) => !retainedIds.has(id)) }
      const fingerprint = JSON.stringify(saveBody)
      if (pendingSave.current?.fingerprint !== fingerprint) pendingSave.current = { fingerprint, id: crypto.randomUUID() }
      const response = await cmsFetch('/api/cms/home/bestsellers', {
        method: 'POST',
        headers: { 'content-type': 'application/json',  },
        body: JSON.stringify({ ...saveBody, request_id: pendingSave.current.id }),
      })
      const payload = await response.json().catch(() => null)
      if (!response.ok) throw new Error(payload?.error ?? 'Unable to save best sellers.')
      if (!Array.isArray(payload?.items) || typeof payload?.revision !== 'string' || !payload?.section) throw new Error('Save response was interrupted. Retry to confirm the same save.')
      const selectedProducts: SavedProductOverride[] = payload.items.map((item: { id: string; product_id: string; display_title?: string | null; display_image_path?: string | null }) => ({
        id: item.id, product_id: item.product_id, display_title: item.display_title ?? '', display_image_path: item.display_image_path ?? '',
      }))
      const nextForm = { ...payload.section, selected_product_ids: selectedProducts.map((item) => item.product_id), selected_products: selectedProducts } as EditorState
      setForm(nextForm)
      setSavedState(editableState(nextForm))
      setSavedItemIds(selectedProducts.map((item) => item.id))
      setRevision(payload.revision)
      pendingSave.current = null
      setConfirmOpen(false)
      setStatus('Best sellers saved')
      toast({ title: 'Saved', description: 'Homepage best sellers updated successfully.' })
    } catch (error) {
      setStatus(error instanceof Error ? error.message : 'Unable to save best sellers.')
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="p-8">
      <div className="mb-8 flex items-center gap-4">
        <Link href="/dashboard/cms/home" onClick={(event) => { event.preventDefault(); unsaved.confirmNavigation(() => router.push('/dashboard/cms/home')) }} className="inline-flex items-center gap-2 text-sm font-semibold text-primary hover:text-primary/80">
          <ArrowLeft size={16} />
          Back to Home
        </Link>
      </div>

      <div className="mb-10">
        <h1 className="font-jakarta text-3xl font-semibold text-foreground">Best Sellers</h1>
        <p className="mt-1 text-sm text-muted-foreground">Select existing products to display in the homepage best sellers section.</p>
        <p className="mt-2 text-xs text-muted-foreground">{status}</p>
      </div>

      <div className="space-y-6">
        <div className="space-y-4 rounded-lg border border-border bg-white p-6 shadow-xs">
          <div>
            <label className="mb-2 block text-sm font-semibold text-foreground">Eyebrow</label>
            <input value={form.eyebrow} onChange={(e) => setForm((prev) => ({ ...prev, eyebrow: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="mb-2 block text-sm font-semibold text-foreground">Heading</label>
            <input value={form.heading} onChange={(e) => setForm((prev) => ({ ...prev, heading: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" />
          </div>
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-1">
            <div>
              <label className="mb-2 block text-sm font-semibold text-foreground">CTA Label</label>
              <input value={form.cta_label} onChange={(e) => setForm((prev) => ({ ...prev, cta_label: e.target.value }))} className="w-full rounded-lg border border-border bg-white px-3 py-2 text-sm" />
            </div>
            <div>
              <label className="mb-2 block text-sm font-semibold text-foreground">CTA Link</label>
