'use client'

import { cmsFetch } from '@/lib/cms-transport'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useState, type ChangeEvent } from 'react'
import { ArrowLeft, Upload } from 'lucide-react'
import { CmsSaveAction } from '@/components/cms-save-action'
import { ConfirmDialog } from '@/components/confirm-dialog'
import { useToast } from '@/hooks/use-toast'
import { uploadCmsAssetDirectWithFallback } from '@/lib/cms-direct-upload-client'
import { useCmsSingletonSave } from '@/hooks/use-cms-singleton-save'
import { useUnsavedChanges } from '@/hooks/use-unsaved-changes'

export type EducationHeroForm = { is_enabled: boolean; heading: string; paragraph: string; button_label: string; button_link: string; desktop_image_path: string; desktop_image_alt: string; mobile_image_path: string; mobile_image_alt: string }

export function EducationHeroEditorClient({ initialData, initialRevision }: { initialData: EducationHeroForm; initialRevision: string }) {
  const router = useRouter()
  const [form, setForm] = useState(initialData)
  const [savedForm, setSavedForm] = useState(initialData)
  const [status, setStatus] = useState('Education hero loaded')
  const [isSaving, setIsSaving] = useState(false)
  const [uploading, setUploading] = useState<'desktop' | 'mobile' | null>(null)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const { toast } = useToast()
  const { prepareSave, acceptSave } = useCmsSingletonSave(initialRevision)
  const dirty = JSON.stringify(form) !== JSON.stringify(savedForm)
  const unsaved = useUnsavedChanges(dirty)

  const upload = async (kind: 'desktop' | 'mobile', file?: File) => {
    if (!file) return



    setUploading(kind)
    try {
      const path = await uploadCmsAssetDirectWithFallback({ file, accessToken: undefined, signEndpoint: '/api/cms/uploads/education/sign', fallbackEndpoint: '/api/cms/uploads/education', maxInputBytes: 5 * 1024 * 1024, rasterWidth: 2200, webpQuality: 84 })
      setForm((current) => ({ ...current, [kind === 'desktop' ? 'desktop_image_path' : 'mobile_image_path']: path }))
      setStatus(`${kind === 'desktop' ? 'Desktop' : 'Mobile'} image uploaded`)
    } catch (error) { setStatus(error instanceof Error ? error.message : 'Unable to upload image.') } finally { setUploading(null) }
  }

  const save = async () => {
    setIsSaving(true)
    try {



      const response = await cmsFetch('/api/cms/education/hero', { method: 'POST', headers: { 'content-type': 'application/json',  }, body: JSON.stringify(prepareSave(form)) })
      const payload = await response.json().catch(() => null) as { error?: string; revision?: string; item?: EducationHeroForm } | null
      if (!response.ok) throw new Error(payload?.error ?? 'Unable to save education hero.')
      if (!payload?.revision || !payload.item) throw new Error('Save response was interrupted. Retry to confirm the same save.')
      setForm(payload.item); setSavedForm(payload.item); acceptSave(payload.revision)
      setConfirmOpen(false); setStatus('Education hero saved')
      toast({ title: 'Saved', description: 'Education page hero updated successfully.' })
    } catch (error) { setStatus(error instanceof Error ? error.message : 'Unable to save education hero.') }
    finally { setIsSaving(false) }
  }

  const input = 'w-full rounded-lg border border-border bg-white px-3 py-2.5 text-sm'
  return <div className="min-h-screen bg-background p-8">
    <div className="mb-8 flex items-center justify-between gap-4"><Link href="/dashboard/cms/education" onClick={(event) => { event.preventDefault(); unsaved.confirmNavigation(() => router.push('/dashboard/cms/education')) }} className="inline-flex items-center gap-2 text-sm font-semibold text-primary"><ArrowLeft size={16} />Back to Education</Link><CmsSaveAction onClick={() => setConfirmOpen(true)} isSaving={isSaving} disabled={!dirty || Boolean(uploading)} position="inline" /></div>
    <div className="mb-8"><h1 className="font-jakarta text-3xl font-semibold">Education Page Hero</h1><p className="mt-2 text-xs text-muted-foreground">{status}</p></div>
    <div className="grid max-w-5xl gap-6 lg:grid-cols-2">
      <section className="space-y-5 rounded-lg border border-border bg-white p-6 shadow-xs">
        <label className="flex items-center gap-3 text-sm font-semibold"><input type="checkbox" checked={form.is_enabled} onChange={(e) => setForm({ ...form, is_enabled: e.target.checked })} className="h-4 w-4" />Show hero on education page</label>
        <div><label className="mb-2 block text-sm font-semibold">Heading</label><input value={form.heading} onChange={(e) => setForm({ ...form, heading: e.target.value })} className={input} /></div>
        <div><label className="mb-2 block text-sm font-semibold">Paragraph</label><textarea rows={5} value={form.paragraph} onChange={(e) => setForm({ ...form, paragraph: e.target.value })} className={input} /></div>
        <div className="grid gap-4 sm:grid-cols-2"><div><label className="mb-2 block text-sm font-semibold">Button label</label><input value={form.button_label} onChange={(e) => setForm({ ...form, button_label: e.target.value })} className={input} /></div><div><label className="mb-2 block text-sm font-semibold">Button link</label><input value={form.button_link} onChange={(e) => setForm({ ...form, button_link: e.target.value })} className={input} /></div></div>
      </section>
      <section className="space-y-6 rounded-lg border border-border bg-white p-6 shadow-xs">
        {(['desktop','mobile'] as const).map((kind) => <div key={kind} className="space-y-3"><label className="block text-sm font-semibold capitalize">{kind} image</label><label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-border px-4 py-2 text-sm font-semibold hover:bg-secondary"><Upload size={14} />{uploading === kind ? 'Uploading...' : `Upload ${kind} image`}<input type="file" accept="image/*" className="hidden" disabled={Boolean(uploading)} onChange={(e: ChangeEvent<HTMLInputElement>) => void upload(kind, e.target.files?.[0])} /></label><p className="break-all text-xs text-muted-foreground">{form[`${kind}_image_path`]}</p><label className="block text-sm font-semibold">{kind === 'desktop' ? 'Desktop' : 'Mobile'} image alt text</label><input value={form[`${kind}_image_alt`]} onChange={(e) => setForm({ ...form, [`${kind}_image_alt`]: e.target.value })} className={input} /></div>)}
      </section>
    </div>
    <ConfirmDialog isOpen={confirmOpen} title="Save Education Hero?" description="This updates the hero shown on the public education page." confirmText="Save" cancelText="Cancel" type="confirm" isLoading={isSaving} onConfirm={save} onCancel={() => setConfirmOpen(false)} />
    <ConfirmDialog isOpen={unsaved.showWarning} title="Discard unsaved Education Hero changes?" description="Your Education Hero changes have not been saved." confirmText="Discard changes" cancelText="Keep editing" type="warning" onConfirm={unsaved.handleDiscard} onCancel={() => unsaved.setShowWarning(false)} />
  </div>
}

import { NextResponse } from 'next/server'
import { withOperationsRoute, isOperationsRds } from '@/lib/operations-route'
import { createSettingsRepository } from '@/lib/db/admin-repositories/settings'
export const runtime='nodejs'
export const dynamic='force-dynamic'
import { settingsDatabaseError, siteSettingsSchema } from '@/lib/settings-validation'

const settingsKey = 'global_site_settings'

export async function GET(request: Request) {
  return withOperationsRoute(request,async access=>{
  if(isOperationsRds(access)) return Response.json({item:await createSettingsRepository(access.db).read()})

  const { data, error } = await access.adminClient
    .from('site_settings')
    .select('whatsapp_number, default_gst_slab_id, maintenance_mode_enabled, maintenance_mode_message, estimated_delivery_text')
    .eq('settings_key', settingsKey)
    .limit(1)
    .maybeSingle()
  if (error) return NextResponse.json({ error: 'Unable to load settings.' }, { status: 500 })

  return NextResponse.json({
    item: {
      settings_key: settingsKey,
      whatsapp_number: data?.whatsapp_number ?? '',
      default_gst_slab_id: data?.default_gst_slab_id ?? '',
      maintenance_mode_enabled: Boolean(data?.maintenance_mode_enabled),
      maintenance_mode_message: data?.maintenance_mode_message ?? '',
      estimated_delivery_text: data?.estimated_delivery_text ?? 'Approximately 3 to 4 weeks',
    },
  }, { headers: { 'Cache-Control': 'no-store' } })
  })
}

export async function POST(request: Request) {
  return withOperationsRoute(request,async access=>{
  if(isOperationsRds(access)) return Response.json(await createSettingsRepository(access.db).save(await request.json().catch(()=>null)))
  const parsed = siteSettingsSchema.safeParse(await request.json().catch(() => null))
  if (!parsed.success) return NextResponse.json({ error: parsed.error.issues[0]?.message ?? 'Invalid settings details.' }, { status: 400 })

  if (parsed.data.default_gst_slab_id) {
    const { data: slab, error } = await access.adminClient
      .from('catalog_gst_slabs')
      .select('id, status')
      .eq('id', parsed.data.default_gst_slab_id)
      .maybeSingle()
    if (error) {
      const safe = settingsDatabaseError(error)
      return NextResponse.json({ error: safe.message }, { status: safe.status })
    }
    if (!slab || slab.status === 'hidden') return NextResponse.json({ error: 'Select an active GST slab.' }, { status: 400 })
  }

  const payload = { settings_key: settingsKey, ...parsed.data }
  const updateResult = await access.adminClient.from('site_settings').update(payload).eq('settings_key', settingsKey).select('settings_key').limit(1)
  if (updateResult.error) {
    const safe = settingsDatabaseError(updateResult.error)
    return NextResponse.json({ error: safe.message }, { status: safe.status })
  }
  if (!updateResult.data?.length) {
    const insertResult = await access.adminClient.from('site_settings').insert(payload)
    if (insertResult.error) {
      const safe = settingsDatabaseError(insertResult.error)
      return NextResponse.json({ error: safe.message }, { status: safe.status })
    }
  }

  return NextResponse.json({ success: true }, { headers: { 'Cache-Control': 'no-store' } })
  })
}

import { NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { withOperationsRoute, isOperationsRds } from '@/lib/operations-route'
import { readAdminAuthProvider } from '@/lib/auth/integration'
import { authorizeProductRequest } from '@/lib/product-session-runtime'
import { ProductSessionError } from '@/lib/product-session-error'

export const runtime='nodejs'
export const dynamic='force-dynamic'
import { passwordChangeSchema } from '@/lib/settings-validation'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

export async function POST(request: Request) {
  try {
    if (readAdminAuthProvider() === 'keycloak') {
      await authorizeProductRequest(request, true)
      return Response.json({ error: 'Manage your password through the verified Keycloak account flow.', action: 'account-console', endpoint: '/api/auth/account' }, { status: 409, headers: { 'Cache-Control': 'no-store' } })
    }
  } catch (error) {
    return Response.json({ error: 'Password management unavailable.' }, { status: error instanceof ProductSessionError ? error.status : 503, headers: { 'Cache-Control': 'no-store' } })
  }
  return withOperationsRoute(request,async access=>{
  if(isOperationsRds(access)) return Response.json({error:'Password management requires the approved Keycloak self-service flow. It is not available yet.'},{status:503,headers:{'Cache-Control':'no-store'}})
  const parsed = passwordChangeSchema.safeParse(await request.json().catch(() => null))
  if (!parsed.success) return NextResponse.json({ error: parsed.error.issues[0]?.message ?? 'Invalid password details.' }, { status: 400 })
  if (!access.user.email) return NextResponse.json({ error: 'Your admin account does not have an email address.' }, { status: 400 })
  if (!supabaseUrl || !supabaseAnonKey) return NextResponse.json({ error: 'Password changes are temporarily unavailable.' }, { status: 503 })

  const verifyClient = createClient(supabaseUrl, supabaseAnonKey, { auth: { autoRefreshToken: false, persistSession: false } })
  const { error: signInError } = await verifyClient.auth.signInWithPassword({ email: access.user.email, password: parsed.data.currentPassword })
  if (signInError) return NextResponse.json({ error: 'Current password is incorrect.' }, { status: 400 })

  const { error: updateError } = await access.adminClient.auth.admin.updateUserById(access.user.id, { password: parsed.data.newPassword })
  if (updateError) return NextResponse.json({ error: 'Unable to update the password.' }, { status: 500 })

  return NextResponse.json({ success: true, message: 'Password updated successfully. Please sign in again for a fresh session.' }, { headers: { 'Cache-Control': 'no-store' } })
  })
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { withCmsDataRoute } from '@/lib/cms-rds-handlers'
import { runBespokeData } from '@/lib/bespoke-rds-data'

export async function GET(request: Request, context: { params: Promise<{ id: string }> }) {
  return withCmsDataRoute(request, async access => {
    if ('provider' in access) return runBespokeData(request, access, (await context.params).id)

  const { id: rawId } = await context.params
  const id = z.string().uuid().safeParse(rawId)
  if (!id.success) return NextResponse.json({ error: 'Invalid submission ID.' }, { status: 400 })

  const { data, error } = await access.adminClient.from('bespoke_submissions').select('id, full_name, email, phone, country, piece_type, stone_preference, approx_carat, preferred_metal, message, status, created_at').eq('id', id.data).maybeSingle()
  if (error) return NextResponse.json({ error: 'Unable to load this Bespoke submission.' }, { status: 500 })
  if (!data) return NextResponse.json({ error: 'Submission not found.' }, { status: 404 })
  return NextResponse.json({ item: data }, { headers: { 'Cache-Control': 'no-store' } })

  })
}

export const runtime = 'nodejs'

import { NextResponse } from 'next/server'
import { withCmsDataRoute } from '@/lib/cms-rds-handlers'
import { runBespokeData } from '@/lib/bespoke-rds-data'
import { bespokeSubmissionQuerySchema } from '@/lib/admin-read-validation'

export async function GET(request: Request) {
  return withCmsDataRoute(request, async access => {
    if ('provider' in access) return runBespokeData(request, access, undefined)

  const { searchParams } = new URL(request.url)
  const filters = bespokeSubmissionQuerySchema.safeParse({ from: searchParams.get('from') ?? undefined, to: searchParams.get('to') ?? undefined, q: searchParams.get('q') ?? undefined })
  if (!filters.success) return NextResponse.json({ error: filters.error.issues[0]?.message ?? 'Invalid submission filters.' }, { status: 400 })

  let builder = access.adminClient.from('bespoke_submissions').select('id, full_name, email, phone, country, piece_type, stone_preference, approx_carat, preferred_metal, message, status, created_at').order('created_at', { ascending: false }).limit(1_000)
  if (filters.data.from) builder = builder.gte('created_at', `${filters.data.from}T00:00:00.000Z`)
  if (filters.data.to) builder = builder.lte('created_at', `${filters.data.to}T23:59:59.999Z`)
  const { data, error } = await builder
  if (error) return NextResponse.json({ error: 'Unable to load Bespoke submissions.' }, { status: 500 })

  const query = filters.data.q?.toLowerCase() ?? ''
  const items = (data ?? []).filter((item) => !query || [item.full_name, item.email, item.phone, item.country, item.piece_type, item.stone_preference, item.approx_carat, item.preferred_metal, item.message, item.status].filter(Boolean).join(' ').toLowerCase().includes(query))
  return NextResponse.json({ items }, { headers: { 'Cache-Control': 'no-store' } })

  })
}

