import { loadCatalogRingSnapshot, saveCatalogRing } from '@/lib/catalog-ring-save'

export async function GET(request: Request) {
  const rds = await runCatalogRdsRoute(request, undefined); if (rds) return rds
 const access = await assertAdmin(request); if ('error' in access) return access.error; const snapshot = await loadCatalogRingSnapshot(access.adminClient); return NextResponse.json({ items: snapshot.categories, revision: snapshot.revision }, { headers: { 'Cache-Control': 'no-store' } }) }
export async function POST(request: Request) {
  const rds = await runCatalogRdsRoute(request, undefined); if (rds) return rds
 const access = await assertAdmin(request); if ('error' in access) return access.error; return saveCatalogRing(access, await request.json().catch(() => null)) }

export const runtime = 'nodejs'

import { runCatalogRdsRoute } from '@/lib/catalog-rds-handlers'
import { assertAdmin } from '@/lib/cms-auth'
import { deleteCatalogMaster, saveCatalogMaster } from '@/lib/catalog-master-save'

export async function PATCH(request: Request, { params }: { params: Promise<{ id: string }> }) {
  const rds = await runCatalogRdsRoute(request, (await params).id); if (rds) return rds
 const access = await assertAdmin(request); if ('error' in access) return access.error; return saveCatalogMaster(access, 'stone_shape', (await params).id, await request.json().catch(() => null)) }
export async function DELETE(request: Request, { params }: { params: Promise<{ id: string }> }) {
  const rds = await runCatalogRdsRoute(request, (await params).id); if (rds) return rds
 const access = await assertAdmin(request); if ('error' in access) return access.error; return deleteCatalogMaster(access, 'stone_shape', (await params).id, await request.json().catch(() => null)) }

export const runtime = 'nodejs'

import { handleImageUpload } from '@/lib/image-route'

const bucket = process.env.SUPABASE_COLLECTION_BUCKET ?? 'hod'

export async function POST(request: Request) {
  return handleImageUpload(request, {
    bucket, maxBytes: 1024 * 1024, rasterWidth: 512, allowSvg: true, svgOnly: true,
    buildPath: () => `catalog/stone-shapes/${crypto.randomUUID()}.svg`,
  })
}

